WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[12926] = { title = "Pieces of the Puzzle", description = "We've seen the iron dwarves and their constructs making war on the creatures of stone that Brann calls the earthen, along with their giant allies. Contact him and aid him in any way you can, and remember that anything we can learn from his search may aid us in fighting against the iron dwarves and their master.", objectives = "Use Brann's Communicator to contact Brann Bronzebeard and find out what to do next.", progress = "Did you complete the disk?", completion = "That was quick! Now that we have the disk, we have to find out how to use it to unlock the first half of the archive key." }
WordHunterWoW_QuestEN[12927] = { title = "Data Mining", description = "That disk you assembled... it's blank! Keeper Mimir, the tinker who built this library, must've hidden the information elsewhere. Look around the Inventor's Library; do you see any databanks there?\n\nThat might be the disk's purpose. Try using it near some of those databanks. Perhaps it's set to retrieve and store information from them. After you've tried your hand at that, contact me again and let me know what you've found. Meanwhile, I'll be trying to track down the other half of the archive key.", objectives = "Use the Inventor's Disk to retrieve 7 pieces of Hidden Data from the Databanks.", progress = "Did you try using the disk? What did you find?", completion = "<Brann looks at the disk as you hold it up.>\n\nI can't tell if there's anything stored there or not, lad. You'll have to tell me what happened.\n\n<You describe the data retrieval process.>\n\nSo it worked? At least we can count on Keeper Mimir to be systematic." }
WordHunterWoW_QuestEN[12928] = { title = "Norgannon's Shell", description = "Charging inventor's disk.\n\nDisk charging completed.\n\nPreparing emergency protocol gamma.\n\nEmergency protocol loaded. Please use the charged disk to activate the guardian of Norgannon's shell, Archivist Mechaton. The archivist will release the shell once your identity has been verified.\n\nPlease have a pleasant millennium.", objectives = "Recover Norgannon's Shell from Archivist Mechaton.", progress = "Did you find Norgannon's shell?", completion = "That's it! That's the first half of Norgannon's keystone. Well done, <name>. I've had Archaeologist Andorin on the lookout for clues to the shell's whereabouts for a long time. He's never going to believe me when I tell him it was an intrepid <race> who found it instead." }
WordHunterWoW_QuestEN[12929] = { title = "The Earthen of Ulduar", description = "The earthen who once inhabited, built, and maintained Ulduar were ousted from their home when Loken took over the city. Since then, his iron dwarf followers have relentlessly attacked the exiles.\n\nThey have taken refuge in an old titan building, which they now call Bouldercrag's Refuge, on the face of a mountain west of the Inventor's Library. Bouldercrag and his brethren fight to keep the irons from overrunning their haven, but they cannot hold their ground long. Find and help them, {name}.", objectives = "Speak with Bouldercrag the Rockshaper at Bouldercrag's Refuge.", completion = "So you know Brann Bronzebeard, then? He is our closest ally among those of the flesh. We are as brothers in the struggle against Loken and his followers, in the fight for Ulduar." }
WordHunterWoW_QuestEN[12930] = { title = "Rare Earth", description = "It seems so long ago that these hammers pounded and hewed stone instead of iron. Our expulsion from Ulduar saw the weakest of us dead and the strongest of our craftsmen reborn as warriors.\n\nAs the irons beat us back, even the strongest find themselves failing.\n\nWe can do little for the wounded, save when we have a stock of enchanted earth. We used to mine it from the deposits on the sheer cliff face to the northwest, but the constant battle has prevented us from replenishing our stock. Would you help?", objectives = "Use the Earthen Mining Pick to mine 7 clumps of Enchanted Earth. Bring the earth and 5 Frostweave Cloth to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Were you able to find any of the earth?", completion = "This will allow us to patch up more of the fallen. Thank you, <name>, on behalf of all who defend the refuge." }
WordHunterWoW_QuestEN[12931] = { title = "Fighting Back", description = "The refuge's defenders have done their best to blunt the iron dwarves' attacks, but we keep losing ground inch by inch. My men are hardy, but not tireless. Without reinforcements, it's only a matter of time until we will be overrun.\n\nWould you lend your skills to the refuge's defense? It would greatly improve the morale of the defenders and give them -- and me -- hope of mounting a counterattack.\n\nKill any of the stormforged or their creations you encounter outside the refuge.", objectives = "Bouldercrag the Rockshaper wants you to slay 10 Stormforged Attackers and return to him at Bouldercrag's Refuge. You may kill either Stormforged Raiders or Stormforged Reavers.", completion = "You've given the defenders something to cheer about. Seeing the enemy fall by your hand has reinvigorated them and bolstered their courage." }
WordHunterWoW_QuestEN[12932] = { title = "The Amphitheater of Anguish: Yggdras!", description = "I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand. These trolls are dirtier than ogres; but hey, I go where the gold's at! So welcome to Zul'Drak, pal.\n\nYou're new to this racket, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match.\n\nIf you're ready and got a group of friends with you, we can start! What do you say?\n", objectives = "Get in the arena at the Amphitheater of Anguish and defeat Yggdras! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "Not bad, friend. You might make some gold out here - if you manage to stay alive." }
WordHunterWoW_QuestEN[12933] = { title = "The Amphitheater of Anguish: Magnataur!", description = "This next match is a doozy, buddy! Apparently some magnataur from the Dragonblight wants a piece of the action. You ever fought one of those before? All I can tell you is to aim high!\n\nWe'll get this party started when you give me the word.", objectives = "Get in the arena at the Amphitheater of Anguish and defeat Stinkbeard! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "Wow! When I first saw Stinkbeard, I thought you were done for! Nice work!" }
WordHunterWoW_QuestEN[12934] = { title = "The Amphitheater of Anguish: From Beyond!", description = "I'm not gonna lie to you, pal. You might be overmatched here. This next one is a being from the elemental planes! I don't even know what's gonna show up in that arena!\n\nIf you think you're up to it, get in there and give 'em hell!", objectives = "Get in the arena at the Amphitheater of Anguish and defeat one of the elemental lords! Return to Wodin the Troll-Servant to redeem your reward.", completion = "Unbelievable! I thought this whole place was going to explode when it first appeared! You really dominated that round!" }
WordHunterWoW_QuestEN[12935] = { title = "The Amphitheater of Anguish: Tuskarrmageddon!", description = "This next one's fightin' from a dark place, kid. The kind of dark that can only happen when you've been on the flip-side. He's hungry and willing to do whatever it takes to win. Watch yourself! I've heard he wrestles yetis for exercise!\n\nWe'll start when you're ready.", objectives = "Get in the arena at the Amphitheater of Anguish and defeat Orinoko Tuskbreaker! Return to Wodin the Troll-Servant to redeem your reward.", completion = "I was worried for a while there, <name>. When he busted out the seals and penguins... Well, I didn't know what to think to be honest. It looked pretty damn ridiculous." }
WordHunterWoW_QuestEN[12936] = { title = "The Amphitheater of Anguish: Korrak the Bloodrager!", description = "You're not gonna believe this, pal. Your next fight is against Korrak the Bloodrager! Looks like the Drakkari trolls are pulling a power play! And let me tell you, buddy, he's been sippin' the animal god juice. He's good and ready to pound you into the ground.\n\nAre you ready?", objectives = "Get in the arena at the Amphitheater of Anguish and defeat Korrak the Bloodrager! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "Damn, I remember Korrak from way back in my younger days when I used to work for the Frostwolf Clan. He would never shut up! I think you just did the world a great service, <name>." }
WordHunterWoW_QuestEN[12937] = { title = "Relief for the Fallen", description = "The refuge's defenders fight bravely, but they cannot keep up with the iron onslaught.\n\nWith the earth you collected, I can make bandages to help heal the wounds of some of the fallen. The more defenders we can patch up, the longer we'll last out there.\n\nTake these poultices and use them to heal the wounds of the fallen defenders outside the refuge. Get as many back into the battle as possible, {name}. Every casualty is one too many.", objectives = "Use the Telluric Poultice to heal 8 Fallen Earthen Defenders, then return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", completion = "The warriors that you've healed will aid us in holding the line even longer. If we are to truly be free of the iron threat, we must find a way to strike at them behind the lines." }
WordHunterWoW_QuestEN[12938] = { title = "The Duke", description = "We need you focused, {name}. We're barely holding The Shadow Vault as it is. As you can see, we've greatly angered the Lich King.\n\n<The baron chuckles.>\n\nI need you to speak with Duke Lankral. He's in charge here now. You'll find him inside the vault building proper.\n\nWere I you, I would not keep him waiting.", objectives = "Speak with Duke Lankral at The Shadow Vault.", completion = "It's a pleasure to finally meet you, <name>. We owe you a great deal, but we're not done with you yet.\n\nThere is a vrykul city just over the mountains to the west, a place called Jotunheim.\n\nThe vrykul there are in a constant state of challenge to 'ascend'. The winners go to Ymirheim to serve as the Lich King's elite warrior caste, the Ymirjar, and the losers are reduced to scourged Vargul.\n\nYou are going to be my instrument to see to it that more Vargul than Ymirjar emerge." }
WordHunterWoW_QuestEN[12939] = { title = "Honor Challenge", description = "The first step we're going to take is at a place in Jotunheim called the Savage Ledge. It's just over the mountains to the west.\n\nOn the ledge the vrykul warriors are always sparring, being instructed in the finer arts of battle by their thane's men.\n\nI want you to take this flag and issue a challenge to a number of them. Let's demoralize them with the 'mere' skills of a {race}, shall we?\n\n<The duke grins, his rotting teeth flashing in the dim light of the vault.>", objectives = "Duke Lankral at The Shadow Vault has asked you to use the Challenge Flag to challenge and defeat 6 Mjordin Combatants.", completion = "Already I'm hearing reports of the prowess you displayed on the Savage Ledge. Excellent, <name>... excellent!\n\n\n\nAnd now I think it's time to issue a decree to the thane of those vrykul that you so easily defeated." }
WordHunterWoW_QuestEN[12940] = { title = "Candy Bucket", description = "", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!" }
WordHunterWoW_QuestEN[12941] = { title = "Candy Bucket", description = "", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!" }
WordHunterWoW_QuestEN[12942] = { title = "Off With Their Black Wings", description = "Traitors.  We Hyldnir have little love for them.\n\nThe dwellers of Valkyrion have gone unpunished for far too long.  While we remained loyal to Thorim, they became the Lich King's lapdogs!\n\nThey call the ones who receive his gift val'kyr.  They fly on feathered wings, like the harpies they are.\n\nYou will find Valkyrion far to the northwest, beyond the Temple of Storms.  Slay these winged she-wolves, sister.  Slay them and I will reward you with one of my most prized possessions.", objectives = "Iva the Vengeful in Brunnhildar Village wants you to go to Valkyrion and slay 12 Nascent Val'kyr.", completion = "The val'kyr are nothing but the Lich King's lapdogs.  They will be put down like the scum they are.  They've made their choice, now they have to live with the consequences." }
WordHunterWoW_QuestEN[12943] = { title = "Shadow Vault Decree", description = "Thane Ufrang the Mighty sits within his hall overlooking the Savage Ledge. I've studied him. The thane is a patient vrykul, with a head for strategy and warfare. He's also shown a penchant for biding his time and not wanting to overplay his hand in the ongoing battle.\n\nI need him dead!\n\nI've written a decree. Stand before the thane and read it aloud.\n\n<The duke arches his eyebrow in amusement.>\n\nIt should... unnerve him at the least.", objectives = "Duke Lankral at The Shadow Vault has ordered you to read the Shadow Vault Decree in the presence of Thane Ufrang the Mighty, and then to slay him.", completion = "<Duke Lankral nods his approval at your report of success.>\n\nWe face a foe that dwarfs us, not only in stature, but also numerically. If we are to win the battle for Icecrown, we must outthink them!\n\nWith Ufrang dead, that gives us an advantage in Jotunheim. Let us see if we can capitalize on it." }
WordHunterWoW_QuestEN[12944] = { title = "Candy Bucket", description = "", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!" }
WordHunterWoW_QuestEN[12945] = { title = "Candy Bucket", description = "", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!" }
