WordHunterWoW_QuestEN[12947] = { title = "Candy Bucket", description = "", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!" }
WordHunterWoW_QuestEN[12948] = { title = "The Champion of Anguish", description = "This is the end, my friend! Your last opponent is going to be your greatest challenge. He's a vrykul champion from the steppes of Icecrown and he's out for blood! Defeat him and you'll be crowned the champion of the Amphitheater of Anguish! This fight is going to make us both rich!\n\nLet me know when you're ready and we'll start.", objectives = "Get in the arena at the Amphitheater of Anguish and defeat Vladof the Butcher! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "You did it, <name>! That was the most exciting fight yet! What are you going to do with your winnings? Me? I'm going to Dalaran and blowing it all in the Underbelly. Lot of hot action going on down there!" }
WordHunterWoW_QuestEN[12949] = { title = "Get the Key", description = "{class}, the key to my shackles is hanging around the neck of Instructor Hroegar outside.\n\nPerhaps you could retrieve it by separating his head from his shoulders?", objectives = "Vaelen the Flayed at Ufrang's Hall has asked you to retrieve the Key to Vaelen's Chains.", progress = "Do you have it?", completion = "Thank you, <race>. Just hand me the key, I'll take care of it myself." }
WordHunterWoW_QuestEN[12950] = { title = "Candy Bucket", description = "", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!" }
WordHunterWoW_QuestEN[12951] = { title = "Let the Baron Know", description = "The most important thing that you can do right now is to return to The Shadow Vault and let Baron Sliver know that I've failed.\n\nYou see, I wasn't the only one captured by these vrykul devils. My entire contingent of death knights was also taken.\n\nI should have seen the trap before it was sprung, but there's no use crying over spilled milk now is there?\n\nGo on before you get captured, too! I'll see you back at the vault.", objectives = "Speak with Baron Sliver at The Shadow Vault.", completion = "What?! We can ill-afford to lose one death knight, let alone an entire contingent!!!" }
WordHunterWoW_QuestEN[12952] = { title = "Gem Perfection", description = "My skills are going to waste in this wretched place.   I spent many years learning to cut gems into their perfect form and have nothing to work on!   You look like the type who may be able to find me some gems and if you do I can teach you the skill of gem perfection.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.You will learn:", objectives = "Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Carter Tiffens in Vengeance Landing." }
WordHunterWoW_QuestEN[12953] = { title = "Valkyrion Must Burn", description = "The crate is filled with incendiary harpoons.  You recall seeing harpoon guns and dry stacks of hay outside.\n\nPerhaps Iva will appreciate the extra effort and reward you appropriately.", objectives = "Use the Valkyrion Harpoon Guns to burn 6 Dry Haystacks.", completion = "Now that is what I call dedication!  Those traitors might have a new master now, but they'll never forget their sisters' parting gift." }
WordHunterWoW_QuestEN[12954] = { title = "The Amphitheater of Anguish: Yggdras!", description = "I was wondering when you'd show up, {name}! Having a past champion of the Ring of Blood here will be a huge draw! We're gonna be rich, buddy! RICH!\n\nAnyway, this dump is Zul'Drak. All the ice trolls seem to use it as a toilet. I dunno, the whole place is off its rocker if you ask me! Who cares, though, right? We're here to make some gold!\n\nYou know the drill, {name}. When you're ready let me know and we'll get this show on the road!\n", objectives = "Get in the arena at the Amphitheater of Anguish and defeat Yggdras! Return to Wodin the Troll-Servant to redeem your reward.", progress = "No payout until the fight's over, man.", completion = "Hey! I know you. Your victory at the Ring of Blood was talked about for months! Too bad you forfeited the championship when you failed to show up to defend your title! Easy come, easy go, eh? At least you're still alive." }
WordHunterWoW_QuestEN[12955] = { title = "Eliminate the Competition", description = "Mrrfrmrfrrmrrr...\n\n<The Leaper clears his throat.>\n\nSorry about that. It can sometimes be hard to understand what I'm saying. You know how it is.\n\nI wanted to make sure that if you find yourself at the Savage Ledge, over the mountains to the west, that you make sure to eliminate the competition there.\n\nSpecifically, I'd like you to challenge to duels and humiliate Sigrid Iceborn, Efrem the Faithful, Onu'zun, and Tinky Wickwhistle in front of the vrykul.", objectives = "The Leaper at The Shadow Vault wants you to duel and defeat Sigrid Iceborn, Efrem the Faithful, Onu'zun and Tinky Wickwhistle.", completion = "That was important, <name>. By driving them off, you're keeping them from interfering with whatever we need you to do over there." }
WordHunterWoW_QuestEN[12956] = { title = "A Spark of Hope", description = "Clearly, this is more than an ordinary hunk of metal.\n\nUnlike any ore you're familiar with, it is hard but not brittle, far lighter than it looks, and glows even when cool.\n\nLooking closer, you can make out one of Thorim's runes shining beneath the surface....", objectives = "You are to bring the Refined Gleaming Ore to Thorim in the Temple of Storms.", progress = "What have you there, little one?", completion = "You notice Thorim's stern countenance brighten with recognition as you present the ore." }
WordHunterWoW_QuestEN[12957] = { title = "Slaves of the Stormforged", description = "To the southwest, on the western side of the Snowdrift Plains, the iron dwarves have dug a mine into the hillside. There, they use captive mechagnomes, servants of Keeper Mimir, to mine ore.\n\nI don't know where these mechagnomes came from, nor what they would do with their freedom, but perhaps we can win their help.\n\nGo to the Frozen Mine, {name}, and set these creatures free from their bondage. Ask if they would fight alongside us against iron dwarf tyranny.", objectives = "Bouldercrag the Rockshaper at Bouldercrag's Refuge wants you to free 6 Captive Mechagnomes and kill 3 Stormforged Taskmasters.", progress = "Have you freed the slaves of the stormforged?", completion = "I had hoped that more of the captives would choose to join us, but I do not blame them. Willing allies are few and far between, and we are thankful that you have lent your blade to our cause." }
WordHunterWoW_QuestEN[12958] = { title = "Shipment: Blood Jade Amulet", description = "A wealthy shipping concern has requested a collection of Blood Jade Amulets to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.\n", objectives = "Combine a Vrykul Amulet, a Dark Jade and a Bloodstone to make a Blood Jade Amulet and bring it to Timothy Jones in Dalaran.\n\nYou can find a Vrykul Amulet on any Northrend Vrykul.", progress = "Do you have a Blood Jade Amulet for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!" }
WordHunterWoW_QuestEN[12959] = { title = "Shipment: Glowing Ivory Figurine", description = "A wealthy shipping concern has requested a collection of Glowing Ivory Figurines to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.\n", objectives = "Combine Northern Ivory, a Chalcedony and a Shadow Crystal to create a Glowing Ivory Figurine and bring it to Timothy Jones in Dalaran.\n\nYou can find a Northern Ivory on any Shoveltusk or Mammoth in Northrend.", progress = "Do you have a Glowing Ivory Figurine for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!" }
WordHunterWoW_QuestEN[12960] = { title = "Shipment: Wicked Sun Brooch", description = "A wealthy shipping concern has requested a collection of Wicked Sun Brooches to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.\n", objectives = "Combine an Iron Dwarf Brooch, a Huge Citrine and a Sun Crystal to create a Wicked Sun Brooch and bring it to Timothy Jones in Dalaran.\n\nYou can find an Iron Dwarf Brooch on any Northrend Iron Dwarf.", progress = "Do you have a Wicked Sun Brooch for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!" }
WordHunterWoW_QuestEN[12961] = { title = "Shipment: Intricate Bone Figurine", description = "A wealthy shipping concern has requested a collection of Intricate Bone Figurines to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.\n", objectives = "Combine a Proto Dragon Bone, a Sun Crystal and a Dark Jade to craft an Intricate Bone Figurine and bring it to Timothy Jones in Dalaran.\n\nYou can find a Proto Dragon Bone on any Northrend Proto Dragon.", progress = "Do you have an Intricate Bone Figurine for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!" }
WordHunterWoW_QuestEN[12962] = { title = "Shipment: Bright Armor Relic", description = "A wealthy shipping concern has requested a collection of Bright Armor Relics to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.\n", objectives = "Combine an Elemental Armor Scrap, a Bloodstone and a Huge Citrine to craft a Bright Armor Relic and bring it to Timothy Jones in Dalaran.\n\nYou can find an Elemental Armor Scrap on any Northrend Revenant.", progress = "Do you have a Bright Armor Relic for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!" }
WordHunterWoW_QuestEN[12963] = { title = "Shipment: Shifting Sun Curio ", description = "A wealthy shipping concern has requested a collection of Shifting Sun Curios to sell at Undermine.   If you can bring me one, I can reward you with a Dalaran Jewelcrafter's Token.\n", objectives = "Combine a Scourge Curio, a Sun Crystal and a Shadow Crystal to make a Shifting Sun Curio and bring it to Timothy Jones in Dalaran.\n\nYou can find a Scourge Curio on any Northrend Scourge.", progress = "Do you have a Shifting Sun Curio for my Undermine shipment?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  Come back tomorrow and I am sure I will have another item I need from you!" }
WordHunterWoW_QuestEN[12964] = { title = "The Dark Ore", description = "At the Frozen Mine in the western part of the Snowdrift Plains, the stormforged iron dwarves have constructed a mine manned by slaves.\n\nIt's well behind the lines, so we haven't been able to find out much about what's going on there, but my scouts have reported seeing them remove cartloads of dark, sickly looking ore.", objectives = "Bring 5 Ore Samples to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "What have you discovered about the ore?", completion = "<Bouldercrag reaches out to take the ore, but then recoils.>\n\nThat ore... I can't touch it. It seethes with unnatural energy. No creature of stone can handle it. What do they mean to do with this?" }
WordHunterWoW_QuestEN[12965] = { title = "The Gifts of Loken", description = "The one who commands the stormforged iron dwarves is called Runeseer Valduran. Although I have never seen them, it is said that his master, Keeper Loken, who took over Ulduar, has given Valduran powerful titan artifacts.\n\nIt could explain the strength and ferocity my men see in the stormforged warriors.\n\nValduran's base, Nidavelir, lies to the southwest, across the Snowdrift Plains. Go there, {name}, and neutralize his power. Destroy these gifts of Loken's and help us to sap the strength of his followers.", objectives = "Destroy Loken's Fury, Loken's Power, and Loken's Favor, and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", completion = "<Bouldercrag nods grimly.>\n\nYou've weakened the stormforged considerably, but they'll keep fighting. Their casualties matter nothing to them, while our defenders continue to fall. Even if it costs them a hundred or a thousand iron corpses, they'll keep fighting until we've been pounded to gravel." }
WordHunterWoW_QuestEN[12966] = { title = "You Can't Miss Him", description = "<Jokkum listens patiently to your request, then ponders it carefully before responding.>\n\nSo it is you we have to thank for Fjorn's demise?\n\nWhile it's true that you have aided us in our time of need, there is still much that must be done to repair our relations with Thorim.\n\nFor now, I shall allow Njormeld to reforge the armor we gifted to the Stormlord so many ages ago. Consider it payment for your assistance against Fjorn.\n\nNjormeld was sent to recover Fjorn's anvil. You should find him there.", objectives = "King Jokkum in Dun Niffelem wants you to find Njormeld at Fjorn's Anvil.", completion = "Reforging Thorim's armor? It can be done.\n\nFirst though, there's the matter of the anvil..." }
WordHunterWoW_QuestEN[12967] = { title = "Battling the Elements", description = "Snorri was once the pride of our nation. A mighty warrior, many an enemy fell to his club.\n\nWe honor him, though he's no longer what he once was. Age has taken its toll, dulling his senses and sapping his strength. Still, he remains as proud as ever, never missing an opportunity to join a battle.\n\nSpeaking of battle, we're cooling Fjorn's anvil so it can be taken home. The remaining fire revenants are putting up some resistance. Help Snorri relive his glory days, {race}. Guide him against this enemy.", objectives = "Njormeld wants you to accompany Snorri to Fjorn's anvil and help him kill 10 Seething Revenants.", progress = "Were you able to lead Snorri to another victory, <class>?", completion = "An honorable performance, <race>. I shall inform the king of your assistance.\n\nThe anvil is nearly cool enough. I shall see you in Dun Niffelem soon." }
WordHunterWoW_QuestEN[12968] = { title = "Yulda's Folly", description = "The witch that started it all, Yulda the Stormspeaker came to our very village.  She dared to insult our noble traditions and spouted the Lich King's venomous promises of power.\n\nShe ought to have left with a sword through her, but her magic was strong and she managed to escape.\n\nSeek her in Valkyrion inside the largest dwelling and show her that we are not to be trifled with.", objectives = "Iva the Vengeful at Brunnhildar Village wants you to slay Yulda the Stormspeaker in Valkyrion.", completion = "Yulda had it coming.  No one gets away with insulting the Hyldsmeet.  Not even one of our own." }
WordHunterWoW_QuestEN[12969] = { title = "Is That Your Goblin?", description = "I trust that's the green little one you've been looking for.  If I were you I'd step in before that Hyldnir splits him in half.\n\nYou've arrived in the middle of the Hyldsmeet, so all challenges must be accepted by participants.  There's nothing to stop you from taking your green friend's place.", objectives = "Challenge Agnetta Tyrsdottar in order to save Zeev Fizzlespark. Return to Lok'lira the Crone in Brunnhildar Village after you've succeeded.", progress = "You're back.", completion = "Well done, young one.  It looks like our deal has been satisfied on both our ends." }
WordHunterWoW_QuestEN[12970] = { title = "The Hyldsmeet", description = "Whether you've noticed or not, by defeating your first Hyldnir in hand-to-hand combat, you've entered the Hyldsmeet -- the great competition of Hyldnir against Hyldnir to determine who will rule by Thorim's side.\n\nThe Hyldsmeet is the reason why I was imprisoned, for I sought to partake in the competition but was far too old and frail to be a match for the Hyldnir.\n\nIf you're willing to listen, I've a proposal for you.", objectives = "Listen to Lok'lira the Crone's proposal.", completion = "It's settled then.  You will compete in the Hyldsmeet and with my help you'll restore great Thorim to his rightful place." }
WordHunterWoW_QuestEN[12971] = { title = "Taking on All Challengers", description = "Let's get you started.  The good news is that by defeating Agnetta, you've earned yourself a spot in the next round of matches.\n\nThe bad news is that all your opponents will also have defeated someone in the first round.  Do not expect pushovers.", objectives = "Lok'lira the Crone in Brunnhildar Village wants you to defeat 6 Victorious Challengers.", completion = "You've done it, <name>.  You've bested some of the fiercest fighters the Hyldnir race has to offer." }
WordHunterWoW_QuestEN[12972] = { title = "You'll Need a Bear", description = "You've succeeded in the first rounds of the Hyldsmeet.  To advance further, you're going to need a warbear of your own.\n\nUnfortunately, the Hyldnir don't give them out to just anyone.  You'll have to emerge victorious from true battle, not just gladiatorial combat.\n\nThe Hyldnir of Brunnhildar are currently involved in a feud against the Sons of Hodir, Thorim's former allies.  Speak to Brijana just outside the village and see how you can help them and prove yourself in the process.", objectives = "Speak to Brijana outside Brunnhildar Village.", completion = "Think we'll give you your own bear just like that?  You'll have to prove yourself before you get anything from us.\n\nDo not think too highly of yourself just because you bested a few challengers in the Hyldsmeet." }
WordHunterWoW_QuestEN[12973] = { title = "The Brothers Bronzebeard", description = "That does it! We finally have the keystone... It's beautiful! I've been around the world more than once, but this thing's got me all jittery with excitement again. I suppose now's not the time to stop and admire though, we need to get the heck out of here.\n\nHop on my flying machine and help keep us covered from those iron dwarves on the way out!", objectives = "Accompany Brann Bronzebeard and his flying machine to Frosthold.", progress = "My pardons, lad! I got all caught up in tha moment and I neglected ye entirely.", completion = "King Stormheart sends his most sincere thanks for reuniting him with his brothers. It seems he's off to settle a score now - perhaps you'll meet with him again on Arthas's doorstep." }
WordHunterWoW_QuestEN[12974] = { title = "The Champion's Call!", description = "Pfft, what happens down here ain't fightin'. It's a couple of guys dancin' around a flag.\n\nYou lookin' for some real action, buddy? 'Cause if you are I got the hottest ticket in town.\n\nEver heard of Gurgthock and Wodin? Goblin and troll who ran the Ring of Blood back in Outland? Well they're here in Northrend and they've started up a whole new fight club over in Zul'Drak. If you're interested go to Zul'Drak, east of Crystalsong. They're at the big arena in the center. Tell 'em Shifty sent ya!", objectives = "Seek out Gurgthock at the Amphitheater of Anguish in Zul'Drak.", completion = "Shifty sent you, eh?" }
WordHunterWoW_QuestEN[12975] = { title = "In Memoriam", description = "Surely Thorim has told you of the tragedy that divides us.\n\nIt was in Thunderfall, northeast of here, that these events unfolded. The frozen fossils there are a reminder of that dark day, as are the spirits that haunt that place.\n\nIf my people are to forgive Thorim, something must take the place of those images. A memorial must be constructed to bring our hearts peace.\n\nGo there, {race}. Collect the fragments of Hodir's Horn that was shattered that day.", objectives = "King Jokkum in Dun Niffelem wants you to collect 8 Horn Fragments from Thunderfall.", progress = "Have you found the pieces of Hodir's Horn?", completion = "Another good deed you have done on Thorim's behalf, <class>.\n\nThis will help to soften the hearts of my people towards him." }
WordHunterWoW_QuestEN[12976] = { title = "A Monument to the Fallen", description = "Bring these fragments to Njormeld. He will use the pieces of that sacred relic in the construction of a mighty monument.\n\nMay it soothe the pains and heal the scars my people have borne these many years.\n\nMay its presence help to bring about a new age that sees us once again in glorious battle at Thorim's side.\n\nGo now, {class}. Njormeld awaits you.", objectives = "King Jokkum wants you to bring Hodir's Horn Fragments to Njormeld in Dun Niffelem.", progress = "You have brought the fragments of Hodir's Horn, <race>?", completion = "<Njormeld's eyes become noticeably moist as he pours the contents of the bag onto the anvil.>\n\nThe Horn of Hodir....\n\nThis was a sacred gift to our people from Hodir himself, <race>. It is a relic of great importance to us.\n\nWhen you next return to our stronghold you shall see the fruits of your labor.\n\nFarewell." }
WordHunterWoW_QuestEN[12977] = { title = "Hodir's Call", description = "You have done a great service to the giants of Dun Niffelem. Without your aid, this monument would not exist.\n\nAs you silently ponder its significance, feelings begin to flood your heart. The feelings fill your mind with thoughts and images... as well as a sense of urgency.\n\nThe sensations fade and leave you with a knowledge of what you must do. The restless spirits at Thunderfall must be put to rest.\n\nAs you set off, you find that your hands have been filled with an ethereal horn.", objectives = "Blow Hodir's Horn over 5 Niffelem Forefathers and 5 Restless Frostborn corpses at Thunderfall.", completion = "You are filled with a sense of peace and contentment knowing that the once tormented souls of Thunderfall are now resting peacefully." }
WordHunterWoW_QuestEN[12978] = { title = "Facing the Storm", description = "Like Bouldercrag, I once served the keepers as a craftsman in Ulduar, but with Loken's betrayal, I turned my hammer toward our new foes.\n\nWhen we could spare the men, I led raids on Nidavelir to relieve the pressure on our defenders, but our lines are near collapse.\n\nYou've proven yourself a capable combatant and a staunch ally. Perhaps you'd be willing to take up our banner and take the fight to Nidavelir, the iron dwarf stronghold to the southwest, across the Snowdrift Plains.", objectives = "Bruor Ironbane at Bouldercrag's Refuge wants you to kill 10 Nidavelir Stormforged. You may kill Stormforged Champions, Stormforged Magi, or Stormforged War Golems.", completion = "There may be hope for victory, <name>. We have never been able to sustain an attack on the stormforged, but with your efforts, Valduran may yet fall!" }
WordHunterWoW_QuestEN[12979] = { title = "Armor of Darkness", description = "This armor plate is thick and oversized compared to the rest of the golem's defenses. A quick examination of the golem's corpse reveals that this heavier plate seems to have been bolted on as an afterthought or a crude upgrade.\n\nWhy would the iron dwarves have added this redundant and mismatched armor to their war golems?\n\nPerhaps Bruor Ironbane would know if he had the chance to examine several of these plates from stormforged war golems.", objectives = "Bring 4 Dark Armor Samples to Bruor Ironbane at Bouldercrag's Refuge.", progress = "What is it you have there?", completion = "Careful, now. Keep that plate as far away from me as you can. Even being in its presence is enough to inflict pain.\n\nBut you're right, <name>, these are gigantic armor plates for a war golem of normal size. What would the stormforged be doing with them? There's only one way to find out." }
WordHunterWoW_QuestEN[12980] = { title = "The Armor's Secrets", description = "The presence of that armor plate is disorienting, but we need to find out all we can from it. It could be part of one of Valduran's schemes.\n\nHe's dedicated an extraordinary amount of effort to mining, refining, smithing, and testing this metal.\n\nTo the east, along the northern mountain face, is a building called Mimir's Workshop. It hasn't been used in quite some time, but if we're lucky, some of its attendants are still functional. Take your armor plate there and learn what you can from it.", objectives = "Take the Dark Armor Plate to Mimir's Workshop and ask Attendant Tock to examine it. When you're finished, return to Bruor Ironbane at Bouldercrag's Refuge.", progress = "What did you learn?", completion = "<Bruor listens as you describe what you learned in the workshop.>\n\nSo Valduran's master has given him this sinister metal to construct a giant weapon? That must be what he intends to use for the final strike against us! We need to stop him before he's able to complete it and unleash this weapon." }
WordHunterWoW_QuestEN[12981] = { title = "Hot and Cold", description = "As you stare at the anvil you relive your recent accomplishments, particularly those which brought this artifact to rest here.\n\nIt suddenly occurs to you that more remains to be done. To the east, smoldering scraps clutter the landscape--shrapnel from the battle fought there.\n\nIf they could be cooled and gathered somehow, the frost giants would have an abundant supply of metal and the region would be cleared of these remnants of war.", objectives = "You are to go to Frostfield Lake, kill the Brittle Revenants there and use the Essence of Ice on the Smoldering Scraps at Fjorn's Anvil. You are then to collect 6 of the Frozen Iron scraps and return to Fjorn's Anvil in Dun Niffelem.", progress = "A luminous blue glow surrounds the anvil.", completion = "You feel a sense of accomplishment as you realize that your efforts continue to strengthen the renewed bonds between Thorim and the Sons of Hodir." }
WordHunterWoW_QuestEN[12982] = { title = "Ebon Blade Prisoners", description = "Now that I'm back, I'm certain that the baron will want me to recover my men. I can see that we're barely hanging on here. The Lich King's forces are about to break through and we won't be able to hold without my captured death knights.\n\nCan you assist me once more, {name}?\n\nGo back to Jotunheim and let them out of those cages. Break the damn locks, I don't care what you have to do. The vrykul likely have the keys.\n\nJust get my men free!", objectives = "Vaelen the Flayed at The Shadow Vault wants you to free 8 Ebon Blade Prisoners. They can be found in the cages throughout the greater Jotunheim region.", completion = "Thank you, <class>. With the death knights that you freed, we'll be able to hold the line... for now." }
WordHunterWoW_QuestEN[12983] = { title = "The Last of Her Kind", description = "For as long as I can remember, we've obtained our best bears from the Hibernal Cave to the east.\n\nThose times might finally be gone.  The cave has been overrun by ravenous jormungar and the wild bears are all but extinct.\n\nIf you were to find a surviving matriarch, however, I would guarantee you that she would fight better than any of these bears born in captivity.\n\nTake this harness to the Hibernal Cave and rescue a surviving matriarch.  Good luck finding one.", objectives = "Astrid Bjornrittar in Brunnhildar Village wants you to rescue an Icemaw Matriarch in the Hibernal Cavern.", completion = "I'm impressed.  I never thought I would see an icemaw matriarch again.  Especially not one this size." }
WordHunterWoW_QuestEN[12984] = { title = "Valduran the Stormborn", description = "We have no choice, {name}. What you learned in Mimir's Workshop means that we must act before Valduran can complete and unleash his new weapon.\n\nEven now, the refuge's defenders fight to buy us time to deal with Valduran the Stormborn.\n\nYou must go to Nidavelir, across the Snowdrift Plains to the southwest, and then find and face Valduran. But you will not be alone. Bring this war horn with you and sound it as you prepare to face the leader of our enemies. Bruor and I will aid you in this battle.", objectives = "Use Bouldercrag's War Horn when you have found Valduran the Stormborn. Defeat Valduran the Stormborn and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", completion = "At last, Valduran is dead, and the stormforged are weakened, but if his boasting is true, we must continue fighting the stormforged in his absence. This weapon they're building could be the end of us." }
WordHunterWoW_QuestEN[12985] = { title = "Forging a Head", description = "Greetings, {race}.\n\nI have a task that King Jokkum felt you would be suited for, assuming you still strive to gain favor with our people.\n\nI have developed plans for another artifact, one that will grant Hodir's blessing of protection to our stronghold. I have nearly all that I require for its construction. All that remains to collect are the very eyes of our fallen enemies.\n\nTake this tool, and gather the eyes from the iron giant corpses that litter our fields.", objectives = "Njormeld in Dun Niffelem needs you to use the Diamond Tipped Pick on the Dead Iron Giants at Frostfield Lake and return to him when you have collected 8 Stormforged Eyes.", progress = "Have you collected the final components I seek, <race>?", completion = "It is nearly done.\n\nWith this artifact in place, Dun Niffelem shall be warned of impending dangers before they are upon us." }
WordHunterWoW_QuestEN[12986] = { title = "Fate of the Titans", description = "Norgannon's Core is not at this location. I am not sure why you seek it, {race}, and I am equally unsure if you truly know the purpose of that which you seek.\n\nI would like you to aid me before I consider extending my assistance.  I have recently encountered knowledge of the watcher, Thorim. His seat of power is contested, and his fate remains to be seen. This troubles me, for I do not know of the other watchers. Utilize this databank to examine their temples to the northeast and return the knowledge to me.", objectives = "Creteus in the Foot Steppes has requested that you travel to the Temple of Invention, the Temple of Winter, the Temple of Life, and the Temple of Order and utilize the databank to examine each area.", progress = "Have you returned with the knowledge that I seek, <race>?", completion = "The news you bear forth is grave indeed. I do not know the fate of the remaining watchers, but their absence spells dark times for all of the lands of Azeroth.\n\nI shall examine the knowledge contained in the databank that you have returned and attempt to fully assess the situation. I believe I am in possession of knowledge that you deem more pertinent at this moment however, so I shall allow you to partake in said wisdom first." }
WordHunterWoW_QuestEN[12987] = { title = "Placing Hodir's Helm", description = "The helm is forged.\n\nYour efforts have not gone unnoticed, small one. Though there remains much to do, we sons of Hodir are grateful for your accomplishments.\n\nIn return, I offer you the opportunity to present Hodir's helm to our king and our brethren.\n\nFly to the sparkling tip of the small ice spike in front of me and read to our people from this tablet.\n\nEnjoy the privilege, {class}. Never before has an outsider been given such an honor!", objectives = "Njormeld wants you to fly to the tip of the northern ice spike in Dun Niffelem and use the Tablets of Pronouncement.", progress = "Have you placed Hodir's Helm, <race>?", completion = "<Njormeld gazes up at Hodir's Helm, visibly moved.>\n\nThat will do, little <race>.\n\nThat will do...." }
WordHunterWoW_QuestEN[12988] = { title = "Destroy the Forges!", description = "In my folly, I'd thought Valduran's project at Narvir's Cradle, a large construction area to the south, no more than a grotesque monument to \"Keeper\" Loken's cruelty.\n\nNow we know the truth, that it was meant to be used as a weapon against us and our allies. We must not allow this iron colossus to reach completion, {name}, for it will mean the end of the refuge.\n\nGo to Narvir's Cradle, find the lightning forges the stormforged artisans use, and sabotage them.", objectives = "Destroy the North Lightning Forge, the Central Lightning Forge, and the South Lightning Forge with Bouldercrag's Bombs, then return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", completion = "Excellent work! Oh, it won't stop the iron dwarves, but it'll take them valuable time to rebuild those forges. I daresay we've gained the advantage." }
WordHunterWoW_QuestEN[12989] = { title = "The Slithering Darkness", description = "The vile jormungar have taken over most of the Hibernal Cavern.  They are despicable beings... children of Loken, Thorim's scumsucker of a brother.\n\nAs Thorim's servants we owe it to ourselves to kill these scum where we find them.  You'll find the cavern just east of here, outside the village.", objectives = "Astrid Bjornrittar wants you to slay 8 Ravenous Jormungar in the Hibernal Cavern east of Brunnhildar Village.", completion = "The jormungar are vile creatures.  You did well in destroying them." }
WordHunterWoW_QuestEN[12990] = { title = "The Wormhole", description = "Bring me materials and I'll teach you how to use your Wormhole Generator.You will learn:", objectives = "Bring Jon LeCraft the materials he seeks to avoid a swift death, and to get a cool new spell." }
WordHunterWoW_QuestEN[12991] = { title = "Hit Them Where it Hurts", description = "Bouldercrag's got a good plan to stymie the efforts of the iron dwarves at Narvir's Cradle, and I've got an idea of my own. Work on the iron colossus will come to a halt without any artisans.\n\nNarvir's Cradle is on the south side of the hill sheltering Bouldercrag's Refuge. Go there and slay any stormforged artificers in your path. They may be no different from what we once were, but they build a weapon that threatens us all.", objectives = "Kill 10 Stormforged Artificers and return to Bruor Ironbane at Bouldercrag's Refuge.", completion = "There were days when I could never ask someone to do what you did, but my experience with the iron dwarves has extinguished those feelings. We have bought time against the enemy's advance." }
WordHunterWoW_QuestEN[12992] = { title = "Crush Dem Vrykuls!", description = "Dem vrykuls at the Jotunheim needs to be crushed!\n\n{name} crush dems good!", objectives = "Vile at The Shadow Vault wants you to slay any 15 vrykul in the greater Jotunheim region.", completion = "<name> is my bestest little <race>!" }
WordHunterWoW_QuestEN[12993] = { title = "A Colossal Threat", description = "You've done an excellent job of delaying the work on the iron colossus, but I fear we've only made the stormforged more determined to complete the weapon.\n\nEven now, they're bringing in new laborers and the overseers push them to the limit. We may not be able to keep them from bringing the colossus online, after all. Return to Narvir's Cradle, to the south and find the documents detailing the colossus' offensive and defensive abilities. They should be near the tents and forges on the bottom level.", objectives = "Retrieve the Colossus Attack Specs and Colossus Defense Specs and bring them to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", progress = "Did you find the documents we're looking for?", completion = "<Bouldercrag begins to look over the documents, his eyes wide.>\n\nI had no idea the irons were capable of this! Our men will have no chance against this behemoth if it's completed. Fortunately, it looks like they're still lacking a key part." }
WordHunterWoW_QuestEN[12994] = { title = "Spy Hunter", description = "The rapport you've developed with the inhabitants of Dun Niffelem has yielded some unexpected discoveries.\n\nFor example, you somehow find yourself able to understand the denmother's guttural growls and sharp quips--at least you think you do.\n\nIt would seem that she senses danger outside the stronghold and wants you to do something about it.\n\nWith her forepaw, she removes the chain from around her neck and lets it drop at your feet. As you pick it up you notice an aged fang attached to it...", objectives = "You must defeat 3 Stormforged Spies in the Valley of Ancient Winters.\n\nUsing the Ethereal Worg's Fang at the Corpse of the Fallen Worg will summon an Ethereal Frostworg, which will expose hidden enemies. You are to return to the Frostworg Denmother in Dun Niffelem when the valley has been cleansed of spies.", progress = "The frostworg denmother looks at you curiously.", completion = "As you slide the chain back around the denmother's neck she licks your face approvingly." }
WordHunterWoW_QuestEN[12995] = { title = "Leave Our Mark", description = "We must attack the vrykul of Jotunheim on many levels. Brute force, of course, is good, but I prefer a more cerebral approach.\n\nI want you to demoralize them.\n\nMy men here have forged a number of banners for you. I would like for you to take and plant them near the corpses of fallen vrykul.\n\nLet the banners serve as a constant reminder to them that they face a more immediate threat than the wrath of the Lich King.", objectives = "Baron Sliver at The Shadow Vault wishes you to plant 15 Ebon Blade Banners near the corpses of vrykul found within the greater Jotunheim region.", completion = "Well done, <name>. Let them see the desecrated corpses of their fallen comrades and think twice about striking at us!\n\nIf you come back tomorrow, I will make certain to have more banners prepared for you." }
WordHunterWoW_QuestEN[12996] = { title = "The Warm-Up", description = "You've been very fortunate, sister.  This is a matriarch the likes of which hasn't been seen in years.\n\nA good bear won't do you much good without the skill to ride it.\n\nI'm going to have you practice some moves on Kirgaraak.  He's the largest yeti we've ever managed to capture so be careful.  Don't be afraid to walk away if he gives you a beating... there's a reason why we keep him chained.", objectives = "Astrid Bjornrittar in Brunnhildar Village wants you to use the Reins of the Warbear Matriarch to defeat Kirgaraak.", progress = "How did it go with the yeti?", completion = "Not bad.  I was hoping Kirgaraak would snap your neck so I could keep your bear.\n\nJust joking, sister.  Well... half-joking.  That's a really nice bear you've got." }
WordHunterWoW_QuestEN[12997] = { title = "Into the Pit", description = "Besting a tethered opponent is one thing.  Fighting other bear riders on equal footing is another.\n\nHead into the Pit of the Fang and use what you've learned to defeat your opponents.  Good luck, sister.\n\nGlory awaits, should you succeed.", objectives = "Astrid Bjornrittar, in Brunnhildar Village, wants you to use the Reins of the Warbear Matriarch inside the Pit of the Fang and defeat 6 Hyldsmeet Warbears.", completion = "You really did it!  You made it out with your health.  Wish we could say the same for your bear.\n\nIt's going to take a while for her to recover.  Fortunately you won't need her for a while." }
WordHunterWoW_QuestEN[12998] = { title = "The Heart of the Storm", description = "According to the documents you captured at Narvir's Cradle, the iron colossus is complete except for one key component -- the Heart of the Storm.\n\nWithout it, the iron colossus' weapons would be much weaker than the design predicts. If we can deny Overseer Narvir the heart, we could defeat the colossus!\n\nNotes on the documents you found say that the heart is in Uldis, a titan facility far to the south. Its entrance is on the south side of a tall mountain overlooking the Bor's Breath River.", objectives = "Bouldercrag the Rockshaper at Bouldercrag's Refuge wants you to travel to Uldis and try to prevent Overseer Narvir from obtaining the Heart of the Storm.", completion = "With the heart in the hands of Narvir, the colossus will achieve its full power! We'll have no choice but to fight it." }
WordHunterWoW_QuestEN[12999] = { title = "The Bone Witch", description = "You remember Lady Nightswood, don't you? She certainly remembers you. She's the forlorn and very angry banshee that you 'saved' when you also broke Vile and myself out from under the Lich King's dominion.\n\nThe lady has gone into Jotunheim and possessed their bone witch. She intends to wreak havoc upon the vrykul from within.\n\nShe has asked that you seek her out. You'll find her in the cave on the south side of Njorndar Village to the southwest within Jotunheim.", objectives = "Speak with The Bone Witch within the cave at Njorndar Village.", completion = "<name>, you came.\n\nAlready I have heard of your activities on the Savage Ledge. This is good. I am glad that you seem willing to help with undermining the vrykul here at Jotunheim.\n\n\n\nYou and I are going to have a great deal of fun with them!" }
WordHunterWoW_QuestEN[13000] = { title = "Emergency Measures", description = "The cold in these mountains is brutal.  We have a day or two before we burn up all the wood from the wreckage.\n\nWe spotted worgs inside a cave directly east of here.  I need you to find the cave and obtain some furs.  It might not sound like much, but it might be the difference between freezing to death and living another day.\n\nWorgs don't hunt alone, so I'm giving you a flare.  It should buy you some time if you find yourself outnumbered.", objectives = "Bloodguard Lorga wants you to go to the Gimorak's Den to the east and obtain 6 Worg Furs.", progress = "Did you bring the furs?", completion = "These furs are rather... large.  I'd hate to see the worgs you had to face off with.\n\nWe're all very thankful.  The temperature is starting to drop already." }
WordHunterWoW_QuestEN[13001] = { title = "Forging Hodir's Spear", description = "The time has come, little {class}. The stars have foretold of this day.\n\nI have received a vision from mighty Hodir himself, revealing the secret to the creation of a great artifact.\n\nWe must obey! Were we to fail in receiving this gift, doom would surely follow.\n\nI call upon you to assist me in this sacred undertaking.\n\nGo across the valley, deep into the Hibernal Cavern and gather everfrost shards from the icy crater there, then collect hides from the mammoths outside the cavern.", objectives = "Lorekeeper Randvir in Dun Niffelem wants you to collect 3 Everfrost Shards from the depths of Hibernal Cavern and 3 Stoic Mammoth Hides from the Stoic Mammoths in the Valley of Ancient Winters.", progress = "Have you gathered the materials for the spear, <race>?", completion = "Stand back, <race>, and behold the fulfilling of a prophecy!" }
WordHunterWoW_QuestEN[13002] = { title = "Gem Perfection", description = "Welcome to de cold, mon.  Dis place may not be so good for keepin' me bones warm, but I have learned how to cut me de perfect gem.  All I be needin' is some gems to do me work on.\n\nBring me some gems and I be teachin' you the skill of gem perfection.  Dis will allow you to sometimes cut a perfect gem with increased bonuses when cuttin' an uncommon quality gem from Northrend.You will learn:", objectives = "Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Geba'li in Warsong Hold." }
WordHunterWoW_QuestEN[13003] = { title = "How To Slay Your Dragon", description = "Hodir's Spear is an icon of great prowess in battle.\n\nIts mere presence instills a deep hunger for glory in all who enter Dun Niffelem. In fact, simply being near it has compelled you to test your own abilities.\n\nScanning the horizon, your vision locks on a wild wyrm as it flies nearby.\n\nIt is decided. Of you and he, only one shall see the next sunrise....", objectives = "You are to use Hodir's Spear to challenge a Wild Wyrm in the Valley of Ancient Winters. Once in its grip, you are to fight to the death.", progress = "The wyrm cries out, almost as if mocking you. Will you accept the challenge?", completion = "It is done.\n\nYou have stared certain death in the face and emerged victorious.\n\nBy single-handedly defeating such a mighty beast, you have brought great honor to Dun Niffelem!" }
WordHunterWoW_QuestEN[13004] = { title = "Gem Perfection", description = "There's a war going on and we each must do our part!  Mine is cutting gems and not only can I cut normal gems but I have the skill to cut perfect gems as well.   If you can bring me several uncut gems to contribute to the cause, I can teach you gem perfection as well.   This will allow you to sometimes cut a perfect gem with increased bonuses when cutting a uncommon quality gem from Northrend.You will learn:", objectives = "Return two Huge Citrines, two Dark Jade and two Shadow Crystals to Alestros in Valiance Keep." }
WordHunterWoW_QuestEN[13005] = { title = "The Earthen Oath", description = "For years I neglected my duties, giving into defeat and self-pity.\n\nNot the brave earthen, however.  Their oath to protect these grounds with their lives has gone unbroken.\n\nEven now, they fight the corruption of iron with selflessness, waiting for the moment in which the tides turn.\n\nThat moment has arrived.  We must rally what remains of the earthen defenders and lead them into a glorious victory.  Sound the Horn of the Peaks to call them to your side and take back the Terrace of the Makers.", objectives = "Thorim, at the Terrace of the Makers, wants you to use the Horn of the Peaks and call on the Earthen to defeat 20 Iron Dwarves and 7 Iron Sentinels.", completion = "It's a good start.  But my brother's forces will not take long to regroup.  We must make our victory a decisive one." }
WordHunterWoW_QuestEN[13006] = { title = "A Viscous Cleaning", description = "As you draw near the helm, you notice that the frigid environment is already taking its toll on the artifact's surface. What is now just a thin layer of ice will surely grow to envelop it entirely.\n\nNot about to let your hard efforts go to waste, you resolve to scour the region in search of a solution.\n\nJust as you set off, the eyes of the helm flash and an image of the nearby Hibernal Cavern enters your mind.", objectives = "You are to enter Hibernal Cavern west of Dun Niffelem and collect 5 units of Viscous Oil from the Viscous Oils there.\n\nYou are then to return to Dun Niffelem and apply the oil to Hodir's Helm.", progress = "Frost is thickening on the helm as you watch, and icicles are beginning to form around its edges...", completion = "As you coat the helm with a thin layer of oil, the frost falls away and the surface gleams." }
WordHunterWoW_QuestEN[13007] = { title = "The Iron Colossus", description = "We have failed to prevent the completion of the iron colossus, {name}, which means we have no choice but to face it in battle.\n\nBruor has devised a plan to exploit the colossus' only weakness.\n\nNo matter how tough the colossus' armor is, it is still vulnerable to a jormungar's acid. Take control of one using the orbs along the northern edge of the Snowdrift Plains, then use it to fight the Iron Colossus on the Snowdrift Plains. If you need help controlling the creature, speak to one of the nearby handlers.", objectives = "Use a Tamed Jormungar to defeat the Iron Colossus and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge.", completion = "We've done it, we've really done it! The refuge is spared and the stormforged are defeated! We must warn Brann before Loken gets it in his mind to try to rebuild his forces. The only way to secure the victory you have won today is to go into Ulduar and defeat Loken for all time!" }
WordHunterWoW_QuestEN[13008] = { title = "Scourge Tactics", description = "We had the element of surprise on our side! We blew a hole in the side of the mountain and charged into Scourgeholme. Scourge opposition was fierce and it wasn't long until we were overwhelmed. We fell back to the valley and began raining artillery down on the Scourge that followed. This held them back for awhile until... Those monsters began using crusaders as living shields. We had to stop shelling for fear of killing our own soldiers.\n\nFree our crusaders trapped on the field outside the base, {class}!", objectives = "Crusade Commander Entari at the Argent Vanguard in Icecrown has asked that you free 5 Webbed Crusaders.", completion = "There are still many Argent Crusade soldiers out on that field and in Scourgeholme, <name>. While your help is appreciated, there is still much left to be done." }
WordHunterWoW_QuestEN[13009] = { title = "A New Beginning", description = "It remains uncertain whether or not our people can ever rekindle the affection we once held for Thorim.\n\nMay this armor, if nothing else, remind him of the days when we stood together in honor, invincible.", objectives = "Njormeld wants you to take the Reforged Armor to Thorim at the Temple of Storms.", progress = "How have your efforts fared, <class>?", completion = "<As you present Thorim with the reforged suit of armor, he is visibly stricken by its splendor.>\n\nYou have done well, <race>, but there remains much to be done." }
WordHunterWoW_QuestEN[13010] = { title = "Krolmir, Hammer of Storms", description = "One task remains before I can reclaim my home at the Terrace of the Makers.\n\nKrolmir must be found.\n\nOn that fateful day, I threw it to the earth with all the power and rage I possessed. A mighty explosion followed.\n\nI've thought it lost for these many years, but now I must be certain.\n\nReturn to King Jokkum and discover what, if anything, he knows of my hammer's fate.", objectives = "Thorim wants you to talk to King Jokkum in Dun Niffelem and discover what he knows of Krolmir.", progress = "Back again, little <race>?", completion = "Words cannot express my gratitude, <class>.\n\nYou have served me honorably. Please accept this token of my gratitude." }
WordHunterWoW_QuestEN[13011] = { title = "Culling Jorcuttar", description = "The jormungar are a nuisance best dealt with quickly. If given any quarter, they breed like hares and spread like fire.\n\nThey have appeared southwest of here, in the Hibernal Cavern. If their spawnmother is not slain soon, they will gain a foothold in our region.\n\nShe cannot refuse food. Take this knife and get the flank of a bear corpse from their cave. Place it near her crater and kill her as she feeds.", objectives = "King Jokkum in Dun Niffelem wants you to slay Jorcuttar in Hibernal Cavern.", progress = "Have you slain Jormuttar?", completion = "So it is done.\n\nWe have heard the screams of Jormuttar as they echoed from across the valley.\n\nYou have done our people a service this day, little <race>." }
