WordHunterWoW_QuestEN[13034] = { title = "The Witness and the Hero", description = "When I began my travels in Northrend, I visited the Borean Tundra and met the taunka for the first time. There, Wind Tamer Barah told me the tale of Stormhoof and his battle against the North Wind, their people's ancient enemy.\n\nI set out for the Storm Peaks to learn more of this hero, but strangely, the people of Tunka'lo seem to know nothing of him.\n\nPerhaps the camp's own records will give us greater insight. Find and read the history scrolls kept throughout the camp, then tell me what you learned.", objectives = "Xarantaur, at Camp Tunka'lo, wants you to read the First History Scroll, the Second History Scroll, and the Third History Scroll.", completion = "How peculiar... that doesn't sound like the story Wind Tamer Barah told me." }
WordHunterWoW_QuestEN[13035] = { title = "Loken's Lackeys", description = "The attack on the Terrace of the Makers was not a half-hearted move on my brother's behalf.  He sent a legion of iron dwarves and some of his most powerful lieutenants.\n\nUse the Horn of the Peaks to call the earthen to your side and defeat Loken's servants.\n\nYou'll find the giant, Eisenfaust, inside the Hall of the Shaper to the north.  You'll find the others deeper inside the Terrace of the Makers, beyond the stairs to the northwest.", objectives = "Thorim wants you to slay Eisenfaust inside the Hall of the Shaper and Halefnir the Windborn and Duronn the Runeforged in the Terrace of the Makers.", completion = "One by one, my brother's servants have fallen.  Loken's insurrection will soon come to an end." }
WordHunterWoW_QuestEN[13036] = { title = "Honor Above All Else", description = "Long has been the path to our salvation, young {class}. We have fought across continents, worlds even, to reach this point. Now we face our greatest challenge: the destruction of the Lich King and his Scourge.\n\nAlas, we fight this battle divided. The Horde and Alliance are in the throes of war and will lend us no support. We must remain unyielding in our cause! For what choice have we to do otherwise?\n\nDo you join the cause? Lend us your strength, {class}! My commander, Entari, awaits you at his post.", objectives = "Report to Crusade Commander Entari at the Argent Vanguard in Icecrown.", completion = "Where both the Alliance and the Horde failed, the Argent Crusade succeeded. The success, however, was short lived. Our breach into Icecrown was quickly - and with force - rebuffed.\n\nThe Lich King's retaliatory strike was immediate and brutal. Now we are on the defensive." }
WordHunterWoW_QuestEN[13037] = { title = "Memories of Stormhoof", description = "When the bronze dragonflight gifted me with immortality and set me on the path of the witness, Nozdormu entrusted me with the Lorehammer.\n\nThe hammer's reaction to your findings means that time has gone awry here and it is our duty to restore the true timeline.\n\nWe must find it. To the northwest is Frostfloe Deep, ancient burial cave of the warriors of Tunka'lo. Seek out the spirit of Chieftain Swiftspear, Stormhoof's brother. Ask him what he remembers of his brother's battle against the North Wind.", objectives = "Speak with Chieftain Swiftspear in Frostfloe Deep, then return to Xarantaur at Camp Tunka'lo.", completion = "Even the chieftain is beginning to lose his memories? The past is being rewritten before our eyes and if we do not find out who is behind this, the entire legacy of Stormhoof could be lost forever." }
WordHunterWoW_QuestEN[13038] = { title = "Distortions in Time", description = "This, the tomb of Tunka'lo's warriors, is supposed to be a serene place, free from the terror of the elements.\n\nFrostfloe Deep has been invaded by a strange force, one that disturbs the spirits of the fallen and blurs my memories of my own life.\n\nIt's as though our deeds and memories are being erased from history.\n\nIn life, this totem was a symbol of my authority. It is the last true link I have to this world. Take it, use it to restore calm to the tomb, and then return it to Camp Tunka'lo.", objectives = "Use the Chieftain's Totem to close 4 Frostfloe Rifts, then bring the totem to Xarantaur at Camp Tunka'lo.", progress = "What is it you have brought from the tomb?", completion = "The chieftain's spirit told you to bring this to me?\n\n<Xarantaur examines the totem.>\n\nAh, I see what he intended. By telling you to use this totem to close the rifts in the deep, he has given us a clue as to what's happening to the timeline. A wise chieftain, this Swiftspear, watching over his people even in death." }
WordHunterWoW_QuestEN[13039] = { title = "Defending The Vanguard", description = "We can't keep this pace up, lad. Once the breach was blown, the floodgates opened up. The Scourge have been pourin' through ever since with no end in sight!\n\nWe need every able bodied man and woman to help keep the tide of evil at bay. Get out there and do yer share, friend. Kill as many of those monsters as ye can!", objectives = "Crusader Lord Dalfors at the Argent Vanguard in Icecrown has asked that you kill 15 Forgotten Depths Nerubians.", progress = "Don't give up, <name>!", completion = "How many of them could there possibly be? We've killed enough to fill ten graveyards and still they come. The situation looks grim, friend." }
WordHunterWoW_QuestEN[13040] = { title = "Curing The Incurable", description = "The number of injured soldiers rises with each passing day. They are being stricken by some type of toxin that we have never before seen. Whatever it is that these Nerubians hold within their venom glands is lethal and incurable! So far we've only been able to slow down the poison flowing through the victim's bodies. We must devise a cure!\n\nVenture northwest to the valley outside of the Vanguard and slay the Forgotten Depths Nerubians. Recover their venom glands and bring them to me.", objectives = "Father Gustav at the Argent Vanguard in Icecrown has asked that you bring him 10 Forgotten Depths Venom Sacs.", progress = "Have you recovered the venom glands, <race>?", completion = "Thank you, <name>. I will begin the tests on these samples immediately. It is my hope that a cure will be found soon." }
WordHunterWoW_QuestEN[13041] = { title = "Finish the Shipment", description = "I'm glad you showed up!   A shipment of Glowing Ivory Figurines needs to go out to Undermine right now, and I am still short a Chalcedony to complete an eye for the last one.\n\nBring me one and a Dalaran Jeweler's token will be yours.", objectives = "Bring a Chalcedony to Timothy Jones in Dalaran.", progress = "Do you have the Chalcedony yet?", completion = "Here is your Dalaran Jewelcrafter's Token as promised.  I have new shipments going out all the time, check by from time to time to see what I need." }
WordHunterWoW_QuestEN[13042] = { title = "Deep in the Bowels of The Underhalls", description = "Deep in the bowels of The Underhalls to the northeast, a mad scientist known as Dr. Terrible is up to something befitting his name.\n\nThe doctor has been given dispensation by the Lich King to perform experiments upon the vargul -- the vrykul who fall in battle and are found unworthy, and then turned into Scourge.\n\nWe must put an end to his work, but my auguries have been unable to find him. He does, however, have an assistant.\n\nBeat the information out of his apprentice, and then dispose of the body.", objectives = "The Bone Witch in Njorndar Village has asked you to beat information out of Apprentice Osterkilgr concerning what Dr. Terrible is truly up to.\n\nYou are then to slay the apprentice.", completion = "Very interesting. It sounds to me that you handled that perfectly. I'm surprised that the doctor was using a vargul as an assistant given what he was working on." }
WordHunterWoW_QuestEN[13043] = { title = "The Sum is Greater than the Parts", description = "Opening the tome, you notice all manner of disgusting illustrations concerning the construction of what the doctor refers to as \"the ultimate weapon\"!\n\nClearly the prototype, Nergeld, is the massive flesh giant standing still at the end of the nearby Hall of Horrors.\n\nIf an army of those things were to be constructed, then it would mean doom. The only way to ensure that doesn't happen is to slay Dr. Terrible!\n\nPerhaps if you were to take control of the construct, the doctor would reveal himself?", objectives = "Mount and take control of Nergeld. Defend it from the denizens of the Hall of Horrors until Dr. Terrible shows himself.\n\nUse Nergeld to slay the doctor, and then return to The Bone Witch in Njorndar Village.", completion = "You discovered and put an end to the doctor's machinations.\n\n<The banshee-controlled witch smiles and places a large hand gently upon your shoulder.>\n\nThat's a fine poke in the eye for the Lich King, but I think we can do better." }
WordHunterWoW_QuestEN[13044] = { title = "If There Are Survivors...", description = "Across the Valley of Echoes, west of here, and through the Breach, is the first Scourge encampment in Icecrown known as Scourgeholme. We fought a good fight at Scourgeholme and killed many Scourge, but in the end we were forced to retreat. Many soldiers were left behind - their fate unknown.\n\nIf there are survivors, we must attempt a rescue. Directly down this southeastern path is Penumbrius, ally of the bronze dragonflight and caretaker of the proto-brood. Seek him out and ask for his assistance.", objectives = "Speak with Penumbrius at the Argent Vanguard in Icecrown.", completion = "<Penumbrius nods.>\n\nMy kin will help. Together we will battle the Lich King and his undead legions." }
WordHunterWoW_QuestEN[13045] = { title = "Into The Wild Green Yonder", description = "We will do all that we can to assist you, {name}. The proto-brood have volunteered to fly you across the Breach and into Scourgeholme. Rescue any captured Argent Crusaders that you find. Return them immediately to the Vanguard Infirmary, located at the center of this base.\n\nChoose one of the Argent Skytalons in the pen behind me and go!\n\nScourgeholme is located northwest, across the Valley of Echoes, through the great Breach.", objectives = "Rescue 3 Captured Argent Crusaders from Scourgeholme and drop them off at the Vanguard Infirmary at the center of the Argent Vanguard. Report to Highlord Tirion Fordring should you succeed.", progress = "With each minute that passes their chance of survival decreases.", completion = "Arthas... He strikes recklessly - without care or caution. We have caught him off guard.\n\n<Highlord Tirion Fordring pauses, lost in thought for a moment.>\n\nWe will bolster our defenses and weather the storm.\n\nHow good are you with a cannon, <name>?" }
WordHunterWoW_QuestEN[13046] = { title = "Feeding Arngrim", description = "Arngrim's hunger was legendary.\n\nEven in death, his expression is one of famished yearning. You find that just looking at him is making your stomach growl.\n\nIt is said that throughout his life he was never truly sated, and that there was absolutely nothing he wouldn't eat. You wonder to yourself if there might be a way to feed the old king.\n\nNo sooner does the thought enter your mind than one of the massive frozen teeth falls from Arngrim's head, bounces off of his beard and lands in your hand.", objectives = "You are to feed Arngrim 5 Disembodied Jormungar, then return to Arngrim's frozen image in Dun Niffelem.\n\nYou must go to the Valley of Ancient Winters and use Arngrim's Tooth on the Roaming Jormungar there. Once they have become disembodied, you must fight them until they are weakened.", completion = "As you anchor the tooth in Arngrim's jaw, you get the impression that your efforts may have taken the edge off of the old king's hunger pangs... for now." }
WordHunterWoW_QuestEN[13047] = { title = "The Reckoning", description = "Loken killed my wife, turned my followers and me against each other.  He took away everything I had, but today... that changes.\n\nToday we reclaim our sacred grounds.  Today... Loken dies.\n\nMeet me on the bridge near the Temple of Wisdom, just southwest of Ulduar.  I will finish this one way or the other.\n\nI need you there as a witness.  You will not aid me -- this is personal.\n\nAfter it's done, send word to Jokkum, King of the Frost Giants.  He's a good friend and will know what to do.", objectives = "Meet Thorim near the Temple of Wisdom. Report the outcome of the fight to King Jokkum in Dun Niffelem.", completion = "No... it cannot be...\n\nNo one can defeat Thorim in single combat.  Not a giant, nor a beast... no one!  Especially not that coward of a brother of his.\n\nOn my forefathers' names, this I swear...\n\nLoken will pay for this!" }
WordHunterWoW_QuestEN[13048] = { title = "Where Time Went Wrong", description = "The Lorehammer can help us correct the damage to the timeline, but only if we can discover where the history was originally corrupted.\n\nFrom Chieftain Swiftspear and your findings at Frostfloe Deep, we know that the change happened around the time of Stormhoof's death.\n\nNow, you must go to the Howling Hollow, north of the camp, and inspect the gravesites the North Wind's minions have already destroyed. The Lorehammer will react to artifacts from Stormhoof's era and attune itself to the proper time.", objectives = "Use the Lorehammer on Taunka Relics to attune it to the time of Stormhoof. Once it has been attuned to 6 relics from the time of Stormhoof, return to Xarantaur at Camp Tunka'lo.", progress = "Have you attuned the Lorehammer to the time period of Stormhoof?", completion = "<Xarantaur accepts the Lorehammer from you.>\n\nAt last, we've pinpointed the time of Stormhoof in history. With this knowledge, we can restore the timeline." }
WordHunterWoW_QuestEN[13049] = { title = "The Hero's Arms", description = "Not all of the camp's records have yet been corrupted. My staff has helped me to find those records which reflect the true timeline.\n\nThey agree that Stormhoof was given a burial of honor among the village elders on the bottom level of the Howling Hollow, to the north.\n\nMost of the graves there have already been destroyed, their contents taken as trophies by the North Wind's subjects. Go to the hollow and see if you can recover Stormhoof's spear and armor from the scions of storm who have claimed them.", objectives = "Recover Stormhoof's Spear and Stormhoof's Mail and return them to Xarantaur at Camp Tunka'lo.", progress = "Have you found Stormhoof's weapon and armor?", completion = "We are fortunate that you have recovered these intact, <name>. With them, I can use the Lorehammer to send you back in time, to where the North Wind started to corrupt the true timeline. It's the only way we can restore the true history of this place." }
WordHunterWoW_QuestEN[13050] = { title = "Veranus", description = "If I'm to launch an attack against my brother's army, I'm going to need some way to get around.\n\nI released my riding drake back into the wild years ago.  Veranus was magnificent.  The leader of her own brood -- to whom she has now returned.\n\nFinding her will be hard, but perhaps there's a way.  She keeps her old empty nest out of pure pride.  She's a broodmother in name only, for she is beyond the age of breeding.\n\nBring me small eggs from the other nests near Brunnhildar.  I think I've an idea.", objectives = "Thorim, at the Temple of Storms, wants you to obtain 5 Small Proto-Drake Eggs from the peaks near Brunnhildar Village.", progress = "Did you obtain the eggs, <name>?", completion = "Yes... these will do.  Let us hope my plan works, <name>.\n\nVeranus is a great drake.  I'd hate to have to settle for a lesser one." }
WordHunterWoW_QuestEN[13051] = { title = "Territorial Trespass", description = "Veranus is proud like no other beast I've known.  She still keeps her old nest and makes sure none of the younger proto-drakes takes it over.\n\nTake the eggs you've collected and place them on her nest.  You'll find it atop a small peak, directly southeast of here.\n\nI should be able to get control of her before she kills you in a fit of rage.  Hopefully.", objectives = "Place the Stolen Proto-Dragon Eggs on top of the Broodmother's Nest and return to Thorim at the Temple of Storms.", progress = "Hail, <name>!", completion = "It's good to have my old friend back.  It appears that my luck is finally starting to change... and it's all thanks to you, little friend." }
WordHunterWoW_QuestEN[13052] = { title = "Aerial Surveillance", description = "You did a good job helping Wes with getting that flying machine back up and running.\n\nIf you'd like to help us further, there is an unusual weather pattern coming in from the northwest.  I have a pilot ready to work for me, but I'm afraid he needs a copilot.\n\nIf you think you're up to it, you can take the flight to Lakeside Landing.  Tell Vic I sent you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Professor Calvert wants you to take the flight to Lakeside Landing and speak with Pilot Vic there.You did a good job helping Wes with getting that flying machine back up and running.\n\nIf you'd like to help us further, there is an unusual weather pattern coming in from the northwest. I have a pilot ready to work for me, but I'm afraid he needs a copilot.\n\nIf you think you're up to it, you can take the flight to Lakeside Landing. Tell Vic I sent you.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[13053] = { title = "Looking for Survivors", description = "Gretchen Fizzlespark wants to use my flying machine to look for survivors from her expedition.  Apparently she thinks they're being held prisoner in the village to the north.\n\nThe only problem is I don't have a co-pilot.  If you're willing to take it on, I'd be more than happy to teach you a move or two.\n\nWhat do you say, <name>?  Deal?You will learn:", objectives = "Help Zak Wobblesprocket complete the Test Flight." }
WordHunterWoW_QuestEN[13054] = { title = "The Missing Tracker", description = "I can't in good conscience send you to the worg cave without warning you that the previous person we sent there hasn't returned.\n\nWe're prepared for the worst, but perhaps there's a chance that he's alive.  We'd appreciate it if you helped him return -- Tracker Val'zij is one of the only hunters we have.", objectives = "Look for Tracker Val'zij inside Gimorak's Den, southeast of the Grom'arsh Crash Site.", completion = "This hurts bad, mon.  Don't know if I'm gonna make it." }
WordHunterWoW_QuestEN[13055] = { title = "Cave Medicine", description = "It's good to see a friendly face.  Might be the last one I see.\n\nOne of those jormungar stung me with some sort of toxin before I managed to get away.  I can feel my whole body getting numb, mon.\n\nI'm going to need a toxin gland to make an antidote.  I will also need some of the cave mushrooms that grow here... they'll slow the toxin down.\n\nHurry, please.  I don't have much time.  ", objectives = "Tracker Val'zij, at Gimorak's Den, wants you to obtain 1 Jormungar Toxin Gland and 8 Cave Mushrooms.", progress = "You back, mon?", completion = "I thank you, mon.  I might live another day now." }
WordHunterWoW_QuestEN[13056] = { title = "There's Always Time for Revenge", description = "I should manage for now, {name}.  There is one favor I'd like to ask, though.\n\nI would never had fallen to one of these worms, but my wind serpent, Heesha, was killed by the meanest worg I've seen in some time.\n\nDon't worry about me now, I'll feel better when that worg is breathing no more.  You should find him deeper in the cave.", objectives = "Tracker Val'zij wants you to slay Gimorak inside Gimorak's Den.", progress = "You find that dirty mongrel, <name>?", completion = "I'm already feeling much better, mon.  Not sure if it's the antidote or the news of that filthy worg getting what he deserved." }
WordHunterWoW_QuestEN[13057] = { title = "The Terrace of the Makers", description = "It is time, {name}.  I am prepared to face Loken now.\n\nLet us make our way to the Terrace of the Makers and face my brother's forces.  The fool will regret ever crossing me.", objectives = "Find Thorim at the southeastern edge of the Terrace of the Makers, just northwest of Dun Niffelem.", completion = "We're here, <name>.  My brother's forces will learn the meaning of defeat today." }
WordHunterWoW_QuestEN[13058] = { title = "Changing the Wind's Course", description = "At last, we have all that we need to right the wrongs of the North Wind and its followers. You have attuned the Lorehammer to Stormhoof's time and his persona.\n\nTake the hammer again, head to the Temple of Life in the plains to the northwest. Use the hammer to assume the role of Stormhoof. Face the North Wind as Stormhoof, but realize that for the timeline to be restored, Stormhoof must die as the North Wind weakens.\n\nThen, you must find and use the Horn of Elemental Fury to destroy the North Wind.", objectives = "Use the Lorehammer to travel back in time and face the North Wind as Stormhoof. When Stormhoof falls and drops the Horn of Elemental Fury, use it to finish off the North Wind, and then return to Xarantaur at Camp Tunka'lo.", progress = "Have you done it? Is the true timeline restored?", completion = "What you have done today will ensure that Stormhoof and his story will never be forgotten. As well, you have written yourself into the pages of Azeroth's history. I will remember and record your accomplishments for all eternity." }
WordHunterWoW_QuestEN[13059] = { title = "Revenge for the Vargul", description = "I've been praying to The Lady of the Sword for one to come and strike down my enemy. Thane Illskar must pay for what he did to me!\n\nI was the champion of Thane Ufrang the Mighty. During my fight for ascendance in Valhalas, Illskar sabotaged me with dark magic, causing me to lose and be reduced to this.\n\nThe thane and his champions can be found below in The Circle of Suffering. Challenge him on my behalf. Defeat him.\n\nMake him know the suffering that I know!", objectives = "Bethod Feigr in The Underhalls wants you to throw down his sword to challenge Thane Illskar and then kill him in The Circle of Suffering.", completion = "Thank you, <class>... thank you!\n\nYou've given me the satisfaction of knowing that the coward who made me into this will rot for all eternity as surely as I will.\n\nNow leave before I lose control of myself and cut you down." }
WordHunterWoW_QuestEN[13060] = { title = "When All Else Fails", description = "So...  so I don't think we're going to be getting a good foothold in those mountains.\n\nTrust me, I'm not one to give up easily... but between freezing engines, nasty vrykul women, territorial dragon want-to-bes and the half a dozen other nasties settled in the area, this just ain't happening.\n\nDon't let that dissuade you though! Just because we can't get a foothold doesn't mean we won't get you there... one-way trips are pretty simple when you get down to it.\n\n<Ricket nods at some nearby rockets.>", objectives = "Speak to Ricket to make use of Ricket's D16 Propelled Delivery Device to enter further into Storm Peaks.", completion = "<Olut winces.>\n\nThat looked painful. It was a pretty grand entrance though.\n\nAre you here to help us find a path into Icecrown? As you can see, our first foray in that direction didn't end too admirably. I'm thinking we might be better off breaching the place from another side." }
WordHunterWoW_QuestEN[13061] = { title = "Prepare for Glory", description = "This is it then.  I'll take care of your bear now, you won't be needing her.  The great Drakkensryd will be your next challenge.\n\nSay goodbye to your friends and leave your affairs in order, for you will return victorious... or you won't return at all.", objectives = "Speak to Lok'lira the Crone in Brunnhildar Village.", completion = "You've really made it this far.  Never would I have thought you'd progress so quickly among the hyldnir." }
WordHunterWoW_QuestEN[13062] = { title = "Lok'lira's Parting Gift", description = "You've been a great ally, {name}.  Now comes your true test.  You will need skill, courage and a little luck.\n\n<Lok'lira attaches a thin strand of hair to yours.>\n\nYou cannot fail now sister.  Speak to Gretta the Arbiter.  She'll see you on your way.", objectives = "Speak to Gretta the Arbiter in Brunnhildar Village.", completion = "Are you ready to ride, sister?  There is no coming back." }
WordHunterWoW_QuestEN[13063] = { title = "Deemed Worthy", description = "You have succeeded where many have failed, sister. Whether it be by strength and courage or mere luck remains to be seen.\n\nGo back to the village and seek out Astrid Bjornrittar. Tell her of your accomplishments. But be warned. She is not easily impressed.", objectives = "Brijana wants you to go to Brunnhildar Village and speak with Astrid Bjornrittar.", completion = "So, sister, you think that completing a few simple chores makes you a heroine?\n\nYou shall learn...." }
WordHunterWoW_QuestEN[13064] = { title = "Sibling Rivalry", description = "Sif? Is it truly you?\n\nNo? A {race}? But for a moment....\n\nEnough of this! The visions of my Sif have tormented me for far too long. It is time for me to avenge her, and to bring honor to her memory.\n\nMy brother must pay!", objectives = "Thorim wants you to listen to his story.", progress = "Hear my words, <race>.", completion = "You now know a bit of the history of this land... my land.\n\nI call upon you to assist me in setting these wrongs to right." }
WordHunterWoW_QuestEN[13065] = { title = "Ohanzee the Elder", description = "", objectives = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, <name>, and offer you this token..." }
WordHunterWoW_QuestEN[13066] = { title = "Yurauk the Elder", description = "", objectives = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, <name>, and offer you this token..." }
WordHunterWoW_QuestEN[13067] = { title = "Chogan'gada the Elder", description = "", objectives = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, <name>, and offer you this token..." }
WordHunterWoW_QuestEN[13068] = { title = "A Tale of Valor", description = "Perhaps you've heard the praises for our missing hero?\n\nCrusader Bridenbrad was in the Broken Front aiding the attack against the Scourge when the undead army came down upon them. The many men of that allied force scattered, but Bridenbrad alone returned and dragged more than a dozen men to safety, one by one through the carnage.\n\n{class}, he has not returned since. He was spotted heading to the far northeast, towards the Silent Vigil. Bring him back to me that I might honor him for his valor.", objectives = "Highlord Tirion Fordring at Crusaders' Pinnacle has requested that you locate the hero, Crusader Bridenbrad at the Silent Vigil, in northeast Icecrown. His fire pit will likely be the most obvious indication of his location from the air.", completion = "Back! Careful! The plague has gripped me and I'll not see it spread to you nor anyone else." }
WordHunterWoW_QuestEN[13069] = { title = "Shoot 'Em Up", description = "Jotunheim has aerial defenses, both in terms of proto-drake riders and harpoon guns. They've concentrated these on their northern and western facings where they are most vulnerable.\n\nLet's use their defenses against them!\n\n<The Leaper pierces you with his single eye and cackles maniacally.>\n\nTake control of a harpoon gun on the platforms that overhang the cliffs on either side of Valhalas to the southwest. Take out the proto-drakes and their riders. Shoot 'em up!", objectives = "The Leaper at The Shadow Vault wants you to use a Jotunheim Rapid-Fire Harpoon to shoot down 15 Jotunheim Proto-Drakes and their riders.", completion = "You are a true champion for the cause, <name>!\n\nWon't you please come speak to me again tomorrow? I'm certain that there will be more of those nasty proto-drakes to shoot down." }
WordHunterWoW_QuestEN[13070] = { title = "A Cold Front Approaches", description = "The chill of death stirs in the west, threatening to freeze our hearts and souls to this wasteland and bind us to its dark master. We will stand and we will fight!\n\nThe preparations have begun. Report to Siegemaster Fezzik at the front gate for your assignment.", objectives = "Report to Siegemaster Fezzik at the Argent Vanguard in Icecrown.", completion = "We must be quick or face being overtaken by the Scourge! There's really no time for instructions, <race>. You're just going to have to jump in and hope for the best." }
WordHunterWoW_QuestEN[13071] = { title = "Vile Like Fire!", description = "Vile like fire! Vile like proto-drakes!\n\n<The abomination claps its hands excitedly.>\n\nLittle {name} go to Jotunheim and steal a pretty proto-drake in Njorndar Village. Make proto-drake make pretty fires on Jotunheim buildings!", objectives = "Vile at The Shadow Vault wants you to steal a Njorndar Proto-Drake and use it to set fire to 8 vrykul buildings in the greater Jotunheim region.\n\nBalargarde Fortress, due to its nature, cannot be set ablaze.", progress = "What? Vile not see lots of fire!!!\n\n<name> go back and make more fire!", completion = "Yay, yay! <name> is best proto-drake stealer.\n\nYou come back tomorrow and we make more fire!!!" }
WordHunterWoW_QuestEN[13072] = { title = "A Hero Remains", description = "I know why you've come... they've sent you to bring me back, but that cannot happen. I carry the plague of undeath, {class}, and I'll not share my fate with those near me. No, I shall stay here.\n\nMy only regret lies in what I may become when death grips me. I do not fear death itself, but I loathe to consider serving the traitor, Arthas.\n\nLeave me... and see to it that no one else comes looking. You would do me a great disservice if you were to expose anyone to the plague that I carry.", objectives = "Bring news of Crusader Bridenbrad's fate to Highlord Tirion Fordring at Crusaders' Pinnacle.", completion = "Bridenbrad has contracted the plague? I cannot imagine a worse fate for one who has devoted his life to the ways of light, nor can I fathom leaving him to die without lifting a finger to help.\n\nNo, undeath shall not be his fate. We shall find a way to aid this hero." }
WordHunterWoW_QuestEN[13073] = { title = "The Keeper's Favor", description = "There are those of this world that tap into power unrestricted by the bounds of our mortal frames - powers of restoration, powers of life, and powers of light.  And Bridenbrad, this is no ordinary man... his valor and devotion shine through. We can only hope that one of these beings will intervene and bring this hero back from a fate worse than death.\n\nGo now and speak to Arch Druid Lilliandra in the Argent Vanguard... request passage to Moonglade and seek the aid of Keeper Remulos.", objectives = "Highlord Tirion Fordring at Crusaders' Pinnacle has requested that you secure passage from Arch Druid Lilliandra and speak to Keeper Remulos in Moonglade.", completion = "Hello child.\n\nI understand Tirion's request and trust in his judgment, we will see what we can do for this Crusader Bridenbrad. What you ask is no simple task - the Scourge are not of this world, and many have failed in attempting to strip their corruption over the years.\n\nIn a being of nobility and light, all is not without hope." }
WordHunterWoW_QuestEN[13074] = { title = "Hope Within the Emerald Nightmare", description = "What we need exists only in the emerald dream... acorns that are infused with a powerful restorative magic. Many places in this sacred glade are closely tied with the dream, and my shrine is among them.\n\nI will send you into the dream to recover some of these acorns. Be prepared though {class}, for this method of entering the dream is dangerous, and it is very likely you will be beset by nightmares.\n\nRecover a few acorns quickly, and then depart from my shrine or pinch yourself to return to our world.", objectives = "Keeper Remulos at Moonglade has instructed you to enter the emerald dream and recover 3 Emerald Acorns.\n\nLeave the vicinity of the Shrine of Remulos to return to Azeroth.", progress = "It is good to see that you are safe. Have you recovered the acorns?", completion = "Excellent work, young one." }
WordHunterWoW_QuestEN[13075] = { title = "The Boon of Remulos", description = "I shall open a portal to take you back to the druid that brought you here. You and your crusader have my well wishes. I hope that this acorn is able to purify your crusader and save him from the wretched fate of the plague.\n\nFarewell, {race}.", objectives = "Return to Crusader Bridenbrad at the Silent Vigil in Icecrown with the Emerald Acorn.", progress = "Well met, <class>. I knew that you would return, despite my warnings, but I'm pleased that you heeded my desire to not risk anyone else.\n\nWhy have you come back to me?", completion = "Tirion sent you to Remulos? I'm... I'm flattered. One does not call favors in with beings of such power idly, no matter how noble or altruistic they might be. You too are kind to have gone to such lengths on my behalf. You have my thanks.\n\nPlant the seed - I am ready." }
WordHunterWoW_QuestEN[13076] = { title = "Time Yet Remains", description = "I feel refreshed... renewed... but the plague still grips me. Not to worry, I am still eternally grateful that you went to such lengths for me, a complete stranger. If nothing else, you've bought me a few more precious hours not plaguing the world as a hideous undead.\n\nThank you, {class}. Please extend my thanks to Tirion as well, and let him know that it has been an honor to serve beside him.", objectives = "Return to Highlord Tirion Fordring at Crusaders' Pinnacle with news of Emerald Acorn's effects.", completion = "It saddens me to hear that it did not work. No reason to fret though, I have met other beings of good that may still be of aid to us." }
WordHunterWoW_QuestEN[13077] = { title = "The Touch of an Aspect", description = "The dragon-queen, Alexstrasza, possesses magics over all life. In the past, she has used great fire to incinerate undead and rebirth fresh new life in their place. Perhaps her powers might be able to save our Bridenbrad as well.\n\nAlexstrasza makes her home at Wyrmrest Temple in Dragonblight - please go to her and humbly request her aid on my behalf.", objectives = "Request the aid of Alexstrasza the Life-Binder at Wyrmrest Temple.", completion = "Greetings to you, <race>.\n\nThe concern is clear on your face. Please tell me what troubles you." }
WordHunterWoW_QuestEN[13078] = { title = "Dahlia's Tears", description = "In this dark time, I'll not be the one to abandon a champion of the Light.\n\nWe will need something sacred for this to have a hope of saving your Bridenbrad... a remnant of a devout being that fell victim to this very same plague.\n\nGo now to the sacred soil of the passages outside my Ruby Dragonshrine where the battle is joined. As my Ruby Keepers fly down and set flame to the ground beneath undead feet, you will witness new life grow forth. Among that life are Dahlia's Tears - bring them to me.", objectives = "Alexstrasza the Life-Binder at Wyrmrest Temple has requested that you recover Dahlia's Tears from soil freshly cleansed by a Ruby Keeper's flames.", progress = "Ah, dear Dahlia. I do miss you so.", completion = "With Dahlia's Tears and ancient magic, I fashion you some small amount of hope for your great crusader." }
WordHunterWoW_QuestEN[13079] = { title = "The Boon of Alexstrasza", description = "You must understand, young {race}, that cleansing the body in favor of life anew is something well within my grasp... removing the plague of undeath without affecting the body, however, is beyond the scope of the powers that I control.\n\nIf this Bridenbrad is the beacon of light that you profess him to be, perhaps he will endure such a cleansing and thrive, but I cannot state with confidence that this is the salvation that you seek. Take it and go with all of my blessings.", objectives = "Bring the Breath of Alexstrasza to Crusader Bridenbrad at the Silent Vigil in Icecrown.", progress = "You have returned yet again, <class>. Why do you risk yourself so?", completion = "The breath of Alexstrasza... you have gone to the dragon-queen herself? I'm extremely grateful.\n\nI understand the risks of such cleansing and I am prepared. Proceed, <class>." }
WordHunterWoW_QuestEN[13080] = { title = "Hope Yet Remains", description = "<Bridenbrad raises a hand to you as he catches his breath.>\n\nIt was nearly as painful as it looked, but it was as if I could feel some of the corruption being burnt away from within my body. It seems the plague is not so readily bested though.\n\n{class}, thank you for everything that you have done. Your selfless actions have renewed my hope that there is yet great good left within this world - I can depart without fear that darkness will prevail in my absence.\n\nGo now, go with no regrets.", objectives = "Return to Highlord Tirion Fordring at Crusaders' Pinnacle with news of the effects of the Breath of Alexstrasza.", completion = "The Scourge plague is no simple foe to defeat. Alexstrasza's words suggest that perhaps we can yet save our Bridenbrad from the unimaginable fate of the unliving should he fall, but I will not give him up so easily.\n\nThere is yet one more path of light I would like to pursue. One more being who might avert this horrible fate." }
WordHunterWoW_QuestEN[13081] = { title = "The Will of the Naaru", description = "I appreciate everything that you have done for us, {name}. I have one last errand for you... one last gleaming hope for a paladin who deserves any salvation that we can extend.\n\nGo now to Shattrath and speak to the naaru, A'dal. He has long been a beacon of light and powerful ally to devout paladins. Impart Bridenbrad's story and seek any aid that he might have to offer.\n\nI cannot impress how important it is that you move quickly - I fear our crusader does not have much more time in this world.", objectives = "Request the aid of A'dal at Shattrath City in Terokkar Forest.", completion = "<A gentle ringing fills your head as you approach the naaru.>\n\nI know why you have come." }
WordHunterWoW_QuestEN[13082] = { title = "The Boon of A'dal", description = "I am pleased that you have come to me, {name}. I know of Crusader Bridenbrad, and of your travels in hope of saving him. Bridenbrad's valor has sparked remarkable selflessness in you, and this is a miracle unto itself.\n\nThe Light will take care of its own. I will extend my blessing to Bridenbrad and he shall not endure the corruption of undeath. I shall return you to Dalaran, and you shall return to him. Know that I remain with you.", objectives = "Return to Crusader Bridenbrad at the Silent Vigil in Icecrown.", completion = "<As you approach Crusader Bridenbrad, you cannot help but notice that his skin has taken on a pale hue and his breaths are shallow. It is clear that he has little time left.>\n\nYou have returned to me, <class>. I must admit... it is good to see you again... your face renews my hope that this land will be free of Arthas's grasp one day soon. I'm proud to have met you..." }
WordHunterWoW_QuestEN[13083] = { title = "Light Within the Darkness", description = "<Crusader Bridenbrad's tabard rests in the bottom of the chest, shifting slightly as the howling wind finds its way in.>\n\nTirion will desire this last remnant of the great crusader.", objectives = "Bring Crusader Bridenbrad's Tabard to Highlord Tirion Fordring at Crusaders' Pinnacle.", progress = "He has departed, hasn't he? I felt a small bit of light leave the land.", completion = "I am glad you were able to save him from undeath. With A'dal's blessing, he will know no evil in his afterlife.\n\nWe shall take heart in his shining example and in your selflessness. Thank you for all that you have done." }
WordHunterWoW_QuestEN[13084] = { title = "Vandalizing Jotunheim", description = "Let us see if we can further weaken the resolve of the vrykul, {name}.\n\nEach day I wish you to travel to Jotunheim and put their banners to the torch. It may seem a trivial thing, but to see their ancestral home vandalized on a daily basis will demoralize them more than any physical punishment you can inflict.\n\nAt least... it can't hurt.", objectives = "Duke Lankral at The Shadow Vault wants you to burn 10 Vrykul Banners.", completion = "<The duke looks at you a moment and nods.>\n\nYou're inflicting horrible mental trauma on the Jotunheim vrykul. This is where they were first reawakened. It is a place of significant importance to them, second only to Ymirheim.\n\nYou must keep up the pressure there while I hold the vault from the assault of the Lich King." }
WordHunterWoW_QuestEN[13085] = { title = "Vaelen Has Returned", description = "I just saw that incompetent fool, Vaelen the Flayed, sneak into the vault building.\n\nGo see to it that he rectifies his mistake and returns my death knights to me!", objectives = "Speak with Vaelen the Flayed at The Shadow Vault.", completion = "I think I can guess why you're here, <name>." }
WordHunterWoW_QuestEN[13086] = { title = "The Last Line Of Defense", description = "I've triggered the base's defenses, {class}! Atop each of the Vanguard's four towers is a retractable Argent Crusade cannon, blessed by Father Gustav himself. You'll need to fly up to one of those towers and man a cannon. Use it to destroy the Scourge onslaught that the Lich King has deployed.\n\nJust one warning, the Scourge will undoubtedly send their frost wyrms to lay siege to the towers. Shoot them out of the sky! If they destroy the walls and towers of this base, we're done for!", objectives = "Use an Argent Cannon to destroy 100 Scourge attackers. You must also kill 3 Frostbrood Destroyers.\n\nReturn to Siegemaster Fezzik should you succeed.", progress = "The screams of the dying will haunt me forever! Help them!", completion = "You handled the cannon like a goblin gunner, friend. You've saved the Vanguard and the Argent Crusade - all the while backing the Highlord himself up on the field of battle! Amazing!" }
WordHunterWoW_QuestEN[13087] = { title = "Northern Cooking", description = "So what are ya doin' if you dinna have any stew for me.   I got me a HUNGER!   At least bring me some chilled meat so I kin cook me own stew!   If ya do, I kin give ya the recipe so you kin make it for yourself.   NOW GO GET ME SOME MEAT!", objectives = "Bring four chilled meat to Brom Brewbaster at Valgarde.  chilled meat can be found on any Northrend beast.", progress = "WHERE IS MY MEAT!", completion = "Ya gots me meat!   Here is your recipe, I gots cookin to do!" }
WordHunterWoW_QuestEN[13088] = { title = "Northern Cooking", description = "We got a lot of new recruits here and these lads are hungry!  If you could go out and get me some chilled meat for stew, I could teach you how to make it for yourself.", objectives = "Bring four chilled meat to Rollick Mackreel at Valiance Keep.  chilled meat can be found on any Northrend beast.", progress = "The lads need meat for their stew.", completion = "That will keep our recruits fed!   Here's how you cook it." }
WordHunterWoW_QuestEN[13089] = { title = "Northern Cooking", description = "Nothing like a stew made from the living to warm your bones.   Bring me some of the chilled meat that can be found on the wretched beasts of this place, and I shall teach you to make a warm stew.", objectives = "Bring four chilled meat to Thomas Kolichio at Vengeance Landing.  chilled meat can be found on any Northrend beast.", progress = "The stew awaits...", completion = "We can quickly turn this flesh into stew." }
WordHunterWoW_QuestEN[13090] = { title = "Northern Cooking", description = "The warriors of the Warsong Offensive need food in their bellies to keep their strength up.   If you could bring some chilled meats from the Rhinos or other beasts, I could make them some stew.   I would be willing to teach you the recipe if you were willing.", objectives = "Bring four chilled meat to Orn Tenderhoof at Warsong Hold.  chilled meat can be found on any Northrend beast.", progress = "When the meat is present, the stew will be prepared.", completion = "I give my thanks to you." }
WordHunterWoW_QuestEN[13091] = { title = "The Art of Being a Water Terror", description = "The water lock outside my cave is teeming with elementals that the vrykul magi have yet to tame. I am going to teach you a trick for possessing these creatures for a short time, and you will use them to wreak havoc upon Jotunheim!\n\n<The banshee-infested vrykul draws magic in the air and touches a large finger to your forehead.>\n\nGo now and open the gate to the lock. A water terror will rush out and you will possess it to destroy our enemies!", objectives = "The Bone Witch in Njorndar Village wants you to possess a Water Terror and use it to slay 10 vrykul in the greater Jotunheim region.\n\nQualifying vrykul are Jotunheim Sleep-Watchers, Jotunheim Warriors, Mjordin Water Magi, Njorndar Spear-Sisters, and Valhalas Vargul.", progress = "My reading of the bones tells me that you're not quite done.", completion = "I have never seen such terror in the eyes of a vrykul. They think themselves masters of their world.\n\nYou and I are going to prove them wrong. Very wrong." }
WordHunterWoW_QuestEN[13092] = { title = "Reading the Bones", description = "One of the benefits of possessing this creature is that I have access to all of her powers. As a bone witch and rune reader, she has the power to throw the bones and determine one's fate.\n\n<The Bone Witch smirks.>\n\nLucky for you and I that I have it within my power to influence those readings.\n\nBring me the bones of the vrykul that you kill here in Jotunheim and I will toss them to allow you to determine your own fate.", objectives = "The Bone Witch in Njorndar Village has instructed you to collect 15 Vrykul Bones.", progress = "I find it remarkable that these beings ever held sway over the world when they utilized such primitive magic.", completion = "And now we shall see what the future holds for you.\n\n<The Bone Witch casts the bones upon the rug in front of her.>\n\nChoose your fate, <class>." }
WordHunterWoW_QuestEN[13093] = { title = "Reading the Bones", description = "", objectives = "Bring me more vrykul bones and we will influence the fates in your favor.", progress = "Bring me more vrykul bones and we will influence the fates in your favor.", completion = "Choose your fate, <name>." }
WordHunterWoW_QuestEN[13094] = { title = "Have They No Shame?", description = "Archmage Berinand loaned me his research on the Arcanomicron, some sort of map that Malygos is trying to assemble.\n\nI made the mistake of discussing it with a group of Horde adventurers and now it's gone!\n\nIt must have been them. Please, recover the book.", objectives = "Image of Warmage Kaitlyn wants you to recover Berinand's Research.", progress = "Please, <name>, tell me you've found the book...", completion = "You found it!? Yes, yes, it's all here.\n\nPlease, take this with my gratitude." }
WordHunterWoW_QuestEN[13095] = { title = "Have They No Shame?", description = "Archmage Berinand loaned me his research on the Arcanomicron, some sort of map that Malygos is trying to assemble.\n\nI made the mistake of discussing it with a group of Alliance adventurers and now it's gone!\n\nIt must have been them. Please, recover the book.", objectives = "Image of Warmage Kaitlyn wants you to recover Berinand's Research.", progress = "Please, <name>, tell me you've found the book...", completion = "You found it!? Yes, yes, it's all here.\n\nPlease, take this with my gratitude." }
WordHunterWoW_QuestEN[13096] = { title = "Gal'darah Must Pay", description = "Did ya see it, mon?\n\nIt musta been da most awful thing I ever seen. Da great Akali - slain right before my eyes. Horrible...\n\nI done took an oath not ta be gettin' involved here. My job be to observe only. But dis cannot stand! Gal'darah must pay!\n\nGo into Gundrak and seek him out. Come back to me when Akali's death been avenged, mon.", objectives = "Tol'mar at Dubra'Jin wants you to slay Gal'darah in Gundrak.", completion = "Ya done it?! Gal'darah be no more?\n\nHere ya go, mon. Take dis gift for bringin' justice to that wretch." }
WordHunterWoW_QuestEN[13097] = { title = "Unfinished Business", description = "While it is true that the Prophet of Akali will trouble this world no more, there yet remains work to be done.\n\nThe greater part of Akali's blood has empowered another, and it is in him that the true danger lies.\n\nQuickly, <name>, make your way north of Gundrak to Dubra'Jin and speak with Tol'mar. He will be able to direct you further in this cause.", objectives = "Har'koa wants you to speak with Tol'mar at Dubra'jin.", completion = "Lissen up, mon. Dere be dangerous work ta be done!" }
WordHunterWoW_QuestEN[13098] = { title = "For Posterity", description = "Gundrak be doomed, mon.\n\nHistory be repeatin' itself before our eyes. When trolls be turnin' on their own gods, the end be certain. It just be a matter of time.\n\nPerhaps if we can record the events clearly, we might prevent future generations from traveling down da same path.\n\nIf you be havin' the courage, enter Gundrak and search for clues to what brought the Drakkari Empire to such an end as dis.", objectives = "Chronicler Bah'Kini at Dubra'Jin wants you to enter Gundrak and collect 6 Drakkari History Tablets.", progress = "You find da Drakkari history tablets, mon?", completion = "<Bah'Kini scans the engraved tablets for a moment, then turns her attention back to you.>\n\nDese be authentic, <race>. I'll be placin' dem in their proper place in my collection.\n\nPerhaps we can finally be puttin' an end to dis behavior." }
WordHunterWoW_QuestEN[13099] = { title = "Just Checkin'", description = "There have been fearsome sounds echoing from Gundrak. They have been increasing in volume and frequency of late.\n\nMy long-time student is currently recording events from her post just west of Gundrak. Perhaps you could find the time to check in on her for me?", objectives = "To'kini wants you to speak to Bah'kini at Dubra'Jin.", completion = "Long-time student? Hah!\n\nIf by long-time ya mean my whole life, den I suppose dat be accurate.\n\nTo'kini be my cowardly father - too fearful to take up a position so near Gundrak... so he sent me!" }
WordHunterWoW_QuestEN[13100] = { title = "Infused Mushroom Meatloaf", description = "We have an important order that needs to go out!  Orton Bennet in Curiosities & Moore needs a mushroom meatloaf.\n\nGet some infused mushrooms found in the Dalaran sewers, chilled meat, and cook them in this meatloaf pan.  When you're done, deliver the cooked meatloaf to Orton.", objectives = "Use your Meatloaf Pan to cook 4 Infused Mushrooms and 2 Chilled Meats and bring the finished Mushroom Meatloaf to Orton Bennet in Curiosities & Moore, located in Runeweaver Square in Dalaran.", progress = "Do you have any food for me?\n\nI never seem to be able to get away from the shop, even for a minute.", completion = "This looks great!  Thanks!" }
WordHunterWoW_QuestEN[13101] = { title = "Convention at the Legerdemain", description = "Arille Azuregaze at the Legerdemain Lounge has a convention coming in and needs a feast pronto!\n\nYou need to provide some Northern Stew and a Jug of Wine from the cheese shop \"One More Glass\" in central Dalaran.  The owner of the cheese shop owes me the wine and you should find it somewhere around the shop.\n\nBring the wine and stews to Arille.", objectives = "Bring 4 Northern Stew that you use your cooking skill to make and a Jug of Wine from the cheese shop in Dalaran to Arille Azuregaze at the Legerdemain Lounge found in Runeweaver Square in Dalaran.", progress = "Where is my food, I will have conventioneers here any minute!", completion = "This is plenty of food for everyone!  I am sure the customers will be pleased." }
WordHunterWoW_QuestEN[13102] = { title = "Sewer Stew", description = "Ajay Green the innkeeper in the Dalaran sewers needs a vegetable stew for his customers as they are running low on food down there.\n\nCollect 4 Crystalsong Carrots from the Crystalsong Forest and cook them together with 4 Chilled Meat.\n\n You can get to the Crystalsong Forest from the portal chamber in the eastern corner of Runeweaver Square.\n\nOnce the vegetable stew is ready, bring it to Ajay.", objectives = "Cook 4 Crystalsong Carrots from Crystalsong Forest with 4 Chilled Meat in the Cookpot.\n\nOnce it is ready bring the Vegetable Stew to the Dalaran sewers Innkeeper Ajay Green.", progress = "I've got hungry people down here!  We need some stew.", completion = "This will be consumed in no time!   Thanks!" }
WordHunterWoW_QuestEN[13103] = { title = "Cheese for Glowergold", description = "Ranid Glowergold in the Leatherworkers shop in Dalaran has had a sudden craving for wine and cheese.\n\nCollect cheese which is on the shelf at \"One More Glass\" in central Dalaran and half full wine glasses found on tables all over the city.  Pour the wine together into a bottle and serve it with the cheese to Ranid.\n\nWe don't think he will know the difference.", objectives = "Combine the Empty Cheese Platter with Aged Dalaran Limburger from the cheese shop \"One More Glass\" and with 6 Half Full Dalaran Wine Glasses found on tables around Dalaran.\n\nBring the Wine and Cheese platter to Ranid Glowergold at the Leatherworkers in the Magus Commerce Exchange.", progress = "Have you seen a servant with my wine and cheese platter.   I am quite peckish!", completion = "Aha, this appears to be a fine vintage!" }
WordHunterWoW_QuestEN[13104] = { title = "Once More Unto The Breach, Hero", description = "The Vanguard is secure, ally. We have reclaimed the Valley of Echoes and taken down the web walls blocking entry to the Breach. Now is the time to strike at Scourgeholme and establish our presence inside Icecrown. The battlefront moves on!\n\nI have asked the Ebon Watcher for his assistance with our assault upon Scourgeholme. His intimate knowledge of the Scourge will be invaluable in our effort.\n\nGo now and report to him at the tent outside of the Breach, northwest of here.", objectives = "Report to the Ebon Watcher in the Valley of Echoes just outside the Breach.", completion = "My knowledge of Scourge tactics is without equal.\n\n<The Ebon Watcher peers at you.>\n\nBefore the battle for Light's Hope Chapel, my knights and I served under the Lich King - his icy grasp controlling our every action. The light of dawn changed everything..." }
WordHunterWoW_QuestEN[13105] = { title = "Once More Unto The Breach, Hero", description = "The Vanguard is secure, ally. We have reclaimed the Valley of Echoes and taken down the web walls blocking entry to the Breach. Now is the time to strike at Scourgeholme and establish our presence inside Icecrown. The battlefront moves on!\n\nI have asked the Ebon Watcher for his assistance with our assault upon Scourgeholme. His intimate knowledge of the Scourge will be invaluable in our effort.\n\nGo now and report to him at the tent outside of the Breach, northwest of here.", objectives = "Report to the Ebon Watcher in the Valley of Echoes just outside the Breach.", completion = "Your power has grown, my faithful knight.\n\n<Highlord Darion Mograine peers at you.>\n\nVengeance is at hand, brother. Koltira aids the Horde upon the gunship, Orgrim's Hammer, while Thassarian assists the Alliance aboard the Skybreaker. The Ebon Blade will soon wash over Icecrown and leave the armies of the Lich King in ruin." }
WordHunterWoW_QuestEN[13106] = { title = "Blackwatch", description = "The Scourge has a large facility called the Fleshwerks, dedicated to producing abominations and flesh giants. If we can shut it down, we can deprive the Lich King of a large component of his armies.\n\nI've sent Darkrider Arly to the area. She has a small base, Blackwatch, on a ridge overlooking the Fleshwerks and to the west of Corp'rethar. I'm told the Argent Crusade is sending someone to coordinate their efforts there, but the darkrider will know what to do. Find and assist her.", objectives = "Speak to Darkrider Arly at Blackwatch in Icecrown.", completion = "Good. We'll need all the help we can get. Olakin here is the Argent Crusade's contribution to our effort. Let's cut the chatter and get down to the business of denying the Scourge their armies of the flesh." }
WordHunterWoW_QuestEN[13107] = { title = "Mustard Dogs!", description = "Archmage Pentarus likes to watch the occasional game of battle ball and is preparing to go, but needs food for the trip.\n\nYou need to fill his picnic basket with 4 rhino dogs that you cook and then 4 wild mustard that are found in grassy areas of the city.\n\nBring him his picnic basket so he can be ready to go see the big game.", objectives = "Fill the Empty Picnic Basket with 4 Rhino Dogs that you cook with your cooking skill and 4 Wild Mustard that you find in the grassy areas of Dalaran.\n\nBring the Picnic Basket to Archmage Pentarus at Krasus' Landing in Dalaran.", progress = "I am almost ready to go, I just need the food and for my mates... er... my fellow mages to arrive.", completion = "Perfect!  I just hope the Dalaran Destroyers finally win one!" }
WordHunterWoW_QuestEN[13108] = { title = "Whatever it Takes!", description = "One way or another, Loken shall fall.\n\nIf I have to rip him limb from limb myself, he soon shall pay for his wretched deeds.\n\nShould you meet with him before I do, the honor and glory of his defeat shall be yours.\n\nReturn to me with his lying tongue, and earn my blessing and gratitude.", objectives = "King Jokkum in Dun Niffelem wants you to enter the Halls of Lightning and defeat Loken. You are then to return to King Jokkum with Loken's Tongue.", progress = "Has justice been brought to Loken?", completion = "That vile worm is dead?\n\nYou have turned out to be a great boon to my people, little <race>.\n\nPlease accept this gift in return for your loyal friendship." }
WordHunterWoW_QuestEN[13109] = { title = "Diametrically Opposed", description = "I shall speak plainly to you, little <race>. My people have not been the same since our ties with Thorim were severed.\n\nAs their leader, I wish nothing more than for their hearts to be mended and our friendship with the Stormlord to be renewed. In your defeat of Fjorn, a step has been taken down that path. I would have you bring us a step further...\n\nIn the Halls of Lightning, one even greater than Fjorn sits in opposition to our existence. Volkhan will not rest until either he, or we, are no more.", objectives = "King Jokkum at Dun Niffelem wants you to enter the Halls of Lightning and defeat Volkhan.", completion = "Volkhan shall haunt the dreams of my people no more.\n\nContinue your efforts, little <race>. In time, I am certain my people will grow to forgive Thorim." }
WordHunterWoW_QuestEN[13110] = { title = "The Restless Dead", description = "Not all of our soldiers made it out of Scourgeholme. Many were slain and turned into twisted reflections of their former selves. Such is the way of the Scourge. For those damned souls, there is no eternal peace. We must provide their souls rest.\n\nTravel through the Breach into Scourgeholme and slay the skeletal reanimated crusaders. Sprinkle this holy water on their bones so that their spirits may be freed.", objectives = "Father Gustav at the Valley of Echoes in Icecrown wants you to use Holy Water on the corpses of Reanimated Crusaders to free 10 restless souls.", progress = "It is a grim task, <name>, but it must be done.", completion = "The path of the righteous crusader is one beset by inequity and evil. To cut through the middle is the only salvation. You have done that on this day and much more." }
WordHunterWoW_QuestEN[13111] = { title = "One of a Kind", description = "Lissen, mon.\n\nAt first glance, it be lookin' like da same old story here - trolls tappin' into forbidden powah by destroyin' da very beings dey should be worshippin'.\n\nWhile dis be true, dere be somethin' special about dese Drakkari. If what I learned be true, den inside Gundrak dere be a special golem - one like nuthin' created before!\n\nYa want adventure, mon? Go inside Gundrak and bring me back a piece from dat golem ta study.", objectives = "Chronicler Bah'Kini at Dubra'Jin wants you to enter Gundrak and recover a piece of the Drakkari Colossus.", progress = "You get me a piece of dat golem, mon?", completion = "Ahh, yeah mon! Dat be what I'm lookin' for.\n\nHere ya go - take somethin' nice for your troubles." }
WordHunterWoW_QuestEN[13112] = { title = "Infused Mushroom Meatloaf", description = "Orton Bennet in Curiosities & Moore be needin' a mushroom meatloaf.\n\nGet ya some infused mushrooms found in the Dalaran sewers, chilled meat, and cook 'em in the meatloaf pan.  When ye be done, bring that meatloaf to Orton.\n\nIf only de council would let me serve me gnome specialty, I would show dem a real treat!", objectives = "Use your Meatloaf Pan to cook 4 Infused Mushrooms and 2 Chilled Meats and bring the finished Mushroom Meatloaf to Orton Bennet in Curiosities & Moore, located in Runeweaver Square in Dalaran.", progress = "Do you have something for me?  I so rarely get away from my shop.", completion = "Is this food from Awilo?  Can you promise me there isn't any gnome in it?" }
WordHunterWoW_QuestEN[13113] = { title = "Convention at the Legerdemain", description = "Can you believe da horde has outlawed cannibalism...it just ain't right I tell ya!  I guess I should keep me mind on me work when we gots an order to fill.\n\nArille Azuregaze at the Legerdemain Lounge has many a guest a'comin to his place, mon.  You gots to be providin' some Northern Stew and a Jug of Wine from the cheese shop in central Dalaran.\n\nBring the wine and stew to Arille.", objectives = "Bring 4 Northern Stews and a Jug of Wine from the cheese shop in Dalaran to Arille Azuregaze at the Legerdemain Lounge found in Runeweaver Square in Dalaran.", progress = "Where is my food?  My guests will be here soon!", completion = "My guests should find this acceptable.  Just don't tell them it came from Awilo." }
WordHunterWoW_QuestEN[13114] = { title = "Sewer Stew", description = "We be havin' another order to fill.  Da innkeeper in da Dalaran sewers needs a vegetable stew as his customers dey don't have so much to eat, mon.\n\nHe asked for a vegetable stew as he didn't appreciate da gnome that was in the last stew I sent.  Get 4 Crystalsong Carrots from the Crystalsong Forest and cook them together with 4 Chilled Meat and bring it to Ajay.\n\nYou can be gettin' to da Forest from da portal chamber in da eastern corner of Runeweaver Square. ", objectives = "Cook 4 Crystalsong Carrots from Crystalsong Forest with 4 Chilled Meat in the Cookpot.\n\nThen bring the Vegetable Stew to the Dalaran sewers Innkeeper Ajay Green.", progress = "Make sure there isn't any gnome in the stew this time!", completion = "Stew looks good.  Thanks for your help." }
WordHunterWoW_QuestEN[13115] = { title = "Cheese for Glowergold", description = "Ranid Glowergold in da Leatherworkers shop be havin' a need for wine and cheese.  Why he don't want some tasty gnome is beyond me.\n\nCollect da cheese from da cheese shop in central Dalaran and da half full wine glasses found on tables around da city.  Bring da wine and serve it with the cheese to Ranid.\n\nYou can call da wine a Wine Medley, mon'.", objectives = "Combine the Empty Cheese Platter with Aged Dalaran Limburger from the cheese shop \"One More Glass\" and with 6 Half Full Dalaran Wine Glasses found on tables around Dalaran.\n\nBring the Wine and Cheese platter to Ranid Glowergold at the Leatherworkers in the Magus Commerce Exchange.", progress = "Have you seen a servant with my wine and cheese platter.  I am quite peckish!", completion = "This wine is quite amazing!  I must know where it's from." }
WordHunterWoW_QuestEN[13116] = { title = "Mustard Dogs!", description = "Da Archmage Pentarus likes to be watchin' his crazy battle ball game, but he be needin' some food for da game.\n\nYou be needin' to fill his picnic basket with 4 cooked rhino dogs and then 4 wild mustard that are found in da grassy corners of de city.\n\nFill up his basket with the mustard dog goodies, mon'.", objectives = "Fill the Empty Picnic Basket with 4 Rhino Dogs that you be cookin' with your skill and 4 Wild Mustard that you find in the grassy areas of Dalaran.\n\nBring the Picnic Basket to Archmage Pentarus at Krasus' Landing in Dalaran.", progress = "Make sure the wild mustard dogs are 100% rhino and have no Gnome in them!", completion = "Perfect!  I just hope the Dalaran Destroyers finally win one!" }
WordHunterWoW_QuestEN[13117] = { title = "Where Are They Coming From?", description = "The Lich King's tireless minions labor away night and day to assemble scores of abominations and flesh giants down there in the Fleshwerks.\n\nYet, that is not enough. More and more skeletal constructors keep appearing to increase the pace of work.\n\nIf we do not discover where they're coming from and how they're able to work so quickly, we'll be overrun before we can act in force. Search to the southeast and see if you can find the source of these skeletons.", objectives = "Investigate a Summoning Altar in the eastern part of the Fleshwerks, then report back to Darkrider Arly at Blackwatch.", completion = "<You tell the darkrider about your discoveries at the summoning altar.>\n\nI suspected such. We can't let this continue. Our first priority is to destroy those summoning altars and then deal with the mess the Scourge has already created here." }
WordHunterWoW_QuestEN[13118] = { title = "The Purging Of Scourgeholme", description = "The Scourge have sent their armies at the Argent Crusade and have been repelled. What they do now is called a 'slash and burn.' All prisoners that they hold at Scourgeholme will be executed and raised as servants of the Lich King.\n\nUndoubtedly the Argent Crusade will request that you give their soldiers a proper farewell. I'll ask no such thing of you. To succeed we must kill Scourge indiscriminately.\n\nVenture to Scourgeholme, northwest through the Breach, and lay waste to all that stand in your way.", objectives = "The Ebon Watcher at the Valley of Echoes in Icecrown wants you to kill 3 Forgotten Depths High Priests, 3 Forgotten Depths Underkings, and 8 Reanimated Crusaders.", completion = "You have done well, <name>. Keeping their numbers down will give the Argent Crusade the time that they need to set a foundation." }
WordHunterWoW_QuestEN[13119] = { title = "Destroying the Altars", description = "So they're summoning in their workers and warriors at those altars?\n\nThey'll need to be the first thing to go. The master summoner should have a staff which allows him to activate the portal. If you kill the master summoner and take the staff, you can use it to overload the summoning portal and destroy its altar.\n\nDo this at all four of the altars and return to me once they've been destroyed.", objectives = "Kill Master Summoner Zarod and use his Summoning Stave to destroy the First, Second, Third, and Fourth Summoning Altars. When you've completed this task, report to Darkrider Arly at Blackwatch.", completion = "<Darkrider Arly nods in approval.>\n\nGood. Now, we can focus our efforts on shutting down the rest of the Fleshwerks." }
WordHunterWoW_QuestEN[13120] = { title = "Death's Gaze", description = "The Fleshwerks is a vast operation, and it will be difficult to keep an eye on all that transpires there. Fortunately, I have a plan.\n\n<Arly produces an orb from the folds of her cloak and shows it to you.>\n\nThis is a death's gaze orb. With it, we can observe the Scourge's actions and decide how best to strike.\n\nPlace these orbs on the stands at three crucial areas -- the abomination lab and the flesh giant lab to the southwest, along with the area surrounding the green cauldron far to the west.", objectives = "Use the Death's Gaze Orb to place orbs on the Abomination Lab Orb Stand, the Flesh Giant Lab Orb Stand, and the Cauldron Area Orb Stand, then return to Darkrider Arly at Blackwatch.", progress = "Have you placed those orbs?", completion = "<Darkrider Arly closes her eyes and seems to focus on something far away.>\n\nWith the eyes of death itself, I watch our enemy. With this knowledge, we will utterly destroy them." }
WordHunterWoW_QuestEN[13121] = { title = "Through the Eye", description = "We must use the Lich King's tools against him if we are to decide our next step.\n\nOver the mountain to the southwest lies Kul'galar Keep. Within it reside the oracles of Jotunheim who receive orders from their master and scry upon others through the Eye of the Lich King.\n\nIt is the eye that you must fight your way to. While it cannot be used to pierce the veil within Icecrown Citadel, you should be able to use it to discern something of value so that we will know how best to proceed.", objectives = "The Bone Witch in Njorndar Village has tasked you with using the Eye of the Lich King to gain information.", progress = "You return with no information at all! Is this how you repay my help to you and the Knights of the Ebon Blade?\n\nBegone and do not return until you have the knowledge which I seek!", completion = "Perfect! It's true that Iskalder is rumored to have been the finest vrykul warrior ever to live. And Vardmadra herself is going to come here to judge him!\n\nWe must move quickly if we are to get to this ancient hero before they do!" }
WordHunterWoW_QuestEN[13122] = { title = "The Scourgestone", description = "A Scourgestone is an item given to all Scourge upon birth or creation. It provides certain benefits to the holder, but more importantly it allows Scourge leaders visibility into the location and movement of all of their units.\n\nWith enough Scourgestones, I might be able to track the movement of other Scourge units across Icecrown.\n\nAs you slaughter Scourge in Scourgeholme, gather all of the Scourgestones that you find. Return to me when your bags are full.", objectives = "The Ebon Watcher at the Valley of Echoes in Icecrown wants you to bring him 15 Scourgestones.", progress = "Scourgestones will help us find our enemy.", completion = "Now let me see if there's something that I can do with these stones to give us a little bit of insight." }
WordHunterWoW_QuestEN[13123] = { title = "WotLK Collector's Edition: - DEM - E - FLAG", description = "", objectives = "" }
WordHunterWoW_QuestEN[13124] = { title = "The Struggle Persists", description = "Malygos and his underlings grow stronger in power with each passing day. And now, our latest assault team has been captured and is being held in the Oculus.\n\nWe must attempt a rescue! Belgaristrasz and his companions are invaluable to our cause.", objectives = "Raelorasz wants you to rescue Belgaristrasz and his companions in the Oculus.", completion = "Listen well, <race>.\n\nYour work here has just begun!" }
WordHunterWoW_QuestEN[13125] = { title = "The Air Stands Still", description = "You must defeat the lords of Scourgeholme if this place is to be free of the Scourge's grasp.\n\nSalranax the Flesh Render lords over the temple on the first tier of Scourgeholme. Nearby Salranax you'll find High Priest Yath'amon preaching at the spirit tower on the second tier. Underking Talonox holds court at the Pit of Fiends, up the high road.\n\nThese are formidable opponents and must be approached with caution. Use this war horn should you require aid. The death knights of Acherus will come.", objectives = "The Ebon Watcher at the Valley of Echoes in Icecrown wants you to kill Salranax the Flesh Render, Underking Talonox and High Priest Yath'amon.", progress = "Finish them, <name>!", completion = "A hard fought victory, <name>! The lieutenants will be replaced, but at least for today the air about Scourgeholme stands still." }
WordHunterWoW_QuestEN[13126] = { title = "A Unified Front", description = "From here, it will take our combined efforts to proceed.\n\nAbove us, Varos hides behind an impenetrable shield. To reach him, you must defeat the Centrifuge Constructs that power his shield.\n\nWe can each provide you with drakes from our respective flights to help you reveal him.", objectives = "Belgaristrasz wants you to destroy 10 Centrifuge Constructs to bring down Varos' shield. You then must defeat Varos Cloudstrider.", completion = "It is as I had hoped, <race>. We work well together.\n\nMay our continued cooperation be enough to overcome the challenges that yet await!" }
WordHunterWoW_QuestEN[13127] = { title = "Mage-Lord Urom", description = "Only one obstacle stands between us and our ultimate goal here. His name is Urom.\n\nHe guards the third ring above us. Beware his powerful conjurings, friend.\n\nBring him down. Make him pay for his treacherous allegiance to the enemy!", objectives = "Belgaristrasz wants you to defeat Mage-Lord Urom in the Oculus.", progress = "Has Mage-Lord Urom been dealt with?", completion = "Victory is in reach, friend.\n\nFocus, for now comes the true test." }
WordHunterWoW_QuestEN[13128] = { title = "A Wing and a Prayer", description = "The time has come to face Eregos.\n\nHe draws strength from the energies he is charged with defending - sipping from the well of the great aspect Malygos.\n\nHowever, defeating the Mage-Lord has allowed us to unlock the full power of our drakes. Use them wisely and Eregos shall surely fall.", objectives = "Belgaristrasz wants you to kill Eregos in the Oculus.", progress = "You've done it, haven't you? You bested Eregos!", completion = "I can already feel their defenses weakening!\n\nNot since the onset of this conflict have we dealt a blow of this magnitude to the Lord of Magic.\n\nDo not forget to visit Eregos' cache. Surely some of his treasures will interest you." }
WordHunterWoW_QuestEN[13129] = { title = "Head Games", description = "<Kurzel rips a long strip of material from her blouse and hands it to you.>\n\nHere, {race}, take this. Dip it in the remains of Novos the Summoner.\n\nWe're going to figure out what makes the Scourge leaders tick.", objectives = "Kurzel wants you to use Kurzel's Blouse Scrap at the corpse of Novos the Summoner, then take the Ichor-Stained Cloth to her inside Drak'Tharon Keep.", progress = "Do you have the cloth?", completion = "Hopefully we can find somebody willing to examine this sample." }
WordHunterWoW_QuestEN[13130] = { title = "The Stone That Started A Revolution", description = "You may look at Scourgeholme now and see a rancid pit of decay, but one day it will be a place of glory and honor. Highlord Fordring has deemed it \"Justice Keep.\"\n\nAlas, even an impregnable fortress like Icecrown Citadel began with but a single stone. So begins our search for the stone to start a revolution.\n\nTravel to Crystalsong, south of here, and seek out the Unbound Thicket in the east. Once there gather crystalline heartwood from the thicket floor and elven masonry from the Ruins of Shandaral.", objectives = "Crusade Architect Silas at the Valley of Echoes in Icecrown wants you to retrieve 10 Trunks of Crystalline Heartwood and 10 pieces of Ancient Elven Masonry.", progress = "Are you lost?", completion = "Heartwood by nature is resistant to disease, rot and plague. This heartwood, however, goes so far as to repel such things! The masonry, affected by the fallout of the Unbound Thicket, will work in much the same way.\n\nSoon we will break ground." }
WordHunterWoW_QuestEN[13131] = { title = "Junk in My Trunk", description = "Just look at it! Me trunk never been so empty.\n\nMe mates jumped at the sight o' all that booty, and now look at 'em! Rattlin' bones, they be!\n\nSay, thar be plenty o' loot farther in, an' not the cursed kind I'll wager.\n\nFetch it fer me an' I'll be rewardin' ya handsomely, matey.\n", objectives = "Brigg in Utgarde Pinnacle wants you to find 5 Untarnished Silver Bars, 3 Shiny Baubles, 2 Golden Goblets, and a Jade Statue.", progress = "How'd yeh fare in thar, matey?", completion = "Brilliant! Ye've gone and done it, matey.\n\nNow I can show me face to the Cap'n without fearin' fer me life, thanks be ta you and yer mates.\n\nHere's a little booty fer you in return." }
WordHunterWoW_QuestEN[13132] = { title = "Vengeance Be Mine!", description = "Only luck spared me from the same fate as me mates.\n\nIn the scurry I got knocked down - was a wee bit tipsy to begin with. Looked up ta see the first of 'em turn.\n\nThere was a big ol' fella watchin' with a whole mess o' guards. They were chantin' Ymiron... maybe killin' him will free me mates?", objectives = "Brigg in Utgarde Pinnacle wants you to kill King Ymiron.", completion = "Splendid! Mebbe now me mateys be able ta rest in peace.\n\nHere ya go, lad. Don't let it be said that ol' Brigg weren't generous ta those who showed 'im a kindness.\n\nGood doin' business wit yeh." }
WordHunterWoW_QuestEN[13133] = { title = "Find the Ancient Hero", description = "Quickly, {name}, head southwest to the Halls of the Ancestors!\n\nWithin you will find slumbering mjordin. Wake them until you find Iskalder. When you do, use this amulet upon him and bring him back to me.\n\nNow go. There is no time to waste!", objectives = "The Bone Witch at Njorndar Village wants you to return with Iskalder.", progress = "Where is the ancient hero?\n\nWe do not have time to chat. Go to the Halls of the Ancestors and find him before it is too late!", completion = "He's a fine specimen and will serve us well.\n\nNow, we have to make sure to use him properly to trap Vardmadra!" }
WordHunterWoW_QuestEN[13134] = { title = "Spill Their Blood", description = "The Scourge cannot create their flesh monsters without blood and embalming fluid to preserve the parts and keep them functioning. If we can deny them these materials, their army will fall apart and we can easily destroy their creations.\n\nThroughout the labs where the flesh giants and abominations are cobbled together, you will find vats of embalming fluid and large orbs filled with blood. Destroy these, and bring death to any who would stop you!", objectives = "Darkrider Arly at Blackwatch wants you to destroy 5 vats of Embalming Fluid and 5 Blood Orbs.", completion = "<A dark, hollow laugh greets you as you report to the darkrider.>\n\nYou reek of victory, <name>, and that is good news, indeed." }
WordHunterWoW_QuestEN[13135] = { title = "It Could Kill Us All", description = "Southeast of here, at the eastern reaches of Crystalsong Forest, is an area known as the Unbound Thicket. Within that thicket creeps all manner of life. One thing all of the affected creatures of the thicket share in common is their affinity for magical energy. Each of them holds pure, crystallized energy. Enough to kill us all should it ever destabilize!\n\nTravel to the Unbound Thicket and kill its denizens for crystallized energy. We need fuel and they need to die. We call that a \"win-win.\"", objectives = "Crusade Engineer Spitzpatrick at the Valley of Echoes in Icecrown wants you to retrieve 8 pieces of Crystallized Energy.", progress = "Did you get the crystallized energy?", completion = "Ah, this is perfect. The bomber should be up and running in no time." }
WordHunterWoW_QuestEN[13136] = { title = "Jagged Shards", description = "You pulled this jagged, dark brittle shard from the body of a ghoul. The metal blade lacks a smooth edge, suggesting it was forged by an unskilled hand, or was broken from a larger piece.\n\nYou recall seeing similar shards embedded in the bodies of all the ghouls you've encountered at the Fleshwerks, leading you to wonder why their creators bothered to include the metal at all. Perhaps Crusader Olakin Sainrith would have some insight if you brought him the shards from several ghouls.", objectives = "Bring 10 Jagged Shards to Crusader Olakin Sainrith at Blackwatch.", progress = "What is that vile thing?", completion = "<Olakin handles the shards of metal gingerly.>\n\nYou saw these on all of the ghouls down there? I've never seen anything like this in all my battles against the Scourge." }
WordHunterWoW_QuestEN[13137] = { title = "Not-So-Honorable Combat", description = "Atop the tallest peak to the southwest overlooking Jotunheim is Battlescar Spire. It is a place of reverence for the vrykul, second only to Valhalas in terms of where they prefer to do honorable combat.\n\nWe shall visit not-so-honorable combat upon it.\n\nGather your companions and fly to the spire. When you are ready, light the signal fire and I will appear within the body of Iskalder.\n\nWe will fight, you will win, and Vardmadra is sure to come to witness the battle!", objectives = "The Bone Witch in Njorndar Village wants you to defeat Iskalder upon Battlescar Spire.", completion = "I've put Vardmadra aside for the moment. She's someplace safe until we can enact our final revenge!" }
WordHunterWoW_QuestEN[13138] = { title = "I'm Smelting... Smelting!", description = "<Olakin turns one of the shards over in an armored fist.>\n\nThese could pierce armor with enough force. We have to find out what they're made of and what the Lich King intends to do with them.\n\nTo the east, nestled next to Icecrown Citadel itself, lies Malykriss. From the few reports we have, it's full of smelting and smithing equipment. Bring these shards there, and smelt them in one of the open furnaces on the bottom level of Malykriss. Once the metal has been reformed, we can identify it.", objectives = "Use the Bag of Jagged Shards near one of the bottom level Malykriss furnaces. Return to Crusader Olakin Sainrith at Blackwatch with the Smelted Metal Bar.", progress = "Have you smelted those fragments yet?", completion = "There is no doubt, this is raw saronite. We've seen weapons made from it in the hands of the Lich King's chosen before, but this is the first time it's been used to arm anything else. The scale of that mining operation must be huge." }
WordHunterWoW_QuestEN[13139] = { title = "Into The Frozen Heart Of Northrend", description = "Silas and Spitzpatrick have signed off on the materials and fuel needed to begin construction of Justice Keep. Thanks to you and the Ebon Blade the Scourge presence within Scourgeholme has been decimated and their lieutenants have been defeated.\n\nI have chosen the site at which we will break ground, but first you must deliver my report to Highlord Tirion Fordring. We will begin our march into Icecrown on his command.\n", objectives = "Deliver Father Gustav's Report to Highlord Tirion Fordring at the Argent Vanguard in Icecrown.", progress = "Stand easy, <name>. What have you to report?", completion = "Your assistance has been integral in securing the front. The first true victory of this war is close at hand - which is why our next step is the most crucial.\n\nRest assured, <name>, the Scourge will not give up without a fight. Your most difficult challenge awaits." }
WordHunterWoW_QuestEN[13140] = { title = "The Runesmiths of Malykriss", description = "Those shards you recovered can only have come from one place, Malykriss. It's the seat of the Lich King's metalworking operations, to the east of Corp'rethar.\n\nWhat's puzzling is that metal isn't needed to stitch together abominations or flesh giants, or to summon skeletal servants. Find the skeletal runesmiths working on the bottom level of Malykriss and capture the plates they're working on. We need to find out why this metal is finding its way to the Fleshwerks.", objectives = "Bring 5 Runed Saronite Plates to Crusader Olakin Sainrith at Blackwatch.", progress = "Were you able to capture those rune plates?", completion = "These plates match the shards almost exactly. They must be using cuttings from them to \"enhance\" the ghouls produced here. The Scourge is desperate enough to make a weapon of anything, it seems. All the more reason to hasten our destruction of this abominable place!" }
WordHunterWoW_QuestEN[13141] = { title = "The Battle For Crusaders' Pinnacle", description = "<Highlord Fordring holds a banner of the Argent Crusade.>\n\nThis banner is like no other, {name}. It carries with it a powerful blessing, able to sanctify large tracts of blighted land.\n\nYou must take it northwest, through the Breach, to an area the Scourge have mockingly named Crusaders' Pinnacle. Plant the banner atop the skulls of our fallen brethren at Crusaders' Pinnacle and defend it against attack. Once the land is sanctified, return to Father Gustav.\n\nGo now, {name}. Hold no fear in your heart.", objectives = "Venture to Crusaders' Pinnacle and use the Blessed Banner of the Crusade atop the Pile of Crusader Skulls. Defend the banner against Scourge attack until the land atop the pinnacle is sanctified and then return to Father Gustav at the Valley of Echoes in Icecrown.", completion = "Blessed Light! We have taken the pinnacle! Finally, construction of Justice Keep can begin. Highlord Fordring and the knights are already en route to our new base. You must meet them there, <name>!" }
WordHunterWoW_QuestEN[13142] = { title = "Banshee's Revenge", description = "The time has come, {name}. You and your friends must challenge the lord of Balargarde Fortress, the master of Jotunheim, Overthane Balargarde.\n\nAtop the fortress, which is on the southwestern edge of Jotunheim, you will find a horn. Blow into it. Allow your challenge to resound throughout the steadfast.\n\nBalargarde will have no choice but to face you. And I... excuse me, Vardmadra will be there to adjudicate the challenge.\n\n<The banshee-possessed vrykul lets out a bellowing cackle.>", objectives = "The Bone Witch at Njorndar Village has asked you to exact her revenge by challenging and defeating Overthane Balargarde.", completion = "Words cannot describe what I'm feeling at the moment, <name>. My revenge is complete and there is naught else for me to do.\n\nIf only I could be there when the Lich King is finally taken down.\n\nDon't fool yourself though, Jotunheim is far from 'dealt' with. I will remain in possession of this witch until such time as the vrykul are no longer a threat.\n\nLook around, there are many items of value in this cave. Take your pick." }
WordHunterWoW_QuestEN[13143] = { title = "New Recruit", description = "First things first. I saw some Lithe Stalkers on the ramparts just east of us. They used to serve us before we broke with Arthas, and they're about as perfect a scout as you can get... with a little prodding from an eye of dominion.\n\nFly up, find one of the stalkers, beat it down a bit, and then use this Sigil of the Ebon Blade to command its obedience. It will recognize the sigil, guaranteed. Lead it back to the top of the rocks northeast of here and it will find its way to me.", objectives = "Vereth the Cunning on the Rise of Suffering has requested that you bring a subdued Lithe Stalker to the top of the rocks northeast of the Rise of Suffering.", progress = "I'm sure their new masters don't go easy on them, but there's no way these things would forget the lessons we lashed into their skins. They'll fear those sigils for as long as they crawl this land.", completion = "I've chained the wretch to the post over there and I'll look into getting my hands on more of them.\n\nNow let's make some use of that eye." }
WordHunterWoW_QuestEN[13144] = { title = "Killing Two Scourge With One Skeleton", description = "The workers in the Fleshwerks abomination lab have already completed a number of their creations. For now, the creatures are chained to the pillars around the edge of the lab, but if we do not act, they will march with the Lich King's armies.\n\nGrasping arms reach out of the bone piles spread throughout the Fleshwerks. These arms belong to skeletons enchanted with the power of fire. Find and free these skeletons, then take them near the completed abominations and watch the show!", objectives = "Darkrider Arly at Blackwatch wants you to destroy 3 Chained Abominations with Burning Skeletons.", progress = "Have you destroyed the completed abominations?", completion = "Ah, good. There's nothing like the smell of roasted putrid flesh in the morning. That's the smell of victory over the Scourge." }
WordHunterWoW_QuestEN[13145] = { title = "The Vile Hold", description = "We need to know what we're up against.\n\nUse the eye of dominion to assume control of a lithe stalker and scout out the area. There are a few spots in particular I saw when flying in that I want you to get a closer look at: the overlook in the northeast, the work area in the southeast, the large forge near the center, and the ritual area in the southwest.\n\nThe stalker can leap far and won't be hurt by large falls - use that to your advantage to get up and down from those ramparts.", objectives = "Vereth the Cunning at the Rise of Suffering has requested that you use a Lithe Stalker to scout out Malykriss.", progress = "Flying may be a bit more graceful, but there's no way that we could get in as close as the stalker can without being detected.", completion = "Excellent work. It seems more death knights remained loyal to Arthas than I initially thought.\n\nHe certainly is sparing nothing in his attempt to replace Acherus. A pure saronite citadel would be hard to destroy indeed. There's no need to destroy it though... we can halt production and put down these death knight leaders here and now, before they become a real threat.\n\nMost importantly, we need to disrupt them enough to get those death knights away from from the leaders so that we can make our strike." }
WordHunterWoW_QuestEN[13146] = { title = "Generosity Abounds", description = "We need to cause some disruption to bring those death knights away from their leaders. If we lay waste to their minions below, I suspect they'll have to devote more attention to keeping a close eye on operations.\n\nAbominations are easy prey - slow, predictable, and most importantly, stupid. Take advantage of their trust of the stalkers to drag them near some of the Scourge bombs scattered throughout the construction area. You'll be able to light the bombs far before they figure out what's going on.", objectives = "Vereth the Cunning wants you to use the Lithe Stalker's Iron Chain to drag Scourge Bombs to 4 Lumbering Atrocities inside Malykriss.", completion = "They didn't even think to lay a hand on you, did they? At least they're predictable." }
WordHunterWoW_QuestEN[13147] = { title = "Matchmaker", description = "The major difference between vargul and lesser undead minions is that vargul still possess enough of their minds to despise being used for labor. Never will a vargul be pleased to be working aside skeletons or ghouls.\n\nLets take advantage of this inevitable animosity and start some fights between the umbral brutes and the other undead in Malykriss. That should serve to slow production and bring the death knights down to babysit.\n\nShould be simple - throw rocks at the brutes as they near lesser undead.", objectives = "Vereth the Cunning at the Rise of Suffering wants you to use a Lithe Stalker to throw rocks at Umbral Brutes as they near lesser undead in Malykriss. Return after you've started 5 fights.", completion = "No need to sacrifice our own men when they are this easily manipulated, eh?" }
WordHunterWoW_QuestEN[13148] = { title = "Necklace Repair", description = "This damaged necklace has an invoice with it that reads \"Property of Timothy Jones - Cartier and Co Fine Jewelry - Magus Commerce Exhange - Dalaran\".\n\nPerhaps you should repair it and return it to him.", objectives = "Repair the necklace with a single Chalcedony and return it to Timothy Jones in at the Jewelcrafters Shop in the Magus Commerce Exchange in Dalaran.", progress = "What brings you here?", completion = "How did you find this!   Many of these necklaces were looted from one of my shipments a few weeks ago!   Let me repay you with this Jewelcrafter's Token." }
WordHunterWoW_QuestEN[13149] = { title = "Dispelling Illusions", description = "The infinite dragonflight seek to disrupt history by deceiving Prince Arthas.\n\nIf they can convince him that none of the grain here carries the plague, then he'll never have to make the fateful decision to cull Stratholme.\n\nUse this arcane disruptor on any suspicious crates of grain you find.", objectives = "Chromie wants you to use the Arcane Disruptor on the suspicious crates in Stratholme Past, then speak to her near the entrance to Stratholme.", progress = "It's good to see you again!", completion = "You have done well, friend. The plagued grain was exposed to Arthas' troops.\n\nListen carefully, now. There remains more to be done." }
WordHunterWoW_QuestEN[13150] = { title = "ZZOLDLost: Widget", description = "Attached to the bottom of the widget is an invoice that indicates the owner is \"Timothy Jones - Jewelershop Name, District Name\" in Dalaran.   Perhaps if you fixed it and returned it to him, he would have a reward for you.", objectives = "Repair the whatsit and return it to Timothy Jones at the Jewelcrafting shop in Dalaran.Attached to the bottom of the widget is an invoice that indicates the owner is \"Timothy Jones - Jewelershop Name, District Name\" in Dalaran.  Perhaps if you fixed it and returned it to him, he would have a reward for you." }
WordHunterWoW_QuestEN[13151] = { title = "A Royal Escort", description = "Arthas will soon face a desperate dilemma, and make a momentous decision.\n\nI must call upon you to accompany the prince in his culling.\n\nArthas must make it through Stratholme alive and you must see to it that he defeats Mal'Ganis!", objectives = "Chromie has asked you to accompany Arthas in the Culling of Stratholme. You are to speak with her again after Mal'Ganis is defeated.", completion = "You have done well, <name>.\n\nThe Infinites have been foiled and this thread of history remains intact.\n\nI thank you for your invaluable assistance, as does the entire Bronze Dragonflight." }
WordHunterWoW_QuestEN[13152] = { title = "A Visit to the Doctor", description = "So they've been embedding these ghouls with broken shards of saronite down in the Sanctum of Reanimation? We must put a stop to this, before these ghouls can be deployed against our troops.\n\nFind the entrance to the Sanctum of Reanimation in the flesh giant lab area of the Fleshwerks. There, the ghoul mastermind, Doctor Sabnok, keeps the most fearsome of his creations, Patches. Free Patches from his chains and help him take his revenge on the doctor. Let his own creation be his undoing.", objectives = "Darkrider Arly at Blackwatch wants you to destroy the Metal Stake imprisoning Patches in the Sanctum of Reanimation and help him get his revenge on Doctor Sabnok.", progress = "Have you unleashed the doctor's creation against him?", completion = "<Dakrider Arly throws her head back and laughs darkly.>\n\nA fitting end for the 'good' doctor, wouldn't you say?" }
WordHunterWoW_QuestEN[13153] = { title = "Warding the Warriors", description = "{name}, good to see you. While the battle has subsided for now, we must hurry and replenish our stocks. My research indicates that the armor of soldiers recently slain in the Glacial Falls becomes imbued with an incredible amount of energy. The Horde has been seen collecting armor in the area.\n\nHead to the Glacial Falls and slay any of the Horde you find there. Return their imbued armor to me.\n\nIf you cannot find any of the Horde, you might find the armor of an adventurer slain by the elementals.", objectives = "Sorceress Kaylana at Wintergrasp Fortress wants you to retrieve 10 sets of Imbued Horde Armor from Horde players at the Glacial Falls.", progress = "So, did you find the armor?", completion = "Augh. It's still dripping. Couldn't you have at least dried it off first?" }
WordHunterWoW_QuestEN[13154] = { title = "Bones and Arrows", description = "Dragons are incredible! Well, their bones at least! I've been equipping our archers with arrowheads made of Dragonbone. Unfortunately, since the massacre at Angrathar, it has become almost impossible to get bone from Dragonblight.\n\nHowever, the Forest of Shadows on the western edge of Wintergrasp has enough bones to tide us over.\n\nHead to the Forest of Shadows and bring back any bone splinters you can find!\n\nThe Horde have been seen collecting bone splinters in the area. Slay them!", objectives = "Bowyer Randolph at Wintergrasp Fortress wants you to retrieve 10 Quivers of Dragonbone Arrows from Horde players at the Forest of Shadows.", progress = "How was the hunting? I've heard rumors the place is haunted, though I never venture out there myself.", completion = "Excellent! This will help fuel the flames of war for days to come." }
WordHunterWoW_QuestEN[13155] = { title = "Vereth the Cunning", description = "I've already heard some rumors regarding Malykriss and Arthas's new death knight order, but I assumed it nothing more than filling the void. These numbers suggest he's trying to take it up a notch though.\n\nWe dispatched one of our best to Malykriss not long ago - Vereth the Cunning. You should be able to find him on the Rise of Suffering, just west of Malykriss, and inside the Court of Bones.\n\nTry not to draw too much attention on your way in.", objectives = "Report to Vereth the Cunning on the Rise of Suffering in Icecrown.", completion = "The Vile Hold... a testament to how much Arthas hates losing. Let's drive the blade deep." }
WordHunterWoW_QuestEN[13156] = { title = "A Rare Herb", description = "My, it its quite chilly up here! Reminds me of the stormy peaks of Kaarinos on Argus. However, with all of this snow and ice, our soldiers can easily catch cold.\n\nHead to the Steppe of Life in southwestern Wintergrasp, and bring me back 10 of the Horde herb pouches you find. I will grind them into a medicine to help protect against the cold.\n\nThe Horde have been seen collecting them from the plant life in the area. Do not hesitate to slay them and retrieve the herbs!", objectives = "Anchorite Tessa in Wintergrasp Fortress wants you to retrieve 10 Horde Herb Pouches from Horde players in the Steppe of Life.", progress = "I hope you didn't pull up any of the lashers by mistake! They gave Private Doane quite a whipping last week.", completion = "Excellent! This will help protect our troops against the cold." }
WordHunterWoW_QuestEN[13157] = { title = "The Crusaders' Pinnacle", description = "Stand proud in knowing that it was you who helped establish the Argent Crusade inside the walls of Icecrown, {name}. The Crusaders' Pinnacle now stands in direct defiance of the Lich King and his twisted minions.\n\nHighlord Fordring and the crusaders who survived await your arrival at Crusaders' Pinnacle. Travel once more through the Breach and seek out the highlord!", objectives = "Seek out Highlord Tirion Fordring at Crusaders' Pinnacle in Icecrown.", completion = "A long and arduous journey awaits us as we make our way to the gates of Icecrown Citadel. I, and the soldiers of the Argent Crusade, wish to thank you for all that you have done. We rest easier knowing that you will fight alongside us in this cursed place.\n\n<Highlord Tirion Fordring salutes.>" }
WordHunterWoW_QuestEN[13158] = { title = "Discretion is Key", description = "Listen to me, <race>.\n\nIt's just been brought to my attention that there's been an incident at the Violet Hold. It would appear that the blues are launching a full scale invasion of Dalaran!\n\nI need you to get to the prison and speak with Warden Alturas at once. He'll give you the details.\n\nThat is not all. I need this handled with utmost discretion. We mustn't alarm the citizens of Dalaran if it can possibly be avoided. Do I make myself clear?\n\nVery well. Now, go!", objectives = "Rhonin wants you to go to the Violet Hold in Dalaran and speak with Warden Alturas.", completion = "Not a moment too soon.\n\nAre you prepared to defend Dalaran, <class>?" }
WordHunterWoW_QuestEN[13159] = { title = "Containment", description = "Here is the prison key.\n\nMy men and I will stay here as a last line of defense in the event that you are unable to overcome the assault.\n\nBe sure to speak with Lieutenant Sinclari. She'll provide you with access to the prison's defenses.\n\nHurry, <race>. There is little time. The few I left inside won't last long without your help. Report back to me once the invasion forces have been successfully dealt with.", objectives = "Warden Alturas wants you to enter the Violet Hold and put an end to the blue dragon invasion force. You are to report back to him once Cyanigosa is slain.", completion = "The crisis is averted, then?\n\nThat is good news indeed. I will forward the news on to Rhonin.\n\nPlease, accept this with the gratitude of Dalaran." }
WordHunterWoW_QuestEN[13160] = { title = "Stunning View", description = "Gargoyles make effective scouts and can be deadly if left to rain attacks from the air, but they have a very obvious weakness. Most of them have to go through long periods resting as stone to maintain the energy they need to carry their heavy bodies through the air.\n\nAs I peered through the eye you were using, I noticed dozens of iceskin sentries resting on the eastern and southern walls inside. Use the stalker to leap up to their ledges and devastate them while they sleep.", objectives = "Vereth the Cunning at the Rise of Suffering wants you to use a Lithe Stalker's heave ability to destroy 12 sleeping Iceskin Sentries.", completion = "Not so much of a threat when they're sleeping." }
WordHunterWoW_QuestEN[13161] = { title = "The Rider of the Unholy", description = "It's time that we start cutting off the heads of the beast.\n\nI served beside Rokir for quite some time. He knows the unholy arts better than most any other death knight I've met and he's equally as ruthless.\n\nRokir's strengths are most apparent when you are fighting him on his own ground. Sadly, we don't have much option in those regards, but stay on your feet to avoid his undead minions and you should come out victorious.\n\nBe nimble, {class}, and do not take him lightly.", objectives = "Vereth the Cunning on the Rise of Suffering wants you to kill Rokir, the Rider of the Unholy.", completion = "The world will be a much better place without Rokir in it - trust me." }
WordHunterWoW_QuestEN[13162] = { title = "The Rider of Frost", description = "Sapph... Sapph's a death knight like no other. She'll shower you with sweet words and you'll swear that she has no evil within her heart, and then she'll run you through without even breaking her smile.\n\nI have no fear that you'll be able to best Sapph, but do not grow overconfident. Her strength lies in lulling her victims into a false ease, shortly before shattering them with a fierce barrage of frost attacks.\n\nDo not let your guard down, and do not underestimate her.", objectives = "Vereth the Cunning on the Rise of Suffering wants you to kill Sapph, the Rider of Frost.", progress = "Are we rid of her?", completion = "I can't deny, I'll miss her laugh... and that smile that would creep onto her face just before she killed someone. A little less need to watch my back though, so I suppose I can't complain." }
WordHunterWoW_QuestEN[13163] = { title = "The Rider of Blood", description = "Baelok is one of the few vrykul that I've ever seen rise through the ranks, and that was mostly accomplished through sheer brutality. If your competition ends up dead, there's far less to compete against.\n\nWhen you join battle with him, spread out from your companions and keep your distance as much as you reasonably can. He will not hesitate to steal your life force for himself, so you will need to hinder his ability to do so as much as possible.\n\nYou have my confidence. See to it that he dies.", objectives = "Vereth the Cunning on the Rise of Suffering wants you to kill Baelok, the Rider of Blood.", completion = "So he finally lost? Good to hear." }
WordHunterWoW_QuestEN[13164] = { title = "The Fate of Bloodbane", description = "With the riders of the Host of Suffering dead, now is the time to put an end to their true leader: Orbaz Bloodbane.\n\nMograine caught up with me while you were off and told me that he found where Orbaz is hiding. Under Icecrown Citadel itself, there is an immense pit - you will find Orbaz just outside its lip.\n\nSome of the Ebon Blade's strongest agents have already been dispatched - gather aid and join the fight. It is time for Bloodbane to die.", objectives = "Vereth on the Rise of Suffering has dispatched you to kill Orbaz Bloodbane.", completion = "Mograine himself arrived to see the deed done then? I imagine there was some ill blood between those two - no surprise that he wanted a piece of the wretch.\n\nYou've done exceedingly well, <race>, and you shall be awarded appropriately. The Ebon Blade thanks you." }
WordHunterWoW_QuestEN[13165] = { title = "Taking Back Acherus", description = "The haze has been lifted. I can see as clearly now as the day that I plunged the Ashbringer into my own heart to free my father's cursed soul: my last memory as a free man.\n\nWe must take back Acherus from the Scourge if our order is to survive in this new world. I have taught you how to call forth a death gate. The death gate will return you to Acherus when you call upon it, {name}. Use it now and meet me at Acherus. The first battle of the Knights of the Ebon Blade is underway! Death to the Scourge!", objectives = "Use your Death Gate spell to return to Acherus: The Ebon Hold. Report to Highlord Darion Mograine once you arrive.", completion = "The Lich King has returned to Northrend, wounded by the Ashbringer, but the second floor still holds the last of his armies." }
WordHunterWoW_QuestEN[13166] = { title = "The Battle For The Ebon Hold", description = "The Hall of Command has been secured, but the Lich King has left us a little present in the Heart of Acherus. The stitched terror, Patchwerk, and a horde of abominations have taken over the second floor.\n\nUse the teleporter to get to the second floor and destroy the Scourge forces that remain. Do not engage Patchwerk alone! You must fight the monstrosity with other death knights of Acherus!\n\nGo, {name}. You have my strength to carry you!", objectives = "Slay 10 Scourge and help kill Patchwerk. Return to Highlord Darion Mograine should you succeed.", progress = "Acherus will be ours!", completion = "Well done, <class>. The remaining Scourge will be dealt with in short order and the rebuilding process will begin anew.\n\nI have but one last task for you." }
WordHunterWoW_QuestEN[13167] = { title = "Death to the Traitor King", description = "Anub'arak, the traitor king, makes his home in the once proud underland of Azjol-Nerub.\n\nSince his betrayal, he has twisted and perverted our homeland into the wretched squalor it is today. He rules over an army of undead nerubians who, like their leader, have pledged themselves to serving the Lich King.\n\nBring an end to the traitor king's reign, <class>. You will be doing a great service to both of our peoples.\n\nIf you manage to succeed where all others have failed, bring me the husk of Anub'arak.", objectives = "Kilix the Unraveler in the Pit of Narjun has tasked you with defeating Anub'arak in Azjol-Nerub. You are to return to Kilix with Anub'arak's Broken Husk.", progress = "Is it done, <class>? Has the traitor king finally met his end?", completion = "<A fierce glow emanantes from all of Kilix's eyes as he stares at the husk.>\n\nIt is DONE!\n\n<race>! Your name shall be recorded in the history of our people.\n\nI am in your debt...." }
WordHunterWoW_QuestEN[13168] = { title = "Parting Gifts", description = "Look what we have here... eyes of dominion. The Cult normally goes to great lengths to keep these things safe, but I suppose their options for retreat are few when we're slaughtering them in their own home.\n\nThe eyes allow a being of any relative power to control an undead minion's actions precisely. As you can imagine, this can be extremely useful when it comes to your typical clumsy ghoul or skeleton.\n\nCare to try your hand at it? Use one of the eyes to control a captured shade.", objectives = "Keritose Bloodblade at the Shadow Vault wants you to use an Eye of Dominion to take control of a captured Eidolon Watcher.", progress = "The options of subterfuge made available to us with the eyes are obvious. These will be very useful tools.", completion = "Nothing to it, eh? Any intelligent being should have little trouble controlling lesser undead. I suspect only the likes of a true necromancer could use these to sieze control of any of the more powerful undead. That won't be a problem though - I can already think of quite a variety of destruction we can wreak with even the most paltry minions.\n\nShall we have at it then?" }
WordHunterWoW_QuestEN[13169] = { title = "An Undead's Best Friend", description = "As is usual practice, the undead at the saronite quarry to the southwest starve plaguehounds to keep them extra aggressive. Use the shade to get up close and feed some of those hounds and I promise you they'll be content to leave you alone, if not side with the hand that fed them.\n\nDon't get too close to those things until you've fed them though. Their noses don't fall victim to your shade's elusiveness.", objectives = "Keritose Bloodblade at the Shadow Vault wants you to use the Eidolon Watcher to feed 18 Hungering Plaguehounds.", completion = "Put them right to sleep, didn't it?" }
WordHunterWoW_QuestEN[13170] = { title = "Honor is for the Weak", description = "Ghouls are fragile things when it comes down to it, and the lookouts at the saronite quarry down the path to the southwest are no exception. Using one of the shades, I have no doubt that you can sneak up and put down their lookouts without making a sound.\n\nClear out as many lookouts as you can reach in a reasonable amount of time... we'll want their ranks thinned for our assault to come.", objectives = "Keritose Bloodblade at the Shadow Vault would like you to assassinate 20 Restless Lookouts.", completion = "Without even getting your hands dirty." }
WordHunterWoW_QuestEN[13171] = { title = "From Whence They Came", description = "My main concern is the saronite quarry down the path to the southwest. They are pulling up immense amounts of ore from that quarry and I'd like to know what they're building with it. To that end, we'll start by weakening their defenses.\n\nI noticed a series of crystals scattered throughout the base and I assume they are defensive structures of some sort, not unlike ziggurats. Use the eidolon watcher to destroy any of those crystals that you find.", objectives = "Keritose Bloodblade at the Shadow Vault has sent you to banish 10 Scourge Containment Crystals.", completion = "Excellent work. We should have little threat in the air then." }
WordHunterWoW_QuestEN[13172] = { title = "Seeds of Chaos", description = "Effective tool, is it not? Excellent job weakening their defenses, {class}. Now we can push the main assault.\n\nThe plan here is straight-foward - we're looking to destroy anything moving, and get in there and steal some information amidst the confusion.\n\nLet me know when you're ready and I'll set you up with a skeletal gryphon.", objectives = "Keritose Bloodblade at the Shadow Vault has dispatched you to slaughter 80 undead in the Weeping Quarry. Speak to him to secure a skeletal gryphon for the assault.", completion = "Practically defenseless. It doesn't get much easier than that." }
WordHunterWoW_QuestEN[13173] = { title = "Amidst the Confusion", description = "We got our hands on quite a few workers. They should do nicely.\n\nI want you to use an eye to bring one of these workers back into the quarry. With the entire camp in disarray, there's no way they'll be able to distinguish you from any of the other workers that were scattered by the assault.\n\nFind whoever is in charge of the operation and get to work. With any luck, we'll find out where that Saronite is being shipped off to pretty quickly. I'll watch over your shoulder through the eye.", objectives = "We got our hands on quite a few workers. They should do nicely.\n\nI want you to use an eye to bring one of these workers back into the quarry. With the entire camp in disarray, there's no way they'll be able to distinguish you from any of the other workers that were scattered by the assault.\n\nFind whoever is in charge of the operation and get to work. With any luck, we'll find out where that Saronite is being shipped off to pretty quickly. I'll watch over your shoulder through the eye." }
WordHunterWoW_QuestEN[13174] = { title = "Amidst the Confusion", description = "Shutting down their operation is just half of the plan. The other important goal here is to find out where all that saronite is being sent. We know of a few places it's been ending up, but the amount they're pulling out suggests to me that there's a bigger project in the works.\n\nOnce you're inside the quarry, get your hands on any of their documents that you can find. If you're assaulting the place with one of the gryphons, you can drop down from it as soon as the wetwork is done.", objectives = "Keritose Bloodblade at the Shadow Vault has requested a Weeping Quarry Document, a Weeping Quarry Ledger, a Weeping Quarry Map, and a Weeping Quarry Schedule.", progress = "Did you bring back what I requested?", completion = "Let's see here... what do we have...\n\n<Keritose buries his head in the papers for a bit, seemingly gleaning little that he did not already know. Suddenly he finds what he is looking for...>\n\nMalykriss! The Vile Hold. It seems Arthas did not take the loss of his death knights so well... I'm not exactly sure what he's doing with all of that saronite, but I have a feeling he might be overcompensating for something.\n\nThat boy is not used to losing." }
WordHunterWoW_QuestEN[13175] = { title = "Regaining Control", description = "", objectives = "" }
WordHunterWoW_QuestEN[13176] = { title = "Preparing the Delivery", description = "", objectives = "" }
WordHunterWoW_QuestEN[13177] = { title = "No Mercy for the Merciless", description = "Welcome to the Wintergrasp Fortress, {name}. Your mission is simple. Defeat ten of the Horde's finest. Now, go! Bring victory to the Alliance!", objectives = "Commander Zanneth in Wintergrasp Fortress wants you to slay 10 members of the Horde.", completion = "Glorious! Truly, you are among the champions of the Alliance." }
WordHunterWoW_QuestEN[13178] = { title = "Slay them all!", description = "Welcome to the Wintergrasp Fortress, {name}. Warlord Garrosh demands one thing: Slay them all!\n\nReturn to me when ten of the strongest members of the Alliance are dead.", objectives = "Commander Dardosh in Wintergrasp Fortress wants you to slay 10 members of the Alliance.", completion = "Lok'tar! Victory for the Horde!" }
WordHunterWoW_QuestEN[13179] = { title = "No Mercy for the Merciless", description = "Welcome to Wintergrasp, {name}. Your mission is simple. Defeat ten of the Horde's finest. Now, go! Bring victory to the Alliance!", objectives = "Commander Zanneth in Wintergrasp wants you to slay 10 members of the Horde.", completion = "Glorious! Truly, you are among the champions of the Alliance." }
WordHunterWoW_QuestEN[13180] = { title = "Slay them all!", description = "Welcome to Wintergrasp, {name}. Warlord Garrosh demands one thing: Slay them all!\n\nReturn to me when ten of the strongest members of the Alliance are dead.", objectives = "Commander Dardosh in Wintergrasp wants you to slay 10 members of the Alliance.", completion = "Lok'tar! Victory for the Horde!" }
WordHunterWoW_QuestEN[13181] = { title = "Victory in Wintergrasp", description = "Commander Zanneth might be satisfied with a pile of Horde corpses at his feet, but controlling Wintergrasp is of the utmost importance to the Valiance Expedition. Make sure it remains in our control.\n\nHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", objectives = "Win a Wintergrasp battleground match and return to Tactical Officer Abrahmis in Wintergrasp. You must have participated in the battle to be credited for the victory.", completion = "Just what I wanted to hear!  A victory in Lake Wintergrasp - even a temporary one - is crucial to our overall strategy against the Horde." }
WordHunterWoW_QuestEN[13182] = { title = "Don't Forget the Eggs!", description = "Throughout Azjol-Nerub, the scourged nerubians carefully nurture eggs that will soon hatch, providing them even greater numbers.\n\nIt would do little good for the caverns to be cleansed of the undead that stain them if these fouled eggs were left to hatch and take their place.\n\nAs you  explore the expanse that was once Azjol-Nerub, be sure to clear our ancient home of any scourge eggs you find.", objectives = "Kilix the Unraveler in the Pit of Narjun wants you to enter Azjol-Nerub and destroy 6 Nerubian Scourge Eggs.", completion = "It saddens me to see that things have come to this. If only we could return our great empire to what it once was..." }
WordHunterWoW_QuestEN[13183] = { title = "Victory in Wintergrasp", description = "While Dardosh might be content with slaying our foes, it is of the utmost importance that we control Wintergrasp Fortress. Do whatever it takes to ensure Wintergrasp is ours.\n\nHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", objectives = "Win a Wintergrasp battleground match and return to Tactical Officer Kilrath in Wintergrasp. You must have participated in the battle to gain credit for the victory.", completion = "It is a truly great thing you have accomplished this day. Be recognized for your sacrifice!" }
WordHunterWoW_QuestEN[13184] = { title = "Outliving Usefulness", description = "", objectives = "" }
WordHunterWoW_QuestEN[13185] = { title = "Stop the Siege", description = "I hears dem! The Alliance come soon. Destroy three Alliance siege devices and come back to Murp.", objectives = "Lieutenant Murp in Wintergrasp Fortress wants you to destroy 3 Alliance siege machines.", completion = "Good job. Murp wish he was there to help." }
WordHunterWoW_QuestEN[13186] = { title = "Stop the Siege", description = "It is only a matter of time before this castle is besieged by the forces of the Horde. Destroy three of their siege devices and return to me.", objectives = "Senior Demolitionist Legoso in Wintergrasp Fortress wants you to destroy 3 Horde siege machines.", completion = "Excellent. That should slow down their assault." }
WordHunterWoW_QuestEN[13187] = { title = "The Faceless Ones", description = "In my peoples' struggle against the forces of the undead, they dug deeper as they lost ground.\n\nThey inadvertently exposed minions of the Old Gods known only as the Faceless.\n\nIn the end, we could not fight a war on two fronts.\n\nWith your aid, perhaps the Faceless will finally fall.", objectives = "Seer Ixit in Ahn'Kahet wants you to kill Herald Volazj and the three Forgotten Ones that accompany him.", progress = "Have you overcome the faceless ones, <class>?", completion = "You have done well, <class>.\n\nWith the servants of the Old Gods defeated, the time is upon my people to retake our ancient home." }
WordHunterWoW_QuestEN[13188] = { title = "Where Kings Walk", description = "You are now, and forever will be, a Knight of the Ebon Blade, {name}, but know this: you were once a hero of the Alliance.\n\n<Darion stares at you.>\n\nThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Alliance.\n\nOn the platform, southeast of me, is a portal to Stormwind City. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to King Anduin Wrynn. Use the portal.", objectives = "Deliver the letter to King Anduin Wrynn of the Alliance at Stormwind Keep in Stormwind City.", progress = "You have mere moments to live.", completion = "<Varian stares off into the distance.>\n\nIndeed old friend... Blood and honor.\n\n<Varian affixes his gaze upon you.>\n\nWere it not for this letter from Tirion, you would be a stain upon my floor. Only an endorsement from one of the greatest paladins to ever live could have ensured your survival.\n\nWe... We will work together against the Scourge. Against the Lich King!\n\nGLORY TO THE ALLIANCE!" }
WordHunterWoW_QuestEN[13189] = { title = "Saurfang's Blessing", description = "You are now, and forever will be, a Knight of the Ebon Blade, {name}, but know this: you were once a hero of the Horde.\n\n<Darion stares at you.>\n\nThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Horde.\n\nOn the platform, southeast of me, is a portal to Orgrimmar. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to High Overlord Saurfang. Use the portal.", objectives = "Deliver the letter to High Overlord Saurfang at Orgrimmar.", progress = "An interesting turn of events.", completion = "Eitrigg is alive because of this paladin. He would have been executed had Lord Fordring not broken him out of Stratholme.\n\nTirion Fordring, to have sacrificed everything to save the life of an orc... Indeed, this is a rare event.\n\nYes. For Tirion Fordring and for Eitrigg! We will accept you as a member of the Horde and your order as allies.\n\nBlood and honor! For the Horde!" }
WordHunterWoW_QuestEN[13190] = { title = "All Things in Good Time", description = "Ahn'kahet, from whence we came...\n\nOne day, I dream, we shall overcome the death and darkness that hold our ancient home in their grip. To that end, I have a plan to weaken the resolve of our enemies.\n\nTheir precious Watchers must burn!\n\nTake their corpses and place them upon the brazier deep within the city. The scent of their burnt remains will linger in the air, reminding our enemy of their weakness.\n\nBe mindful, <class>! Their undead corpses are most fragile and will deteriorate rapidly.", objectives = "Kilix the Unraveler in the Pit of Narjun wants you to obtain an Ahn'kahar Watcher's Corpse and place it upon the Ahn'kahet Brazier in Ahn'kahet.\n\nThis quest can only be completed on Heroic Difficulty.", completion = "Ahah!\n\nMay the mocking scent of failure eat at their empty souls!\n\nThank you, <class>. Today, you have struck a blow against the unliving." }
WordHunterWoW_QuestEN[13191] = { title = "Fueling the Demolishers", description = "Lok'tar, {name}! While the battle may be over, we must prepare for the Alliance's next assault! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers.\n\nThe embers are mixed in with coal to fuel the Demolishers and Siege Engines. \n\nWe've heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!", objectives = "Siegesmith Stronghoof at Wintergrasp Fortress wants you to retrieve 10 Eternal Embers from Alliance players in the Cauldron of Flames.", progress = "Well? Did you manage to find the embers or did the Alliance beat you to it and leave you crying?", completion = "Excellent! This will help us defeat the Alliance in the battles to come!" }
WordHunterWoW_QuestEN[13192] = { title = "Warding the Walls", description = "Hey 'mon. This place be givin' me dah heebie jeebies, don't cha know?\n\nWay too many spirits haunting dis place. I want ta be placing hoodoo wards up, but I be needin' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job.\n\nThe Glacial Falls in east Wintergrasp be havin' dem special properties to extract da soul. Slay the Alliance there, mebbe they be havin' the stuff we need.\n\nBring back da armor of the slain. If there be no Alliance maybe da elementals got 'em, mon.", objectives = "Hoodoo Master Fu'jin at Wintergrasp Fortress wants you to retrieve 10 Enchanted Alliance Breastplates at the Glacial Falls.", progress = "Did ya bring da armor, mon?", completion = "Ooh, ya dats da stuff, mon!" }
WordHunterWoW_QuestEN[13193] = { title = "Bones and Arrows", description = "Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. {name}, I am in need of dragon bone for our arrowheads.\n\nTravel to the Forest of Shadows on the western side of Wintergrasp. Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones.\n\nIf that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.", objectives = "Lieutenant Vieron Blazefeather at Wintergrasp Fortress wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players in the Forest of Shadows.", progress = "Back so soon? Drat, I was hoping to catch a moment's rest.", completion = "Well, I guess its another night of sharpening bones for me. Why didn't I stay in Silvermoon City like my brother?" }
WordHunterWoW_QuestEN[13194] = { title = "Healing with Roses", description = "Between the battles, one might almost believe that there was hope for peace in this land. Sadly, that is not to be our fate.\n\nTravel to the Steppe of Life in southwestern Wintergrasp. I have need of the roses that grow there for salve to treat the wounded.\n\nSadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies.\n\nIf that fails, perhaps a lasher or two might have one.", objectives = "Primalist Mulfort wants you to retrieve 10 Alliance Herb Pouches from Alliance players at the Steppe of Life.", progress = "Were you able to recover the herbs? The sick and wounded increase by the hour.", completion = "Thank you, this will go far to treat our soldiers' wounds." }
WordHunterWoW_QuestEN[13195] = { title = "A Rare Herb", description = "My, it is quite chilly up here! Reminds me of the stormy peaks of Kaarinos on Argus. However, with all of this snow and ice, our soldiers can easily catch cold.\n\nHead to the Steppe of Life in southwestern Wintergrasp, and bring me back 10 Horde Herb Pouches. I will grind the herbs into a medicine to protect against the cold.\n\nThe Horde have been seen collecting them from the plant life in the area. Do not hesitate to slay them and retrieve the herbs!\n\nYou may also find one on a lasher in the area.", objectives = "Anchorite Tessa in Wintergrasp wants you to retrieve 10 Horde Herb Pouches from Horde players in the Steppe of Life.", progress = "I hope you didn't pull up any of the lashers by mistake! They gave Private Doane quite a whipping last week.", completion = "Excellent! This will help protect our troops against the cold." }
WordHunterWoW_QuestEN[13196] = { title = "Bones and Arrows", description = "Dragons are incredible! Well, their bones at least! I've been equipping our archers with arrowheads made of Dragonbone. Unfortunately, since the massacre at Angrathar, it has become almost impossible to get bone from Dragonblight.\n\nHowever, the Forest of Shadows on the western edge of Wintergrasp has enough bones to tide us over.\n\nHead to the Forest of Shadows and bring back any bone splinters you can find!\n\nThe Horde have been seen collecting bone splinters in the area. Slay them!", objectives = "Bowyer Randolph in Wintergrasp wants you to retrieve 10 Quivers of Dragonbone Arrows from Horde players at the Forest of Shadows.", progress = "How was the hunting? I've heard rumors the place is haunted, though I never venture out there myself.", completion = "Excellent! This will help fuel the flames of war for days to come." }
WordHunterWoW_QuestEN[13197] = { title = "Fueling the Demolishers", description = "{name}! About time you showed up. While we may have lost the last battle, we should prepare for the next! Travel to the Cauldron of Flames in southeastern Wintergrasp and retrieve several eternal embers.\n\nThe embers are mixed in with coal to fuel the Demolisher and Siege Engines. \n\nOh, and if you happen to see some of the Horde in the Cauldron, don't hesitate to slay them and take their embers. We must prevent them from holding the keep!", objectives = "Siegesmith Stouthandle in Wintergrasp wants you to retrieve 10 Eternal Embers from Horde players at the Cauldron of Flames.", progress = "Well? Did you manage to find the embers or did the Horde beat you to it and leave you crying?", completion = "Excellent! This will help fuel the flames of war for days to come." }
WordHunterWoW_QuestEN[13198] = { title = "Warding the Warriors", description = "{name}, good to see you. We must prepare for our next assault on the fortress. My research indicates that the armor of soldiers recently slain in the Glacial Falls becomes imbued with an incredible amount of energy. The Horde has been collecting armor in the area.\n\nHead to the Glacial Falls and slay any of the Horde you find there. Return their imbued armor to me.\n\nIf you cannot find any of the Horde, you might find the armor of an adventurer slain by the elementals.", objectives = "Sorceress Kaylana in Wintergrasp wants you to retrieve 10 sets of Imbued Horde Armor at the Glacial Falls.", progress = "So, did you find the armor?", completion = "Augh. It's still dripping. Couldn't you have at least dried it off first?" }
WordHunterWoW_QuestEN[13199] = { title = "Bones and Arrows", description = "Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. {name}, I am in need of dragon bone for our arrowheads.\n\nTravel to the Forest of Shadows on the western side of Wintergrasp. Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones.\n\nIf that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.", objectives = "Lieutenant Vieron Blazefeather in Wintergrasp wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players at the Forest of Shadows.", progress = "Back so soon? Drat, I was hoping to catch a moment's rest.", completion = "Well, I guess its another night of sharpening bones for me. Why didn't I stay in Silvermoon City like my brother?" }
WordHunterWoW_QuestEN[13200] = { title = "Fueling the Demolishers", description = "Lok'tar, {name}! While the battle may have subsided, we must prepare to retake the fortress! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers.\n\nThe embers are mixed in with coal to fuel the Demolishers and Siege Engines. \n\nWe've heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!", objectives = "Siegesmith Stronghoof in Wintergrasp wants you to retrieve 10 Eternal Embers from Alliance players at the Cauldron of Flames.", progress = "Well? Did you manage to find the embers or did the Alliance beat you to it and leave you crying?", completion = "Excellent! That should put a dent in their war machines!" }
WordHunterWoW_QuestEN[13201] = { title = "Healing with Roses", description = "So many of our braves were lost during the battle, but even more shall die if left untreated. \n\nTravel to the Steppe of Life in southwestern Wintergrasp. I have need of the roses that grow there for salve to treat the wounded.\n\nSadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies.\n\nIf that fails, perhaps a lasher or two might be in bloom.", objectives = "Primalist Mulfort in Wintergrasp wants you to retrieve 10 Alliance Herb Pouches from Alliance players at the Steppe of Life.", progress = "Were you able to recover the herbs? The sick and wounded increase by the hour.", completion = "Thank you, this will go far to treat our soldiers' wounds." }
WordHunterWoW_QuestEN[13202] = { title = "Jinxing the Walls", description = "Hey 'mon. See dem Alliance sitting comfy in their keep?\n\nI think they be a bit too comfy, ya? I want ta be jinxing the place, but I be needin' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job.\n\nThe Glacial Falls in east Wintergrasp be havin' dem special properties to extract da soul. Slay the Alliance there, they be havin' the stuff we need.\n\nBring back da armor of the slain. If there be no Alliance maybe da elementals got 'em, mon.", objectives = "Hoodoo Master Fu'jin in Wintergrasp wants you to retrieve 10 Enchanted Alliance Breastplates from Alliance players at the Glacial Falls.", progress = "Did ya bring da armor, mon?", completion = "Ooh, ya dats da stuff, mon!" }
WordHunterWoW_QuestEN[13203] = { title = "A Winter Veil Gift", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[13204] = { title = "Funky Fungi", description = "A misshapen piece of mushroom-like fungus falls from a particularly smelly, ooze-covered patch of the cave beast's flesh. Examining it, you are violently repulsed by its overwhelming stench.\n\nYou wonder to yourself if this is the kind of thing that the nerubians might find appetizing. Placing the sticky organism in your pack, you determine to find out...", objectives = "You are to collect 6 Grotesque Fungus from Savage Cave Beasts in Ahn'kahet and deliver them to Kilix the Unraveler in The Pit of Narjun.", progress = "What in creation are these?!", completion = "Do you have any idea what you've been carrying around, <class>?\n\nThe cave beasts you've been harvesting have no traditional method of excreting their waste. You might want to wash your hands...\n\nThank you for the thought, but if you come across any more of these please keep them for yourself." }
WordHunterWoW_QuestEN[13205] = { title = "Disarmament", description = "Take it from me, <lad/lass>, them vrykul weapons be downright nasty!\n\nI've felt their edge personally, and there be somethin' unnatural about 'em. Deceptively well-balanced, wickedly sharp - just plain deadly.\n\nGet into their stronghold and if nuthin' else, pilfer some o' them weapons! Mebbe we can learn us a thing 'er two about 'em, mebbe not.\n\nBottom line - the fewer axes they be swingin' around, the better.", objectives = "Defender Mordun wants you to enter Utgarde Keep and steal 5 Vrykul Weapons", progress = "You pinch a load a' them vrykul axes?", completion = "<Mordun whistles.>\n\nWill ya just look at 'em? Incredible.\n\nI half expected these neanderthals to be swingin' around clubs and throwin' rock.\n\nNo such luck..." }
WordHunterWoW_QuestEN[13206] = { title = "Disarmament", description = "We must discover the secret to these savages' weapons!\n\nIf you'd have seen how easily they cut through my companions, you'd understand my sense of urgency.\n\nScour the place. Gather all of their arms that you can carry.", objectives = "Dark Ranger Marrah wants you to steal 5 Vrykul Weapons from Utgarde Keep and bring them to her inside Utgarde Keep.", progress = "What have you got there, <class>?", completion = "Marrah has informed us of the superiority of the Vrykul's weaponry. We'll have a look at these and see if there's anything to learn.\n\nTake this for your trouble, <class>." }
WordHunterWoW_QuestEN[13207] = { title = "Halls of Stone", description = "Well now, I'm surprised to see other adventurers in a place such as this.\n\nIf my research on these halls is accurate, there be monumental discoveries to be made here!\n\nAssumin' I can count on ya to watch my back, you're welcome to tag along.", objectives = "Brann Bronzebeard wants you to accompany him as he uncovers the secrets that lie in the Halls of Stone.", progress = "Well, now, it turned out ta be a good thing we ran into each other after all.", completion = "Always more questions than answers, eh, lad?" }
WordHunterWoW_QuestEN[13210] = { title = "Blizzard Account: - DEM - E - FLAG", description = "", objectives = "" }
WordHunterWoW_QuestEN[13211] = { title = "By Fire Be Purged", description = "The Scourge uses our own fallen against us, by raising them as ghouls or skeletons, or by dismembering their corpses and using the parts to make abominations. This must stop!\n\nThe dead are heroes who fell in defense of all the living, and they cannot be confined to so grisly a fate. Moreover, we cannot afford to face them again on the field, used as weapons against us. Take this torch with you to the Fleshwerks, and burn any of the corpses you find in the Sanctum of Reanimation or the abomination lab.", objectives = "Crusader Olakin Sainrith at Blackwatch wants you to burn 7 Festering Corpses using Olakin's Torch.", completion = "<Crusader Olakin Sainrith listens solemnly to your report.>\n\nIt is not the burial they deserved, but it is better than nothing, and better for those who yet live. Thank you, <name>." }
WordHunterWoW_QuestEN[13212] = { title = "He's Gone to Pieces", description = "With the abduction of Crusader Olakin, the Argent Crusade's forces will have no commander in the final assault on the Fleshwerks. While one crusader is the same as any other to me, the argents won't see it that way.\n\nI hate to see us waste time chasing after this, but I have no choice. Our gallant crusader has likely been dismembered by now, and his remains used to construct abominations. Go down into the Fleshwerks, kill the corpulent horrors fighting our forces, and recover Olakin's body parts.", objectives = "Recover Olakin's Torso, Olakin's Legs, Olakin's Left Arm, and Olakin's Right Arm and bring them to Darkrider Arly at Blackwatch.", progress = "Have you recovered the, uh, remains of Crusader Olakin?", completion = "Well, I suppose it's good that we've \"recovered\" the crusader, though I doubt his comrades had this in mind. Let's see what we can do to get him back on his feet so we can get this charade over with and complete our mission here." }
WordHunterWoW_QuestEN[13213] = { title = "Battle at Valhalas", description = "I see and hear many things, {name}, and something very important has happened since your defeat of Overthane Balargarde: you are wanted for battle in Valhalas!\n\nYou will find the battle pit to the north. Go now with your friends and speak with Geirrvif the val'kyr. The challengers that she will offer you within Valhalas are sure to require their help.\n\nGood luck.", objectives = "Speak with Geirrvif in Valhalas.", completion = "You have bested our finest warriors. Your name is renowned, <name>.\n\nPerhaps you think that this concerns me: it does not. If they can fall to you then they are not worthy and should be nothing but lowly vargul!\n\nBut perhaps I can give you and your friends different sport. Valhalas is also a place for combat of all types with many different kinds of foes.\n\nSpeak to me again when you and your friends are ready to proceed. We shall see if you are truly worthy." }
WordHunterWoW_QuestEN[13214] = { title = "Battle at Valhalas: Fallen Heroes", description = "If you believe yourself ready to begin then I have just the match for you to cut your teeth on.\n\nAnother group of outsiders thought themselves prepared for the rigors of Valhalas. They had much hubris, but in the end they fell like all of the others.\n\nIf you think yourselves so different -- if you think that you have the skill and experience to fight here amongst such storied warriors -- then please accept the challenge.", objectives = "Geirrvif at Valhalas has challenged you to, in a single combat, defeat all six of the fallen heroes: Eldreth, Geness Half-Soul, Jhadras, Masud, Rith, and Talla.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "New blood.\n\n<The vrykul death knight spits on the ground at your feet.>\n\nYou all think that you have what it takes to fight here.\n\nYou are nothing before the might of the vrykul and the Scourge!\n\nStill, you did manage to defeat six incompetent corpses, so you must have some skill in you. Not likely enough for the next challenge though." }
WordHunterWoW_QuestEN[13215] = { title = "Battle at Valhalas: Khit'rix the Dark Master", description = "A variety of beings travel the world to prove themselves within Valhalas. Some even come from under the world.\n\nKhit'rix the Dark Master is one such.\n\nHailing from deep within the ground where insanity reigns, Khit'rix has asked for someone exotic to face in the ring. You will do.\n\nDare you face this Nerubian nightmare, {race}?", objectives = "Geirrvif at Valhalas has challenged you to defeat Khit'rix the Dark Master.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "You want me to be impressed by the fact that you and your friends were able to bring down a lone Nerubian priest?\n\nGet out of my sight before I summon my ghouls upon you!" }
WordHunterWoW_QuestEN[13216] = { title = "Battle at Valhalas: The Return of Sigrid Iceborn", description = "An old foe of yours has returned: Sigrid Iceborn. Perhaps you remember besting her in a duel upon the Savage Ledge?\n\nNo matter, she certainly remembers you. She's insisting upon a chance to prove herself once more.\n\nPersonally, I think it's more a chance for revenge, but that too can be useful in this place.\n\nI leave it up to you, {name}. Will you face Sigrid Iceborn once more?", objectives = "Geirrvif at Valhalas has challenged you to defeat Sigrid Iceborn.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "The defeat of one of the hyldnir is mildly impressive, <race>, but you did have the help of your friends.\n\nYou're lucky that her drake didn't get involved." }
WordHunterWoW_QuestEN[13217] = { title = "Battle at Valhalas: Carnage!", description = "You've been successful up to this point, {name}, but what you must face to continue to battle within Valhalas is a gigantic horror beyond imagining.\n\nI must warn you to turn away now. Carnage is a mountain of flesh constructed by the Lich King's most fiendish minds.\n\nI do not see how you and your friends will defeat it. However, the choice is yours.", objectives = "Geirrvif at Valhalas has challenged you to defeat Carnage.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "I'm starting to respect your prowess in the ring, <name>. Now I really don't like you.\n\nI would much rather have preferred to see you and your friends stuck to the bottom of that flesh giant's foot!" }
WordHunterWoW_QuestEN[13218] = { title = "Battle at Valhalas: Thane Deathblow", description = "Your skills have not gone unnoticed by the vrykul of Jotunheim, {name}. Thane Banahogg has taken a personal interest in you and has insisted that he be your next match.\n\nIf you thought Carnage was bad, then you might want to go home now. Thane Banahogg's nickname is The Deathblow. I think you can guess how he earned it.\n\nDo you accept the thane's challenge?", objectives = "Geirrvif at Valhalas has challenged you to defeat Thane Banahogg, the Deathblow.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "I don't know what trickery it was that you used to bring down the thane -- I couldn't see it from this angle -- but I can assure you that you will not survive your next match.\n\nYes, I know who it is. Run, little <race>. Flee to the far corners of the world.\n\nOr stay and die. It matters little to me." }
WordHunterWoW_QuestEN[13219] = { title = "Battle at Valhalas: Final Challenge", description = "I'm afraid that your success is going to be your undoing, {name}.\n\n<If the val'kyr could turn more white, she would.>\n\nWord of your success in Valhalas has reached deep into Icecrown Citadel, stirring one whom you have no desire to meet.\n\nPrince Sandoval himself is on his way at this very moment. Gjonner warned you that you should run and I cannot disagree.\n\nWhat will you do? He's on his way. Will you face the blood prince in final battle?", objectives = "Geirrvif at Valhalas has challenged you to defeat Prince Sandoval.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "Your defeat of Prince Sandoval sickens me. An unwashed peasant such as yourself should have willingly given over his life simply for the chance to meet him and kneel at his feet.\n\nYou've earned your damned reward. Be quick about your choosing." }
WordHunterWoW_QuestEN[13220] = { title = "Putting Olakin Back Together Again", description = "We can't afford to waste any time putting Olakin back together. Fortunately, the Scourge has provided a perfect place for you to stitch him back together.\n\nNear the Fleshwerks' flesh giant lab is the Sanctum of Reanimation. Search the area for a spool of thread and the doctor's cleaver. Then, take Olakin's remains to the large slab in the middle of the sanctum and get to work.", objectives = "Obtain a Spool of Thread and the Doctor's Cleaver, then take them to the Sanctum of Reanimation Slab and use Olakin's remains to attempt to reanimate the crusader. Return to Darkrider Arly at Blackwatch when this task is complete.", progress = "Have you put our brave crusader back together?", completion = "Olakin should consider himself fortunate. No one is rescued from the Scourge, no one. No amount of thread and heroism will save him a second time. I'll make certain he remembers it." }
WordHunterWoW_QuestEN[13221] = { title = "I'm Not Dead Yet!", description = "The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape.\n\nI cannot make it on my own, my child, but with your help, I may yet live to fight the Scourge again.\n\nWill you help me make my escape before the Scourge's butchers come to finish me off?", objectives = "Escort Father Kamaros to safety and then report to Absalan the Pious aboard the Skybreaker.", completion = "Thank the Light. I'd thought Father Kamaros dead, or worse. Through your bravery and compassion, you have restored a great ally to the Argent Crusade. You have my thanks and those of the crusade." }
WordHunterWoW_QuestEN[13222] = { title = "Defend the Siege", description = "Front and center, {name}! We're beginning our assault on Wintergrasp Fortress. Those Horde animals think they can hide cowardly behind their walls? Well, I think not! We'll show them the power of Gnomish technology and smash their walls to bits!\n\nHowever, even the most powerful siege device is helpless without a crew. Pilot or protect one of our siege vehicles as it destroys three of the Horde structures.", objectives = "Senior Demolitionist Legoso in Wintergrasp wants you to pilot or protect a siege device as it destroys three structures.\n\nPlayers of private rank or higher can build siege devices at Goblin Workshops.", completion = "That should show them the power of Gnomish invention!" }
WordHunterWoW_QuestEN[13223] = { title = "Defend the Siege", description = "Dem Alliance won't be long to hold that keep. Murp would smash walls, but Murp has to stay in camp. Murp wish he could smash Alliance who want to hurt Horde demolishers.\n\nYou, {name}! You go in Murp's place. Protect 3 siege vehicles while they smash Alliance buildings. Alliance not expect you to defend demolisher. Show Alliance how smart Murp is! ", objectives = "Lieutenant Murp in Wintergrasp wants you to defend or pilot a siege vehicle while they destroy three Alliance structures.\n\nSiege devices can be built by ranked Horde players at the Goblin Workshops.", completion = "Good job. Murp wish he was there to help." }
WordHunterWoW_QuestEN[13224] = { title = "Orgrim's Hammer", description = "The Argent Crusade pulled my ravaged body from the Broken Front. What a glorious battle, {race}. My axe sang as it cut down Alliance filth and Scourge alike.\n\nMy time is over. It will be a good death. Carry a message for me, soldier.\n\nOur base flies out of reach of Scourge - overhead between Mord'rethar and Aldur'thar. It is called \"Orgrim's Hammer.\"\n\n<Hork futilely attempts to salute.>\n\nFly high and avoid the Alliance juggernaut, Skybreaker. Tell Korm... tell him I died... fighting... For the Horde.", objectives = "Seek out Sky-Reaver Korm Blackscar aboard Orgrim's Hammer flying above Icecrown.", completion = "<Korm salutes.>\n\nDamn the Scourge and damn the Alliance! Hork was one of our best. We will have our revenge. For Hellscream and for the Horde!" }
WordHunterWoW_QuestEN[13225] = { title = "The Skybreaker", description = "We were neck deep in Scourge and Horde. The screams of the dying covered that field. It was torturous... unrelenting!\n\nAt some point my body gave out. I fell, only to be awoken by the Argent Crusade. They pulled me out of the Broken Front and brought me here. I'm not going to make it. Grant a dying soldier one last wish, {race}? Our base, the Skybreaker, flies high above Icecrown. It is there that you'll find my commanding officer, High Captain Bartlett. Tell him that I died a soldier of the Alliance.", objectives = "Seek out High Captain Justin Bartlett aboard the Skybreaker flying above Icecrown.", completion = "<Captain Bartlett salutes.>\n\nHe was a damn fine soldier. Damn the Horde and damn the Scourge!" }
WordHunterWoW_QuestEN[13226] = { title = "Judgment Day Comes!", description = "We cannot defeat the Lich King on our own. Divided we shall all fall!\n\nI implore you to answer the call, brother. The Argent Crusade accepts all who would volunteer to aid in the war effort. Highlord Tirion Fordring himself awaits you at the Argent Vanguard! Get upon your mount and fly to the southeastern reaches of Icecrown. It is there that you will find Lord Fordring and the soldiers of the Argent Crusade.\n\nGo now, {class}, for judgment day comes!", objectives = "Report to Highlord Tirion Fordring at the Argent Vanguard in Icecrown.", completion = "My faithful knights have served me well. It seems that their recruitment efforts have yielded a hero!" }
WordHunterWoW_QuestEN[13227] = { title = "Judgment Day Comes!", description = "We cannot defeat the Lich King on our own. Divided we shall all fall!\n\nI implore you answer the call, brother. The Argent Crusade accepts all that would volunteer to aid in the war effort. Highlord Tirion Fordring himself awaits you at the Argent Vanguard! Get upon your mount and fly to the southeastern reaches of Icecrown. It is there that you will find Lord Fordring and the soldiers of the Argent Crusade.\n\nGo now, {class}, for judgment day comes!", objectives = "Report to Highlord Tirion Fordring at the Argent Vanguard in Icecrown.", completion = "My faithful knights have served me well. It seems that their recruitment efforts have yielded a hero!" }
WordHunterWoW_QuestEN[13228] = { title = "The Broken Front", description = "What battle?! Those troops were on a recon mission!\n\nAnd what's this talk of Alliance - you're sure he said Alliance?\n\nListen to me, {name}! I need to know what's going on and I need to know NOW!\n\nGet yourself down there and get me some answers! Scour the battlefield and look for survivors - clues - anything!", objectives = "Korm Blackscar on Orgrim's Hammer wants you to go to The Broken Front and question a Dying Berserker to discover what happened there.", completion = "They saw the Alliance assaulting the gate and they attacked them from behind...\n\n<After a brief pause, Korm bursts into laughter.>\n\nTHAT is what it means to be HORDE!\n\nWere it not for them, the Alliance maggots would likely be holding that gate!\n\nTheir boldness has bought us precious time." }
WordHunterWoW_QuestEN[13229] = { title = "I'm Not Dead Yet!", description = "The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape.\n\nI cannot make it on my own, {class}, but with your help, I may yet live to fight the Scourge again.\n\nWill you help me make my escape before the Scourge's butchers come to finish me off?", objectives = "Escort Father Kamaros to safety and then report to Brother Keltan aboard Orgrim's Hammer.", completion = "You have done well. We thought Father Kamaros lost, for certain. Your bravery will serve as an example to all those who oppose the Scourge." }
WordHunterWoW_QuestEN[13230] = { title = "Avenge Me!", description = "I hear them, brother....\n\nThe moans of the wounded Alliance... they taunt me...\n\nFinish what we have begun here, {class}. Show no mercy... let none of them survive.\n\nFor... the Horde...", objectives = "A Dying Berserker has asked that you slay 5 Dying Soldiers at the Broken Front. Report to Sky-Reaver Korm Blackscar on Orgrim's Hammer when it is done.", completion = "The time of tolerance for the Alliance has passed, <name>.\n\nThey have earned our hatred! They shall live in fear of the Horde until they no longer pollute our world!" }
WordHunterWoW_QuestEN[13231] = { title = "The Broken Front", description = "What?! Noooo!\n\nWe went to such great pains to keep this attack secret. How could the Horde have known? The resources... the men... all lost? Inconceivable!\n\nOur plans here in Icecrown hinged upon our taking that gate before the Horde could. We must recover quickly and prepare to mount another offensive.\n\nVisit the battlefield and search for any survivors. See if there's anything to be learned from this tragedy.\n\nAnd prepare yourself, {name}, for a war - on two fronts...", objectives = "High Captain Justin Bartlett aboard the Skybreaker wants you to go to the Broken Front and question a Dying Soldier, then report back to him.", completion = "So... It was a rout - a total loss. This shall not be forgotten.\n\nMark my words, <class>. The Horde shall pay for this... there will be no mercy!" }
WordHunterWoW_QuestEN[13232] = { title = "Finish Me!", description = "They taunt us - even as they lie dying here...\n\nPlease, brother... Don't allow their mocking to be the last sounds I hear...\n\nFinish me... deliver me from this torment... into... the Light.\n\nSeek out  my companions... offer them the same mercy.\n\nLeave nothing for the Scourge to raise!\n\nI beg you...", objectives = "A Dying Soldier in the Broken Front wants you to kill 5 Dying Soldiers and report to High Captain Justin Bartlett on the Skybreaker.", completion = "That was a difficult thing you did, <class>. But it was the right thing.\n\nDon't allow the memory of your actions to haunt you. Harness that sorrow and pain you feel! Direct it at those who caused it.\n\nThe Horde must pay!" }
WordHunterWoW_QuestEN[13233] = { title = "No Mercy!", description = "It is as I told you. They were not merely idle words spoken in a fit of anger.\n\nTime and again, the Horde have demonstrated their disdain for everything we hold dear and holy. They must pay with their lives for their transgressions against the light.\n\nAll of them.\n\nJust imagine a world free of their stain, {name}. Envision the joy our children will know. Think of the reverence your descendants will have for your memory, knowing they owe their happiness to you.\n\nNow go, and make that vision a reality!", objectives = "High Captain Justin Bartlett aboard the Skybreaker wants you to kill 15 Horde Players in Icecrown.", completion = "Well done, <name>!\n\nHunt them down and make them pay!" }
WordHunterWoW_QuestEN[13234] = { title = "Make Them Pay!", description = "The time has come!\n\nToo long have we suffered the company of the self-righteous Alliance! Too long have we stayed our hand from cleansing our world of the weak and the desperate.\n\nNow, we bring an end to our humiliation! Now, we show them the true meaning of fear! Now, we bring honor to the Horde!\n\nHere, at Icecrown, we break the Alliance!\n\nGo, {class}. Hunt them down. Break them. Take their will to live!", objectives = "Sky-Reaver Korm Blackscar wants you to kill 15 Alliance Players in Icecrown.", completion = "You have done well, <class>.\n\nSoon, the Alliance shall run from you in fear and the Horde shall honor your name!" }
WordHunterWoW_QuestEN[13235] = { title = "The Flesh Giant Champion", description = "You've done well in destroying the Fleshwerks and slaughtering the Lich King's servants. Now, all that remains is to defeat the Fleshwerks' greatest accomplishment -- the flesh giant known as Morbidus.\n\nIt will not be an easy fight, but the Shadow Vault has dispatched Margrave Dhakar with some reinforcements. Meet up with him at the highest point at the western end of the Fleshwerks. Tell him when you're ready to begin the attack and he'll order his forces into battle.", objectives = "Speak with Margrave Dhakar at the western end of the Fleshworks to engage Morbidus. After you have defeated Morbidus, report to Darkrider Arly at Blackwatch.", completion = "With the Lich King's flesh giant champion defeated, he must know that the rest of his forces are vulnerable as well. With you by our side, we will teach the Lich King the meaning of fear once more." }
WordHunterWoW_QuestEN[13236] = { title = "Army of the Damned", description = "You probably think you're quite strong -- fighting these undead and crushing their bones beneath your war machines.\n\nThat is nothing compared to the strength it took to create them.\n\nI saw the prince do it himself.  I can show you how it happened... if you'd like.", objectives = "Matthias Lehner at the First Legion Forward Camp wants you to raise an army of 100 Ghoulish Minions.", progress = "Did you see, <name>?", completion = "The prince's true power wasn't his ability to make armies out of corpses... that was easy.\n\nBut killing his own men, with whom he'd shared many battles... the prince's true power was his ability to do what had to be done." }
WordHunterWoW_QuestEN[13237] = { title = "Poke and Prod", description = "While your commander has his focus diluted by his loathing of your Alliance rivals, you can depend on me to direct my attention squarely on the real enemy here - the Lich King and his minions.\n\nIn order to hold any hope of conquering him at the citadel, your people must take and hold each gate.\n\nFor now, let us focus on the first. Return to the front and prod their defenses. Look for any sign of weakness that we might exploit.\n\nI'll await your report, {class}.", objectives = "Koltira Deathweaver aboard Orgrim's Hammer wants you to go the Broken Front and defeat 5 Hulking Abominations, 5 Malefic Necromancers, and 5 Shadow Adepts.", completion = "Really, <class>?\n\nNothing notable to report?\n\n\n\nI beg to differ..." }
WordHunterWoW_QuestEN[13238] = { title = "Good For Something?", description = "Goblins! Hyper little busy-bodies...\n\nListen, {name}. Copperclaw, our resident engineer, is insisting that he's got something useful to show me.\n\nI'm in no mood to endure his squeaky nagging. The last time I acknowledged him, he chirped on for an hour straight. It was all I could do to keep from drop-kicking him into Sindragosa's Fall!\n\nYou go in my place and humor him. Let me know if indeed he's on to anything.", objectives = "Sky-Reaver Korm Blackscar wants you to speak with Chief Engineer Copperclaw aboard Orgrim's Hammer.", completion = "Too busy? Phooey! This baby flies herself!\n\nNevermind that. You'll do..." }
WordHunterWoW_QuestEN[13239] = { title = "Volatility", description = "Where to begin... well, you must know that as chief engineer of this vessel I have access to all of the intelligence reports - yes, yes, it's true, and I've recently taken a particular interest in the frostwyrms you reported seeing to the south, and I do believe I've developed a plan that just might work against them... now it'll take a little legwork on your part, but essentially, you build a dummy out of armor and coat it with a splash of this solution, then run for cover!\n\n...You still here, {race}?", objectives = "Chief Engineer Copperclaw wants you to use Copperclaw's Volatile Oil at the Broken Front to attract 3 Frostbrood Skytalons.\n\nTo use the oil, you must collect a Pile of Bones, an Abandoned Helm, and Abandoned Armor from the battlefield there.", completion = "Wahooo! I saw them light up all the way from here! I'll just chalk that up as another success and begin bottling this stuff up for the invasion - of course it might need a little more testing as we go if you're at all interested...." }
WordHunterWoW_QuestEN[13240] = { title = "Timear Foresees Centrifuge Constructs in your Future!", description = "It is into the Oculus floating above Coldarra that you must travel, <name>.\n\nI have foreseen a situation in which you must destroy the centrifuge constructs therein. I can assure you that if you do not first eliminate these magical creations, you and your friends will fail.\n\nThus I have seen, thus you must do.You will be able to choose one of these rewards:", objectives = "Archmage Timear in Dalaran has foreseen that you must destroy 10 Centrifuge Constructs." }
WordHunterWoW_QuestEN[13241] = { title = "Timear Foresees Ymirjar Berserkers in your Future!", description = "King Ymiron's champions stand between you and victory in the not-too-distant future.\n\nYou will travel to the fortress known as Utgarde Pinnacle nestled deep within the woods of the Howling Fjord. I cannot stress how important it is that you and your traveling companions deal with the Ymirjar berserkers therein.\n\nFailure to do so may very well doom you, <name>!You will be able to choose one of these rewards:", objectives = "Archmage Timear in Dalaran wants you to slay 7 Ymirjar Berserkers." }
WordHunterWoW_QuestEN[13242] = { title = "Darkness Stirs", description = "Darkness stirs, <name>. A tragic event has transpired that none but the Timeless One could have foreseen. Soon your people will be gripped by anger and hatred. War is on the horizon.\n\nThe red dragonflight has done all that it can. What happens next is in the hands of the mortal races of Azeroth.\n\nRegrettably, your journey begins with anguish. A father has lost a child today. You must bear the grim news. Gather the armaments of Saurfang and return them to the elder Saurfang.", objectives = "Gather Saurfang's Battle Armor from the field of battle and return it to High Overlord Saurfang at Warsong Hold in Borean Tundra.", progress = "<Saurfang's face contorts.>\n\nMy heart... my strength...", completion = "<Saurfang looks to the heavens.>\n\nLike Brox, my son died a hero. Do not mourn him, <name>. For an orc, there could be no better end! No greater honor! At this moment, my heart swells with pride.\n\nI thank you for returning our battle armor. It will be placed upon his pyre at the Ancestral Grounds of Nagrand.\n\nWe must turn our full attention to more pressing matters." }
WordHunterWoW_QuestEN[13243] = { title = "Timear Foresees Infinite Agents in your Future!", description = "The timeline is in danger from the Infinite dragonflight. Without your intervention, all of time will unravel!\n\nYou must travel to a point in time known as the Culling of Stratholme within the Caverns of Time.\n\nIt gives me a migraine just to attempt to see into all of the possible pasts, but I do know that it is crucial for you to kill the Infinite agents.\n\nOnly by slaying them will the true past be preserved and the present and future kept from being undone forever!You will be able to choose one of these rewards:", objectives = "Archmage Timear in Dalaran has foreseen that you must slay 4 Infinite Agents." }
WordHunterWoW_QuestEN[13244] = { title = "Timear Foresees Titanium Vanguards in your Future!", description = "The entirety of Azeroth is in peril. The mad god Loken has it within his power to put an end to everything!\n\nWithin the Terrestrial Watchtower at the Halls of Lightning, the titanium vanguards stand poised to execute Loken's dread will upon countless unknowing victims.\n\nI have looked into the future, <name>. You are the one to see that this does not come to pass!You will be able to choose one of these rewards:", objectives = "Archmage Timear in Dalaran has foreseen that you must slay 7 Titanium Vanguards." }
WordHunterWoW_QuestEN[13245] = { title = "Proof of Demise: Ingvar the Plunderer", description = "I need you to assemble a group and lead them into Utgarde Keep. Therein, you are to find and slay Ingvar the Plunderer before he can lead his vrykul forces to sack the nearby Alliance and Horde towns.\n\nI require his axe as proof that he has been dealt with. It's not that I don't trust you. It's simply prudent to be certain that the deed has been done.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Axe of the Plunderer.\n\nThis quest may only be completed on Heroic difficulty." }
WordHunterWoW_QuestEN[13246] = { title = "Proof of Demise: Keristrasza", description = "Are you familiar with the story of Keristrasza?\n\nHow she was instrumental in the slaying of Saragosa, the mate of Malygos? How, in turn, he took Keristrasza as his consort, freezing her within a block of ice?\n\nWe have become aware that Malygos has been using his magic to break her will. This has driven her insane.\n\n<name>, you must go into the Nexus in Coldarra and put an end to her before she can be fully turned.\n\nThough it saddens me, I must insist that you bring me her heart as proof.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Archmage Lan'dalock in Dalaran wants you to return with Keristrasza's Broken Heart.\n\nThis quest may only be completed on Heroic difficulty." }
WordHunterWoW_QuestEN[13247] = { title = "Proof of Demise: Ley-Guardian Eregos", description = "The Nexus War rages on and we must do something to turn the tide! Are you willing to fly into the heart of the battle, <name>?\n\nLey-Guardian Eregos is the protector of the conduit through which Malygos is funneling the magical power of Azeroth's ley lines. If he can be slain it will be a great blow to the enemy.\n\nPlease bring me one of his ley line tuners so that we might study it.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Archmage Lan'dalock in Dalaran wants you to return with a Ley Line Tuner.\n\nThis quest may only be completed on Heroic difficulty." }
WordHunterWoW_QuestEN[13248] = { title = "Proof of Demise: King Ymiron", description = "King Ymiron of Utgarde Pinnacle is the favored vrykul of the Lich King. That alone is reason enough to put an end to him.\n\nBut should he blow the horns and call for all of the leaders of the ymirjar and mjordin alike, the vrykul will become a force more powerful than any other within the Scourge!\n\nIt is up to you, <name>, to see to it that this does not come to pass. Bring me the locket from around his neck so that I will know that Ymiron no longer poses a threat.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Locket of the Deceased Queen.\n\nThis quest may only be completed on Heroic difficulty." }
WordHunterWoW_QuestEN[13249] = { title = "Proof of Demise: The Prophet Tharon'ja", description = "Drak'Tharon Keep once stood as a proud bastion of the Drakkari nation. Now it is nothing more than a stepping stone for the Lich King in his fight to put an end to Zul'Drak and steal the powers of the troll gods.\n\nBut if we were to eliminate their leader, the Prophet Tharon'ja, perhaps we could stop the flow of Scourge troll reinforcements. At the very least this would give the Argent Crusade in Zul'Drak one less thing to worry about.\n\nReturn to me with his tiki so I will know the prophet is slain.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Prophet's Enchanted Tiki.\n\nThis quest may only be completed on Heroic difficulty." }
WordHunterWoW_QuestEN[13250] = { title = "Proof of Demise: Gal'darah", description = "The Drakkari prophets of Zul'Drak have done the unthinkable: they've slain most of their gods to absorb their powers! The most dangerous of all is the High Prophet of Akali, Gal'darah.\n\nSequestered within the bowels of Gundrak, Gal'darah has absorbed almost all of the mojo from slain Akali and now stands poised to erupt with his followers from the city. If we do not kill him now, we will be awash in a sea of madness and unthinkable power!\n\nHurry, <name>, bring me what's left of Akali's mojo.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Mojo Remnant of Akali.\n\nThis quest may only be completed on Heroic difficulty." }
WordHunterWoW_QuestEN[13251] = { title = "Proof of Demise: Mal'Ganis", description = "<name>, a friend within the bronze dragonflight has given me information that we must exploit.\n\nThe mysterious beings of the Burning Legion called the dreadlords are also known racially as the Nathrezim. Little is known of their homeworld and even that is rumor.\n\nHowever, it is known that Mal'Ganis of the past has made a critical error: he left behind an artifact from his homeworld!\n\nThrough the Caverns of Time, you must travel back to the time known as the Culling of Stratholme. Recover the artifact.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Artifact from the Nathrezim Homeworld.\n\nThis quest may only be completed on Heroic difficulty." }
WordHunterWoW_QuestEN[13252] = { title = "Proof of Demise: Sjonnir The Ironshaper", description = "Little is understood about the condition known as the Curse of Flesh. However, there is information to be had within the Halls of Stone.\n\nSjonnir The Ironshaper seems to know a great deal with regard to the curse. We have it on good authority that he is carrying a Titan disc of information upon him that could answer all of our questions.\n\nRetrieve this disc for me, <name>, so that we may learn.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Curse of Flesh Disc.\n\nThis quest may only be completed on Heroic difficulty." }
WordHunterWoW_QuestEN[13253] = { title = "Proof of Demise: Loken", description = "Within the Halls of Lightning, Loken is poised to put an end to our world. Need I say more, <name>?\n\nHe sits there listening to the mad whisperings of the Old God trapped beneath Northrend. You and your friends must travel to the Storm Peaks immediately!\n\nConfront Loken within the Terrestrial Watchtower and stop him before it is too late! Bring me his ruby ring so that I will know we are safe once more.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Celestial Ruby Ring.\n\nThis quest may only be completed on Heroic difficulty." }
WordHunterWoW_QuestEN[13254] = { title = "Proof of Demise: Anub'arak", description = "The Scourged nerubians are a plague upon our forces.\n\nWhile we are safe from them here, floating above the world, when we set foot upon the land below, it is always with the thought that the undead nerubians could burrow up from the depths of Azjol-Nerub and attack.\n\nIt's in the best interests of everyone if they are thrown into a state of disarray. Kill their former king, and major-domo to the Lich King, the crypt lord, Anub'arak.\n\nPlease bring me his crown... not that he wears it any longer.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Idle Crown of Anub'arak.\n\nThis quest may only be completed on Heroic difficulty." }
WordHunterWoW_QuestEN[13255] = { title = "Proof of Demise: Herald Volazj", description = "The nerubians of Ahn'kahet dug too deep during their attempt to escape the invasion of the Scourge. They got too close to the Old God under Northrend.\n\nRousing its awareness, the Old God sent its insane creatures against them, and the nerubians were caught between the proverbial rock and a hard place.\n\nThe leader of the Old Gods' forces, Herald Volazj is one of the nightmarish beings known as The Faceless. Put an end to him and bring me his withered brain.\n\nJust please, try to keep your sanity.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Faceless One's Withered Brain.\n\nThis quest may only be completed on Heroic difficulty." }
WordHunterWoW_QuestEN[13256] = { title = "Proof of Demise: Cyanigosa", description = "We're being invaded! The blue dragonflight has teleported into the Violet Hold and they're planning on breaking out from there into the rest of Dalaran!\n\nThere have already been reports of prisoners inadvertently being freed by their actions. It wouldn't surprise me if they're purposefully letting some of them free.\n\n<name>, can you assemble your team quickly and get in there? Cyanigosa is the leader of their invasion force. Bring me her head!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Archmage Lan'dalock in Dalaran wants you to return with the Head of Cyanigosa.\n\nThis quest may only be completed on Heroic difficulty." }
WordHunterWoW_QuestEN[13257] = { title = "Herald of War", description = "The Warchief needs you, champion. Orgrimmar is in a state of martial law. All merchants and services have been shut down as the Warchief prepares for an unavoidable conflict.\n\nI cannot tell you much more - not now. Not in this place.\n\nThe Warchief commands that our strongest champions report to his throne room. Go now, <name>! Take the portal back to Orgrimmar and seek out Thrall.", objectives = "Report to Thrall at Grommash Hold in Orgrimmar.The Warchief needs you, champion. Orgrimmar is in a state of martial law. All merchants and services have been shut down as the Warchief prepares for an unavoidable conflict.\n\nI cannot tell you much more - not now. Not in this place.\n\nThe Warchief commands that our strongest champions report to his throne room. Go now, <name>! Take the portal back to Orgrimmar and seek out Thrall.", completion = "The demon lord, Varimathras, and the Forsaken's chief apothecary, Putress, are responsible for this betrayal.\n\n<Thrall nods.>\n\nYes, the same Putress responsible for discovering the cure for the recent Scourge plague outbreak.\n\nThose that would not side with their regime have been executed or banished. Sylvanas was nearly killed in the coup.\n\nThe Horde has lost the Undercity. Orgrimmar will take on the Forsaken refugees until there is a resolution to this crisis. For now we are under martial law." }
WordHunterWoW_QuestEN[13258] = { title = "Opportunity", description = "We recently came upon schematics that indicate a weakness in Icecrown Citadel.  An opening in its defenses, both figuratively and literally.\n\nThe captured diagrams show an orifice leading several hundred feet into the ground.  We're unsure of its purpose, but our scouting has revealed it to be of high importance to the Scourge.\n\nSpeak to Sergeant Kregga below Icecrown Citadel, she's leading the attack on the site.", objectives = "Speak to Sergeant Kregga below Icecrown Citadel.", completion = "Just in time, <name>.  Koltira spoke highly of you.  Perhaps you'll be able to push the scales in our favor." }
WordHunterWoW_QuestEN[13259] = { title = "Establishing Superiority", description = "We've one shot at dealing some damage to this place -- let's make sure we get it right.\n\nWe've acquired potent, Scourge-made, saronite bombs.  But we must secure this area before we can set them off.\n\nWe're going to need to get the Scourge defenses under control quickly, before reinforcements arrive.\n\nHelp my men out and come back when you're ready for some fireworks.", objectives = "Sergeant Kregga at Icecrown Citadel wants you to slay 10 Hulking Horrors.", completion = "You made quick work of the Scourge, <name>.  Let's finish what we came to do here." }
WordHunterWoW_QuestEN[13260] = { title = "Takes One to Know One", description = "While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge.\n\nWe won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses.\n\nI have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they?\n\nAllow me to introduce Koltira Deathweaver.\n", objectives = "Sky-Reaver Korm wants you to speak to Koltira Deathweaver on Orgrim's Hammer.", completion = "<Koltira looks you up and down.>\n\nI hope for your sake that you're up to this, <class>." }
WordHunterWoW_QuestEN[13261] = { title = "Volatility", description = "Wahooo! It works! Not that I had any doubts in my supernatural ingenuity, only that I wasn't quite sure what kind of explosion to expect - let's just say I'm glad to see that you didn't get your eyebrows singed off. So now I just need to show ol' Korm how ya thaw out one 'a them wyrms. He'll hafta promote me to... to... to whatever comes after Chief Engineer! Here, you take another batch of the stuff and head back out to the front and I'll go get Korm...\n\nWell? Move out!", objectives = "Chief Engineer Copperclaw wants you to use Copperclaw's Volatile Oil at the Broken Front to attract 3 Frostbrood Skytalons.\n\nTo use the oil, you must collect a Pile of Bones, an Abandoned Helm, and Abandoned Armor from the battlefield there.", completion = "No good!\n\nKorm kept telling me he was too busy and when I finally got him to come topside and have a look, you had already used the last of the oil. Now he's ticked at me and won't even allow me in his presence again until tomorrow...\n\nCome back then and we'll try again!" }
WordHunterWoW_QuestEN[13262] = { title = "Blow it Up!", description = "This is probably as under-control as this situation is going to get.  Let's do this, {name}.\n\nI need someone to light the fuse on those bombs and it looks like you're the one to do it.", objectives = "Go to the nearby Saronite Bomb Stack to light the fuse.", completion = "These bombs look pretty potent.  They should at least put a dent in the surrounding structure." }
WordHunterWoW_QuestEN[13263] = { title = "A Short Fuse", description = "As you light the fuse, you notice that it is consumed by fire far quicker than you would expect.\n\nThe bombs are about to go off and your best chance at surviving is to lean towards the pit and hope the fall doesn't kill you.", objectives = "Look for clues wherever the fall takes you.", completion = "This pulsing object is covered in a thick layer of ice.  It shimmers strangely beneath the water." }
WordHunterWoW_QuestEN[13264] = { title = "That's Abominable!", description = "Abominations...\n\nThey can be a very capable enemy. I've seen them turn the tide of battle more than once. What few realize, is that they can also be very capable friends.\n\nThey are not deep thinkers. If you know the secrets of their creation, you can issue them basic orders that they will not question.\n\nFortunately for you, I know these secrets.\n\nThis kit will reanimate the remains of the abominations you defeat. Take it, and learn to use them against the Scourge on the death gate.", objectives = "Koltira Deathweaver on Orgrim's Hammer wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", completion = "You see, <class>?\n\nIngenuity can sometimes even the odds against a seemingly overwhelming enemy." }
WordHunterWoW_QuestEN[13265] = { title = "Cloth Scavenging", description = "The cut of your clothes suggests to me that you are a Tailor yourself and could easily learn the skill that I have to teach.\n\nMany of the northern humanoids wear clothes that can quickly be converted into cloth if you know the knack of doing it.\n\nFor a small fee I can teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", objectives = "The cut of your clothes suggests to me that you are a Tailor yourself and could easily learn the skill that I have to teach.\n\nMany of the northern humanoids wear clothes that can quickly be converted into cloth if you know the knack of doing it.\n\nFor a small fee I can teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", progress = "The cut of your clothes suggests to me that you are a Tailor yourself and could easily learn the skill that I have to teach.\n\nMany of the northern humanoids wear clothes that can quickly be converted into cloth if you know the knack of doing it.\n\nFor a small fee I can teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", completion = "Turn that extra cloth you find into something that looks marvelous!" }
WordHunterWoW_QuestEN[13266] = { title = "A Life Without Regret", description = "On the day of my death I wish to be able to say that I lived a life without regret. Those who mourn my passing will know that I was a Warchief who made decisions that best served his people.\n\nBut this betrayal by Varimathras and Putress... All that we have worked for is for nothing.\n\n<Thrall's chest heaves with a heavy sigh.>\n\nJustice must be served.\n\nPortals to Undercity will be active momentarily. Vol'jin will be waiting for you. I will meet you there soon. Together we will make it right, <name>.", objectives = "Take the portal to Undercity located in Grommash Hold and report to Vol'jin.On the day of my death I wish to be able to say that I lived a life without regret. Those who mourn my passing will know that I was a Warchief who made decisions that best served his people.\n\nBut this betrayal by Varimathras and Putress... All that we have worked for is for nothing.\n\n<Thrall's chest heaves with a heavy sigh.>\n\nJustice must be served.\n\nPortals to Undercity will be active momentarily. Vol'jin will be waiting for you. I will meet you there soon. Together we will make it right, <name>.", completion = "Let me get you up to speed, <name>.\n\nUndercity is a war-zone. Putress' apothecaries and Varimathras' demons have seized control. They've taken a defensive position inside and are using that damned blight against our troops." }
WordHunterWoW_QuestEN[13267] = { title = "The Battle For The Undercity", description = "The entirety of the Undercity is controlled by Varimathras. Our soldiers stand ready, waiting for the Warchief to give the attack orders.\n\nHelp the Horde take back the Undercity and earn your place among our greatest champions! Should you survive the assault, report to Thrall.\n\nCheck in with the Warchief when you are ready to begin.", objectives = "Assist Thrall and Sylvanas in retaking the Undercity for the Horde.\n\nReport to Thrall should you succeed.The entirety of the Undercity is controlled by Varimathras. Our soldiers stand ready, waiting for the Warchief to give the attack orders.\n\nHelp the Horde take back the Undercity and earn your place among our greatest champions! Should you survive the assault, report to Thrall.\n\nCheck in with the Warchief when you are ready to begin.", completion = "Tomorrow brings with it uncertainty. Gone are the days of Alliance and Horde battling alongside each other in pursuit of a common enemy. A new battle dawns, <name> - a battle in which there can be no victor.\n\nBut we must continue our march towards Icecrown. We have no choice in that matter. Our salvation lies with heroes like you, <name>. The future of the Horde - of the world - depends on you.\n\nLet us return to Orgrimmar. You must return to Northrend at once." }
WordHunterWoW_QuestEN[13268] = { title = "Cloth Scavenging", description = "You look like someone who knows their way around a needle and thread so maybe I can help you.\n\nThe northern humanoids wear clothes that can quickly be converted into cloth if you know how.\n\nFor a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", objectives = "You look like someone who knows their way around a needle and thread so maybe I can help you.\n\nThe northern humanoids wear clothes that can quickly be converted into cloth if you know how.\n\nFor a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", progress = "You look like someone who knows their way around a needle and thread so maybe I can help you.\n\nThe northern humanoids wear clothes that can quickly be converted into cloth if you know how.\n\nFor a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", completion = "Come back when you have the skill and I can provide all of your tailoring training." }
WordHunterWoW_QuestEN[13269] = { title = "Cloth Scavenging", description = "The humanoids of the northern lands wear garments that can be converted into cloth if you know how.\n\nFor a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional frostweave cloth from the humanoids of Northrend that you slay.", objectives = "The humanoids of the northern lands wear garments that can be converted into cloth if you know how.\n\nFor a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional frostweave cloth from the humanoids of Northrend that you slay.", progress = "The humanoids of the northern lands wear garments that can be converted into cloth if you know how.\n\nFor a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional frostweave cloth from the humanoids of Northrend that you slay.", completion = "May you slay many humanoids and take their cloth." }
WordHunterWoW_QuestEN[13270] = { title = "Cloth Scavenging", description = "You be looking like da type who be knowin' how to sew some threads and so I got somethin' for ya.\n\nDa humanoids of da north be wearin' tings dat can be changed into cloth if you be knowin' da trick of it.\n\nIf you been willin' to part with some cash I can teach you da skill of Cloth Scavenging that be givin' ya extra frostweave cloth from the humanoids of Northrend.", objectives = "You be looking like da type who be knowin' how to sew some threads and so I got somethin' for ya.\n\nDa humanoids of da north be wearin' tings dat can be changed into cloth if you be knowin' da trick of it.\n\nIf you been willin' to part with some cash I can teach you da skill of Cloth Scavenging that be givin' ya extra frostweave cloth from the humanoids of Northrend.", progress = "You be looking like da type who be knowin' how to sew some threads and so I got somethin' for ya.\n\nDa humanoids of da north be wearin' tings dat can be changed into cloth if you be knowin' da trick of it.\n\nIf you been willin' to part with some cash I can teach you da skill of Cloth Scavenging that be givin' ya extra frostweave cloth from the humanoids of Northrend.", completion = "I be appreciatin' your business." }
WordHunterWoW_QuestEN[13271] = { title = "A Voice in the Dark", description = "The object is not a crystal at all, but some form of organ, encased in ice.\n\nAs you touch it, your hand reels in horrible pain.  You feel as if your hand has been cut, yet there is no visible wound.\n\nAs you collect your thoughts, you hear a young boy's voice nearby.\n\n\"You really shouldn't have done that.\"", objectives = "Investigate the nearby voice in Naz'anak, the Forgotten Depths.", completion = "I saw him get rid of it, you know?  He threw it all the way down here.\n\nSaid he wouldn't need it anymore.  Said it made him weak." }
WordHunterWoW_QuestEN[13272] = { title = "Cloth Scavenging", description = "As a Tailor I think you are ready to learn what I have to teach.\n\nMany of the northern humanoids wear clothes that can quickly be converted into cloth if you have the proper skill.\n\nFor a couple of gold coins I can teach you the skill of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", objectives = "As a Tailor I think you are ready to learn what I have to teach.\n\nMany of the northern humanoids wear clothes that can quickly be converted into cloth if you have the proper skill.\n\nFor a couple of gold coins I can teach you the skill of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", progress = "As a Tailor I think you are ready to learn what I have to teach.\n\nMany of the northern humanoids wear clothes that can quickly be converted into cloth if you have the proper skill.\n\nFor a couple of gold coins I can teach you the skill of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", completion = "I think you will find this skill helps you a great deal on your path to tailoring greatness!" }
WordHunterWoW_QuestEN[13273] = { title = "Going After the Core", description = "With Norgannon's Shell in hand, only half of the archive key remains to be found. Luckily, I've had the Explorers' League hard at work chasing down leads about the whereabouts of Norgannon's Core.\n\nFar to the southeast of the Inventor's Library, on the slopes to the north of Dun Niffelem, is a camp bearing my name. The Explorers' League representatives seeking the second half of the key are based there. Bring me the maps and the notes they've made and we should be able to track down the other key half.", objectives = "Find Prospector Khrona's Notes and Prospector Soren's Maps at Brann's Base-Camp.", progress = "Have you recovered those notes?", completion = "Ruined? What d'you mean, the camp's been ruined?\n\n<Brann clenches his fists in anger.>\n\nThose iron dwarves will pay for this! There's little we can do now, and we have to focus on finishing the key. But once I get into the halls of Ulduar, the irons and their masters will answer for what they've done!" }
WordHunterWoW_QuestEN[13274] = { title = "The Core's Keeper", description = "Prospector Soren's notes say that Norgannon's Core is in the keeping of a sentinel named Athan, one of Mimir's creations.\n\nSoren says the vault where Athan resides is called \"Loken's Bargain\" these days.\n\nLoken, eh? The earthen have mentioned him.\n\nThe vault is said to be southwest of the ruined Explorers' League camp, with a round entrance on a mountainside overlooking the Valley of Ancient Winters.\n\nFind this Athan and get the core from him, but I wouldn't be surprised if you were in for a fight.", objectives = "Obtain Norgannon's Core.", progress = "Was Prospector Soren right? Did you finally find Norgannon's Core?", completion = "This is really it! The key is almost within our grasp. All we need now is a way to combine the shell and the core into a single key. Let's see what Prospector Soren had to say about this..." }
WordHunterWoW_QuestEN[13275] = { title = "Time to Hide", description = "You shouldn't have touched it.  But now that you did, he's going to come looking for you.\n\nAnd he'll find you.  Unless you hide yourself from him.\n\nBring me blood from the faceless ones if you want to live!", objectives = "Matthias Lehner wants you to obtain 3 Faceless One's Blood.", progress = "Did you get the blood?", completion = "What are you waiting for?  You have to rub it on you!\n\nQuick!  Or he'll see you!" }
WordHunterWoW_QuestEN[13276] = { title = "That's Abominable!", description = "You know what to do, {class}.\n\nTake this kit and use the guts from their abominations to create one of your own, then command it to attack the enemy forces at the gate.\n\nYou would do well to refine this tactic for when we make our assault on the gate.", objectives = "Koltira Deathweaver on Orgrim's Hammer wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", completion = "I see your skills with the abominations are developing nicely.\n\nBe diligent, friend, and soon the gate will belong to the Horde." }
WordHunterWoW_QuestEN[13277] = { title = "Against the Giants", description = "While it's going to be crucial to defeat the Scourge on the ground, we mustn't neglect the gate itself.\n\nThe flesh giants on the ramparts are capable of hurling massive boulders and chunks of ice, inflicting devastating damage to enemy infantry below.\n\nMuster a force and defeat these giants. We need to know just what we're up against in terms of their strength.\n\nOh... and bring me their spines. If memory serves, there's a little trick I can share with you.", objectives = "Koltira Deathweaver on Orgrim's Hammer wants you to bring him 5 Pustulant Spines from the Pustulant Horrors on Mord'rethar.", progress = "Any success against the giants, <race>?", completion = "Excellent. These look to be usable samples.\n\nTime again to use the enemy's strength against them...." }
WordHunterWoW_QuestEN[13278] = { title = "Coprous the Defiled", description = "Reports of a powerful zombie at the death gate have reached my ears, {class}.\n\nWe cannot allow a potential threat such as this to go unchallenged. Any information you are able to glean from engaging it will be better than what we know now.\n\nGo to the western chamber of the gate and find this creature. Fight him, and find a weakness we might exploit.", objectives = "Koltira Deathweaver aboard Orgrim's Hammer wants you to kill Coprous the Defiled at Mord'rethar.", completion = "Well done, <class>.\n\nPerhaps with some investigation, we can discover how they are bringing such a creature into existence." }
WordHunterWoW_QuestEN[13279] = { title = "Basic Chemistry", description = "<Koltira takes the pustulant spines and drains their fluid into a flask.>\n\nA little-known quality of the flesh giants...\n\nTheir spinal fluid interacts with the plague in a very interesting way, turning it into a corrosive acid.\n\nPoured from the towering ramparts, acid may not be a welcome sight to the troops below, but at least the victims won't rise up and add to the enemy's numbers.\n\nPour the contents of this flask into one of the plague cauldrons in the western chamber of the death gate.", objectives = "Koltira Deathweaver aboard Orgrim's Hammer wants you to use Pustulant Spinal Fluid on a plague cauldron at Mord'rethar.", completion = "You have done well, <class>.\n\nWhen our armies arrive to march on the Citadel, we will have a solid plan in place for taking the death gate." }
WordHunterWoW_QuestEN[13280] = { title = "King of the Mountain", description = "You've just got to get my jumpbot to the tippy top of the mountain to the northwest here at Ymirheim pronto, {name}!\n\nThat dastardly, no-good Blast Thunderbomb is working on his own bot, and I'm afraid he almost has it completed. We're in a race to see who's gonna be king of the mountain!\n\nOnce you jump up there, plant our battle standard in the pile of bones and show everyone that the Alliance, and my engineering skills, are the best!", objectives = "Frazzle Geargrinder in Ymirheim wants you to use her Geargrinder's Jumpbot to plant the Alliance Battle Standard in the skulls at the top of the mountain.", progress = "Hold on a second... you haven't planted our battle standard yet!\n\nWhat's the hold up?", completion = "YOU DID IT! YOU DID IT!\n\n<Frazzle jumps and gives you a big hug.>\n\nOh, you're just my favorite hero ever!\n\nYou think you could come back again tomorrow?" }
WordHunterWoW_QuestEN[13281] = { title = "Neutralizing the Plague", description = "You no longer need my assistance in neutralizing the enemy's plague cauldrons, {race}.\n\nHunt down the flesh giants at the death gate and use the fluid from their spines to render batches of the plague ineffective.\n\nYou are striking at the heart of the enemy's strategy. This is an important mission - vital to our cause, and should be carried out whenever time permits.\n\nRemember, the giants and the plague cauldrons can be found on Mord'rethar.", objectives = "Koltira Deathweaver aboard Orgrim's Hammer wants you use Pustulant Spinal Fluid on a blight cauldron at Mord'rethar.\n\nYou can create Pustulant Spinal Fluid by using a Giant Spine collected from a Pustulant Horror.", completion = "One less plague cauldron to account for when the battle commences.\n\nYour commander will be pleased." }
WordHunterWoW_QuestEN[13282] = { title = "Return to the Surface", description = "You should leave now.  You'll find a portal behind me.  It'll take you to the surface.\n\nWe'll meet again.  He'll be looking for you.\n\nIt's only a matter of time until he finds you.", objectives = "Return to Koltira Deathweaver aboard Orgrim's Hammer.", completion = "<name>!  We thought you were dead!\n\nWe lost a few men in that explosion... but we sure put a hurt on the Scourge.  They're scrambling their forces back to the citadel and leaving big gaps in their defenses.  It's time to push forward." }
WordHunterWoW_QuestEN[13283] = { title = "King of the Mountain", description = "Yo, {name}, I need you to get my jumpbot to the top of this mountain to the southeast, like yesterday!\n\nThat girly, self-righteous Frazzle Geargrinder thinks that her jumpbot's better than mine. Hah! We're in a race to see who's gonna be king of the mountain!\n\nOnce you jump up there, plant our battle standard in the pile of bones and show everyone that the Horde, and my mad engineering skills, are the best!", objectives = "Blast Thunderbomb in Ymirheim wants you to use his Thunderbomb's Jumpbot to plant the Horde Battle Standard in the skulls at the top of the mountain.", completion = "I knew you were the right <race> for the job!\n\n\n\nI gotta admit that right now you're my favorite <class> of all time!\n\nWhat do you say to a repeat performance again tomorrow? I can make it worth your while!" }
WordHunterWoW_QuestEN[13284] = { title = "Assault by Ground", description = "Greetings {class}.\n\nOur troops have been attempting to storm Ymirheim for some time, but these vrykul are far more vicious than any we've faced before. They've been ambushing us repeatedly as we try to make it up the pass, and we've lost a lot of men.\n\nIf you want to lend yourself to the battle and help get my squad to the gates of Ymirheim safely, we will gladly reward you for your efforts. Once at the gates, we'll dig in and wait for reinforcements to catch up to us.", objectives = "Escort the Skybreaker troops to the gates of Ymirheim. Return to Ground Commander Koup at the edge of the glacier east of Ymirheim for compensation after the task is complete.", completion = "You have my thanks.\n\nThis has been a brutal operation, but we haven't had any great options otherwise - they're being equally as unforgiving to our aerial assault. We need to rout these vrykul if we're going to stand any chance of pressing on in Icecrown.\n\nWe're likely to need more help later. Please lend yourself to the battle again should the chance present itself." }
WordHunterWoW_QuestEN[13285] = { title = "Forging the Keystone", description = "Aha! Here it is: the Temple of Invention, the seat of Keeper Mimir himself! Of course, that's where one would go to join the two parts of the key.\n\nAccording to the prospector's notes, the Temple of Invention is one of the highest points on the western side of the Terrace of the Makers. That means it should be roughly east of your Grom'arsh Crash Site.\n\nI'll meet you at the temple and we'll combine the parts together.", objectives = "Brann Bronzebeard wants you to meet him at the Temple of Invention and help him combine Norgannon's Shell and Norgannon's Core. Once you have helped Brann, report back to Boktar Bloodfury at the Grom'arsh Crash-Site.", completion = "<Boktar nods in approval as you tell him how you helped Brann recover the pieces of the keystone and combine them.>\n\nBrann may prove to be just the ally we need to discover what is truly happening in Ulduar. You've done well in aiding him. We need all the help we can get against this Loken and his iron dwarf minions." }
WordHunterWoW_QuestEN[13286] = { title = "...All the Help We Can Get.", description = "Desperate times, {class}...\n\nAs uncomfortable as it makes me, I'm prepared to accept assistance from anyone - including our resident death knight.\n\nGo to Thassarian and see if he can help us develop tactics against the Scourge that will ensure victory once we are able to mount another offensive.\n\nWe have come so far... we must not fail here!", objectives = "High Captain Justin Bartlett aboard the Skybreaker wants you to speak to Thassarian.", completion = "It was wise of Captain Bartlett to send you.\n\nWhile he frets over your conflict with the Horde, someone must remain exclusively focused on the real mission here - the march on Icecrown Citadel.\n\nWho better to direct your efforts than a former servant of the Lich King?" }
WordHunterWoW_QuestEN[13287] = { title = "Poke and Prod", description = "As someone of your experience must surely know, there's no better way to familiarize one's self with their enemy than by confronting them in combat.\n\nWhile you no doubt lust for the glory of taking Icecrown Citadel, that cannot happen without taking each of the Lich King's gates first. For now, you must focus your efforts on the first of these...\n\nReturn to the Broken Front. Engage the enemy in battle. Search for a weakness we might exploit and return to me with a detailed report.", objectives = "Thassarian on the Alliance gunship, Skybreaker, wants you to kill 5 Hulking Abominations, 5 Malefic Necromancers, and 5 Shadow Adepts at the Broken Front.", completion = "Really, <class>?\n\nNothing notable to report?\n\n\n\nI beg to differ..." }
WordHunterWoW_QuestEN[13288] = { title = "That's Abominable!", description = "Abominations...\n\nThey can be a very capable enemy. I've seen them turn the tide of battle more than once. What few realize, is that they can also be very capable friends.\n\nThey are not deep thinkers. If you know the secrets of their creation, you can issue them basic orders that they will not question.\n\nFortunately for you, I know these secrets.\n\nThis kit will reanimate the remains of the abominations you defeat. Take it, and learn to use them against the Scourge on the death gate.", objectives = "Thassarian on the Skybreaker wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", completion = "You see, <class>?\n\nIngenuity can sometimes even the odds against a seemingly overwhelming enemy." }
WordHunterWoW_QuestEN[13289] = { title = "That's Abominable!", description = "You know what to do, {class}.\n\nTake this kit and use the guts from their abominations to create one of your own, then command it to attack the enemy forces at the gate.\n\nYou would do well to refine this tactic for when we make another assault on the gate.", objectives = "Thassarian on the Skybreaker wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", completion = "I see your skills with the abominations are developing nicely.\n\nBe diligent, friend, and soon the death gate will belong to the Alliance." }
WordHunterWoW_QuestEN[13290] = { title = "Your Attention, Please", description = "Chief Engineer Boltwrench has proven invaluable in his service aboard the Stormbreaker. Were it not for his ingenuity, we'd be sprinkled across half of the glacier several times over by now.\n\nThe thing is, he feels he must share his every miniscule invention or discovery - most of which I don't even understand.\n\nMy focus must be squarely on our enemies right now. I cannot afford any distractions.\n\nPlease visit him in my stead, {name}. And if you can, assist him. You'll find him belowdecks.", objectives = "High Captain Bartlett wants you to speak with Chief Engineer Boltwrench in the Skybreaker.", completion = "Cappy sent you in his place, did he?\n\nVery well, <class>. Roll up those sleeves... time to get to work!" }
WordHunterWoW_QuestEN[13291] = { title = "Borrowed Technology", description = "I get it, I get it. Cappy's too busy to see this for himself. His loss!\n\nSee, I've managed to 'acquire' a certain shipment of solution from the enemy. And as much as I hate tinkerin' with inferior goblin technology, I'm inclined to make an exception here.\n\nTake this sample. I'll need you to run a few field tests, just to prove its usefulness, while I try to do a little reverse engineering to duplicate the creation process.\n\nGo to the front and gather the materials to make a decoy, then use the oil.", objectives = "Chief Engineer Boltwrench aboard the Skybreaker wants you to use the Smuggled Solution at the Broken Front.\n\nUsing the solution will require an Abandoned Helm, Abandoned Armor, and Pile of Bones, all found at the Broken Front.", completion = "Good news!\n\nI've managed to reproduce the solution - hardly an accomplishment, of course.\n\nDoubt I'll live to see the day those neanderthal goblins cook up somethin' a gnome can't recreate in his sleep!" }
WordHunterWoW_QuestEN[13292] = { title = "The Solution Solution", description = "Oh, yes, yes. Back again, are we? Never enough practice, I suppose.\n\nHere we are, the solution to that pesky frostwyrm problem.\n\nMake them scarce, {race}. The more you take out now, the less we face when we are again ready to attempt our march on the citadel.\n\nBest of luck, now. And do bring back whatever you don't use.", objectives = "Chief Engineer Boltwrench aboard the Skybreaker wants you to use the Smuggled Solution at the Broken Front.\n\nUsing the solution will require an Abandoned Helm, Abandoned Armor, and Pile of Bones, all found at the Broken Front.", completion = "Good show! Good show indeed. You're turning into a regular wyrmslayer!\n\nCome back when you're ready to thin their numbers even further." }
WordHunterWoW_QuestEN[13293] = { title = "Get to Ymirheim!", description = "You need to get down to Ymirheim, that big frost vrykul town in the middle of Icecrown.\n\nOur boy, Blast Thunderbomb, is down there on the west side of town representing the Warsong Offensive in a competition against the Alliance. It's his jumpbot versus theirs in a king of the mountain contest!\n\nDon't let us down, {name}. Goblin engineering pride is on the line! Besides, all the boys here in the hold are counting on you.\n\nThat and we've got money riding on it that you can kick those cowards in the pants!", objectives = "Speak with Blast Thunderbomb in Ymirheim.", completion = "Oh man, am I glad to see you! Did the chief send you down from the Hammer?" }
WordHunterWoW_QuestEN[13294] = { title = "Against the Giants", description = "While it's going to be crucial to defeat the Scourge on the ground, we mustn't neglect the gate itself.\n\nThe flesh giants on the ramparts are capable of hurling massive boulders and chunks of ice, inflicting devastating damage to enemy infantry below.\n\nMuster a force and defeat these giants. We need to know just what we're up against in terms of their strength.\n\nOh... and bring me their spines. If memory serves, there's a little trick I can share with you.", objectives = "Thassarian on the Skybreaker wants you to bring him 5 Pustulant Spines from the Pustulant Horrors on Mord'rethar.", progress = "Any success against the giants, <race>?", completion = "Excellent. These look to be usable samples.\n\nTime again to use the enemy's strength against them...." }
WordHunterWoW_QuestEN[13295] = { title = "Basic Chemistry", description = "<Thassarian takes the pustulant spines and drains their fluid into a flask.>\n\nA little-known quality of the flesh giants...\n\nTheir spinal fluid interacts with the plague in a very interesting way, turning it into a corrosive acid.\n\nPoured from the towering ramparts, acid may not be a welcome sight to the troops below, but at least the victims won't rise up and add to the enemy's numbers.\n\nPour the contents of this flask into one of the plague cauldrons in the western chamber of the death gate.", objectives = "Thassarian aboard the Skybreaker wants you to use Pustulant Spinal Fluid on a plague cauldron at Mord'rethar.", completion = "You have done well, <class>.\n\nWhen our armies arrive to march on the Citadel, we will have a solid plan in place for taking the death gate." }
WordHunterWoW_QuestEN[13296] = { title = "Get to Ymirheim!", description = "I need you down in Ymirheim, that big frost vrykul town in the middle of Icecrown.\n\nFrazzle Geargrinder is down there on the south side of town representing the Valiance Expedition in a competition against the Horde scum. It's her jumpbot versus theirs in a king of the mountain contest!\n\nDon't let us down, {name}. Gnomish engineering pride is on the line! Besides, all the boys here in the hold are counting on you.\n\nThat and we've got money riding on it that you can kick those idiots in the pants!", objectives = "Speak with Frazzle Geargrinder in Ymirheim.", completion = "Did the chief send you down from the Skybreaker? Isn't that thing sweet?!" }
WordHunterWoW_QuestEN[13297] = { title = "Neutralizing the Plague", description = "You no longer need my assistance in neutralizing the enemy's plague cauldrons, {race}.\n\nHunt down the flesh giants at the death gate and use the fluid from their spines to render batches of the plague ineffective.\n\nYou are striking at the heart of the enemy's strategy. This is an important mission - vital to our cause, and should be carried out whenever time permits.\n\nRemember, the giants and the plague cauldrons can be found on Mord'rethar.", objectives = "Thassarian aboard the Skybreaker wants you use Pustulant Spinal Fluid on a plague cauldron at Mord'rethar.\n\nYou can create Pustulant Spinal Fluid by using a Giant Spine collected from a Pustulant Horror.", completion = "One less plague cauldron to account for when the battle commences.\n\nYour captain will be highly pleased." }
WordHunterWoW_QuestEN[13298] = { title = "Coprous the Defiled", description = "Reports of a powerful zombie at the death gate have reached my ears, {class}.\n\nWe cannot allow a potential threat such as this to go unchallenged. Any information you are able to glean from engaging it will be better than what we know now.\n\nGo to the western chamber of the gate and find this creature. Fight him, and find a weakness we might exploit.", objectives = "Thassarian aboard the Skybreaker wants you to kill Coprous the Defiled at Mord'rethar.", completion = "Well done, <class>.\n\nPerhaps with some investigation, we can discover how they are bringing such a creature into existence." }
WordHunterWoW_QuestEN[13299] = { title = "ZZOLDWisp Cloak", description = "", objectives = "" }
WordHunterWoW_QuestEN[13300] = { title = "Slaves to Saronite", description = "Our people are being captured and put to work as slaves in the saronite mines of Ymirheim, the vrykul stronghold in the middle of Icecrown. The Lich King has them mining that unholy ore day and night.\n\nI made a promise to Highlord Fordring that we would get those wretches out of there alive, and that's exactly what we will do.\n\nUnfortunately, I've been ordered to stay on this gunship and serve as an ambassador to the Valiance Expedition. Will you please rescue them in my stead, {name}?", objectives = "Absalan the Pious aboard the Skybreaker wants you to rescue 10 Saronite Mine Slaves.", completion = "They're being driven insane? Voices in their heads?\n\nVoices in your head?!\n\nI want you to clear your mind of the taint that has crept into that place, boy.\n\nWe'll try to get the remainder of them out of there again tomorrow when you've had a chance to rest." }
WordHunterWoW_QuestEN[13301] = { title = "Assault by Ground", description = "Greetings {class}.\n\nOur troops have been attempting to storm Ymirheim for some time, but these vrykul are far more vicious than any we've faced before. They've been ambushing us repeatedly as we try to make it up the pass, and we've lost a lot of men.\n\nIf you want to lend yourself to the battle and help get my squad to the gates of Ymirheim safely, we will gladly reward you for your efforts. Once at the gates, we'll dig in and wait for reinforcements to catch up to us.", objectives = "Escort the Kor'kron troops to the gates of Ymirheim. Return to Ground Commander Xutjja at the edge of the glacier north of Ymirheim for compensation after the task is complete.", completion = "You have my thanks.\n\nThis has been a brutal operation, but we haven't had any great options otherwise - they're being equally as unforgiving to our aerial assault. We need to rout these vrykul if we're going to stand any chance of pressing on in Icecrown.\n\nWe're likely to need more help later. Please lend yourself to the battle again should the chance present itself." }
WordHunterWoW_QuestEN[13302] = { title = "Slaves to Saronite", description = "Our people are being captured and put to work as slaves in the saronite mines of Ymirheim, the vrykul stronghold in the middle of Icecrown. The Lich King has them mining that unholy ore day and night.\n\nI made a promise to Highlord Fordring that we would get those wretches out of there alive, and that's exactly what we will do.\n\nUnfortunately, I've been ordered to stay on this gunship and serve as an ambassador to the Warsong Offensive. Will you please rescue them in my stead, {name}?", objectives = "Brother Keltan aboard Orgrim's Hammer wants you to rescue 10 Saronite Mine Slaves.", completion = "They're being driven insane? Voices in their heads?\n\nVoices in your head?!\n\nI want you to clear your mind of the taint that has crept into that place, boy.\n\nWe'll try to get the remainder of them out of there again tomorrow when you've had a chance to rest." }
WordHunterWoW_QuestEN[13303] = { title = "The Panchurian Candidate", description = "", objectives = "" }
WordHunterWoW_QuestEN[13304] = { title = "Field Repairs", description = "The Scourge is still reeling from our attack, {name}.  Now is the time to capitalize on our momentum.\n\nThe strategically important valley below us is wide open.  We've located a disassembled demolisher vehicle in what we believe is working condition in the southeastern corner of the Valley of Lost Hope area.\n\nIf you can get the remaining parts from the Scourge scavengers, you should be able to get it running again.  A single working demolisher can wreak havoc on the enemy's ground units.", objectives = "Koltira Deathweaver aboard Orgrim's Hammer wants you to collect 5 Demolisher Parts from the Scavenging Geists in the Valley of Lost Hope and take them to the Wrecked Demolisher.", progress = "The demolisher has suffered much damage.", completion = "The Demolisher has seen better days, but the structure hasn't suffered any permanent damage.  The parts you obtained should be enough to get it running again, at least temporarily." }
WordHunterWoW_QuestEN[13305] = { title = "Do Your Worst", description = "You're going to use this machine against the Scourge?  You're not going to win against them like that.\n\nYou can destroy hundreds... even thousands of them.  But you won't win.  Not out here.\n\nWhen you're done playing with your machine, meet me to the north.  There is an old army encampment.  What I will show you will teach you a little bit about who you're up against.", objectives = "Use the Refurbished Demolisher to destroy 150 Decomposed Ghouls, 20 Frostskull Mages and 2 Bone Giants in the Valley of Lost Hope. Speak to Matthias Lehner at the First Legion Forward Camp when you've completed this task.", completion = "You see?  You killed your fair share, but for every one you destroyed, another rose from the dirt to take its place.\n\nYou don't know what you're up against, <name>.  Let me show you." }
WordHunterWoW_QuestEN[13306] = { title = "Raise the Barricades", description = "When our forces begin to move beyond Aldur'thar, they will be vulnerable to attack from the Ironwall Rampart and the broad glacier below.\n\nWe have neither the time nor the materials to build fortifications, but we can put up some barricades to shield our men from fire and break up Scourge charges.\n\nTake this barricade kit to the Valley of Fallen Heroes, on the west side of Aldur'thar. Locate the markers I've placed there and use this kit to construct your barricades there.", objectives = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to construct 8 Barricades using your Barricade Construction Kit.", completion = "<Koltira nods curtly.>\n\nGood. It's not much protection, but it's better than nothing. That gate is still the perfect choke point if the Scourge commanders know what they're doing. We must gain control of as much of the surrounding area as possible." }
WordHunterWoW_QuestEN[13307] = { title = "Bloodspattered Banners", description = "In the Valley of Fallen Heroes and Icecrown Glacier, to the west of Aldur'thar, the Scourge seeks to use the fallen against us. Scourge lieutenants have woken the valley's dead and imbued them with fearsome strength and fervor. The banners carried by the Scourge leaders in the glacier area are the source of these powers. Kill the banner-bearers, and you will weaken the converted heroes they lead.\n\nIt falls to you to rid us of this obstacle, and thin the resistance before the main body can advance.", objectives = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to kill 5 Scourge Banner-Bearers, 5 Scourge Converters, and 20 Converted Heroes.", completion = "You have removed the Scourge banner-bearers and their minions? Good. Our preparations must continue." }
WordHunterWoW_QuestEN[13308] = { title = "Mind Tricks", description = "<The creature speaks directly into your mind, its thoughts painful and strange.>\n\n{race}-thing, I am in need of your assistance. Like your enslaved friends, I am a victim of the Lich King's ymirjar and their avarice. When I rose from below to investigate the noises coming from this cavern they captured and chained me.\n\nWill you please help me? The foreman of these mines holds the key to my chains. Kill him!\n\n<You can feel a pushing against your mind as if the creature is trying to coerce you.>", objectives = "Darkspeaker R'khem in the Saronite Mines wants you to recover the Foreman's Key to his chains.", progress = "You will be richly rewarded for your service to me.\n\n<The darkspeaker projects soothing feelings into your mind.>\n\nYou will not regret unfettering me.", completion = "<Another wave of euphoria, mixed with some pain, crashes through your mind as you approach the creature.>\n\nGood... good! So that you know I am being fair, I will first give you your reward as promised.\n\nAnd then you will willingly hand me the key." }
WordHunterWoW_QuestEN[13309] = { title = "Assault by Air", description = "I've got some boys suited and ready for their drops inside of Ymirheim. I could use you to see them there safely.\n\nInside the walls, the vrykul have set up some kind of automated spear guns that have been tearing up our transports. We had our engineers install a Suppression Turret to shut down those spear guns - just fire a round near any gun and the smoke should block its sight and clog its gears.\n\nHop on the turret and see to it that all my boys make it to their drops in one piece.", objectives = "Ground Commander Koup at the edge of the glacier east of Ymirheim has ordered you to use the Skybreaker Suppression Turret to keep the Skybreaker Troop Transport alive long enough to make all of its drops.", progress = "Did you get my boys inside?", completion = "Excellent work, soldier. We could use more able bodies like you around here - stop by another day if the operation hasn't wrapped up." }
WordHunterWoW_QuestEN[13310] = { title = "Assault by Air", description = "Alright scrub, I've got something to keep you from being a complete waste.\n\nA unit of highly trained infiltrators is ready to be dropped inside of Ymirheim. The vrykul inside have automated spear guns that have been ripping our transports to shreds, so we had the engineers on Orgrim's Hammer whip us up a suppression turret.\n\nYou're the gunner. Launch rounds at their spear guns to obscure their vision and clog their gears. See to it that my men all make their drops and the transport stays in one piece.", objectives = "Ground Commander Xutjja at the edge of the glacier north of Ymirheim has ordered you to use the Kor'kron Suppression Turret to keep the Kor'kron Troop Transport alive long enough to make all of its drops.", progress = "Get the job done?", completion = "Only partly useless then. Good work." }
WordHunterWoW_QuestEN[13311] = { title = "Demons Deck", description = "Now that you have gathered all of the Demon cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.\n\nYou feel the card could be used to communicate with someone or something.", objectives = "Use the Demons Deck to summon a Darkmoon Fortune Teller and give the deck to them.", progress = "I see that you have managed to complete a deck of Demons!   Congratulations!", completion = "The tarot cards are of great interest to the Darkmoon Faire, so do not hesitate to call upon us if you manage to collect more.  We are not without our own skilled tradesmen, so please allow us to offer something in return." }
WordHunterWoW_QuestEN[13312] = { title = "The Ironwall Rampart", description = "The Ironwall Rampart overlooks the Valley of Fallen Heroes, west of Aldur'thar. The rampart dominates the fields below on all sides. We will not be able to advance if the rampart cannot be taken, but it is held by Grimkor the Wicked and his Cult of the Damned disciples.\n\nIf you can weaken Grimkor, our forces know what to expect as we advance. Take this rune of distortion. Unleashing its power near Grimkor's orb at the end of the rampart should be enough to get the necromancer's attention.", objectives = "Defeat Grimkor the Wicked and return to Koltira Deathweaver aboard Orgrim's Hammer.", completion = "So Grimkor has fallen by your hand? Excellent work. With him out of the way, our chances of taking and holding the rampart during the assault are greatly improved." }
WordHunterWoW_QuestEN[13313] = { title = "Blinding the Eyes in the Sky", description = "The Alliance has somehow managed to field a squadron of recon vehicles over the Valley of Fallen Heroes and Icecrown Glacier, the broad areas west of Aldur'thar.\n\nThey cannot be permitted to take the lead in this fight. Chief Engineer Copperclaw has supplied me with the perfect weapon to deal with this threat -- he calls his new missile the SGM-3. I have his assurances that it will take out the Alliance flying machines in a single hit. Go and use this weapon to give us the upper hand.", objectives = "Use the SGM-3 to destroy 6 Skybreaker Recon Fighters, then report back to Sky-Reaver Korm Blackscar aboard Orgrim's Hammer.", completion = "Good. Fewer Alliance pests to stand in our way. We'll show them what true warriors look like." }
WordHunterWoW_QuestEN[13314] = { title = "Get the Message", description = "The Horde is up to something and I don't like it. After the stunt they pulled on the Broken Front, they're capable of anything, and it's up to us to stop it.\n\nThere's been a flurry of activity in the skies over the Icecrown Glacier, to the west of Aldur'thar and the Ironwall Rampart. Horde scouts and messengers streak in and out on dragonhawks, carrying reports and orders. Take this dart gun and use it to kill the Orgrim's Hammer Scouts. It'll probably work best if you're flying, too.", objectives = "Capture 6 Orgrim's Hammer Dispatches from Orgrim's Hammer Scouts and bring them to High Captain Justin Bartlett aboard the Skybreaker.", progress = "Have you intercepted those dispatches?", completion = "It's good to have someone competent running missions, <name>. If only we had an army of paladins like you, we could show the Horde what we're made of. These captured reports will help us to maintain the upper hand in this fight. We may be down, but we're far from out." }
WordHunterWoW_QuestEN[13315] = { title = "Sneak Preview", description = "Progress is being made. We have a promising array of tactics that should gain us control of the death gate. There will doubtlessly be many casualties, but in the end,  we should be able to prevail - barring any interference from those Horde you insist on contending with...\n\nAt any rate, our next focus will be the gate of desolation. Fly down and become familiar with it and with the enemies posted there.\n\nWhen you return, I will have your missions prepared.", objectives = "Thassarian, aboard the Skybreaker, wants you to fly down to the gate of desolation, visiting the south, central, north, and northwest regions of the gate.", progress = "Have you scouted the gate of desolation, <class>?", completion = "Well and good, <class>.\n\nNow that you've seen firsthand what we're up against, it's time to get to work..." }
WordHunterWoW_QuestEN[13316] = { title = "The Guardians of Corp'rethar", description = "Corp'rethar, called the Horror Gate. It is the last barrier between us and the Icecrown Citadel. It waits to the south of the Ironwall Rampart, beyond the glacier and the Conflagration. By the time our troops reach it, they will be exhausted and worse.\n\nWe must weaken its defenses, or our army's strength will break upon its walls.\n\nIts battlements are manned by some of the Lich King's fiercest and most zealous servants. Do all you can to destroy these guardians and hope it is enough.", objectives = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to kill 5 Harbingers of Horror and 5 Corp'rethar Guardians.", completion = "I hope your success at Corp'rethar will prove an omen of the battle ahead. The Lich King cannot sit idly by as we march to the very gates of his stronghold." }
WordHunterWoW_QuestEN[13318] = { title = "Drag and Drop", description = "The Cult of the Damned hold the gate of desolation, eh? No surprise there.\n\nTime to have a little fun. At the southern end of the gate, you mentioned there were new cultists being trained. They're almost certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nKill the fools until you find one, {class}, then use it on a subjugator.", objectives = "Thassarian, aboard the Skybreaker, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old...." }
WordHunterWoW_QuestEN[13319] = { title = "Chain of Command", description = "Based on your report, and my knowledge of the Cult, they have an overseer managing the operation of each encampment on the gate.\n\nWhile taking their leaders down will only be a temporary setback, it will at least slow them down and keep them off-balance. And that, {race}, is a worthy enough goal for now.\n\nSeek out these overseers and return to me when they have been dispatched.", objectives = "Thassarian aboard the Skybreaker wants you to go to Aldur'thar and defeat Overseer Faedris, Overseer Savryn, Overseer Veraj, and Overseer Jhaeqon.", completion = "Well done, <race>. But don't break your arm patting yourself on the back. They'll have those overseers replaced in no time..." }
WordHunterWoW_QuestEN[13320] = { title = "Cannot Reproduce", description = "I smell their cauldrons from here, but that's not plague they're cooking.\n\nPledges to the cult are forced to drink a concoction that steals their will and enslaves them forever to the Lich King.\n\nSome say the potion contains the twisted soul of a being who was tormented before being mercilessly slaughtered, but I've never been able to reproduce it...\n\nFill this flask with a sample from each of the three cauldrons in the northwest region of the gate and bring it to Chief Engineer Boltwrench.", objectives = "Thassarian aboard the Skybreaker wants you to use the Partitioned Flask at each of the 3 Cultists' Cauldrons at Aldur'thar, then bring it to Chief Engineer Boltwrench.", progress = "Whatdya got there, <race>?", completion = "<Boltwrench pours the contents of the flask into his tetrahydroparticle analyzer.>\n\nWhat we have here is a simple failure to conglomerate..." }
WordHunterWoW_QuestEN[13321] = { title = "Retest Now", description = "This should do the trick!\n\nThose twisted hooligans are looking for souls to put in their crazy-juice? Then I say we help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence once you've defeated them.\n\nWhen you've collected a bunch of them, throw the writhing mass of twisted souls into any of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", objectives = "Chief Engineer Boltwrench aboard the Skybreaker wants you to throw a Writhing Mass into a cauldron at Aldur'thar.", completion = "Wahoo!\n\nThat'll teach 'em!" }
WordHunterWoW_QuestEN[13322] = { title = "Retest Now", description = "Those twisted cultists are looking for souls to put in their crazy-juice? Then let's help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence.\n\nOnce you've collected a bunch of 'em, throw the writhing mass of twisted souls in one of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", objectives = "Chief Engineer Boltwrench aboard the Skybreaker wants you to drink the Diluted Cult Tonic, kill any Cultists at Aldur'thar and take their Tainted Essences. You are then to combine 10 of the essences into a Writhing Mass and throw it into any of their cauldrons.", completion = "Wahoo!\n\nThat'll teach 'em!" }
WordHunterWoW_QuestEN[13323] = { title = "Drag and Drop", description = "Looks like those initiates are increasing in number again. You know what to do...\n\nAt the southern portion of the gate, the new cultists are being trained. They're certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nSlay the fools until you find some, then use them on the subjugators there.", objectives = "Thassarian, aboard the Skybreaker, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old...." }
WordHunterWoW_QuestEN[13324] = { title = "Darkmoon Prisms Deck", description = "Now that you have gathered all of the Prism cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Prisms Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Prisms!   Congratulations!", completion = "So you have put together a deck of Prisms.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[13325] = { title = "Darkmoon Chaos Deck", description = "Now that you have gathered all of the Chaos cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Chaos Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Chaos!   Congratulations!", completion = "So you have put together a deck of Chaos.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[13326] = { title = "Darkmoon Nobles Deck", description = "Now that you have gathered all of the Nobles cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Nobles Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Nobles!   Congratulations!", completion = "So you have put together a deck of Nobles.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[13327] = { title = "Darkmoon Undeath Deck", description = "Now that you have gathered all of the Undeath cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Undeath Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Undeath!   Congratulations!", completion = "So you have put together a deck of Undeath.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[13328] = { title = "Shatter the Shards", description = "Atop the battlements of Corp'rethar, the Lich King's minions have erected three crystals, the shards of horror, despair, and suffering. Should our men reach the walls of Corp'rethar, he will unleash these weapons on our army.\n\nIn full effect, the crystals will afflict the minds of our men with paralyzing pain and fear. Then, the Scourge will be able to slaughter them at will.\n\nFind these shards, destroy them, and bring me their broken remains. We cannot allow the Lich King to deploy these weapons!", objectives = "Bring the Broken Shard of Horror, the Broken Shard of Despair, and the Broken Shard of Suffering to Koltira Deathweaver aboard Orgrim's Hammer.", progress = "Have you shattered the Lich King's new weapons?", completion = "<Koltira takes the crystal shards from you and speaks in a quiet voice.>\n\nI remember these...\n\nLesser men would easily crumble beneath their assault. You have done well in removing their threat." }
WordHunterWoW_QuestEN[13329] = { title = "Before the Gate of Horror", description = "The Conflagration, the ground before Corp'rethar, south of the Ironwall Rampart, is where the Lich King's elite soldiers have formed up to defend the citadel.\n\nLed by a contingent of death knights, a legion of skeletal reavers bars the way. I fear that even when these reavers fall, the Scourge will simply reconstitute them and send them back at us.\n\nI've come up with a plan to stop this, but I have no way of knowing if it will work. Take this solution and use it to dissolve the remains of the reavers.", objectives = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to use the Volatile Acid to dissolve the remains of 6 Skeletal Reavers.", completion = "<Koltira listens to your report.>\n\nGood. I'll have the engineers mix up as much of that acid as they can before we prepare to assault Corp'rethar with the main force." }
WordHunterWoW_QuestEN[13330] = { title = "Blood of the Chosen", description = "Those vrykul that have gained the favor of the Lich King call themselves the Ymirjar. They inhabit a city in the center of Icecrown. We have a lot of preparations to make before we assault Icecrown Citadel, and the one that stands before us now is routing these so-called \"Chosen\" of the Lich King.\n\nGo to their city, Ymirheim, and slaughter them in their home. Let there be no questions as to who the stronger combatants are here.", objectives = "Warbringer Davos Rioht on Orgrim's Hammer has sent you to kill 20 vrykul in Ymirheim.", completion = "Not so strong after all, it seems. The Lich King will get what's coming to him." }
WordHunterWoW_QuestEN[13331] = { title = "Keeping the Alliance Blind", description = "The Alliance is tenacious, I'll give them that, but it'll take more than that to stop us. Take this SGM-3 with you and shoot down the Skybreaker's recon fighters once again.\n\nI doubt the message will get through their thick skulls, but there are enough missiles to keep trying to get our point across. Go and find their fighters flying above the Valley of Fallen Heroes, west of Aldur'thar, and don't come back until you've made wreckage of them.", objectives = "Use the SGM-3 to destroy 6 Skybreaker Recon Fighters, then report back to Sky-Reaver Korm Blackscar aboard Orgrim's Hammer.", completion = "Well done, once again. Horde superiority is assured, at least until those Alliance pukes decide to challenge us again." }
WordHunterWoW_QuestEN[13332] = { title = "Raise the Barricades", description = "When our forces begin to move beyond Aldur'thar, they will be vulnerable to attack from the Ironwall Rampart and the broad glacier below.\n\nWe have neither the time nor the materials to build fortifications, but we can put up some barricades to shield our men from fire and break up Scourge charges.\n\nTake this barricade kit to the Valley of Fallen Heroes, on the west side of Aldur'thar. Locate the markers I've placed there and use this kit to construct your barricades there.", objectives = "Thassarian, aboard the Skybreaker, wants you to construct 8 Barricades using your Barricade Construction Kit.", completion = "<Thassarian nods.>\n\nGood. It's not much protection, but it's better than nothing. That gate is still the perfect choke point if the Scourge commanders know what they're doing. We must gain control of as much of the surrounding area as possible." }
WordHunterWoW_QuestEN[13333] = { title = "Capture More Dispatches", description = "Despite our efforts, the Horde continues to send scouts to the area of the Icecrown Glacier, to the west of the Ironwall Rampart and Aldur'thar.\n\nWe can't afford to let the Horde gain the upper hand with this scouting operation. Take the dart gun with you again and show the Orgrim's Hammer scouts no mercy! Bring the captured dispatches to me.\n\nThe Horde's wasted efforts will be our gain.", objectives = "Capture 6 Orgrim's Hammer Dispatches from Orgrim's Hammer Scouts and bring them to High Captain Justin Bartlett aboard the Skybreaker.", progress = "Have you intercepted those dispatches?", completion = "<The high captain accepts the dispatches.>\n\nThis is just what we need. Not even the Horde is so stupid as to charge in blindly against the Scourge. With their reports in hand, we'll be well prepared." }
WordHunterWoW_QuestEN[13334] = { title = "Bloodspattered Banners", description = "In the Valley of Fallen Heroes and Icecrown Glacier, to the west of Aldur'thar, the Scourge seeks to use the fallen against us. Scourge lieutenants have woken the valley's dead and imbued them with fearsome strength and fervor. The banners carried by the Scourge leaders in the glacier area are the source of these powers. Kill the banner-bearers, and you will weaken the converted heroes they lead.\n\nIt falls to you to rid us of this obstacle, and test the resistance before the main body can advance.", objectives = "Thassarian, aboard the Skybreaker, wants you to kill 5 Scourge Banner-Bearers, 5 Scourge Converters, and 20 Converted Heroes.", completion = "You have removed the Scourge banner-bearers and their minions? Good. Our preparations must continue." }
WordHunterWoW_QuestEN[13335] = { title = "Before the Gate of Horror", description = "The Conflagration, the ground before Corp'rethar, south of the Ironwall Rampart, is where the Lich King's elite soldiers have formed up to defend the citadel.\n\nLed by a contingent of death knights, a legion of skeletal reavers bars the way. I fear that even when these reavers fall, the Scourge will simply reconstitute them and send them back at us.\n\nI've come up with a plan to stop this, but I have no way of knowing if it will work. Take this solution and use it to dissolve the remains of the reavers.", objectives = "Thassarian, aboard the Skybreaker, wants you to use the Volatile Acid to dissolve the corpses of 6 Skeletal Reavers.", completion = "<Thassarian listens as you describe your successful tests.>\n\nSo the acid worked? Good. We'll need it when the army goes up against the reavers in force." }
WordHunterWoW_QuestEN[13336] = { title = "Blood of the Chosen", description = "Those vrykul that have gained the favor of the Lich King call themselves the Ymirjar. They inhabit a city in the center of Icecrown. We have a lot of preparations to make before we assault Icecrown Citadel, and the one that stands before us now is routing these so-called \"Chosen\" of the Lich King.\n\nGo to their city, Ymirheim, and slaughter them in their home. Let there be no questions as to who the stronger combatants are here.", objectives = "Knight-Captain Drosche on the Skybreaker has sent you to kill 20 vrykul in Ymirheim.", completion = "The traitor king will fall. Of that I have no doubt." }
WordHunterWoW_QuestEN[13337] = { title = "The Ironwall Rampart", description = "The Ironwall Rampart overlooks the Valley of Fallen Heroes, west of Aldur'thar. The rampart dominates the fields below on all sides. We will not be able to advance if the rampart cannot be taken, but it is held by Grimkor the Wicked and his Cult of the Damned disciples.\n\nIf you can weaken Grimkor, our forces will know what to expect as we advance. Take this rune of distortion. Unleashing its power near Grimkor's orb at the end of the rampart should be enough to get the necromancer's attention.", objectives = "Defeat Grimkor the Wicked and return to Thassarian aboard the Skybreaker.", completion = "So Grimkor has fallen by your hand? Excellent work. With him out of the way, our chances of taking and holding the rampart during the assault are greatly improved." }
WordHunterWoW_QuestEN[13338] = { title = "The Guardians of Corp'rethar", description = "Corp'rethar, called the Horror Gate. It is the last barrier between us and the Icecrown Citadel. It waits to the south of the Ironwall Rampart, beyond the glacier and the Conflagration. By the time our troops reach it, they will be exhausted and worse.\n\nWe must weaken its defenses, or our army's strength will break upon its walls.\n\nIts battlements are manned by some of the Lich King's fiercest and most zealous servants. Do all you can to destroy these guardians and hope it is enough.", objectives = "Thassarian, aboard the Skybreaker, wants you to kill 5 Harbingers of Horror and 5 Corp'rethar Guardians.", completion = "I hope your success at Corp'rethar will prove an omen of the battle ahead. The Lich King cannot sit idly by as we march to the very gates of his stronghold." }
WordHunterWoW_QuestEN[13339] = { title = "Shatter the Shards", description = "Atop the battlements of Corp'rethar, the Lich King's minions have erected three crystals, the shards of horror, despair, and suffering. Should our men reach the walls of Corp'rethar, he will unleash these weapons on our army.\n\nIn full effect, the crystals will afflict the minds of our men with paralyzing pain and fear. Then, the Scourge will be able to slaughter them at will.\n\nFind these shards, destroy them, and bring me their broken remains. We cannot allow the Lich King to deploy these weapons!", objectives = "Bring the Broken Shard of Horror, the Broken Shard of Despair, and the Broken Shard of Suffering to Thassarian, aboard the Skybreaker.", progress = "Have you shattered the Lich King's new weapons?", completion = "<Thassarian takes the crystal shards from you and speaks in a quiet voice.>\n\nI remember these...\n\nLesser men would easily crumble beneath their assault. You have done well in removing their threat." }
WordHunterWoW_QuestEN[13340] = { title = "Joining the Assault", description = "We need more men to join the main assault on Ymirheim.\n\nAny warrior with half a brain can tell you that vrykul are fierce fighters and should not be taken lightly. That goes two-fold for the Ymirjar. They have shown us no restraint in proving why the Lich King deemed them worthy.\n\nGround Commander Xutjja is overseeing the assault. The city itself is located in the center of Icecrown - Xutjja's troops are positioned near the edge of the glacier, north of the city.", objectives = "Report to Ground Commander Xutjja at the edge of the glacier north of Ymirheim.", completion = "More meat for the grinder. Welcome to hell, soldier.\n\nMy men are leading the assault on the gate from this position, and we're dropping some infiltrators in the city via air - we need more people on both fronts. I have a feeling that this attack will be going on for some time." }
WordHunterWoW_QuestEN[13341] = { title = "Joining the Assault", description = "We need more men to join the main assault on Ymirheim.\n\nAny warrior with half a brain can tell you that vrykul are fierce fighters and should not be taken lightly. That goes two-fold for the Ymirjar. They have shown no restraint in proving to us why the Lich King deemed them worthy.\n\nGround Commander Koup is overseeing the assault. The city itself is located in the center of Icecrown - Koup's troops are positioned near the edge of the glacier, east of the city.", objectives = "Report to Ground Commander Koup at the edge of the glacier east of Ymirheim.", completion = "Welcome to hell, soldier.\n\nMy men are leading the assault on the gate from this position, and we're dropping some infiltrators in the city via air - we need more people on both fronts. I have a feeling that this attack will be going on for some time." }
WordHunterWoW_QuestEN[13342] = { title = "Not a Bug", description = "Alright, friend, time to plant a bug.\n\nRelax, it's not a bug exactly, but it'll serve our purposes.\n\nIn the northern portion of Aldur'thar the cult's void summoners enslave demonic minions. Use this rod to siphon the dark matter from the corpses of these enslaved minions, and then use their summoning crystal to bring our little spy into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", objectives = "Thassarian, aboard the Skybreaker, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", completion = "You have done well, <class>.\n\nThe messenger has already turned up some valuable information." }
WordHunterWoW_QuestEN[13343] = { title = "Mystery of the Infinite, Redux", description = "There you are! Or, were we just talking?\n\n<Chromie muses over the temporal possibilities.>\n\nAnyway, the Infinites are after you! Well, not you per-se. Rather, they're after the past version of you that defended the Hourglass of Eternity. You remember, right?\n\nThat was you back then, except it's you now too. Wait, that's not important. What is important is that you head back to the Bronze Dragonshrine and defend yourself and the hourglass from their attacks before you get erased from history!", objectives = "Chromie, at the top of Wyrmrest Temple, has asked you to travel once more to the Bronze Dragonshrine.\n\nOnce inside, place the Hourglass of Eternity on the ground and help your Past Self to protect it from the forces of the Infinite Dragonflight.", completion = "Oh my goodness, you made it! I was uncertain.\n\nYou flickered in and out of the time stream there for a moment during the fight! I thought for sure that we'd lost you!\n\nBut here you are safe and sound, with your past self rescued, on the other side of the time loop you were in.\n\nYou're quite the temporal hero, <name>!" }
WordHunterWoW_QuestEN[13344] = { title = "Not a Bug", description = "The cultists have discovered the last messenger you summoned, {race}.\n\nWhile it was quite informative, it's important that we continue to monitor their every move.\n\nUse this rod to siphon the dark matter from the corpses of enslaved minions at Aldur'thar. Then use their summoning crystal to bring another dark messenger into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", objectives = "Thassarian, aboard the Skybreaker, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", completion = "Well done, friend.\n\nThe messenger is up and reporting in as we speak." }
WordHunterWoW_QuestEN[13345] = { title = "Need More Info", description = "The Cult of the Damned are notorious for concocting grandiose plans that in the end, rarely succeed. But something feels different this time....\n\nPerhaps it's the proximity to the Lich King that has their fervor heightened. Whatever it is, they appear to be more confident than ever. We must know what feeds this bravado and then find a way to strip them of it!\n\nI believe the key lies with their researchers. Find out what they're up to and report back to me with the details.", objectives = "Thassarian, aboard the Skybreaker, wants you to collect the 3 pages of Cultists' Research from the Cult Researchers at Aldur'thar and use them to create the Cult of the Damned Thesis.", progress = "Have you determined what their researchers are up to, <race>?", completion = "This is alarming, indeed...." }
WordHunterWoW_QuestEN[13346] = { title = "No Rest For The Wicked", description = "These fools have actually stumbled upon something that could pose a serious threat to our plans!\n\nThe leader of this particular sect, Alumeth, has ritualistically sacrificed himself and now his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nCombine his heart, skull, scepter and robes from around their chamber and use his remains on the crystal there.\n\nHurry, {race}! Destroy him before he becomes any more powerful!", objectives = "Thassarian, aboard the Skybreaker, wants you to defeat Alumeth the Ascended at Aldur'thar.", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers..." }
WordHunterWoW_QuestEN[13347] = { title = "Reborn From The Ashes", description = "Our fate is emblazoned upon our souls at birth. Bolvar's fall, while tragic, was unavoidable.\n\nAll that you can do now is honor your hero, <name>. Collect Bolvar's shield from the field of battle and return it to your king. When you present the shield to Varian, tell him this: \"All is not lost. From the ashes of the fallen will rise a force that will unite nations and purge the evil from this world.\"\n\nHe mustn't lose faith. Go now, <name>. Your people need a hero. They need you.", objectives = "Gather Fordragon's Shield from the field of battle at Angrathar the Wrath Gate and return it to King Varian Wrynn at Stormwind Keep in Stormwind City.", progress = "<King Wrynn brushes away a tear.>\n\n<King Wrynn nods.>\n\nThis is my fault.", completion = "The Dragon Queen is right, <name>. All is not lost. I will be the force that rises from the ashes and I will purge the evil of the Horde from this world. The deaths of our brothers and sisters will not have been in vain." }
WordHunterWoW_QuestEN[13348] = { title = "Futility", description = "Do you see now?  Sending your men against the prince's armies just swells their numbers.\n\nI don't expect you to understand... you'll probably just end up like the others.  You'd best return to whoever sent you.  They might be worried.", objectives = "Return to Koltira Deathweaver aboard Orgrim's Hammer.", completion = "There you are.  Nice work down in the valley.  The carnage was visible all the way up here.\n\nAre you okay?  You look like you've seen a ghost." }
WordHunterWoW_QuestEN[13349] = { title = "Cradle of the Frostbrood", description = "We need to keep our momentum going.  Let's not give the Scourge forces any respite.\n\nSindragosa's Fall lies east just beyond the Valley of Lost Hope.  The Cult of the Damned operate there, under close supervision of the Lich King's undead vrykul lackeys.\n\nIt is a place of great power, possibly a blue dragonflight graveyard.  The feared frostbrood are raised there from the bones of blue dragons.\n\nAn attack there would have great impact on the enemy's access to frost wyrms.  Are you up to it, {name}?", objectives = "Koltira Deathweaver aboard Orgrim's Hammer wants you to slay 5 Wyrm Reanimators, 8 Cultist Corrupters and 3 Vrykul Necrolords at Sindragosa's Fall.", completion = "You've done well, <name>.  You might want to rest for a while.  You look a little pale." }
WordHunterWoW_QuestEN[13350] = { title = "No Rest For The Wicked", description = "It's Alumeth... He's growing in power again. I can sense it. Again his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nReturn to his chamber in the north portion of Aldur'thar. Combine his heart, skull, scepter and robes, then use his remains on the crystal there.\n\nHurry, {race}! Destroy him before he becomes any more powerful!", objectives = "Thassarian, aboard the Skybreaker, wants you to defeat Alumeth the Ascended at Aldur'thar.", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers..." }
WordHunterWoW_QuestEN[13351] = { title = "Sneak Preview", description = "Progress is being made. We have a promising array of tactics that should gain us control of the death gate. There will doubtlessly be many casualties, but in the end,  we should be able to prevail - barring any interference from the Alliance.\n\nOur next focus will be Aldur'thar, the gate of desolation. Fly down and become familiar with it and with the enemies posted there.\n\nWhen you return, I will have your missions prepared.", objectives = "Koltira, aboard Orgrim's Hammer, wants you to fly down to the gate of desolation, visiting the south, central, north, and northwest regions of the gate.", completion = "Well and good, <class>.\n\nNow that you've seen firsthand what we're up against, it's time to get to work..." }
WordHunterWoW_QuestEN[13352] = { title = "Drag and Drop", description = "The Cult of the Damned hold the gate of desolation, eh? No surprise there.\n\nTime to have a little fun. At the southern end of the gate, you mentioned there were new cultists being trained. They're almost certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nKill the fools until you find one, {class}, then use it on a subjugator.", objectives = "Koltira, aboard Orgrim's Hammer, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old...." }
WordHunterWoW_QuestEN[13353] = { title = "Drag and Drop", description = "Looks like those initiates are increasing in number again. You know what to do...\n\nAt the southern portion of the gate, the new cultists are being trained. They're certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nSlay the fools until you find some, then use them on the subjugators there.", objectives = "Koltira, aboard Orgrim's Hammer, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old...." }
WordHunterWoW_QuestEN[13354] = { title = "Chain of Command", description = "Based on your report, and my knowledge of the Cult, they have an overseer managing the operation of each encampment on the gate.\n\nWhile taking their leaders down will only be a temporary setback, it will at least slow them down and keep them off-balance. And that, {race}, is a worthy enough goal for now.\n\nSeek out these overseers and return to me when they have been dispatched.", objectives = "Koltira aboard Orgrim's Hammer wants you to go to Aldur'thar and defeat Overseer Faedris, Overseer Savryn, Overseer Veraj, and Overseer Jhaeqon.", completion = "Well done, <race>. But don't break your arm patting yourself on the back. They'll have those overseers replaced in no time..." }
WordHunterWoW_QuestEN[13355] = { title = "Cannot Reproduce", description = "I smell their cauldrons from here, but that's not plague they're cooking.\n\nPledges to the cult are forced to drink a concoction that steals their will and enslaves them forever to the Lich King.\n\nSome say the potion contains the twisted soul of a being who was tormented before being mercilessly slaughtered, but I've never been able to reproduce it...\n\nFill this flask with a sample from each of the three cauldrons in the northwest region of the gate and bring it to Chief Engineer Copperclaw.", objectives = "Koltira aboard Orgrim's Hammer wants you to use the Partitioned Flask at each of the 3 Cultists' Cauldrons at Aldur'thar, then bring it to Chief Engineer Copperclaw.", progress = "Whatdya got there, <class>?", completion = "<Copperclaw pours the contents of the flask into his particle analyzer.>\n\nAhh... I know just the thing!" }
WordHunterWoW_QuestEN[13356] = { title = "Retest Now", description = "This should do the trick!\n\nThose twisted hooligans are looking for souls to put in their crazy-juice? Then I say we help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... Its only effect will be to detect any cultist's essence once you've defeated them.\n\nWhen you've collected a bunch of essences, throw the writhing mass of twisted souls into any of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", objectives = "Chief Engineer Copperclaw aboard Orgrim's Hammer wants you to throw a Writhing Mass into a cauldron at Aldur'thar.", completion = "Wahoo!\n\nThat'll teach 'em!" }
WordHunterWoW_QuestEN[13357] = { title = "Retest Now", description = "Those twisted cultists are looking for souls to put in their crazy-juice? Then let's help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence.\n\nOnce you've collected a bunch of 'em, throw the writhing mass of twisted souls in one of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", objectives = "Chief Engineer Copperclaw aboard Orgrim's Hammer wants you to throw a Writhing Mass into a cauldron at Aldur'thar.", completion = "Wahoo!\n\nThat'll teach 'em!" }
WordHunterWoW_QuestEN[13358] = { title = "Not a Bug", description = "Alright, friend, time to plant a bug.\n\nRelax, it's not a bug exactly, but it'll serve our purposes.\n\nIn the northern portion of Aldur'thar, the cult's void summoners enslave demonic minions. Use this rod to siphon the dark matter from the corpses of these enslaved minions, and then use the cultists' summoning crystal to bring our little spy into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", objectives = "Koltira, aboard Orgrim's Hammer, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", completion = "You have done well, <class>.\n\nThe messenger has already turned up some valuable information." }
WordHunterWoW_QuestEN[13359] = { title = "Where Dragons Fell", description = "A whole brood of blue dragons fell here.  And now, one by one, they're being raised by his servants.\n\nHe raised the biggest of them all himself.  Bring me some bone dust from the whelps and I'll show you exactly how he did it.", objectives = "Matthias Lehner at Sindragosa's Fall wants you to obtain 6 Whelp Bone Dusts.", progress = "Did you get the dust, <name>?", completion = "Even the mighty wyrms had to heed his call.  How is a simple mortal like you going to resist him?" }
WordHunterWoW_QuestEN[13360] = { title = "Time for Answers", description = "You have a lot of questions, {name}.  You're the only one who can see me because you touched something that once belonged to him... don't you remember?\n\nYou don't know what it is?  Well I can't just tell you... that would make him really mad.  He's not just a prince anymore... he's the king!\n\nMeet me at the Court of Bones, north of Icecrown Citadel and you can see for yourself.", objectives = "Speak to Matthias Lehner at the Court of Bones.", completion = "There you are.  I started to wonder whether you'd show up." }
WordHunterWoW_QuestEN[13361] = { title = "The Hunter and the Prince", description = "Before the prince became a king, he fought many battles... but only one where he came close to dying.\n\nIt was fought right here.  After you let me show you what happened, you'll understand everything.\n\nFind a bloodstained stone and pick it up from the floor.  You'll see what happened.", objectives = "Matthias Lehner in the Court of Bones wants you to look for a Bloodstained Stone and complete the Prince's Destiny.", progress = "Did you see, <name>?  Did you?", completion = "After that fight, the prince realized what was holding him back was that he was still human... he could still feel... he could still bleed.  He still had a heart.\n\nThe first thing he did when he became king was to rid of himself of it.  He threw it down the pit where we first met.  And you, <name>, were the first person to touch it since." }
WordHunterWoW_QuestEN[13362] = { title = "Knowledge is a Terrible Burden", description = "Now you know what you're up against, {name}.  An opponent who no longer knows pain... remorse... or humanity.  An opponent who will do anything to get what he wants.\n\nThe heart was his weakness and now he knows you've found it.\n\nIf you're going to go back for it, you'd best bring help.  He will not leave it unguarded again.", objectives = "Report back to Koltira aboard Orgrim's Hammer.", completion = "Little kid's ghost... Arthas's heart... you'd better slow down... you're making my head spin." }
WordHunterWoW_QuestEN[13363] = { title = "Argent Aid", description = "There were rumors about the events you speak of among the death knights.  I always expected the story to be more... symbolic.\n\nWe must warn others, but we must be discreet.  As soon as the Lich King knows we're making our move, he'll move the location of the heart -- we'll never get a chance like this again.\n\nThe Horde and the Alliance have been infiltrated by the Cult of the Damned before.  The Ebon Blade operates too close to the Scourge.\n\nWe have to speak to Tirion Fordring and his Argent Crusade.", objectives = "Speak to Highlord Tirion Fordring at the Crusader's Pinnacle.", completion = "Heavy words, <name>.  If it were somebody else saying them, I'd be likely to judge them insane." }
WordHunterWoW_QuestEN[13364] = { title = "Tirion's Gambit", description = "Just this morning, my scouts informed me of a Cult of the Damned procession leaving from Icecrown Citadel to the Cathedral of Darkness, bearing an artifact.\n\nAnd now I learn that it might be Arthas's own heart... a thing containing the last bit of his remaining humanity.\n\nThis is a sign of the Light.  As long as such an artifact exists, there is a chance that Arthas Menethil can become a man again!\n\nMeet me at the cathedral's entrance.  Be sure to bring a cultist's hood -- we're going incognito.", objectives = "Tirion Fordring, at the Crusader's Pinnacle, wants you to obtain and wear a Cultist Acolyte's Hood and meet him at the entrance of the Cathedral of Darkness, northwest of Icecrown Citadel.", completion = "I do not view what we just went through as a failure, <name>... quite the opposite.\n\nBy allowing me to peer into his heart, you allowed me to confirm what I needed to know.  There is no Arthas Menethil anymore -- there is only the Lich King." }
WordHunterWoW_QuestEN[13365] = { title = "Not a Bug", description = "The cultists have discovered the last messenger you summoned, {race}.\n\nWhile it was quite informative, it's important that we continue to monitor the cult's every move.\n\nUse this rod to siphon the dark matter from the corpses of enslaved minions at Aldur'thar. Then use their summoning crystal to bring another dark messenger into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", objectives = "Koltira, aboard Orgrim's Hammer, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", completion = "Well done, friend.\n\nThe messenger is up and reporting in as we speak." }
WordHunterWoW_QuestEN[13366] = { title = "Need More Info", description = "The Cult of the Damned are notorious for concocting grandiose plans that in the end, rarely succeed. But something feels different this time....\n\nPerhaps it's the proximity to the Lich King that has their fervor heightened. Whatever it is, they appear to be more confident than ever. We must know what feeds this bravado and then find a way to strip them of it!\n\nI believe the key lies with their researchers. Find out what they're up to and report back to me with the details.", objectives = "Koltira, aboard Orgrim's Hammer, wants you to collect the 3 pages of Cultists' Research from the Cult Researchers at Aldur'thar and use them to create the Cult of the Damned Thesis.", progress = "Have you discovered what their researchers are up to, <class>?", completion = "This is alarming, indeed...." }
WordHunterWoW_QuestEN[13367] = { title = "No Rest For The Wicked", description = "These fools have actually stumbled upon something that could pose a serious threat to our plans!\n\nThe leader of this particular sect, Alumeth, has ritualistically sacrificed himself and now his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nCombine his heart, skull, scepter and robes from around their chamber and use his remains on the crystal there.\n\nHurry, {race}! Destroy him before he becomes any more powerful!", objectives = "Koltira, aboard Orgrim's Hammer, wants you to slay Alumeth the Ascended at Aldur'thar.", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers..." }
WordHunterWoW_QuestEN[13368] = { title = "No Rest For The Wicked", description = "It's Alumeth... He's growing in power again. I can sense it. Again his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nReturn to his chamber in the north portion of Aldur'thar. Combine his heart, skull, scepter and robes, then use his remains on the crystal there.\n\nHurry, {race}! Destroy him while there's still time!", objectives = "Koltira, aboard Orgrim's Hammer, wants you to slay Alumeth the Ascended at Aldur'thar.", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers..." }
WordHunterWoW_QuestEN[13369] = { title = "Fate, Up Against Your Will", description = "At the behest of Lady Proudmoore, I will allow a diplomatic mission to Orgrimmar to question the Horde's Warchief, Thrall. You will assist her in this journey and keep her safe from harm. Return to me with news from Orgrimmar.\n\nSpeak to Jaina when you are ready to leave.", objectives = "Assist Lady Jaina Proudmoore in Orgrimmar. Speak to the Warchief of the Horde, Thrall, at Orgrimmar on the continent of Kalimdor.At the behest of Lady Proudmoore, I will allow a diplomatic mission to Orgrimmar to question the Horde's Warchief, Thrall. You will assist her in this journey and keep her safe from harm. Return to me with news from Orgrimmar.\n\nSpeak to Jaina when you are ready to leave.", completion = "The Horde does not want war, <race>. Listen well..." }
WordHunterWoW_QuestEN[13370] = { title = "A Royal Coup", description = "Your champion, Bolvar, died in defense of our world. The Horde is saddened by the loss of such a great hero, but the Horde was not responsible for the cowardly attacks made by Putress at the Wrath Gate. We have also lost mighty heroes because of this betrayal.\n\nTell your king that we will do everything in our power to bring the perpetrators of this cowardly act to justice. We will do all that we can to avoid conflict with the Alliance, but we will not hesitate to defend ourselves if provoked.", objectives = "Use the portal in Grommash Hold to return to Stormwind Keep and deliver Thrall's message to King Varian Wrynn.", completion = "They have lost the Undercity? Then the time to strike is now. We will deal with Putress ourselves and retake the Ruins of Lordaeron for the Alliance!" }
WordHunterWoW_QuestEN[13371] = { title = "The Killing Time", description = "I sent Broll and Valeera to the Undercity before you left for Orgrimmar. In fact, they're now stationed outside the sewer entrance to the ruins, awaiting orders.\n\nLady Proudmoore will open a portal to our forces outside the Undercity. Go there and report to Broll. Jaina and I will be close behind.", objectives = "Use the Portal to the Undercity inside Stormwind Keep to teleport to the Undercity. Report to Broll Bearmantle when you arrive at your destination.", completion = "Who are you supposed to be? Varian said he'd send heroes." }
WordHunterWoW_QuestEN[13372] = { title = "The Key to the Focusing Iris", description = "A potent thrumming of magical nature can be heard and felt emanating from the eye-shaped jewel dropped from Sapphiron's clutches. To mortal ears it is nearly painful to be in the presence of the stone.\n\nSurely such a powerful item of import can only be taken to the queen of the dragons, Alexstrasza the Life-Binder. Seek her counsel atop Wyrmrest Temple in the Dragonblight.", objectives = "Deliver the Key to the Focusing Iris to Alexstrasza the Life-Binder atop Wyrmrest Temple in the Dragonblight.", progress = "<name>, you have come into contact with a key to the focusing iris! Do you have it upon your person?\n\n\n\nHow did you ever come into its possession? Oh, Sapphiron still had his?", completion = "These keys are held by the most ancient members of the blue dragonflight. Only they are entrusted with them by their master, Malygos.\n\nThis is the break that we've been waiting for to strike at the Aspect of Magic!\n\n<The queen of dragons studies you for a brief moment.>\n\nYou are not able to use the key as-is to access the Focusing Iris, but I can imbue you with a portion of my power; enough to enable you to use it to open the iris a fraction.\n\nIt will be enough to draw Malygos's ire!" }
WordHunterWoW_QuestEN[13373] = { title = "Fringe Science Benefits", description = "I installed our infra-green technology into commandeered bombers; it'll protect you on your first mission into enemy territory!  Speak with Rizzy Ratchwiggle to get a bomber, then fly into The Bombardment!\n\nYou'll have bombs and rockets and shields.  Keep the shields charged and use bombs on the ground Scourge at The Bombardment.  Come back after you hit your targets, and more work will await you.", objectives = "Fringe Engineer Tezzla wants you to kill 40 Bombardment Infantry, 8 Bombardment Captains and 15 Gargoyle Ambushers.", completion = "Hah, you got them!  How did you like the bomber?  I hope you got the hang of it, because I have more missions for you..." }
WordHunterWoW_QuestEN[13374] = { title = "Amped for Revolt!", description = "{name}, only our best pilots are given a mission like this, one deep, deep into enemy territory with only the power of infra-green technology to protect you!\n\nRequest another bomber from Rizzle, and this time fly it through the Valley of Lost Hope.  You have both air and ground targets on this mission, so keep your eyes open and your shields at full!\n\nGood luck!", objectives = "Fringe Engineer Tezzla wants you to kill Bombardment Infantry, Gargoyle Ambushers, Frostbrood Sentries and Scourge War Machines." }
WordHunterWoW_QuestEN[13375] = { title = "The Heroic Key to the Focusing Iris", description = "A potent thrumming of magical nature can be heard and felt emanating from the eye-shaped jewel dropped from Sapphiron's clutches. To mortal ears it is nearly painful to be in the presence of the stone.\n\nSurely such a powerful item of import can only be taken to the queen of the dragons, Alexstrasza the Life-Binder. Seek her counsel atop Wyrmrest Temple in the Dragonblight.", objectives = "Deliver the Heroic Key to the Focusing Iris to Alexstrasza the Life-Binder atop Wyrmrest Temple in the Dragonblight.", progress = "<name>, you have come into contact with a key to the iris! Do you have it upon your person?\n\n\n\nHow did you ever come into its possession? Oh, Sapphiron still had his?", completion = "These keys are held by the most ancient members of the blue dragonflight. Only they are entrusted with them by their master, Malygos.\n\nThis is the break that we've been waiting for to strike at the Aspect of Magic!\n\n<The queen of dragons studies you for a brief moment.>\n\nYou are not able to use the key as-is to access the Focusing Iris, but I can imbue you with a portion of my power; enough to enable you to use it to open the iris a fraction.\n\nIt will be enough to draw Malygos's ire!" }
WordHunterWoW_QuestEN[13376] = { title = "Total Ohmage: The Valley of Lost Hope!", description = "<name>, the struggle continues.  Lucky for us, we're stocked up on bombs and rockets!  Time for another bombing mission  --  this one's a long one, through the Bombardment and into the Valley of Lost Hope.  Head back out with an infra-green bomber and blow those Scourge into little scourge-lets!", objectives = "Fringe Engineer Tezzla wants you to kill 50 Bombardment Infantry, 20 Gargoyle Ambushers, 12 Frostbrood Sentries and 12 Scourge War Machines.", completion = "Great work, <name>.  While you were out, I heard other gunners talking about you... I think you have a real future in air offense!" }
WordHunterWoW_QuestEN[13377] = { title = "The Battle For The Undercity", description = "Deep inside the bowels of the Undercity hides the assassin responsible for the deaths of Bolvar and our brave soldiers at the Wrath Gate.\n\nVarian has brought the full might of the Alliance with him to assist in the take down. Join him and Lady Proudmoore in the manhunt and earn your place among the greatest champions of the Alliance!\n\nSpeak to King Varian Wrynn when you are ready.", objectives = "Assist King Varian Wrynn and Lady Jaina Proudmoore in bringing Grand Apothecary Putress to justice! Report to King Varian Wrynn should you succeed.", completion = "For too long have the Horde been left unchecked. We allowed their territories to prosper and in return for our generosity they plotted and planned our demise.\n\nPeace? Useless... It's gotten us nowhere. We have lost some of our greatest heroes to \"peace.\" Let us see what battle brings...\n\nReturn to Northrend, <name>. Conquer it for your king - FOR THE ALLIANCE!" }
WordHunterWoW_QuestEN[13378] = { title = "Chief Engineer Copperclaw", description = "Speak with Chief Engineer Copperclaw.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Chief Engineer Copperclaw.Speak with Chief Engineer Copperclaw.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[13379] = { title = "Green Technology", description = "Tezzla is the one you want to meet, yes she is... she mastered a new wavelength, infra-green, and used it to hide herself near the Scourge!  Near enough to bomb them!\n\nI'll give you infra-green vision so you can find her hiding above Aldur'thar, the Desolation Gate.  Go, go... I know she has work for brave heroes eager to blow up!  I mean... eager to blow up the Scourge!\n\nAnd <name>, the Alliance has stolen our technology and has their own hidden airport nearby.  Avoid the dome with the Alliance banners!", objectives = "Speak with Fringe Engineer Tezzla.", completion = "Yes, yes!  You found me!  And just in time!" }
WordHunterWoW_QuestEN[13380] = { title = "Leading the Charge", description = "Infra-green technology allows us to stay hidden here, right over the Scourge's nose!  What's more, we installed infra-green in specially constructed bombers... but not to hide them, no!  We use infra-green tech to shield them!\n\nSpeak with Karen No and request a bomber.  Fly it over the Bombardment... use its shields and turret to protect yourself, and use the bomb launcher to hit Scourge targets.  Practice well, then return to me and I'll have an even more vital mission for you!", objectives = "Kibli Killohertz wants you to kill 40 Bombardment Infantry, 8 Bombardment Captains and 15 Gargoyle Ambushers.", completion = "I could hear your explosions from here, <name>.  How did the shields work?  Did they keep your bomber intact?\n\nI hope they did, because now I have more missions for you...." }
WordHunterWoW_QuestEN[13381] = { title = "Watts My Target", description = "Put on your lucky socks, {name}, and say your favorite prayers.  This next mission will test your wit and fortitude like a visit from the in-laws!\n\nRequest another bomber from Karen No.  Take it beyond The Bombardment and over the Valley of Lost Hope.  You have more targets this time, both on the land an in the air.  Keep your shields charged and your ammo loaded, {name}!  I'll see you when it's over.", objectives = "Kibli Killohertz wants you to kill Bombardment Infantry, Gargoyle Ambushers, Frostbrood Sentries and Scourge War Machines." }
WordHunterWoW_QuestEN[13382] = { title = "Putting the Hertz: The Valley of Lost Hope", description = "The fight goes on!  Your new orders arrived for a long-range bombing mission through the Bombardment and into the Valley of Lost Hope -- when you're ready, ask Karen for a bomber and pour those bombs and rockets onto the Scourge!", objectives = "Kibli Killohertz wants you to kill 50 Bombardment Infantry, 20 Gargoyle Ambushers, 12 Frostbrood Sentries and 12 Scourge War Machines.", completion = "Welcome back, <name>.  How was the battle?  Exciting?  Take a rest for now.  But come back when you have fresh orders.\n\nFor the Alliance!" }
WordHunterWoW_QuestEN[13383] = { title = "Killohertz", description = "The goblins got lucky and found a new energy.  They call it infra-green, and I'll be a one-eyed ogre if those psychos didn't strike green gold.\n\nGo find Kibli Killohertz.  He's leading the reverse engineering efforts of infra-green, at a small, hidden Alliance airport above Aldur'thar, the Desolation Gate.  I'll give you infra-green vision to help you find it.  Go to the dome with our Alliance banners -- if you fly near the Horde airport then you'll be in a load of green trouble.", objectives = "Chief Engineer Boltwrench wants you to find Kibli Killohertz at the hidden Alliance airport above Aldur'thar, the Desolation Gate.", completion = "Yes, yes, yes!  A thousand times, hello!" }
WordHunterWoW_QuestEN[13384] = { title = "Judgment at the Eye of Eternity", description = "Now that you have access to the focusing iris it's time to put that key to use.\n\nAs much as I would like to see Malygos brought back into the fold, that's just not going to happen at this point. With everything that's at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.\n\n<Krasus says this last with a great deal of trepidation.>\n\n{name}, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.", objectives = "Krasus atop Wyrmrest Temple in the Dragonblight wants you to return with the Heart of Magic.\n\nThis quest is for the Normal mode, 10-person version of The Eye of Eternity.", progress = "Only Malygos carries the Heart of Magic. It is his most prized possession.", completion = "This is a very sad day, not only for dragonkind, but for all of the living creatures of Azeroth. We have lost one of our most thoughtful, intelligent and ancient friends. Magic is now without its guardian.\n\nLet us hope that this was a wise decision in the coming years, <name>. A storm is still brewing on the horizon and now we are without one of our most powerful defenders." }
WordHunterWoW_QuestEN[13385] = { title = "Heroic Judgment at the Eye of Eternity", description = "Now that you have access to the focusing iris it's time to put that key to use.\n\nAs much as I would like to see Malygos brought back into the fold, that's just not going to happen at this point. With everything that's at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.\n\n<Krasus says this last with a great deal of trepidation.>\n\n{name}, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.", objectives = "Krasus atop Wyrmrest Temple in the Dragonblight wants you to return with the Heart of Magic.\n\nThis quest is for the Heroic mode, 25-person version of The Eye of Eternity.", progress = "Only Malygos carries the Heart of Magic. It is his most prized possession.", completion = "This is a very sad day, not only for dragonkind, but for all of the living creatures of Azeroth. We have lost one of our most thoughtful, intelligent and ancient friends. Magic is now without its guardian.\n\nLet us hope that this was a wise decision in the coming years, <name>. A storm is still brewing on the horizon and now we are without one of our most powerful defenders." }
WordHunterWoW_QuestEN[13386] = { title = "Exploiting an Opening", description = "I've got an interesting assignment for you, {name}.  If you're up for a challenge, that is.\n\nWe've been tipped off about an opening below Icecrown Citadel.  Our engineers have studied the layout and have decided it's a structural weakness.\n\nWe've sent some men there along with some \"borrowed\" saronite bombs.  They're under Captain Kendall's command.\n\nWith a little help we could deal a huge blow to the forces of the Scourge.  What do you say, {name}?", objectives = "Speak to Captain Kendall below Icecrown Citadel.", completion = "Hail, <name>.  Thassarian mentioned you'd be dropping by.  Any friend of Thassarian's is my friend.  Well, any living friend of Thassarian, that is...  He does keep odd company." }
WordHunterWoW_QuestEN[13387] = { title = "Securing the Perimeter", description = "The saronite bombs are in place, {name}.  We're only going to get one shot at this, however.  Let's make it count.\n\nWe need temporary control of the area for a safe detonation.  Let's try to put a dent in the Scourge's numbers.", objectives = "Captain Kendall at Icecrown Citadel wants you to slay 10 Hulking Horrors.", completion = "You're as good as Thassarian said.  Good job!" }
WordHunterWoW_QuestEN[13388] = { title = "Set it Off!", description = "Things are looking good.  Let's do this.\n\nThe stack of bombs is right near the pit.  I'll start to evacuate the men.", objectives = "Captain Kendall, below Icecrown Citadel, wants you to go to the nearby Saronite Bomb Stack to light the fuse.", completion = "These bombs look pretty potent.  They should at least put a dent in the surrounding structure." }
WordHunterWoW_QuestEN[13389] = { title = "A Short Fuse", description = "As you light the fuse, you notice that it is consumed by fire far quicker than you would expect.\n\nThe bombs are about to go off and your best chance at surviving is to lean towards the pit and hope the fall doesn't kill you.", objectives = "Look for clues wherever the fall takes you.", completion = "This pulsing object is covered in a thick layer of ice.  It shimmers strangely beneath the water." }
WordHunterWoW_QuestEN[13390] = { title = "A Voice in the Dark", description = "The object is not a crystal at all, but some form of organ, encased in ice.\n\nAs you touch it, your hand reels in horrible pain.  You feel as if your hand has been cut, yet there is no visible wound.\n\nAs you collect your thoughts, you hear a young boy's voice nearby.\n\n\"You really shouldn't have done that.\"", objectives = "Investigate the nearby voice in Naz'anak, the Forgotten Depths.", completion = "I saw him get rid of it, you know?  He threw it all the way down here.\n\nSaid he wouldn't need it anymore.  Said it made him weak." }
WordHunterWoW_QuestEN[13391] = { title = "Time to Hide", description = "You shouldn't have touched it.  But now that you did, he's going to come looking for you.\n\nAnd he'll find you.  Unless you hide yourself from him.\n\nBring me blood from the faceless ones if you want to live!", objectives = "Matthias Lehner wants you to obtain 3 Faceless One's Blood.", progress = "Did you get the blood?", completion = "What are you waiting for?  You have to rub it on you!\n\nQuick!  Or he'll see you!" }
WordHunterWoW_QuestEN[13392] = { title = "Return to the Surface", description = "You should leave now.  You'll find a portal behind me.  It'll take you to the surface.\n\nWe'll meet again.  He'll be looking for you.\n\nIt's only a matter of time until he finds you.", objectives = "Return to Thassarian aboard the Skybreaker.", completion = "It's you, <name>!  We thought you were a goner.\n\nThat explosion of yours put quite a bit of hurt on the Scourge.  Nearly took Captain's Kendall's eyebrows off in the process..." }
WordHunterWoW_QuestEN[13393] = { title = "Field Repairs", description = "All right.  Let's not celebrate just yet.  We need to capitalize on the momentum we've gathered with our little bombing mission.\n\nWe've spotted a workable Horde demolisher-class catapult in the field below.  The geist seem to be taking it apart.\n\nIf you can put it back together, we'll be able to do some serious damage to the Scourge's armies in the Valley.\n\nSure, you'll be a little outnumbered, but I've a lot of faith in you!", objectives = "Thassarian, aboard the Skybreaker, wants you to collect 5 Demolisher Parts from the Scavenging Geists and take them to the Wrecked Demolisher in the Valley of Lost Hope.", progress = "The demolisher has suffered much damage.", completion = "The demolisher has seen better days, but the structure hasn't suffered any permanent damage.  The parts you obtained should be enough to get it running again, at least temporarily." }
WordHunterWoW_QuestEN[13394] = { title = "Do Your Worst", description = "You're going to use this machine against the Scourge?  You're not going to win against them like that.\n\nYou can destroy hundreds... even thousands of them.  But you won't win.  Not out here.\n\nWhen you're done playing with your machine, meet me to the north.  There is an old army encampment.  What I will show you will teach you a little bit about who you're up against.", objectives = "Use the Refurbished Demolisher to destroy 150 Decomposed Ghouls, 20 Frostskull Mages and 2 Bone Giants in the Valley of Lost Hope. Speak to Matthias Lehner at the First Legion Forward Camp when you've completed this task.", completion = "You see?  You killed your fair share, but for every one you destroyed, another rose from the dirt to take its place.\n\nYou don't know what you're up against, <name>.  Let me show you." }
WordHunterWoW_QuestEN[13395] = { title = "Army of the Damned", description = "You probably think you're quite strong -- fighting these undead and crushing their bones beneath your war machines.\n\nThat is nothing compared to the strength it took to create them.\n\nI saw the prince do it himself.  I can show you how it happened... if you'd like.", objectives = "Matthias Lehner at the First Legion Forward Camp wants you to raise an army of 100 Ghoulish Minions.", completion = "The prince's true power wasn't his ability to make armies out of corpses... that was easy.\n\nBut killing his own men, with whom he'd shared many battles... the prince's true power was his ability to do what had to be done." }
WordHunterWoW_QuestEN[13396] = { title = "Futility", description = "Do you see now?  Sending your men against the prince's armies just swells their numbers.\n\nI don't expect you to understand... you'll probably just end up like the others.  You'd best return to whoever sent you.  They might be worried.", objectives = "Return to Thassarian aboard the Skybreaker.", completion = "Nice shooting, <name>.  The Scourge never had a chance.\n\nAre you feeling okay?  You look like you've seen a ghost.  Not that it would be an unusual thing around these parts, now that I think about it." }
WordHunterWoW_QuestEN[13397] = { title = "Sindragosa's Fall", description = "You're a real star, {name}.  See, when I give one of these other soldiers an assignment, the odds of them getting it done are about fifty-fifty.  The odds of them coming back... well, slightly worse.\n\nBut with you, it's always a guaranteed thing.  Like gnomish clockwork!\n\nAnyway, I have another one for you.  Sindragosa's Fall, east of the valley.  There is some serious cultist activity, including and not limited to, the raising of frost wyrms.  I need you to go kick their teeth in.\n\nI hate cultists.", objectives = "Thassarian aboard the Skybreaker wants you to slay 5 Wyrm Reanimators, 8 Cultist Corrupters and 3 Vrykul Necrolords at Sindragosa's Fall.", completion = "Nice job, <name>.  You make the rest of us look bad!" }
WordHunterWoW_QuestEN[13398] = { title = "Where Dragons Fell", description = "A whole brood of blue dragons fell here.  And now, one by one, they're being raised by his servants.\n\nHe raised the biggest of them all himself.  Bring me some bone dust from the whelps and I'll show you exactly how he did it.", objectives = "Matthias Lehner at Sindragosa's Fall wants you to obtain 6 Whelp Bone Dusts.", progress = "Did you get the dust, <name>?", completion = "Even the mighty wyrms had to heed his call.  How is a simple mortal like you going to resist him?" }
WordHunterWoW_QuestEN[13399] = { title = "Time for Answers", description = "You have a lot of questions, {name}.  You're the only one who can see me because you touched something that once belonged to him... don't you remember?\n\nYou don't know what it is?  Well I can't just tell you... that would make him really mad.  He's not just a prince anymore... he's the king!\n\nMeet me at the Court of Bones, north of Icecrown Citadel and you can see for yourself.", objectives = "Speak to Matthias Lehner at the Court of Bones.", completion = "There you are.  I started to wonder whether you'd show up." }
WordHunterWoW_QuestEN[13400] = { title = "The Hunter and the Prince", description = "Before the prince became a king, he fought many battles... but only one where he came close to dying.\n\nIt was fought right here.  After you let me show you what happened, you'll understand everything.\n\nFind a bloodstained stone and pick it up from the floor.  You'll see what happened.", objectives = "Matthias Lehner in the Court of Bones wants you to look for a Bloodstained Stone and complete the Prince's Destiny.", progress = "Did you see, <name>?  Did you?", completion = "After that fight, the prince realized what was holding him back was that he was still human... he could still feel... he could still bleed.  He still had a heart.\n\nThe first thing he did when he became king was to rid of himself of it.  He threw it down the pit where we first met.  And you, <name>, were the first person to touch it since." }
WordHunterWoW_QuestEN[13401] = { title = "Knowledge is a Terrible Burden", description = "Now you know what you're up against, {name}.  An opponent who no longer knows pain... remorse... or humanity.  An opponent who will do anything to get what he wants.\n\nThe heart was his weakness and now he knows you've found it.\n\nIf you're going to go back for it, you'd best bring help.  He will not leave it unguarded again.", objectives = "Report back to Thassarian aboard the Skybreaker.", completion = "Slow down, <name>.  Why don't you start again... from the beginning?" }
WordHunterWoW_QuestEN[13402] = { title = "Tirion's Help", description = "It's not the first time I've heard that story about Arthas and his heart... always thought it was some made-up tale to impress the rank and file.\n\nWe must act on this information immediately.  Unfortunately, we must do so in secret.\n\nArthas's agents are everywhere and if he finds out, our plan is dead in the water.\n\nWe need to take this to the Argent Crusade.  Every single paladin in that order was hand-picked by Tirion himself.  If there's anyone free of cultist infiltration, it's those guys.", objectives = "Speak to Highlord Tirion Fordring at the Crusader's Pinnacle.", completion = "Heavy words, <name>.  If it were somebody else saying them, I'd be likely to judge them insane." }
WordHunterWoW_QuestEN[13403] = { title = "Tirion's Gambit", description = "Just this morning, my scouts informed me of a Cult of the Damned procession leaving from Icecrown Citadel to the Cathedral of Darkness, bearing an artifact.\n\nAnd now I learn that it might be Arthas's own heart... a thing containing the last bit of his remaining humanity.\n\nThis is a sign of the Light.  As long as such an artifact exists, there is a chance that Arthas Menethil can become a man again!\n\nMeet me at the cathedral's entrance.  Be sure to bring a cultist's hood -- we're going incognito.", objectives = "Tirion Fordring, at the Crusader's Pinnacle, wants you to obtain and wear a Cultist Acolyte's Hood and meet him at the entrance of the Cathedral of Darkness, northwest of Icecrown Citadel.", progress = "Light be with you, <name>.", completion = "I do not view what we just went through as a failure, <name>... quite the opposite.\n\nBy allowing me to peer into his heart, you allowed me to confirm what I needed to know.  There is no Arthas Menethil anymore -- there is only the Lich King." }
WordHunterWoW_QuestEN[13404] = { title = "Static Shock Troops: the Bombardment", description = "This is a short-ranged mission, over The Bombardment.  A good warm up.  Ready?", objectives = "Kibli Killohertz wants you to kill 50 Bombardment Infantry, 10 Bombardment Captains and 20 Gargoyle Ambushers.", completion = "Welcome back, <name>.  A short mission, but invigorating, yes?  Take a rest for now.  But come back when you have fresh orders." }
WordHunterWoW_QuestEN[13405] = { title = "Call to Arms: Strand of the Ancients", description = "The fight in Northrend is not only against the armies of the Lich King, but also against those of the Horde.\n\nA powerful titan relic has been found in the Strand of the Ancients.  As you might know, we dwarves have been custodians of such artifacts for years and as such we're their rightful keepers.\n\nIn this case, the Horde has developed a keen interest in pilfering the relic from the titan ruins.  They're certain to use it as a weapon against us; we must do whatever we can to stop them.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win a Strand of the Ancients battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[13406] = { title = "Riding the Wavelength: The Bombardment", description = "Ready to warm up with a short bombing mission?  You have your orders, and we have our bombers stocked and ready.", objectives = "Fringe Engineer Tezzla wants you to kill 50 Bombardment Infantry, 10 Bombardment Captains and 20 Gargoyle Ambushers.", completion = "Hah, you got them!  I could hear their Scourge parts clatter off the mountain walls.  Good work.  We'll have more for you soon..." }
WordHunterWoW_QuestEN[13407] = { title = "Call to Arms: Strand of the Ancients", description = "Just because we march into Northrend to smash the Scourge, doesn't mean we get to take a break from crushing the Alliance.\n\nThose Explorers' League dwarves have found the location of a powerful titan relic and we'll be damned if we let the Alliance take control of it.\n\nGo, <name>, and destroy our enemies.  Make them see that no matter where we meet, they remain our sworn enemies.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win a Strand of the Ancients battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[13408] = { title = "Hellfire Fortifications", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, {name}, for you will no doubt clash with Horde forces eager to gain these same fortifications.", objectives = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.", progress = "<name>, return to me when you have aided in the capture of each of the forts!", completion = "Well done, <name>.  Your actions in the field are instrumental in our battle for Hellfire Peninsula." }
WordHunterWoW_QuestEN[13409] = { title = "Hellfire Fortifications", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", objectives = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", completion = "Nice work, <name>.  I could almost hear the battles waged at those forts.  I wish I was there to see them!" }
WordHunterWoW_QuestEN[13410] = { title = "Hellfire Fortifications", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, {name}, for you will no doubt clash with Horde forces eager to gain these same fortifications.", objectives = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.", completion = "Well done, <name>.  Your actions in the field are instrumental in our battle for Hellfire Peninsula." }
WordHunterWoW_QuestEN[13411] = { title = "Hellfire Fortifications", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", objectives = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", completion = "Nice work, <name>.  I could almost hear the battles waged at those forts.  I wish I was there to see them!" }
WordHunterWoW_QuestEN[13412] = { title = "Corastrasza", description = "Greetings, {class}. Might I impose on you for a favor?\n\nCorastrasza is the sister of Raelorasz - the red dragon in charge of our outpost here. Against his will, she has ascended to one of the upper rings of the Nexus to observe some frighteningly powerful blue drakes.\n\nThough he will never say it, he worries about her, and would welcome any news of her well-being.\n\nPlease seek her out. Ask her to put her pride aside and send word to her brother.", objectives = "Librarian Serrah wants you to speak to Corastrasza in Coldarra.", completion = "It's quite presumptuous of you to interfere in the personal affairs of a dragon, don't you think, <race>?\n\nThat aside, it would be wrong of me not to let my brother know that I am well. You may tell your meddling friend that I will keep my brother abreast of my actions." }
WordHunterWoW_QuestEN[13413] = { title = "Aces High!", description = "You possess the courage to draw so near to Malygos' lair, mortal? Or is it simply ignorance? Soon we shall know....\n\nI am a seasoned trainer of the graceful drakes of the red dragonflight. My business here is to study the enemy and teach my precious pets the tactics that will be most effective when we face the master of the blues.\n\nTo demonstrate your nerve and ability, I will allow you to ride one of my drakes against the enemy's minions.\n\nThe opportunity is yours for the asking...", objectives = "Corastrasza on the upper ring of the Nexus in Coldarra wants you to ride her drake and kill 5 Scalesworn Elites.", progress = "Well, mortal, what do you think of my pets?", completion = "My drake tells me that with practice, you might become a capable combatant.\n\nVery well, then. In the interest of our war on Malygos, I shall allow you to practice with my pets at your leisure.\n\nMake ready, <race>, for he is a fierce and unforgiving opponent." }
WordHunterWoW_QuestEN[13414] = { title = "Aces High!", description = "Again we meet, {race}. I confess, your presence is beginning to grow on me.\n\nAm I correct in assuming that you've come to hone your aerial combat skills?\n\nAs always, my pets stand ready to bring fiery destruction to the enemy.\n\nSpeak, and they shall be at your disposal.", objectives = "Corastrasza on the upper ring of the Nexus in Coldarra wants you to ride her drake and kill 5 Scalesworn Elites.", progress = "Yes, <race>?", completion = "I noticed some improvement today, <class>. At moments, it was as if you were one with the drake.\n\nYou are welcome to practice with my precious pets at your leisure." }
WordHunterWoW_QuestEN[13415] = { title = "The Library Console", description = "Norgannon's shell is within our reach, {name}. Take the inventor's disk into the library's interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon's shell. There are probably enough schematics stored there to keep Ironforge's engineers occupied for years!\n\nAnyway, use the disk to recover the shell. Hopefully, Mimir hasn't decided to put any more obstacles in our way. ", objectives = "Take the Inventor's Disk to the Inventor's Library Console inside the Inventor's Library.", progress = "The console appears to have an opening for the inventor's disk.", completion = "<You insert the disk into the console. Suddenly, lights on its surface illuminate and a mechanical voice speaks.>\n\nInventor's disk authenticated. Welcome back, Keeper Mimir." }
WordHunterWoW_QuestEN[13416] = { title = "The Library Console", description = "Norgannon's shell is within our reach, {name}. Take the inventor's disk into the library's interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon's shell. There are probably enough schematics stored there to keep Ironforge's engineers occupied for years!\n\nAnyway, bring the disk to the console. Hopefully, Mimir hasn't decided to put any more obstacles in our way. ", objectives = "Take the Inventor's Disk to the Inventor's Library Console inside the Inventor's Library.", progress = "The console appears to have an opening for the inventor's disk.", completion = "<You insert the disk into the console. Suddenly, lights on its surface illuminate and a mechanical voice speaks.>\n\nInventor's disk authenticated. Welcome back, Keeper Mimir." }
WordHunterWoW_QuestEN[13417] = { title = "The Brothers Bronzebeard", description = "That does it! We finally have the keystone... It's beautiful! I've been around the world more than once, but this thing's got me all jittery with excitement again. I suppose now's not the time to stop and admire though, we need to get the heck out of here.\n\nHop on my flying machine and help keep us covered from those iron dwarves on the way out!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Accompany Brann Bronzebeard and his flying machine to Frosthold." }
WordHunterWoW_QuestEN[13418] = { title = "Preparations for War", description = "You there!\n\nYou look like you have some wits about you. We could use some more able bodies in Icecrown.\n\nYou may have heard rumors of our failure in assaulting the glacier from the ground, but let me set those concerns to rest. We're now mounting our assault from one of the most advanced pieces of engineering known to Azeroth, the Skybreaker. The Horde don't stand a chance, and neither does Arthas.\n\nSpeak to me when you're ready to depart.", objectives = "Speak to Officer Van Rossem to secure passage to the Skybreaker in Icecrown, and then report to High Captain Justin Bartlett.", completion = "Welcome to the Skybreaker.\n\nFrom here we are laying our groundwork for the assault on Arthas. There's a lot of work to be done, but before we can get into the real meat of it, we want to make sure that the Argent Crusade is adequately reinforced - we're going to need their help later.\n\nIf you have not already, speak to Absalan the Pious on the main deck." }
WordHunterWoW_QuestEN[13419] = { title = "Preparations for War", description = "You there!\n\nYou look like you have some wits about you. We could use some more able bodies in Icecrown.\n\nThe Alliance scum rushed into Icecrown ahead of us, unprepared, and got just what they deserved for their impatience. We took our time, we made ready, and soon we will mount a true assault from one of the most advanced pieces of engineering known to Azeroth - Orgrim's Hammer. The Alliance don't stand a chance, and neither does Arthas.\n\nSpeak to me when you're ready to depart and lend a hand.", objectives = "Speak to Sky-Reaver Klum to secure passage to Orgrim's Hammer in Icecrown, and then report to Sky-Reaver Korm Blackscar.", completion = "Welcome to Orgrim's Hammer.\n\nFrom here we are laying our groundwork for the assault on Arthas. There's a lot of preparation to be done, but before we can get into the real meat of it, we want to make sure that the Argent Crusade is adequately reinforced - we're going to need their help later.\n\nIf you have not already, speak to Brother Keltan on the main deck." }
WordHunterWoW_QuestEN[13420] = { title = "Everfrost", description = "This piece of ice has been submitted to immense pressures and exposed to natural magics from deep beneath the world's surface. In combination, these effects have yielded an ice that will never melt.\n\nKnowing little of these things, you resolve to bring the sample back to Dun Niffelem. Someone there is bound to be familiar with its properties.", objectives = "You are to return to Dun Niffelem and ask Calder about the piece of Everfrost.\n\nProvided item:", completion = "<The reflection of the everfrost sparkles in Calder's eye as he holds it aloft.>\n\nAhh, everfrost. The symbol of the heart of our people...\n\nEverfrost was once plentiful in this region. Over the ages, though, the jormungar have devoured nearly all of it. It is now very rare and very precious to my people.\n\nAs you roam these lands, keep a lookout for more pieces of everfrost. Return to me with any that you find and we will be most grateful." }
WordHunterWoW_QuestEN[13421] = { title = "Remember Everfrost!", description = "", objectives = "Have you discovered any more everfrost, little <race>?", progress = "Have you discovered any more everfrost, little <race>?", completion = "Well done, little <class>.\n\nEverfrost was once plentiful in this region. Over the ages, though, the jormungar devoured nearly all of it. It is now very rare and very precious to my people.\n\nAs you roam these lands, keep a lookout for more pieces of everfrost. Return to me with any that you find and we will be most grateful." }
WordHunterWoW_QuestEN[13422] = { title = "Maintaining Discipline", description = "You've succeeded where others have failed.  Yet you cannot rest on your laurels.\n\nYou must show others what strength and commitment really mean.\n\nThe male insubordinates inside the Forlorn Mine need to be disciplined once again.  Show them sister... show them what it means to disobey us.", objectives = "Gretta the Arbiter in Brunnhildar Village wants you to use the Disciplining Rod on 6 Exhausted Vrykul inside the Forlorn Mine.", completion = "You continue to lead by example.  We look up to you, sister." }
WordHunterWoW_QuestEN[13423] = { title = "Defending Your Title", description = "Everyone's impressed by your performance, sister.  But do not let your guard down -- every new challenger with delusions of grandeur is going to come out swinging for your title of Hyldskvinnar.\n\nShow these upstarts what you're made of.", objectives = "Gretta the Arbiter in Brunnhildar Village wants you to defeat 6 Victorious Challengers.", completion = "You continue to prove yourself worthy.  We are honored by your presence." }
WordHunterWoW_QuestEN[13424] = { title = "Back to the Pit", description = "To truly stay in your best riding shape you'll want to test yourself against the other Hyldnir every day.\n\nHead back into the Pit of the Fang and show them what you're capable of.  They'll appreciate suffering defeat to one as skilled as yourself.", objectives = "Gretta the Arbiter, in Brunnhildar Village, wants you to use the Reins of the Icemaw Matriarch inside the Pit of the Fang and defeat 6 Hyldsmeet Warbears.", progress = "Hail, sister.", completion = "You continue to demonstrate your prowess.  Your sisters have not lost their respect for you." }
WordHunterWoW_QuestEN[13425] = { title = "The Aberrations Must Die", description = "It is not enough to demonstrate your prowess among your peers.  You must also fight our enemies, dear sister.\n\nThe Valkyrion traitors continue to mock our noble drake-riding traditions by rearing plagued proto-drakes.\n\nSeize the frost oil they wield and use it to freeze their abominable plagued eggs.", objectives = "Gretta the Arbiter in Brunnhildar Village wants you to go to Valkyrion and obtain Vials of Frost Oil from the Valkyrion Aspirants. Use the Vials of Frost Oil to destroy 30 Plagued Proto-Drake Eggs.", completion = "A leader in more ways than one.  We thank you, sister." }
WordHunterWoW_QuestEN[13426] = { title = "Xarantaur, the Witness", description = "It seems we're not the only visitors to this area. A courier relayed a message from a tauren named Xarantaur, who said he was visiting a taunka village called Camp Tunka'lo. The note was somewhat cryptic, but it seems this Xarantaur has come to Storm Peaks to learn the history of a taunka legend.\n\nMeet up with him, {name}. See if what he knows can help us in any way. From his description, Camp Tunka'lo is far to the east, beyond the Terrace of the Makers and north of Dun Niffelem.", objectives = "Speak with Xarantaur at Camp Tunka'lo.", completion = "So Boktar received my note? That's excellent news. I doubted the taunka longrunner who carried it would reach anyone." }
WordHunterWoW_QuestEN[13427] = { title = "Call to Arms: Alterac Valley", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.\n\nGo now, <name>, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran or Shattrath." }
WordHunterWoW_QuestEN[13428] = { title = "Call to Arms: Alterac Valley", description = "We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.\n\nA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.\n\nGo, <name>.  Earn great honor by heeding the call of the brave Frostwolf warriors.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran or Shattrath." }
WordHunterWoW_QuestEN[13429] = { title = "A Distraction for Akama", description = "<Xi'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders.  Xi'ri's army is ready to push Illidan's forces back and create a distraction for Akama.  The naaru awaits your request to begin the attack.>", objectives = "Ensure that Akama and Maiev enter the Black Temple in Shadowmoon Valley after Xi'ri's forces create a distraction.", progress = "<Xi'ri acknowledges your presence.>", completion = "<Xi'ri pulses with energy as you feel an object materialize in your hands.  It is the medallion you gave to A'dal on Akama's behalf, its power augmented by the naaru's magic.  The Sha'tar have entrusted you with the Medallion of Karabor, and with it access to the Black Temple.>" }
WordHunterWoW_QuestEN[13430] = { title = "Trial of the Naaru: Magtheridon", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!", objectives = "A'dal in Shattrath City wants you to slay Magtheridon.", completion = "You have proven yourself as a being of great power. The naaru approve..." }
WordHunterWoW_QuestEN[13431] = { title = "The Cudgel of Kar'desh", description = "Bring me the elemental signets that the cudgel requires!\n\nThe earthen signet is held by Gruul the Dragonkiller. Gruul can be found inside his lair in the Blade's Edge Mountains.\n\nThe second signet is the blazing heart of a creature known as Nightbane. This mythical beast is said to reside in the hallowed halls of the prophet, Medivh.\n\nMake haste!\n", objectives = "Skar'this the Heretic in the heroic Slave Pens of Coilfang Reservoir wants you to bring him the Earthen Signet and the Blazing Signet.", progress = "With the cudgel reformed, I shall break free of my bonds and return to Serpentshrine to exact vengeance on Vashj and her minions!", completion = "At last!\n\nWith these bonds broken and the cudgel in my possession I shall send  the sea witch back to the icy depths..." }
WordHunterWoW_QuestEN[13432] = { title = "The Vials of Eternity", description = "Seven vials were drawn from the Well of Eternity by Illidan.  He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created.  For years the rest were believed lost.\n\nWith the opening of the Dark Portal, we've come to know that he gave one each to his lieutenants Kael'thas and Vashj.  Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal, recent or ancient.  The outcome of the Battle of Mount Hyjal must be preserved.", objectives = "Soridormi at Caverns of Time wants you to retrieve Vashj's Vial Remnant from Lady Vashj at Coilfang Reservoir and Kael's Vial Remnant from Kael'thas Sunstrider at Tempest Keep.", progress = "I've asked the impossible of you, yet I expect you to succeed.  Much depends on it.", completion = "The power contained even in this small amount of water from the Well of Eternity is incredible.\n\nI can see clearly into every moment in time linked to Hyjal... the creation of the second Well of Eternity, Illidan's imprisonment, the enchantment of the World Tree and... yes!  The Battle of Mount Hyjal.\n\nWe must make haste, the timeline is not safe." }
