WordHunterWoW_QuestEN[13476] = { title = "For Great Honor", description = "Serving the Horde in one of the great battles against the Alliance is a source of great honor!  The few however, that have served the Horde in ALL of our active battlefronts are our truly great fighters.  We shall vanquish our opponents, not by fighting isolated skirmishes, but by waging a well-coordinated war.\n\nGo forth and crush the Alliance on every front!  For Honor!  For the Horde!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring a Mark of Honor from each battleground to a Horde Warbringer in any Horde capital city, Shattrath, Dalaran, or Wintergrasp." }
WordHunterWoW_QuestEN[13477] = { title = "Concerted Efforts", description = "", objectives = "" }
WordHunterWoW_QuestEN[13478] = { title = "Concerted Efforts", description = "We're not fighting isolated battles against the Horde anymore, <lad/lass>.\n\nVictory in one front means denying the Horde resources they'd use against us in a different battle.  By the same token, abandoning any given battle could give the advantage to our opponent somewhere else around the world.\n\nThe Alliance is in need of more combatants with this sort of worldly understanding... truly seasoned veterans!  <name>, come back to me after you've served against the Horde at all of our active battlegrounds.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring a Mark of Honor from each battleground to an Alliance Brigadier General in any Alliance Capital City, Shattrath, Dalaran, or Wintergrasp." }
WordHunterWoW_QuestEN[13479] = { title = "The Great Egg Hunt", description = "Noblegarden, celebration of life and spring! I hope you've been enjoying the egg hunt, friend, because I could use the services of a capable individual like you. \n\nI'm not certain what form of magic was used in the creation of the eggs, and the druids aren't keen on explaining it to me. Perhaps you could collect some shell fragments for me during your egg collection. You can keep the contents of the eggs; all I require is a sufficient sample of the eggs themselves.", objectives = "Get 20 shell fragments.", progress = "Do you have the fragments?", completion = "Excellent, excellent, thank you! I may need more of a sample to get truly conclusive results, but you've done well today." }
WordHunterWoW_QuestEN[13480] = { title = "The Great Egg Hunt", description = "Noblegarden, celebration of life and spring! I hope you've been enjoying the egg hunt, friend, because I could use the services of a capable individual like you.\n\nI'm not certain what form of magic was used in the creation of the eggs, and the druids aren't keen on explaining it to me. Perhaps you could collect some shell fragments for me during your egg collection. You can keep the contents of the eggs; all I require is a sufficient sample of the eggs themselves.", objectives = "Get 20 shell fragments.", progress = "Do you have the fragments?", completion = "Excellent, excellent, thank you! I may need more of a sample to get truly conclusive results, but you've done well today." }
WordHunterWoW_QuestEN[13481] = { title = "Let's Get Out of Here!", description = "The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape.\n\nI cannot make it on my own, {class}, but with your help, I may yet live to fight the Scourge again.\n\nWill you help me make my escape before the Scourge's butchers come to finish me off?", objectives = "Escort Father Kamaros to safety and then report to Brother Keltan aboard Orgrim's Hammer.", completion = "You have done well. We thought Father Kamaros lost, for certain. Your bravery will serve as an example to all those who oppose the Scourge." }
WordHunterWoW_QuestEN[13482] = { title = "Let's Get Out of Here", description = "The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape.\n\nI cannot make it on my own, my child, but with your help, I may yet live to fight the Scourge again.\n\nWill you help me make my escape before the Scourge's butchers come to finish me off?", objectives = "Escort Father Kamaros to safety and then report to Absalan the Pious aboard the Skybreaker.", completion = "Thank the Light. I'd thought Father Kamaros dead, or worse. Through your bravery and compassion, you have restored a great ally to the Argent Crusade. You have my thanks and those of the crusade." }
WordHunterWoW_QuestEN[13483] = { title = "Spring Gatherers", description = "If you're looking for something to do, I hear there are mages in the settlements near capital cities--Razor Hill, Brill, Bloodhoof Village, and Falconwing Square--who have been recruiting egg hunters for help with some research they're doing. I don't know the particulars, but I'm sure they'd tell you.", objectives = "Talk to a Spring Gatherer in Razor Hill, Brill, Bloodhoof Village, or Falconwing Square.", completion = "Yes! Yes, I think I have just the task for you..." }
WordHunterWoW_QuestEN[13484] = { title = "Spring Collectors", description = "If you're looking for something to do, I hear there are mages in the settlements near capital cities --Goldshire, Kharanos, Dolanaar, and Azure Watch--who have been recruiting egg hunters for help with some research they're doing. I don't know the particulars, but I'm sure they'd tell you.", objectives = "Talk to a Spring Collector in Goldshire, Kharanos, Dolanaar, or Azure Watch.", completion = "Yes! Yes, I think I have just the task for you..." }
