WordHunterWoW_QuestEN[13723] = { title = "The Valiant's Challenge", description = "You are nearly ready to compete on behalf of Gnomeregan in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.\n", objectives = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Ambrose Boltspark at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", completion = "You have proven yourself worthy of the title of champion, <name>. You will compete at the tournament's highest level on behalf of Gnomeregan, riding in the grand melee with your weapon at the ready and our mighty pennant at your back." }
