WordHunterWoW_QuestEN[13725] = { title = "The Valiant's Challenge", description = "You are nearly ready to compete on behalf of Darnassus in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", objectives = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Jaelyne Evensong at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", completion = "You have proven yourself worthy of the title of champion, <name>. You will compete at the tournament's highest level on behalf of Darnassus, riding in the grand melee with your weapon at the ready and our mighty pennant at your back." }
WordHunterWoW_QuestEN[13726] = { title = "The Valiant's Challenge", description = "You are nearly ready to compete in the grand melee. To prove yourself worthy of this honor, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", objectives = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Mokra the Skullcrusher at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", completion = "You have proven yourself worthy of the title of champion, <name>. You will compete at the tournament's highest level, riding in the grand melee and crushing the competition under the banner of Orgrimmar." }
WordHunterWoW_QuestEN[13727] = { title = "The Valiant's Challenge", description = "You are nearly ready to compete in the grand melee. To prove yourself worthy of this honor, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", objectives = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Zul'tore at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you overcome the Argent champion?", completion = "You have proven yourself worthy of the title of champion, <name>. You will compete at the tournament's highest level, riding in the grand melee and crushing the competition under the banner of the Darkspears." }
WordHunterWoW_QuestEN[13728] = { title = "The Valiant's Challenge", description = "You are nearly ready to compete in the grand melee. To prove yourself worthy of this honor, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", objectives = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Runok Wildmane at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", completion = "You have proven yourself worthy of the title of champion, <name>. You will compete at the tournament's highest level, riding in the grand melee and crushing the competition under the banner of the Thunder Bluff." }
WordHunterWoW_QuestEN[13729] = { title = "The Valiant's Challenge", description = "You are nearly ready to compete in the grand melee. To prove yourself worthy of this honor, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", objectives = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Deathstalker Visceri at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", completion = "You have proven yourself worthy of the title of champion, <name>. You will compete at the tournament's highest level, riding in the grand melee and crushing the competition under the banner of the Undercity." }
WordHunterWoW_QuestEN[13730] = { title = "Playing With Felfire", description = "<Draaka leans down to speak to you.>\n\nListen... Before you say anything, I KNOW we're not to meddle with demonic energies....\n\nBut look around you! These are desperate times, {class}.\n\nWe'll most likely die here, regardless. May as well go out in a blaze of glory, I say!\n\nSo... Are you in?\n\nTake this canister and go southeast to Felfire Hill. Use it near the patches of felfire and bring it back to me when you've filled it.\n\nOh, and best not to mention this to anyone....", objectives = "Draaka in Splintertree wants you to fill the Reinforced Canister with 7 Felfires from Felfire Hill.", progress = "Did you fill up that canister for me, <class>?", completion = "Oh, yes!\n\nThis will teach those elves, just you watch!" }
WordHunterWoW_QuestEN[13731] = { title = "The Valiant's Challenge", description = "You are nearly ready to compete in the grand melee. To prove yourself worthy of this honor, you must defeat a champion of the Argent Crusade.\n\nGo to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready.\n\nAfter the battle is concluded, we will speak of the outcome.", objectives = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Eressea Dawnsinger at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", completion = "You have proven yourself worthy of the title of champion, <name>. You will compete at the tournament's highest level, riding in the grand melee and crushing the competition under the banner of Silvermoon." }
WordHunterWoW_QuestEN[13732] = { title = "A Champion Rises", description = "Congratulations, {name}. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities.\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the grand melee.", objectives = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, <name>. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Alliance city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, <name>, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion." }
WordHunterWoW_QuestEN[13733] = { title = "A Champion Rises", description = "Congratulations, {name}. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities.\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the grand melee.", objectives = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, <name>. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Alliance city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, <name>, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion." }
