WordHunterWoW_QuestEN[13736] = { title = "A Champion Rises", description = "You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of Orgrimmar!\n\nJusticar Mariel Trueheart has asked to speak with you, {name}, and to formally enter you in the champions' grand melee.", objectives = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", completion = "I welcome you as a champion of the tournament, <name>. As a champion, you will be able to compete for the grand championship of the tournament. You may also choose to become a valiant with another Horde city's delegation and in time, a champion for that city as well.\n\nAll champions must have the assistance of a squire, <name>, and you are no exception. Allow me to appoint one of ours to accompany you in battle. He will proudly carry the banner of any city that has named you a champion." }
