WordHunterWoW_QuestEN[13761] = { title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. The people of Darnassus are looking forward to seeing us win the melee. To that end, they've been honing their skills against the valiants representing the other Alliance capitals.\n\nI suggest you do the same.\n\nThe Alliance Valiants' Ring is just outside our tent. Go to the stables on the outside the pavilion, equip your lance, mount the stabled Darnassian mistsaber, and challenge the valiants.", objectives = "Bring 3 Marks of the Valiant to Airae Starseeker at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Well done. Training against the other valiants is one of the best ways to prepare yourself for tournament competition. I know you'll make Darnassus proud, <name>." }
WordHunterWoW_QuestEN[13762] = { title = "A Blade Fit For A Champion", description = "I've heard that the Alliance champions are seeking after ancient blades for their warriors. We can't afford to let them have that kind of advantage.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", objectives = "Retrieve the Ashwood Brand and bring it to Mokra the Skullcrusher at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This blade should be enough to best anything those Alliance entrants can come up with." }
WordHunterWoW_QuestEN[13763] = { title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.\n", objectives = "Bring the Blade of Drak'Mar to Mokra the Skullcrusher at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "This is a fine weapon that will help me crush the competition. Thank you, <name>." }
WordHunterWoW_QuestEN[13764] = { title = "The Edge Of Winter", description = "Curse that death knight for breaking my sword!\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", objectives = "Mokra the Skullcrusher at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, <name>." }
WordHunterWoW_QuestEN[13765] = { title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", objectives = "Akinos at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", completion = "A good day of training will never hurt anyone. It's good to see you keeping up." }
WordHunterWoW_QuestEN[13766] = { title = "Closure is Only Natural", description = "Through the ground I can feel more demons being brought into our world. Soon there will be too many and we will be overrun without hope of turning them back.\n\nTake this piece of me and return to Demon Fall Canyon and Demon Fall Ridge, south of Felfire Hill. Aim the bough at a demon gate and concentrate. I have stored a portion of the forest's life force in its wood, and it will close the gate.", objectives = "Use Gnarl's Bough to close 10 Demon Gates.", completion = "With their gates closed and no further reinforcements coming, it is only a matter of time now before the demons are no more.\n\nYou are a hero of the forest, <name>. I give you thanks on behalf of all of Ashenvale's creatures!" }
WordHunterWoW_QuestEN[13767] = { title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.\n\nIt will help prepare you for the rigors of tournament combat.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Orgrimmar wolf, and challenge the valiants. They wait in the Horde Valiants' Ring just outside our tent.\n\n", objectives = "Bring 3 Marks of the Valiant to Morah Worgsister at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Training against the other valiants will sharpen your claws and hone your battle instincts. When the competition begins, you will be ready." }
WordHunterWoW_QuestEN[13768] = { title = "A Blade Fit For A Champion", description = "I've heard that the Alliance champions are seeking after ancient blades for their warriors. We can't afford to let them have that kind of advantage.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", objectives = "Retrieve the Ashwood Brand and bring it to Zul'tore at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This blade should be enough to best anything those Alliance entrants can come up with." }
WordHunterWoW_QuestEN[13769] = { title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", objectives = "Bring the Blade of Drak'Mar to Zul'tore at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "This is a fine weapon that will help me crush the competition. Thank you, <name>." }
WordHunterWoW_QuestEN[13770] = { title = "The Edge Of Winter", description = "Curse that death knight for breaking my sword!\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", objectives = "Zul'tore at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, <name>." }
WordHunterWoW_QuestEN[13771] = { title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", objectives = "Shadow Hunter Mezil-kree at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", completion = "A good day of training will never hurt anyone. It's good to see you keeping up." }
WordHunterWoW_QuestEN[13772] = { title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.\n\nIt will help prepare you for the rigors of tournament combat.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Darkspear raptor, and challenge the valiants. They wait in the Horde Valiants' Ring just outside our tent.\n\n", objectives = "Bring 3 Marks of the Valiant to Gahju at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Training against other valiants will quickly teach you what you need to know to best them. Keep it up and you'll have no trouble defeating them in competition." }
WordHunterWoW_QuestEN[13773] = { title = "A Blade Fit For A Champion", description = "I've heard that the Alliance champions are seeking after ancient blades for their warriors. We can't afford to let them have that kind of advantage.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", objectives = "Retrieve the Ashwood Brand and bring it to Runok Wildmane at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This blade should be enough to best anything those Alliance entrants can come up with." }
WordHunterWoW_QuestEN[13774] = { title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.\n", objectives = "Bring the Blade of Drak'Mar to Runok Wildmane at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "This is a fine weapon that will help me crush the competition. Thank you, <name>." }
WordHunterWoW_QuestEN[13775] = { title = "The Edge Of Winter", description = "Curse that death knight for breaking my sword!\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", objectives = "Runok Wildmane at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, <name>." }
WordHunterWoW_QuestEN[13776] = { title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", objectives = "Dern Ragetotem at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", completion = "A good day of training will never hurt anyone. It's good to see you keeping up." }
WordHunterWoW_QuestEN[13777] = { title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.\n\nIt will help prepare you for the rigors of tournament combat.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Mulgore kodo, and challenge the valiants. They wait in the Horde Valiants' Ring just outside our tent.", objectives = "Bring 3 Marks of the Valiant to Anka Clawhoof at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Training against the other valiants will sharpen your claws and hone your battle instincts. When the competition begins, you will be ready." }
WordHunterWoW_QuestEN[13778] = { title = "A Blade Fit For A Champion", description = "I've heard that the Alliance champions are seeking after ancient blades for their warriors. We can't afford to let them have that kind of advantage.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", objectives = "Retrieve the Ashwood Brand and bring it to Deathstalker Visceri at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This blade should be enough to best anything those Alliance entrants can come up with." }
WordHunterWoW_QuestEN[13779] = { title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", objectives = "Bring the Blade of Drak'Mar to Deathstalker Visceri at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "This is a fine weapon that will help me crush the competition. Thank you, <name>." }
WordHunterWoW_QuestEN[13780] = { title = "The Edge Of Winter", description = "Curse that death knight for breaking my sword!\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.\n", objectives = "Deathstalker Visceri at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, <name>." }
WordHunterWoW_QuestEN[13781] = { title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", objectives = "Sarah Chalke at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", completion = "A good day of training will never hurt anyone. It's good to see you keeping up." }
WordHunterWoW_QuestEN[13782] = { title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.\n\nIt will help prepare you for the rigors of tournament combat. \n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Forsaken warhorse, and challenge the valiants. They wait in the Horde Valiants' Ring just outside our tent.\n", objectives = "Bring 3 Marks of the Valiant to Handler Dretch at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Training against the other valiants will sharpen your claws and hone your battle instincts. When the competition begins, you will be ready." }
WordHunterWoW_QuestEN[13783] = { title = "A Blade Fit For A Champion", description = "I've heard that the Alliance champions are seeking after ancient blades for their warriors. We can't afford to let them have that kind of advantage.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", objectives = "Retrieve the Ashwood Brand and bring it to Eressea Dawnsinger at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This blade should be enough to best anything those Alliance entrants can come up with." }
WordHunterWoW_QuestEN[13784] = { title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", objectives = "Bring the Blade of Drak'Mar to Eressea Dawnsinger at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "This is a fine weapon that will help me crush the competition. Thank you, <name>." }
WordHunterWoW_QuestEN[13785] = { title = "The Edge Of Winter", description = "Curse that death knight for breaking my sword!\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", objectives = "Eressea Dawnsinger at the Argent Tournament Grounds wants you to bring her Winter's Edge.", progress = "Did you win the blade?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, <name>." }
WordHunterWoW_QuestEN[13786] = { title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", objectives = "Kethiel Sunlance at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", progress = "Have you tested yourself in combat against the Scourge?", completion = "A good day of training will never hurt anyone. It's good to see you keeping up." }
WordHunterWoW_QuestEN[13787] = { title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one.\n\nIt will help prepare you for the rigors of tournament combat.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Silvermoon hawkstrider, and challenge the valiants. They wait in the Horde Valiants' Ring just outside our tent.\n\n", objectives = "Bring 3 Marks of the Valiant to Aneera Thuron at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Training against the other valiants will sharpen your claws and hone your battle instincts. When the competition begins, you will be ready." }
WordHunterWoW_QuestEN[13788] = { title = "Threat From Above", description = "The Argent Crusade has doubled the guard since your exposure of the Cult of the Damned's infiltrator. They know the cultists won't stop until they've destroyed this area and thwarted the tournament.\n\nThe Argent Crusade's scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party.\n\nYou must intercept and destroy them before they attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", objectives = "Crok Scourgebane at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers.", completion = "<name>, you have spared the tournament from a devastating attack. The Argent Crusade and all who gather here are in our debt and we'll make certain they remember it. For all their bluster about providing protection, the peacekeepers and skytalons spend more time breaking up drunken brawls than keeping us safe from the Scourge.\n\nIt's no matter. We always protect our own." }
WordHunterWoW_QuestEN[13789] = { title = "Taking Battle To The Enemy", description = "The coliseum is perched in the most dangerous part of the world, {name}. The territory we've taken from the Scourge has been paid for in blood and misery, yet the enemy continues to strike back with a seemingly limitless army. To make matters worse, this undead army is supported and assisted by mortal sympathizers, the Cult of the Damned.\n\nGo forth into Icecrown and slay any cultists you encounter. ", objectives = "Cellian Daybreak at the Argent Tournament Grounds wants you to kill 15 members of the Cult of the Damned. You may kill Cult of the Damned members in any part of Icecrown.", completion = "You are a true champion, <name>, both inside the ring and on the field. We must all be vigilant against the Scourge and you are a great example to our brethren and your own people." }
WordHunterWoW_QuestEN[13790] = { title = "Among the Champions", description = "As a champion, you have mastered the art of mounted combat, besting challengers of all levels. When the tournament begins, those you have defeated will have redoubled their efforts and will seek to avenge their losses to you.\n\nIt would be wise to continue practicing your skills against the combatants waiting in the Ring of Champions. Equip your lance, go to the stables on the southern side of the grounds. then mount up on any mount you're permitted to use, and face the champions.", objectives = "Bring 4 Marks of the Champion to Luuri at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you finished training with the other champions?", completion = "Well done. Training against the other champions is one of the best ways to prepare yourself for tournament competition. I know you'll make the Alliance proud, <name>." }
WordHunterWoW_QuestEN[13791] = { title = "Taking Battle To The Enemy", description = "While we all play at mock combat, it will do us good to remember that the real enemy surrounds us. The Argent Crusade wants to use competition to find the best fighters, but we can tell that by who returns from battle. Let's show the paladins that we are willing to take battle to the Cult of the Damned, even while making preparations for the tournament.\n\nGo forth into Icecrown and slay any of the cultists you encounter. They have a strong presence around Aldur'thar and Deathspeaker's Watch.", objectives = "Zor'be the Bloodletter at the Argent Tournament Grounds wants you to kill 15 members of the Cult of the Damned. You may kill cultists in any part of Icecrown.", completion = "You have done well in demonstrating our commitment to fighting the Scourge, no matter where we are or what we are doing." }
WordHunterWoW_QuestEN[13792] = { title = "The Shadewalker", description = "Now that the demon gates have been destroyed, the power of the forest must be replenished. The Forest Heart must be retrieved!\n\nGaivan Shadewalker, a powerful druid of the claw, has gone southwest, past Felfire Hill, to the Dor'Danil Barrow Den. Therein rests the Forest Heart. It is protected by the druids of Ashenvale deep below the ground.\n\nSeek out Gaivan and tell him of what has transpired, {name}.", objectives = "Speak with Gaivan Shadewalker pacing outside the entrance to the Dor'Danil Barrow Den in Ashenvale.", completion = "You are brave to come here, <class>, but you may be too late. All of the druids are either dead or have been driven insane.\n\nStill, your tale is intriguing, and if what you say is true, then Gnarl must have the Forest Heart and soon, or Ashenvale will begin to wither!" }
WordHunterWoW_QuestEN[13793] = { title = "Among the Champions", description = "As a champion, you have mastered the art of mounted combat, overcoming challengers of all levels. You must make certain that you can defeat anyone you face when the tournament begins.\n\nYou should continue honing your own skills and learning more about the weaknesses of your opponents. Champions representing all cities practice in the Ring of Champions near the stables. Go to the stables, equip your lance, and pick any mount you're permitted to ride, then face the champions.", objectives = "Bring 4 Marks of the Champion to Illyrie Nightfall at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you finished training with the other champions?", completion = "You handle your mount well, <name>. In time, your competitors will learn to fear you." }
WordHunterWoW_QuestEN[13794] = { title = "Eadric the Pure", description = "I have asked my brothers of the Argent Crusade to work closely with those who rise to the rank of champion. Eadric the Pure, our brotherhood's grand champion, helps oversee training exercises for champions from all cities and helps them make their final preparations for tournament competition.\n\nPlease go and introduce yourself to him. I know he'll be eager to meet you and work with you on your way to competing against Azeroth's greatest champions.", objectives = "Speak with Eadric the Pure at the Argent Tournament Grounds.", completion = "It's good to finally meet you, champion. The highlord has asked me to help coordinate the efforts of all champions to train together and bolster the defenses of the tournament grounds." }
WordHunterWoW_QuestEN[13795] = { title = "The Scourgebane", description = "The leader of the Knights of the Ebon Blade delegation has asked to speak you, {class}. Crok Scourgebane is as fearsome a combatant as they come and I have no doubt he'll have much to ask of you.\n\nThe Knights of the Ebon Blade have made camp on the north side of the tournament grounds, west of the tent housing the Alliance delegations.", objectives = "Speak with Crok Scourgebane at the Argent Tournament Grounds.", completion = "So you have become a champion, <name>. I had no doubt that it would happen. We knights have been trained in the heat of battle, not in front of wooden dummies. Let's show the paladins and their guests what battle has made us." }
WordHunterWoW_QuestEN[13796] = { title = "The Forest Heart", description = "You must get the Forest Heart to Gnarl at all costs!\n\nDown at the bottom of the Dor'Danil Barrow Den it sits, corrupted by the Horde. Only Gnarl can cleanse it.\n\nIn order to move it, though, you'll need a Power of Nature. If you collect enough untainted spirits from the Severed druids and keepers, the spirits can be combined into a Power of Nature.\n\nGood luck, {name}!", objectives = "Obtain the Forest Heart.", progress = "<name>, you have returned.", completion = "The Forest Heart! It's corrupted!\n\n<The great ancient creaks as its immense limbs begin to perform a ritual.>\n\nStand back, <name>, I will try to cleanse the heart before all is lost!" }
WordHunterWoW_QuestEN[13797] = { title = "Dirty Deeds", description = "What Draaka requires is a magnet of sorts - something that her demonic missiles will be drawn to.\n\n<Durak grins slyly.>\n\nI happen to know of a method that should suit our purposes.\n\nYou scour the mines for fist-sized chunks of ore, while I prepare a special... enchantment.", objectives = "Search the piles of Fresh Rubble to find 10 Chunks of Ore.", progress = "Have you collected the ore we need?", completion = "Well done! These should hold a curse long enough for our purposes...." }
WordHunterWoW_QuestEN[13798] = { title = "Rain of Destruction", description = "Just in time, {class}. The elves have launched another attack!\n\nFrom the guard towers, use the accursed ore to mark targets for Draaka.\n\nHer projectiles will strike your target and erupt in fel magic flame, destroying any nearby enemies.\n\nThere is strong prejudice against the use of demonic magics. Unjustified, but real nonetheless. For this reason, I will transform you into an imp for the duration of the mission to prevent you from being identified.", objectives = "Using Accursed Ore to mark targets for Draaka, you are to kill 30 Night Elf troops and 5 Raging Ancients.\n\nSpeak with Durak to reapply Imp Disguise.", progress = "Has the enemy fallen, <name>?", completion = "Did you feel it, <name>!?\n\nThe raw fel power seething through your being?\n\nThere is nothing else like it!" }
WordHunterWoW_QuestEN[13799] = { title = "Where Are My Keys?", description = "I can't find my keys -- I suspect my evil twin is at fault. \"Take care\" of him for me, <name>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Dr. Fingers wants you to kill his evil clone, Evil Fingers, and retrieve his keys." }
WordHunterWoW_QuestEN[13800] = { title = "Get My Keys!", description = "Get 'em!You will receive:", objectives = "Find Dr. Fingers' Keys." }
WordHunterWoW_QuestEN[13801] = { title = "Dead Elves Walking", description = "D-did you hear that? Ghosts! I hate ghosts!\n\nTheir eerie howls are coming from the barrows to the south. Ahhh! Make them stop!!\n\nPlease, mister I'll pay good money to get those voices out of my head!", objectives = "Destroy any 15 of the night elf ghosts at Dor'danil Barrow Den.", completion = "Woohooo!!\n\nYou've silenced the voices! Thank you, thank you!" }
WordHunterWoW_QuestEN[13802] = { title = "The Goblin with Two Brains", description = "Do you see them, along the shore? Such magnificent specimens! Look at their primitive society in action, working like a well-oiled machine from the lowliest grunt to their leader, who I've named \"King Burgrurble.\"\n\nI must study their brains.\n\nCan you procure an intact Slobberfang Murloc brain stem for me? Kill them - for science!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring a Slobberfang Murloc Brain Stem to Professor Flozz along the coast." }
WordHunterWoW_QuestEN[13803] = { title = "Blood of the Weak", description = "We knew the elves wouldn't go down without a fight, but no one expected them to be able to lay siege to Splintertree...\n\nTime for them to pay for their actions!\n\nNearby, in the Dor'Danil Barrow Den, lies something very dear to the enemy - the Forest Heart.\n\nI need someone to make their way to the heart and corrupt it.\n\nThat someone is you, {name}.\n\nFirst though, bring my axe to Durak here in the mines. He'll make use of the blood of our enemies.", objectives = "Kadrak wants you to bring the Blood-Soaked Axe to Durak in Splintertree Post.\n\nProvided item:", completion = "Tainting the Forest's Heart?\n\nHow ruthless - an utterly vicious blow....\n\nI adore the idea!" }
WordHunterWoW_QuestEN[13804] = { title = "To Catch a Fish-Thing", description = "Look at these results! Such a unique electrochemical makeup -- ah, but I wouldn't suspect a lowly <class> would understand the magnormity of what I've discovered here. I'll need a live specimen.\n\nI would acquire one myself, but apparently they bite.\n\nHere, I've configured this trap to hone in on their unique brain patterns. Just set the trap, then hit this button to slurp up a Slobberfang. But first, I'll need you to sign this indemnification waiver. This technology is bleeding edge!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Place a trap and use the remote to capture a live Slobberfang Murloc. Return the filled trap to Professor Flozz." }
WordHunterWoW_QuestEN[13805] = { title = "Pierce Their Heart!", description = "There...\n\nThe blood of the fallen Kaldorei is turned. It can now be used on the Forest Heart in Dor'Danil Barrow Den. Doing so will utterly corrupt it.\n\nThe sacred relic of the arrogant elves will be turned against them. How poetic!\n\n<Durak laughs cruelly.>\n\nThe barrow den lies nestled against the hills to the southeast. One of my imps has laid a blood trail from the entrance to the heart.\n\nMake haste! Kadrak is not likely to be in a patient mood.\n\nOff you go, {class}.", objectives = "Durak wants you to use the Tainted Blood of the Kaldorei on the Forest Heart.", completion = "It is done?\n\nGood work, <name>. That will gradually weaken their forces, as well as their spirit." }
WordHunterWoW_QuestEN[13806] = { title = "Demon Duty", description = "Listen, {class}, I know this assault on Splintertree has everyone worked up, but if we forget about the satyr portals we'll come out of this crisis to face an even larger one.\n\n<Locke stares at your expressionless face.>\n\nYou don't know about the portals?\n\nTo the northeast, in the regions of Satyrnaar and Xavian, the satyrs are attempting to summon in demons to bolster their numbers.\n\nWe must be vigilant in closing those portals, no matter what issues we face here!", objectives = "Locke Okarr in Splintertree wants you to close 12 Satyr Portals in Satyrnaar and Xavian.", completion = "Good work, <race>.\n\nOne less thing we have to worry about!" }
WordHunterWoW_QuestEN[13807] = { title = "FLAG: Tournament Invitation", description = "", objectives = "" }
WordHunterWoW_QuestEN[13808] = { title = "Mission Improbable", description = "I have a special mission that requires a well equipped, competent {class}. As I have no one else to spare, I suppose I'll have to settle for you...\n\nThe enemy has assaulted Warsong Lumber Camp and cut it off from the rest of our forces. An important blood elf diplomat en route to Orgrimmar is trapped there.\n\nShe must be liberated.\n\nTake the road northeast and light the smoldering brazier to summon our operative there. Do whatever he might require of you.\n\nDismissed!", objectives = "Kadrak wants you to light the Smoldering Brazier across from Satyrnaar.", completion = "You have your work cut out for you here, friend.\n\nLet's hope that you're up to the task,,,," }
WordHunterWoW_QuestEN[13809] = { title = "Threat From Above", description = "Highlord Tirion Fordring has doubled the guard since your exposure of the Cult of the Damned's infiltrator. He doesn't believe that they will stop just because their Black Knight has been defeated.\n\nOur skytalon scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party. If we don't intercept them, the tournament will come under attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", objectives = "Eadric the Pure at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers.", progress = "Have you defeated the Cult of the Damned raiding party?", completion = "<name>, you and your allies have spared the tournament from a devastating attack. Though our skytalon riders are brave, they  have their hands full keeping the peace on the tournament grounds and would be hard-pressed to defend the skies against the cult's attack. You have the thanks of the Argent Crusade and all who have gathered here to compete." }
WordHunterWoW_QuestEN[13810] = { title = "Taking Battle To The Enemy", description = "The coliseum is perched in the most dangerous part of the world, {name}. The territory we've taken from the Scourge has been paid for in blood and misery, yet the enemy continues to strike back with a seemingly limitless army. To make matters worse, this undead army is supported and assisted by mortal sympathizers, the Cult of the Damned.\n\nGo forth into Icecrown and slay any cultists you encounter.", objectives = "Cellian Daybreak at the Argent Tournament Grounds wants you to kill 15 members of the Cult of the Damned. You may kill cultists in any part of Icecrown.", progress = "Have you tested yourself in combat?", completion = "You are a true champion, <name>, both inside the ring and on the field. We must all be vigilant against the Scourge and you are a great example to our brethren and your own people." }
WordHunterWoW_QuestEN[13811] = { title = "Among the Champions", description = "As a champion, you have mastered the art of mounted combat, besting challengers of all levels. When the tournament begins, those you have defeated will have redoubled their efforts and will seek to avenge their losses.\n\nIt would be wise to continue honing your own skills and learning from your opponents. Champions representing all cities practice in the Ring of Champions. Equip your lance, mount up on any mount you're entitled to use at the stables, and face the champions.", objectives = "Bring 4 Marks of the Champion to Luuri at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you finished training with the other champions?", completion = "Well done. Training against the other champions is one of the best ways to prepare yourself for tournament competition. I know you'll make the Horde proud, <name>." }
WordHunterWoW_QuestEN[13812] = { title = "Threat From Above", description = "The Argent Crusade has doubled the guard since your exposure of the Cult of the Damned's infiltrator. They know the cultists won't stop until they've destroyed this area and thwarted the tournament.\n\nThe Argent Crusade's scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party.\n\nYou must intercept and destroy them before they attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", objectives = "Crok Scourgebane at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers.", completion = "<name>, you have spared the tournament from a devastating attack. The Argent Crusade and all who gather here are in our debt and we'll make certain they remember it. For all their bluster about providing protection, the peacekeepers and skytalons spend more time breaking up drunken brawls than keeping us safe from the Scourge.\n\nIt's no matter. We always protect our own." }
WordHunterWoW_QuestEN[13813] = { title = "Taking Battle To The Enemy", description = "While we all play at mock combat, it will do us good to remember that the real enemy surrounds us. The Argent Crusade wants to use competition to find the best fighters, but we can tell that by who returns from battle. Let's show the paladins that we are willing to take battle to the Cult of the Damned, even while making preparations for the tournament.\n\nGo forth into Icecrown and slay any of the cultists you encounter. They have a strong presence around Aldur'thar and Deathspeaker's Watch.", objectives = "Zor'be the Bloodletter at the Argent Tournament Grounds wants you to kill 15 members of the Cult of the Damned. You may kill cultists in any part of Icecrown.", completion = "You have done well in demonstrating our commitment to fighting the Scourge, no matter where we are or what we are doing." }
WordHunterWoW_QuestEN[13814] = { title = "Among the Champions", description = "As a champion, you have mastered the art of mounted combat, overcoming challengers of all levels. You must make certain that you can defeat anyone you face when the tournament begins.\n\nYou should continue honing your own skills and learning more about the weaknesses of your opponents. Champions representing all cities practice in the Ring of Champions near the stables. Go to the stables, equip your lance, pick any mount you can ride, then face the champions in practice bouts.", objectives = "Bring 4 Marks of the Champion to Illyrie Nightfall at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion.", progress = "Have you finished training with the other champions?", completion = "You handle your mount well, <name>. In time, your competitors will learn to fear you." }
WordHunterWoW_QuestEN[13815] = { title = "Making Stumps", description = "As you've been told by now, we are to escort a diplomat from within the besieged lumber camp to safety.\n\nAs it stands, that's simply impossible. The elves have a thousand arrows trained on the camp's exits.\n\nFirst we must create a diversion - something that will take their eyes off of the camp for a time.\n\nMy idea is simple. Take this axe and cut down the trees they've been nurturing in the region.\n\nWhen you're through, light the brazier here to speak with me again.", objectives = "Krokk wants you to use the Splintertree Axe to cut down the Ashenvale Oaks in Warsong Lumber Camp.", completion = "Nice work, <name>.\n\nYou've demoralized the enemy and harvested resources for the Horde.\n\nLet's hope the rest of the mission goes as well." }
WordHunterWoW_QuestEN[13816] = { title = "Heroic: The Celestial Planetarium", description = "Listen, lad!  Azeroth's fate is at stake here.\n\nOur only chance is to get to the Celestial Planetarium in time to find this Algalon and stop him from beaming back any messages to his Titan masters.\n\nLocate the Celestial Planetarium and come back with any information you get.  We might still have some time to prepare for Algalon's arrival.", objectives = "Prospector Loren at the Archivum in Ulduar wants you to locate the entrance to the Celestial Planetarium.", progress = "Did you find it, <name>?", completion = "It's locked?  Figures!\n\nI'll let Brann know... maybe he can uncover something in the Archivum." }
WordHunterWoW_QuestEN[13817] = { title = "Heroic: Archivum Data Disc", description = "This platinum disc is surprisingly symmetrical and devoid of any scratches or imperfections.  Engraved along its edge, bold runes spell out the word \"ARCHIVUM.\"\n\nThere must be a device inside Ulduar capable of reading the disc.", objectives = "Bring the Archivum Data Disc to the Archivum Console in Ulduar.", progress = "The console whirrs with energy as the round receptacle opens.", completion = "The platinum disc fits perfectly inside the console.  It begins to spin as its contents are scanned by white beams of light." }
WordHunterWoW_QuestEN[13818] = { title = "Heroic: Algalon", description = "You really did it, {name}.  Take the sigils to the Archivum Console and see if you can gain access to the Celestial Planetarium.\n\nYou best hurry, lad.  Time is of the essence.", objectives = "Bring the Sigils of the Watchers to the Archivum Console in Ulduar.", progress = "The console's bright lights scan the glass surface repeatedly, as if awaiting some form of input.", completion = "Stand by for verification.\n\nAccess to the Celestial Planetarium granted.  Please retrieve your key." }
WordHunterWoW_QuestEN[13819] = { title = "Heroic: All Is Well That Ends Well", description = "We'd best hurry now, {name}.  We're going to have to transmit the reply-code from Dalaran.\n\nTake it to Rhonin, I will meet you there.", objectives = "Take the Reply-Code Alpha to Rhonin in Dalaran.", progress = "You're ready, <name>?", completion = "You're here.  Let us hope this works.  For all our sakes." }
WordHunterWoW_QuestEN[13820] = { title = "The Blastbolt Brothers", description = "The highlord has tasked me with getting that coliseum completed as soon as possible. We've put our own masons to work on the project, but we found out very quickly that we were going to need help procuring materials. I've hired a couple of goblins, Bezzle Blastbolt and his brother, Bozzle.\n\nThey're supervising construction at the southeastern end of the tournament grounds. Speak with Bezzle and see if he and his brother could use any more help getting the building materials we need.", objectives = "Speak with Bezzle Blastbolt at the Argent Tournament Grounds.The highlord has tasked me with getting that coliseum completed as soon as possible. We've put our own masons to work on the project, but we found out very quickly that we were going to need help procuring materials. I've hired a couple of goblins, Bezzle Blastbolt and his brother, Bozzle.\n\nThey're supervising construction at the southeastern end of the tournament grounds. Speak with Bezzle and see if he and his brother could use any more help getting the building materials we need.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[13821] = { title = "Heroic: Freya's Sigil", description = "Freya's Sigil is going to be one of the tougher ones, I reckon.\n\nAccording to the Archivum, the essence of the Sigil is tied to her three elder servants, Brightleaf, Ironbranch and Stonebark.  Should any of the elders be harmed, the Sigil's integrity will be compromised.\n\nSparing the elders, however, means that Freya will be more powerful when you face her.\n\nWhat can I say, {name}.  We're stuck between a rock and hard place.", objectives = "Prospector Loren at the Archivum in Ulduar wants you to obtain Freya's Sigil.\n\nFor more information on obtaining Freya's Sigil consult the Archivum Console.", progress = "Freya's sigil, <name>?  Do ye have it?", completion = "Excellent job, <name>.  We're one step closer to saving Azeroth!" }
WordHunterWoW_QuestEN[13822] = { title = "Heroic: Hodir's Sigil", description = "Hodir's Sigil won't be easy to obtain.  Not only are ye going to have to defeat Hodir himself, but yer going to have to do it before he destroys the chest that contains it!\n\nCheck the Archivum console if you need more information.  That thing contains more knowledge than all of the world's libraries put together!", objectives = "Prospector Loren at the Archivum in Ulduar wants you to obtain Hodir's Sigil.\n\nFor more information on obtaining Hodir's Sigil, consult the Archivum Console.", progress = "Did ye obtain the sigil, <name>?", completion = "Ye did it!  I don't know how, but ye did!" }
WordHunterWoW_QuestEN[13823] = { title = "Heroic: Thorim's Sigil", description = "Thorim's not himself, {name}.  He's come under a dark influence.\n\nAn evil presence under the guise of an illusion pretends to be his lost wife, Sif.\n\nYe can't let him be overcome by this impostor's spell.  If he does, the location of his sigil might forever be lost!\n\nYer going to have to beat some sense into him and yer going to have to do it quick.\n\nAs always, the Archivum Console will give ye all the gory details... even the ones ye don't like.", objectives = "Prospector Loren at the Archivum in Ulduar wants you to obtain Thorim's Sigil.\n\nFor more information on obtaining Thorim's Sigil consult the Archivum Console.", progress = "Well, <name>?  Do ye have it?", completion = "Ye never cease to impress, <name>.\n\nYe and me are having a pint together after all this is done, ye hear me?" }
WordHunterWoW_QuestEN[13824] = { title = "Heroic: Mimiron's Sigil", description = "Mimiron's a clever one.  His entire abode is rigged with some sort of self-destruction mechanism.\n\nUnfortunately yer gonna have to race against it if ye want to get his sigil.  Check the Archivum Console for more details if ye need them.", objectives = "Prospector Loren at the Ulduar Archivum wants you to obtain Mimiron's Sigil.\n\nFor more information on obtaining Mimiron's Sigil consult the Archivum Console.", progress = "Were you able to obtain the sigil, <name>?", completion = "I've got to hand it to you, <name>.  Our odds might not be the best, but I feel a lot better with you lending a hand." }
WordHunterWoW_QuestEN[13825] = { title = "Clamlette Surprise", description = "", objectives = "Hey, I remember you!  Aren't you the <class> that helped me make all that clamlette back in the day?\n\nTell you what, step on up and I'll show you my newest recipe - it's simple and delicious!" }
WordHunterWoW_QuestEN[13826] = { title = "Nat Pagle, Angler Extreme", description = "", objectives = "Well hello there, young <class>. Either my memory is failing me, or I forgot to give you this last time we spoke..." }
WordHunterWoW_QuestEN[13827] = { title = "Treasure!", description = "", objectives = "" }
WordHunterWoW_QuestEN[13828] = { title = "Mastery Of Melee", description = "The heart of tournament competition is mounted melee combat. Take this lance and mount the stabled Quel'dorei steed just outside the pavilion.\n\nOnce you're mounted, seek out Jeran Lockwood. He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Jeran will instruct you on how to use your defenses to keep you safe while attacking a melee target at close range.", objectives = "Equip your lance, then mount the Stabled Quel'dorei Steed outside the pavilion. Speak to Jeran Lockwood and use Thrust 5 times on a Melee Target, then return to Arcanist Taelis at the Argent Tournament Grounds.", completion = "Keep the words of the master in mind as you practice with the training dummies." }
WordHunterWoW_QuestEN[13829] = { title = "Mastery Of Melee", description = "The heart of tournament competition is mounted melee combat. Take this lance and mount the stabled Sunreaver hawkstrider just outside the pavilion.\n\nOnce you're mounted, seek out Jeran Lockwood. He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Jeran will instruct you on how to use your defenses to keep you safe while attacking a melee target at close range.", objectives = "Equip your lance, then mount the Stabled Sunreaver Hawkstrider outside the pavilion. Speak to Jeran Lockwood and use Thrust 5 times on a Melee Target, then return to Magister Edien Sunhollow at the Argent Tournament Grounds.", completion = "Keep the words of the master in mind as you practice with the training dummies." }
WordHunterWoW_QuestEN[13830] = { title = "The Ghostfish", description = "Any Northrend angler worth his salt knows about the pygmy suckerfish.  It's not edible, but sometimes useful to alchemists.\n\nThere is, however, a stealthy fish that hides among the suckerfish in the River's Heart of Sholazar Basin.  The phantom ghostfish.  When out of water, they become increasingly translucent until they fade away completely.  Some hypothesize they return to Sholazar, and others are more... superstitious.\n\nI want you to catch this fish and discover its secret by any means!", objectives = "Marcia Chase in Dalaran City wants you to discover the mystery of the Phantom Ghostfish.", completion = "So eating it makes you invisible... what a strange defense this clever fish has developed.\n\nI'd like to digest this for a bit.  Pun not intended, <name>.  Really.  Why don't you come see me tomorrow?" }
WordHunterWoW_QuestEN[13831] = { title = "A Troubling Prescription", description = "A crude, hastily-assembled apothecary's workbench stands here, heaped with scrawled notes and noxious brews. It looks as though the Forsaken have also been studying Foulhoof's handiwork. You grab the most important-looking notes and prepare to smash the laboratory before notifying Treetender of your discovery.", objectives = "Deliver the Apothecary's notes to Tharnariun Treetender in Lor'danel.", progress = "What's this? You found something else in the cave?", completion = "<Tharnariun Treetender pages through the notes as you relate your story, the lines in his face deepening with concern.>\n\nSo the Forsaken have been studying Foulhoof's work? My gut crawls at the thought of what they might have done were they able to weaponize his corruption. You've done well to destroy their work, but this raises deeper concerns. What brought the Forsaken to our doorstep? Are they working with the Shatterspear trolls to our north? Sorrows are heaping upon sorrows, <class>. I'm glad you're here." }
WordHunterWoW_QuestEN[13832] = { title = "Jewel Of The Sewers", description = "Hard to believe that most people fish in the Dalaran Sewers for giant rats and mutated fish.  Especially when those waters are filled with priceless jewelry - discarded by broken hearted fools, thieves, and careless drunks.\n\nThe trick is to let your hook drag the bottom and don't pull up too hard when you get something.  Try it out, {name}.  I'd be willing to trade whatever you find for a few trinkets of my own.", objectives = "Marcia Chase in Dalaran City wants you to bring her a piece of Corroded Jewelry.", progress = "Any luck?", completion = "Well now, that looks like it could be valuable.  Difficult to know until it's cleaned up and appraised, but I'm still willing to make the trade if you are." }
WordHunterWoW_QuestEN[13833] = { title = "Blood Is Thicker", description = "The bloodtooth is a feisty little fish used in a recipe to cure infected wounds.  We could use some of them, if you're up to it.\n\nAs the name suggests, they've a hunger for blood.  The only way I know how to catch the little devils is by creating a blood pool and fishing in it.\n\nGet yourself covered in blood - just slaughter a beast in the Borean Tundra - and then jump in the water.  It'll wash right off and create the perfect fishing spot.", objectives = "Marcia Chase in Dalaran City wants you to bring her 5 Bloodtooth Frenzies.", progress = "Any luck with the bloodtooth?  Don't forget what I told you about making blood pools.", completion = "You are a brave one, <name>.  I hope you didn't lose any extremities making your fishing spot.  If you've still got the fishing bug, come back tomorrow and we'll talk some more." }
WordHunterWoW_QuestEN[13834] = { title = "Dangerously Delicious", description = "The best fishing is often the most dangerous.  Wintergrasp boasts a bountiful catch for the brazen.\n\nIn fact, it's the only place to catch the fabled Terrorfish - a fish both lethal and delicious.  Bring me some, and we'll have something to discuss.", objectives = "Marcia Chase in Dalaran City wants you to bring her 10 Terrorfish.", progress = "Be on your guard when you're after the Terrorfish.", completion = "My, my, my!  You've caught yourself some Terrorfish.  Why, that reminds me of the time...\n\n<Marcia regales you with stories of adventure and fishing for as long as you're willing to listen.>" }
WordHunterWoW_QuestEN[13835] = { title = "Mastery Of The Shield-Breaker", description = "You'll need to learn how to break through an opponent's defenses to succeed in mounted combat. Take this lance and mount the stabled Quel'dorei steed just outside the pavilion.\n\nOnce you're mounted, seek out Valis Windchaser. He'll be on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Valis will teach you the basics of using a ranged shield breaker attack to make a ranged target vulnerable.", objectives = "Equip your lance and mount the Stabled Quel'dorei Steed outside the pavilion. Speak to Valis Windchaser and use Shield-Breaker on 2 vulnerable Ranged Targets, then return to Scout Shalyndria at the Argent Tournament Grounds.", completion = "Commit Valis's lesson to memory, <name>. It will mean the difference between winning and losing your mounted combat matches." }
WordHunterWoW_QuestEN[13836] = { title = "Disarmed!", description = "I've received word of an unfortunate accident at the Dalaran prison; a guard had his arm severed and thrown into the water by a particularly vicious inmate.\n\nOur first aid clinic promises they can reattach the arm if we bring it back.\n\nYou fish long enough in the water outside the prison, and I'd bet my favorite fishing pole that arm will surface.  Find that arm, and bring it to Olisarra the Kind here in Dalaran.  She'll know what to do.", objectives = "Olisarra the Kind in Dalaran City wants you to return the Severed Arm to her.", progress = "Hi there.  Do you have something for me?", completion = "Oh, hello there <name>.  Marcia said you'd be coming by with that poor man's missing arm.\n\nShe also gave me this bag to give you as a reward.  It smells horrible, and I'm anxious to make the trade if you don't mind." }
WordHunterWoW_QuestEN[13837] = { title = "Mastery Of The Charge", description = "Your strongest attack in mounted combat is undoubtedly the charge. Take this lance and mount the stabled Quel'dorei steed just outside the pavilion.\n\nOnce you're mounted, speak with Rugan Steelbelly. He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Rugan will tell you how to use this powerful ability and teach you some basic strategies.", objectives = "Equip your lance and mount the Stabled Quel'dorei Steed outside the pavilion. Speak to Rugan Steelbelly and Charge 2 vulnerable Charge Targets, then return to Avareth Swiftstrike at the Argent Tournament Grounds.", progress = "Have you mastered the use of the charge?", completion = "With a teacher like Rugan, you'll be an expert at mounted combat in no time." }
WordHunterWoW_QuestEN[13838] = { title = "Mastery Of The Shield-Breaker", description = "You'll need to learn how to break through an opponent's defenses to succeed in mounted combat. Take this lance and mount the stabled Sunreaver hawkstrider just outside the pavilion.\n\nOnce you're mounted, seek out Valis Windchaser. He'll be on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Valis will teach you the basics of using a ranged shield breaker attack to make a ranged target vulnerable.", objectives = "Equip your lance and mount the Stabled Sunreaver Hawkstrider. Speak to Valis Windchaser and use Shield-Breaker on 2 vulnerable Ranged Targets, then return to Galathia Brightdawn at the Argent Tournament Grounds.", completion = "Commit Valis's lesson to memory, <name>. It will mean the difference between winning and losing your mounted combat matches." }
WordHunterWoW_QuestEN[13839] = { title = "Mastery Of The Charge", description = "Your strongest attack in mounted combat is undoubtedly the charge. Take this lance and mount the stabled Sunreaver hawkstrider just outside the pavilion.\n\nOnce you're mounted, speak with Rugan Steelbelly. He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Rugan will tell you how to use this powerful ability and teach you some basic strategies.", objectives = "Equip your lance and mount the Stabled Sunreaver Hawkstrider outside the pavilion. Speak to Rugan Steelbelly and Charge 2 vulnerable Charge Targets, then return to Amariel Sunsworn at the Argent Tournament Grounds.", progress = "Have you mastered the use of the charge?", completion = "With experience and practice, you will become deadly with the charge." }
WordHunterWoW_QuestEN[13840] = { title = "REUSE", description = "\"Cluck... cluck... cluck... BACAW!\n\nCluck... cluck... cluck.\"\n\nThe chicken looks up at you and then starts to scratch its claws into the ground. You think it is spelling out a word, but you are not sure what it is. Could it be... S-A-L-D-E-A-N? Before you can ask, the chicken turns away and goes about its business.", objectives = "Find some Special Chicken Feed and return to your befriended chicken. When you find it, /cheer at it before trying to give it the Special Chicken Feed." }
WordHunterWoW_QuestEN[13841] = { title = "All Apologies", description = "This could be the end of me... Perhaps my actions were not thought out as well as they should have been...\n\nThe good news is that we pushed back an attack that would have otherwise meant the end of Splintertree. Let us pray that Saurfang sees it that way.\n\nI am certain to be summoned to Orgrimmar to explain my actions.\n\nPlease, {name}, go ahead of me and present this letter to his advisor Eitrigg.\n\nDo what you can to soften his heart towards me.", objectives = "Draaka wants you to bring her Letter of Explanation to Eitrigg in Orgrimmar.\n\nProvided item:", completion = "Fools!!\n\nThis Draaka woman has allowed herself to be manipulated by a demon!\n\n<Garrosh studies you for a moment.>\n\nAnd I smell its taint on you as well, <class>...." }
WordHunterWoW_QuestEN[13842] = { title = "Dread Head Redemption", description = "I sense that Durak is more than he seems. Demonic power is dangerous and it is easy to fall to its corruption - even for a trained warlock. \n\nI do not trust him, {name}.\n\nFind this Durak and tell him that the Horde will have nothing to do with him.", objectives = "Speak to Durak in Splintertree Mines.", progress = "Have you brought me the head of the enemy, <race>?", completion = "Grah... very well.\n\nI'll remove the bounty I had placed upon your head. Though I am sorely tempted to end your life anyway, just on principle.\n\nBe sure that you never raise my ire again, <name>. Now, get out of my sight..." }
WordHunterWoW_QuestEN[13843] = { title = "The Scrapbot Construction Kit", description = "Searching the databanks of the prototype console reveals schematics for a scrapbot construction kit. With your engineering expertise, you could learn this schematic and produce scrapbot construction kits of your own.", objectives = "Interact with the Prototype Console in The Inventor's Library.", completion = "You take note of the information displayed in the schematic and the materials required to construct the scrapbot kit." }
WordHunterWoW_QuestEN[13844] = { title = "The Looting of Althalaxx", description = "Before you rejoin the battle, {class}, something urgent has come to my attention. My scouts report that the Forsaken are scouring the ruined tower of Althalaxx to our south.\n\nPrior to the assault, that bleak tower housed a fanatical arm of the Shadow Council commanded by the fallen highborne Athrikus Narassin. Narassin is long since dead, but if any of his work survives, we can't allow it out of our sight. Retrieve his research and kill the Forsaken commander who's plundering the ruins.", objectives = "Locate Narassin's Tome among the ruins of Althalaxx and kill the Forsaken commander Teegan Holloway.", progress = "Narassin is no longer our concern, but if his life's work should fall to our enemies, centuries of dark wisdom could be called down onto our heads. How goes the hunt?", completion = "Let's see what we've got here.... By Elune, his notes are scrawled in a half dozen languages. What is this, blood? This archive makes my flesh seethe, but at least it's secure. It will take us some time to decipher these notes.\n\nOh - your reward? Yes, here. Nice work with those undead scavengers. Now get back to the fight." }
WordHunterWoW_QuestEN[13845] = { title = "Sealed Vial of Poison", description = "This vial of poison looks particularly dangerous.  Perhaps someone in Dalaran might be interested in it.", objectives = "Bring the Sealed Vial of Poison to Alchemist Cinesra in the Dalaran Sewers.", progress = "Is that what I think it is, <class>?", completion = "You are brave to have carried this.  If even one drop were to touch your skin, you'd have died an agonizing death.\n\nAllow me to pay you for it... I can always use venom of exceptional potency." }
WordHunterWoW_QuestEN[13846] = { title = "Contributin' To The Cause", description = "The bestest of the champions come to the chapel to hear the argent confessor speak every day.\n\nYou should see how much she inspires them, {name}. Not only do they fight for the Argent Crusade, but they put a lot of money into the collection basket when I take it around.\n\nMaybe you'd like to contribute too?", objectives = "Speak with Squire Artie to contribute 10 gold to the Argent Crusade's cause.", progress = "Do you want to contribute?", completion = "Thank you. I just know the crusade will put it to good use!" }
WordHunterWoW_QuestEN[13847] = { title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "Captain Joseph Holley at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, and 3 Boneguard Lieutenants.", completion = "Your bravery on the field has shown the crusaders what they already knew -- that our warriors are more than just parade ground decorations." }
WordHunterWoW_QuestEN[13848] = { title = "Bad News Bear-er", description = "No reports have made it out of here since the beginning of the siege on Splintertree. By now, Commander Grimfang must be getting anxious.\n\nI am sending you to Zoram Strand to deliver our report. It's not pretty, but at least he'll have the facts.\n\nSpeak to Vhulgra when you're ready to make the trip.", objectives = "Kadrak wants you to speak to Commander Grimfang in Zoram Strand.\n\nProvided item:", completion = "<Commander Grimfang's brow wrinkles as he reads the report.>\n\nThis is grim news, indeed.\n\nMay the spirits preserve them until we can fight our way to Splintertree...." }
WordHunterWoW_QuestEN[13849] = { title = "Astranaar's Burning!", description = "{class}, Astranaar's burning!\n\nQuickly, take this bucket of water and put out the fires before there's nothing left!", objectives = "Extinguish 15 fires.", completion = "Thank you!\n\nNow it's time to deal with the Horde!" }
WordHunterWoW_QuestEN[13850] = { title = "Toxic Tolerance", description = "You want to ride a Venomhide? Then I've got bad news for you.\n\nThe Venomhide Ravasaurs, they're all poison: Poison blood, poison spit, poison skin. You climb on one, you fall off dead in a few hours.\n\nYou'd have to build up a resistance to their toxins before I sold you one, and that takes a long, LONG time... you'd need to be splashed with poisonous blood while fighting one numerous times. If you're really interested, the venomhides prefer the northern area of the Marshlands, northwest of here.", objectives = "Mor'vek in Un'goro Crater claims that if you were poisoned by Venomhide Ravasaur blood 20 times, you could ride one without dying. Attack Venomhide Ravasaurs for a chance to be poisoned.", completion = "You did it? You actually did it?!\n\nHo ho! Stubborn as my wife, you are." }
WordHunterWoW_QuestEN[13851] = { title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "Clara Tumblebrew at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, and 3 Boneguard Lieutenants.", completion = "Your bravery on the field has shown the crusaders that we are worthy allies." }
WordHunterWoW_QuestEN[13852] = { title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "Flickin Gearspanner at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, and 3 Boneguard Lieutenants.", completion = "Your bravery on the field has shown the that we are a match for the Argent Crusade's own." }
WordHunterWoW_QuestEN[13853] = { title = "Return Fire", description = "The fires are mostly contained, but we have to do something about those wind riders!\n\nQuick, {name}, you have to jump into one of our glaive throwers and return fire!", objectives = "Use an Astranaar Thrower to shoot down 15 Hellscream's Hellions & their Watch Wind Riders.", progress = "There's still more of them bombing us. Please, <name>, shoot them down!", completion = "We're saved! You've shot down enough of them that we should be able to handle the rest.\n\nI cannot thank you enough, <name>." }
WordHunterWoW_QuestEN[13854] = { title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "Ranii at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, and 3 Boneguard Lieutenants.", completion = "Your bravery on the field has shown the crusaders what they already knew -- that our warriors are more than just parade ground decorations." }
WordHunterWoW_QuestEN[13855] = { title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "Airae Starseeker at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, and 3 Boneguard Lieutenants.", progress = "Have served alongside the crusaders in the Court of Bones?", completion = "Your bravery on the field has shown the crusaders that they can rely on us in the battle against the Lich King." }
WordHunterWoW_QuestEN[13856] = { title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "Morah Worgsister at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, and 3 Boneguard Lieutenants.", completion = "Your bravery on the field has shown the crusaders what they already knew -- that our warriors are the best in Azeroth." }
WordHunterWoW_QuestEN[13857] = { title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "Gahju at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, 3 Boneguard Lieutenants.", completion = "Your bravery on the field has shown the crusaders that we are fearless in the face of the Lich King's minions." }
WordHunterWoW_QuestEN[13858] = { title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "Anka Clawhoof at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, 3 Boneguard Lieutenants.", completion = "Your bravery on the field has shown the crusaders that we are steadfast allies in the battle against the Lich King." }
WordHunterWoW_QuestEN[13859] = { title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "Aneera Thuron at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, 3 Boneguard Lieutenants.", completion = "Your bravery on the field has shown the crusaders that we are ready to face any enemy." }
WordHunterWoW_QuestEN[13860] = { title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "Handler Dretch at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, 3 Boneguard Lieutenants.", progress = "Have served alongside the crusaders in the Court of Bones?", completion = "The Argent Crusade has seen our resolve and they know that our warriors will see this through to the end." }
WordHunterWoW_QuestEN[13861] = { title = "Battle Before The Citadel", description = "Even as some of us labor on the tournament, our brothers prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's commanders.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "Eadric the Pure at the Argent Tournament Grounds wants you to kill 3 Boneguard Commanders.", completion = "The Argent Crusade is heartened to have paladins like you fighting alongside us in the battle against the Lich King." }
WordHunterWoW_QuestEN[13862] = { title = "Battle Before The Citadel", description = "Even as some of us labor on the tournament, our brothers prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled argent charger at the camp, then destroy the Lich King's commanders.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "Eadric the Pure at the Argent Tournament Grounds wants you to kill 3 Boneguard Commanders.", completion = "The Argent Crusade is heartened to have paladins like you fighting alongside us in the battle against the Lich King." }
WordHunterWoW_QuestEN[13863] = { title = "Battle Before The Citadel", description = "As some crusaders prepare for the tournament, they have sent others to make an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's commanders.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "Crok Scourgebane at the Argent Tournament Grounds wants you to kill 3 Boneguard Commanders.", completion = "Everywhere we have met the Scourge, we have made them fear us, and this campaign is no different." }
WordHunterWoW_QuestEN[13864] = { title = "Battle Before The Citadel", description = "As some crusaders prepare for the tournament, they have sent others to make an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's commanders.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", objectives = "Crok Scourgebane at the Argent Tournament Grounds wants you to kill 3 Boneguard Commanders.", progress = "Have you fought against the enemy in the Court of Bones?", completion = "Everywhere we have fought the Scourge, we have taught them to fear us and this campaign will be no different." }
WordHunterWoW_QuestEN[13865] = { title = "Wet Work", description = "Listen carefully, {class}.\n\nThere are three leaders in this region who are commanding the elves, keeping their focus directed on the lumber camp. Slaying them will certainly cause panic and disarray, hopefully enough for us to successfully complete our mission.\n\nWhile you're at it, bringing down their scouts can only aid our cause.", objectives = "Krokk wants you to kill Dorinar, Arminon, Endolar, and 12 Ashenvale Scouts.", completion = "Well done, <class>.\n\nThey're in complete disarray. Just look at them!" }
WordHunterWoW_QuestEN[13866] = { title = "To The Ramparts!", description = "These woods may be silent but our enemies lurk behind every trunk. I've discovered many an orc with arrows in his back, his weapon still sheathed.\n\nIt is treacherous here, behind the lines, but we could use strong arms and sharp minds down at the Mor'shan Ramparts. Kadrak is preparing an offensive from there - he prefers action to talk. You and he will get along.\n\nSpeak with me when you are ready and I will fly you there. ", objectives = "Speak with Kulg Gorespatter at the Ashenvale/Azshara border to be transported to the Mor'shan Ramparts. Report to Kadrak when you arrive.", completion = "You are just in time, <class>. Old Kulg has been slinking around those woods too long. He grows too cautious, jumping at shadows. We will fear this forest no longer - the time has come to subdue Ashenvale once and for all!" }
WordHunterWoW_QuestEN[13867] = { title = "Culling the Furbolg Threat", description = "Directly to the north of Astranaar are the Thistlefur furbolg. My scouts report that their numbers have grown greatly over the past few months. If they grow too great, they may find the courage to attack Astranaar directly!\n\nGo to Thistlefur Village and kill as many of their kind as you can.\n\nI shall remain here in Astranaar and await word from you. Elune be with you, {class}.", objectives = "Slay any 15 furbolg at Thistlefur Village in Ashenvale.", completion = "Well done, <name>.\n\nWe are under constant threat from the furbolg. Hopefully this will keep them at bay for a bit longer." }
WordHunterWoW_QuestEN[13868] = { title = "Corrupting Influence?", description = "As you search through the belongings of the dead furbolg lying before you, a small charm, very obviously created by trolls,  spills out onto the ground.\n\nTouching the charm, you immediately get a sense that something is not right about the wood. A feeling of unease, of corruption, permeates the object.\n\nWrapping it in some spare cloth, you put it in your pack and resolve to show it to Raene Wolfrunner when next you find yourself in Astranaar.", objectives = "Deliver the Troll Charm to Raene Wolfrunner at Astranaar in Ashenvale.", progress = "What's troubling you, <class>?", completion = "A troll charm? What are the furbolg doing with such a thing?\n\nYou're right, it does have a feeling of corruption about it... even I can sense that.\n\nThere's someone here who might be able to help." }
WordHunterWoW_QuestEN[13869] = { title = "Recover the Remains", description = "While what the satyrs have done to the trees is horrible, nothing compares to the mass slaughter that the orcs have been engaging in!\n\n<The ancient shakes with visible rage, his leaves falling all around you.>\n\n{race}, I would have you head across the road here at the lumber camp and recover the remains of those trees, treants, and ancients that the Horde have hewn down in their prime.", objectives = "Collect 10 Warsong Lumber.", progress = "Have you the remains, little one?", completion = "I have lived a very long time in peace with the forest, but what these orc-things are doing makes me want to feed them back to the ground!\n\nI will put this wood to rest now. Thank you for this kindness, <name>. I will never forget." }
WordHunterWoW_QuestEN[13870] = { title = "As Good as it Gets", description = "Well, {class}, this is as good as it gets.\n\nThe elves are scrambling to recover from your recent deeds. There's no better time to break into the lumber camp!\n\nMake your way in and speak with Overseer Gorthak. He'll instruct you as to how best escort the diplomat to safety.\n\nGood luck!", objectives = "Krokk wants you to enter the Warsong Lumber Camp and speak with Overseer Gorthak.", completion = "<Gorthak sighs disappointedly.>\n\nIf only you'd arrived an hour ago....\n\nThe diplomat suffered mortal wounds at the hands of an elf assassin.\n\nHow the enemy was able to infiltrate the camp undetected remains a mystery." }
WordHunterWoW_QuestEN[13871] = { title = "Security!", description = "It's not as like I haven't got enough to think about here!\n\nKeeping this place operational is hard enough without constant elf and draenei harassment.\n\nNow, on top of everything, there's an assassin lurking around the camp who's killed an important diplomat... on my watch!\n\nWhoever it is couldn't have gotten far, {class}. Scour the camp until you find her and then avenge the diplomat!\n\nAt least I can bring the assassin's head with me when I have to answer to Hellscream.", objectives = "Overseer Gorthak wants you to bring him the Kaldorei Assassin's Head.", progress = "I want to know one thing, <race>.\n\nIs that assassin dead?", completion = "Well done, <class>.\n\nOne last request - it would probably be best if none of my laborers knew this assassin ever existed." }
WordHunterWoW_QuestEN[13872] = { title = "Worgen Wisdom", description = "The man standing right across from me is known as Hephaestus Pilgrim. He's one of the worgen.\n\nHe and his sister came to Astranaar not long ago looking for a place to live. From what little I've been able to glean, he's interested in trying to help the Earthen Ring with the Cataclysm. His sister is even more powerful. She's gone east to try and help the shaman deal with the volcano.\n\nPerhaps he can help. Take the charm over to him and see what he thinks.", objectives = "Take the Troll Charm to Hephaestus Pilgrim at Astranaar in Ashenvale.", progress = "<The worgen gives you a blank look as you walk up to him.>", completion = "<Looking down at the wooden carving in your extended hand, the worgen reaches out to take it.>" }
WordHunterWoW_QuestEN[13873] = { title = "Sheelah's Last Wish", description = "I... I cannot believe she's gone. It all happened so fast....\n\nI understand that I have you to thank for avenging my mistress. For that, you have my gratitude, and that of Silvermoon.\n\nIn her wisdom, my lady foresaw this end. She prepared a missive to be delivered in the event that something happened to her.\n\nWe were to join an Orgrimmar retinue at the crossroads just north of here. Please, {race}, meet them in our stead and see that the message is delivered.", objectives = "Guardian Menerin wants you to deliver the Sealed Missive to Guardian Gurtar.\n\nProvided item:", completion = "<Gurtar listens as you inform him of Sheelah's passing.>\n\nI'll deliver this to Hellscream personally, <race>.\n\nIn the meantime, there's something I need you to do for me...." }
WordHunterWoW_QuestEN[13874] = { title = "A Not-So-Charmed Life", description = "The furbolg covet that which does not belong to them.\n\n<Hephaestus turns the charm over in his hand and then discards it.>\n\nThere's a property to the carving that slowly corrupts those that aren't trolls. As I understand it, the furbolg have done this sort of thing before. Some never learn.\n\nNo doubt they hoard most of the charms in Thistlefur Hold above their village to the north.", objectives = "Collect 8 Troll Charms.", progress = "Do you think that you retrieved all of the troll charms from Thistlefur Hold?\n\nIf any are left behind, the Thistlefur tribe will continue to be influenced by them, and eventually they will attack this place.", completion = "<Hephaestus nods slowly as he looks you straight in the eye.>\n\nYou've likely saved the Thistlefur from themselves, at least in the short run.  If they can keep from stealing objects of power that don't belong to them, that is.\n\nI understand that the night elves are having problems with the other furbolg tribe to the south. That's something that Raene is going to want to speak to you about.\n\nHowever, there are more immediate concerns that I would ask for your help with." }
WordHunterWoW_QuestEN[13875] = { title = "Gurtar's Request", description = "I have a bit of a personal request for you, {class}.\n\nIt has been many moons since I have seen my love, Draaka. It will be many more before we are able to be together again. I fear that as time passes, her love for me will wane.\n\nThis braid has special meaning to the two of us, as do Thorned Bloodcups, the flower of this region.\n\nI ask that you pluck the flowers and weave them into this twine, then present the gift to Draaka on my behalf.", objectives = "Guardian Gurtar wants you to give the Bloodcup Braid to Draaka in Splintertree.", progress = "Hello, <name>.", completion = "<Recognizing at once the nature of the gift, Draaka begins to weep.>\n\nOh, <name>. Thank you for this gift! It means more than you could know.\n\nHe hasn't forgotten..." }
WordHunterWoW_QuestEN[13876] = { title = "Too Far Gone", description = "Yes, I speak your tongue, {race}.\n\nWe furbolg have been through this kind of corruption before. Not long ago our leader stole the Idol of Remulos. The demon-tainted thing ensorcelled the entire tribe and our redemption was barely delivered by a druid known as Broll Bearmantle.\n\nBut this time, we did not steal. The trolls of Zoram'gar gave us the charms as a sign of friendship. A deadly friendship it would seem.\n\nOur chief, Dal Bloodclaw, is too far gone. Enter the hold and return with his charms.", objectives = "Obtain Bloodclaw's Collection.", progress = "Well? The future of the Thistlefur rests upon your shoulders, <race>.", completion = "What was done had to be done. As our leader, Dal's sickness from the troll charms was destroying us.\n\nIt was better for the health and dignity of the tribe that it was you, outsider. This way there will be no civil war amongst us and we will easily find new leadership... hopefully one that does not have a tendency to so easily trust outsiders. Perhaps I am guilty of this as well?\n\nHere, allow me to repay the debt we owe you before we part ways forever." }
WordHunterWoW_QuestEN[13877] = { title = "Go With The Flow", description = "<The worgen stares at you intently before launching into his request.>\n\nThe volcano threatens to engulf all of Ashenvale if we do not act quickly. Let me assure you, this was no natural eruption.\n\nMy sister, Sabina, is powerful. She has gone east to the edge of Thunder Peak's lava flow, just north of the road to enlist the aid of the other elements against the fire lord that has caused this destruction.\n\n{name}, go to her and give her what assistance you can.", objectives = "Speak with Sabina Pilgrim at the southern edge of Thunder Peak's lava flow in Ashenvale.", completion = "My brother must have sent you. He wouldn't have done so unless you are capable of doing what must be done.\n\nFor all of our sakes I hope that he's right.\n\nThe elementals here are now my allies. You must do as they ask if we are to prevent the destruction of the rest of Ashenvale." }
WordHunterWoW_QuestEN[13878] = { title = "Through Fire and Flames", description = "Help me, {class}! Piggy men come burn stables - fire! Fire!\n\n<Dorak wails incoherently before you can settle him down.>\n\nWolves still chained inside. Someone's got to save the wee wolves!  ", objectives = "Break the chains to free the wolves from the burning stables.", progress = "Hot!", completion = "You save the wolves! So brave! Someday, maybe you get a wolf just like that to ride.\n\n<Dorak looks at the burning stables, then at the nearby river.>\n\nWhat should I do now?" }
WordHunterWoW_QuestEN[13879] = { title = "Thunder Peak", description = "Greetings, {class}.\n\nCongratulations on your victorious assault on Astranaar. The elves shall not soon forget the humiliation they have suffered at your hand.\n\nBut you must know, the elves are not the only obstacle to the Horde's conquering of Ashenvale....\n\nTo the east, a shaman of the Earthen Ring requires assistance with yet another crisis. You can find him near the base of the volcano, Thunder Peak.", objectives = "Broyk wants you to find Stikwad at Thunder Peak.", completion = "<The goblin stares at you and blinks several times before speaking.>\n\nThe spirits whispered that help would soon arrive.\n\nPardon my surprise, but I was hoping the spirits would guide someone a little more... heroic.\n\nThese elementals are trusted allies. Listen to them and do their bidding. If we fail, there will remain nothing in Ashenvale worth fighting for." }
WordHunterWoW_QuestEN[13880] = { title = "Hot Lava", description = "<The massive earth elemental gazes down upon you.>\n\nThe flow of the lava must be stopped if we are to prevail. I will grant to you a portion of my power. Use it to fill the lava fissures!", objectives = "Use the Gift of the Earth to fill 8 Lava Fissures.", progress = "Done?", completion = "Well done, <race>. Lord Magmathar's fire is now trapped, restrained within the earth once more." }
WordHunterWoW_QuestEN[13881] = { title = "Consumed", description = "My first concern right now is for the thistle bear families who call what's left of these woods home. Just to our south, beyond the bear shrine, an entire generation has fallen ill. Gruesomely ill.\n\n{name}, I don't know what they're suffering from, but it's consumed them from within. It pains me that a whole generation is beyond saving, but we've got to kill them off so that the earth can reclaim their bodies.\n\nMore importantly, we need to find the source. Investigate the shallow lake they drink from!", objectives = "Kill 6 Consumed Thistle Bears and investigate the lake they're drinking from.", completion = "<Kathrena recoils at your description of the ravaged animals and the cruel device at the bottom of the lake>\n\n<name>, this is terrible. What is that thing, and how did it get there? Something is devouring these animals, physically and spiritually. I had suspected the satyrs or some sort of disease was the culprit, but this is shaping up to be something ... unnatural." }
WordHunterWoW_QuestEN[13882] = { title = "The Seeds of Life", description = "Something is trying to devour the life of Darkshore from within! I'll ask around to learn more about the - thing - you discovered in the lake. Meanwhile, we need to protect the local wildlife from further harm.\n\nCan you gather some materials for me? I'll need life in all its incarnations. Talk to Onu here in the grove to acquire a Seed of the Earth. Capture a Darkshore Wisp floating amongst the trees and we'll have a Seed of the Sky. Find a Seed of the Sea within seashells along the coast, west of here.", objectives = "Gather a Seed of the Earth, a Seed of the Sea, and a Seed of the Sky.", progress = "Life is powerful, <name>. Concentrated in its purest form, it can overcome anything. Someday, even Darkshore will heal from its wounds. Did you find everything I need?", completion = "Perfect, this is everything. Did you have fun collecting the wisp? I used to chase the wisps around Ashenvale when I was just a girl.\n\n<Lost in memories for a moment, Kathrena suddenly grows somber.>\n\nI'm afraid I've found out what we're dealing with." }
WordHunterWoW_QuestEN[13883] = { title = "Lousy Pieces of Ship", description = "Shoddy workmanship! There's no other explanation...\n\nThese ships must've been constructed in a hurry. Entire pieces of armor plating are falling off without even sustaining a direct hit!\n\nI'll show them how it is to be done. But first, I need you to recover the pieces from the sea floor.\n\nReturn to me with the pieces and I'll do the rest.", objectives = "Recover 10 pieces of Sunken Scrap Metal.", progress = "Were you able to recover that armor plating, <race>?", completion = "Good work, <race>.\n\nI'll show them how an armored ship should be built!" }
WordHunterWoW_QuestEN[13884] = { title = "Put Out The Fire", description = "Lord Magmathar's minions must first be dealt with if we're to retake this area and put a stop to the fiery destruction of the forest.\n\nThe lava ragers on the flow to the north are strengthened by being on their own element. I fear that on your own, you won't have much chance against them.\n\nWhen you are ready, speak to me again, and I will summon one of my own to assist you.", objectives = "Slay 10 Lava Ragers. If you need another Freezing Surger, speak with Arctanus.", progress = "There are yet more lava ragers to be destroyed, <race>.", completion = "You acquitted yourself well in battle on the field. However, I'm afraid that Lord Magmathar has taken notice of you and the destruction that you've wreaked upon his minions.\n\nYou will have to deal with him or he is sure to burn you alive, <name>." }
WordHunterWoW_QuestEN[13885] = { title = "In Defense of Darkshore", description = "Now that we know our preventative measures work, we should cover as much ground as possible.\n\nI've arranged to commandeer one of our hippogryphs, but I can't do this alone. Talk to my friend Orseus, next to the flight master right outside the grove here. Let him know when you're ready and I'll meet you there. We'll canvas Darkshore from the air and protect as many animals as we can!", objectives = "Talk to Orseus outside the Grove of the Ancients and mount a hippogryph. From the air, protect 8 Whitetail Deer, 8 Grizzled Thistle Bears, and 8 Moonstalker Matriarchs/Sires from the consumption.", completion = "So the animals are safe, then. Thank you, thank you!\n\nBut now it's time to turn our attention to the source." }
WordHunterWoW_QuestEN[13886] = { title = "Vortex", description = "The time has come, {name}. When you have steeled yourself we will speak again and I will summon forth a whirling vortex to speed your way up to the skies over Thunder Peak.\n\nChannel the power of the Earthen Ring through the elemental to slay Lord Magmathar so that we may bring him into balance once more.", objectives = "Use the powers of the Whirling Vortex to slay Lord Magmathar.", completion = "It is done. The power of fire is subdued and the four elements are returned to harmony.\n\nYou have saved the rest of Ashenvale through your brave and selfless actions, <name>. You have our eternal thanks." }
WordHunterWoW_QuestEN[13887] = { title = "Venomhide Eggs", description = "Now that you've built up an immunity to venomhide toxin, you can safely handle the animals and their eggs. Venomhides are vicious and must be trained from the moment they hatch.\n\nIf you want to ride one, you'll need an unhatched egg. Scattered throughout the Marshlands are a number of ravasaur nests. Look for the eggs with lighter colored shells -- those are the ones that will hatch venomhides.\n\nIf you bring me several of the eggs, I'll allow you to keep one and raise its hatchling, with my guidance.", objectives = "Bring 4 Venomhide Ravasaur Eggs to Mor'vek in the southeast part of the Marshlands.", progress = "Did you find those eggs?", completion = "Good work. Honestly, I'm amazed you were able to find this many. With each clutch, they seem fewer in number.\n\nI'll let you raise one of the freshly-hatched venomhides. It shouldn't be shy about letting you know what it needs." }
WordHunterWoW_QuestEN[13888] = { title = "Vortex", description = "The time has come, {name}. When you have steeled yourself we will speak again and I will summon forth a whirling vortex to speed your way up to the skies over Thunder Peak.\n\nChannel the power of the Earthen Ring through the elemental to slay Lord Magmathar so that we may bring him into balance once more.", objectives = "Use the powers of the Whirling Vortex to slay Lord Magmathar.", progress = "Lord Magmathar must still be slain, <name>.", completion = "You've done it! The spirits were right after all!\n\nThe power of fire is subdued and the four elements are returned to harmony.\n\nThe rest of Ashenvale is spared this fiery fate. You have the eternal thanks of the Earthen Ring." }
WordHunterWoW_QuestEN[13889] = { title = "Hungry, Hungry Hatchling", description = "The venomhide hatchling looks at you expectantly, then begins to scrawl a pictogram into the dirt.\n\nThe drawings are rough, but you can make out the shapes of diemetradons, stegodons, and pterrordaxes. As the raptor finishes the sketch, it looks up at you, bares its teeth, and makes a biting motion.\n\nYour venomhide hatchling must be craving fresh meat from these animals. Find and kill any type of diematradon, stegodon, or pterrordax in Un'Goro Crater and feed its meat to your hungry hatchling.", objectives = "Your Venomhide Hatchling wants you to feed it 15 pieces of Fresh Dinosaur Meat.", progress = "The venomhide hatchling licks its lips and tilts its head to the side.", completion = "The venomhide hatchling seems satisfied with the giant meal you've provided, but there's no way of telling when it will be hungry again." }
WordHunterWoW_QuestEN[13890] = { title = "Keep the Fires Burning", description = "This is no small task, {race}!\n\nWe have more ships arriving, and without the lighthouse they'll be lost - or worse! You are hereby charged with keeping its fire lit.\n\nCollect the blubber from the hydras in these waters, then bring it to the forge here to melt it into oil.\n\nThrowing that oil on the lighthouse fire will buy us the time we need.", objectives = "Commander Grimfang at Zoram'gar wants you to pour Mystlash Hydra Oil on the lighthouse fire.", progress = "Well, <class>...\n\nHave you done as I asked?", completion = "Nice work, <race>!\n\nNo more ships will run aground, thanks to you." }
WordHunterWoW_QuestEN[13891] = { title = "The Devourer of Darkshore", description = "Now that the creatures of Darkshore are safe, let's turn our attention to the artifact you found in the lake. I believe it's the work of a minion of the Old Gods. We'll fight these fiends using the very lifegiving energies of Darkshore itself! Take the Lifebringer Sapling to the shore of the shallow lake to the south of here. Wave it over the waters of the lake and it should disable that ancient artifact.\n\nBe careful, {name}. The artifact is likely to be guarded by who-knows-what.", objectives = "Use the Lifebringer Sapling on the shore of the shallow lake south of the Grove of the Ancients to destroy the Devouring Artifact and its guardian.", progress = "I'm afraid to ask, <name>. Is the artifact destroyed? What about its guardian?", completion = "Love of Elune, look at you. That must've been some fight! You're covered in what looks like... chowder.\n\nIf a mere minion could cause so much agony here in Darkshore, I can't even imagine the suffering that a true Old One could bring about.\n\nWell, at least the animals are safe for now. I will plant the sapling you created to help rebuild this shattered land. Thank you, <name>! I'd give you a hug but, you know. Chowder." }
WordHunterWoW_QuestEN[13892] = { title = "Leave No Tracks", description = "To the southwest lies the corpse of a being somehow related to the Old Gods that the Twilight's Hammer cultists worship.\n\nHe was defeated before our time -- if not by the Titans themselves, certainly by one of their creations.\n\nWe've noted an increase in cult activity in that area which can only mean something terrible is amiss.\n\nWe're going to need to find out what they're planning to do there and why.  Take this figurine, it'll help you avoid being detected while you gather intelligence.", objectives = "Sneak into the Master's Glaive using the Panther Figurine and spy on the Twilight's Hammer.", completion = "This is dire news, <name>.  If you are correct, then we'd best act swiftly and decisively.\n\nWe cannot allow this \"Soggoth\" to be brought back to life." }
WordHunterWoW_QuestEN[13893] = { title = "Soggoth and Kronn", description = "The Master's Glaive was the site of an ancient battle, {name}.  The titans sent twenty of their stone giants against Soggoth.\n\nOf those twenty giants, one survived.\n\nThe tablets say that Kronn, the largest of the stone giants allowed himself to be entangled by Soggoth's tendrils -- just long enough to be lifted close enough to the creature's skull... within reach of his mighty sword.\n\nIt's a good thing he's dead... we don't really have twenty stone giants lying around to stop him again.  ", objectives = "Return to Larien at the Grove of the Ancients with the information you've obtained.", completion = "The dwarf's story is unsettling... yet informative.  It seems we have few options left." }
WordHunterWoW_QuestEN[13894] = { title = "Marking the Kills (DEPRECATED)", description = "", objectives = "" }
WordHunterWoW_QuestEN[13895] = { title = "The Slumbering Ancients", description = "We may not have twenty stone giants to take on our enemy, but we giants of ancient lumber are as strong as any rock.\n\nLook around you, {race}.  My kindred sleep... yet they will heed the keeper's horn when the time of need is upon them.\n\nYou will find Aros, the keeper of the grove, beyond the bridge northeast of here.\n\nTell him the urgency of our situation.", objectives = "Find Aros northeast of the Grove of the Ancients in Darkshore.", completion = "Aros's body appears to be lifeless yet still warm.  Perhaps his killers are nearby." }
WordHunterWoW_QuestEN[13896] = { title = "Unearthed Knowledge", description = "Listen, {name}.  We need to learn more about what we're up against.\n\nTo the southwest, beyond the Master's Glaive, there is a group of dwarven prospectors who were excavating the nearby ruins.\n\nPerhaps they have uncovered knowledge that is useful to us in this matter.", objectives = "Speak to Archaeologist Groff at Remtravel's Excavation.", completion = "Oh, we know a thing or two about this Soggoth.  The question is... do you really want to know?" }
WordHunterWoW_QuestEN[13897] = { title = "The Battle for Darkshore", description = "The ancients of the grove have come to our aid, {name}.  I can see through their eyes even as we speak.\n\nThe Twilight's Hammer has been forced to hasten their ritual and have thus only managed to resurrect but a remnant of dread Soggoth.\n\nDestroy it before it's too late, {name}.  I am needed elsewhere.\n\nReturn to the druids at the Grove of the Ancients when it is all over they will direct you further.", objectives = "Slay the Avatar of Soggoth at the Master's Glaive.", completion = "We can finally rest here now, <name>.  It appears Darkshore has been saved -- and we have you to thank for it." }
WordHunterWoW_QuestEN[13898] = { title = "The Tides Turn Against Us", description = "We cannot let the naga get away with this, {name}.  Slaying the keeper of the grove amounts to a declaration of war.\n\nYou'll find their den inside a cave on the island of Naj'vel, far to the southwest.\n\nI want you to send them a clear message.", objectives = "Slay 8 Darkscale Myrmidons.", completion = "Well done, <name>.  The naga seek the destruction and subjugation of all surface-dwellers -- do not hesitate to drive them out of our lands and back into the shadowy ocean depths where they belong." }
WordHunterWoW_QuestEN[13899] = { title = "The Darkscale Warlord", description = "If the naga want to throw in their lot with the Twilight's Hammer, then may Elune have mercy on them.\n\nGo into their lair in the island of Nazj'vel and find their leader, the naga warlord known only as Wrathspine.\n\nPerhaps the horn of the ancients can still be saved.", objectives = "Slay Warlord Wrathspine inside Nazj'vel.", completion = "The walord doesn't seem to have the horn on him.  Perhaps he was telling the truth." }
WordHunterWoW_QuestEN[13900] = { title = "The Offering to Azshara", description = "The warlord said the horn of the ancients was being offered to Azshara above Nazj'vel.\n\nPerhaps it's not too late to save the ancient relic from being destroyed.", objectives = "Stop the Darkscale Priestesses from offering the Horn of the Ancients to Azshara above Nazj'vel.", completion = "You've done well, <name>.  Unfortunately the battle is far from over." }
WordHunterWoW_QuestEN[13901] = { title = "Deep Despair", description = "There is more to this naga problem than meets the eye, {class}.  It appears that the issue will not be resolved by merely thinning their numbers. To humble them, a more severe impression must be made.\n\nTravel to the northern end of Zoram Strand and enter Blackfathom Deep. Once there, demonstrate to the naga that their presence in this region will no longer be tolerated!", objectives = "Kill 6 Blackfathom Tide Priestesses.", completion = "Excellent!\n\nLet the naga retreat back into the seas where they belong!" }
WordHunterWoW_QuestEN[13902] = { title = "Mounting the Offensive", description = "Our work in Darkshore is not yet done.  We might have stopped the landmass from shattering, but our enemies still have a strong presence in the area.\n\nI want you to contact a group of druids at the Grove of the Ancients, far to the south.  They are led by an old friend of mine, Balren of the Claw.\n\nTell them that the time has come to take the battle to our foes.  I will come to aid them as soon as we stabilize the area.", objectives = "Speak to Balren of the Claw at the Grove of the Ancients in Darkshore.", completion = "If Malfurion placed his trust on you, then so shall I.  You'll find that our enemies greatly outnumber us this far south.\n\nWhere brute force and numbers fail us, strategy and guile will prove our biggest advantages." }
WordHunterWoW_QuestEN[13903] = { title = "Gorishi Grub", description = "The venomhide hatchling looks at you expectantly, then begins to scrawl a pictogram into the dirt.\n\nThe hatchling's drawings seem to resemble various types of large insects, perhaps the gorishi silithids. The hatchling finishes his picture, then gestures at it with one short arm, snaps its jaws, and licks its lips.\n\nIt must want you to go to the Slithering Scar, in the center of the southern part of Un'Goro Crater, and gather silithid meat. When you have the meat, feed it to your hungry hatchling.", objectives = "Your Venomhide Hatchling wants you to feed it 10 Silithid Meat.", progress = "The hatchling cocks its head and looks at you.", completion = "Your venomhide hatchling flashes you a toothy smile and then settles in for a nap." }
WordHunterWoW_QuestEN[13904] = { title = "Poached, Scrambled, Or Raw?", description = "The venomhide hatchling's stomach growls as it gestures to get your attention. It begins scratching pictures of silithids into the dirt, adding small ovals underneath them. It looks at you hopefully and gestures at the circles.\n\nThey can only mean silithid eggs. The Noxious Lair, in western Tanaris and near the border with Un'Goro Crater, would probably be a great place to find the eggs your little hatchling wants.", objectives = "Your Venomhide Hatchling wants you to feed it 12 Silithid Eggs.", progress = "The hatchling looks at you.", completion = "Your hatchling licks its lips after devouring the meal of silithid eggs. For a moment, you think it seems disappointed that feeding time has come to an end." }
WordHunterWoW_QuestEN[13905] = { title = "Searing Roc Feathers", description = "The hatchling looks at you for a moment, almost as if wondering whether you'll understand. It scrawls a picture of a pair of feathers in the dirt, then points with one claw to the bindings at its elbows and knees.\n\nIt doesn't seem hungry, but what could the feathers be for?\n\nIt must want them for adornments like the ones you've seen on other raptors. The largest feathers come from the searing rocs that congregate around the bones of large creatures in western Tanaris, northeast of Thistleshrub Valley.", objectives = "Your Venomhide Hatchling wants you to get 5 pieces of Searing Roc Plumage.", progress = "Your venomhide hatchling looks at you with anticipation.", completion = "The venomhide hatchling accepts the feathers and begins looking them over, holding several up to its armbands." }
WordHunterWoW_QuestEN[13906] = { title = "They Grow Up So Fast", description = "With your expert feeding and care, your venomhide hatchling will grow quickly. As they grow, their hatchling teeth will be replaced by adult teeth. If you keep the teeth shed by your hatchling as it grows, you'll have an easy way to tell when it's mature enough to be trained as a mount.\n\nYour venomhide will let you know what it needs, so pay close attention. When it has shed all of its baby teeth, return to me with your venomhide and the materials for your saddle and I'll do the rest.", objectives = "Return 20 Venomhide Baby Teeth,  the Venomhide Hatchling, 20 Runecloth, 20 Rugged Leather, and 80 gold to Mor'vek in the southeastern part of the Marshlands in Un'Goro Crater.", progress = "Have you been taking good care of that raptor?", completion = "It looks like both of you have managed to do some growing without killing one another.\n\nThere, everything's finished. I've trained your venomhide ravasaur to respond when you blow this whistle.\n\nFew have the dedication to hand-feed and raise a venomhide, but they're well worth the effort." }
WordHunterWoW_QuestEN[13907] = { title = "Sweeping Clean the Ruins", description = "The big beards at Ironforge sent me here to check on Remtravel's dig the moment they got word of the disaster. Look at it! Precious artifacts washed to sea, months of tedious digging undone in a moment.\n\nWhen the tidal waves hit, they demolished the murloc encampments along the shore. Good news? Naw, not with my luck. The survivors are squatting in the shelter of the ruins, and they're doing more damage than the elements ever could. Would you mind getting your waders on and taking care of things?", objectives = "Kill 10 of any combination of Greymist Oracles or Greymist Refugees squatting within Remtravel's Excavation.", completion = "Bravo, <name>! Now let's take a look-see at our new situation.\n\nWhat? MORE murlocs? I swear on my stones, the more murlocs you kill, the more murlocs appear. Is it just me? We're going to need a new approach." }
WordHunterWoW_QuestEN[13908] = { title = "Gearing Up To Ride", description = "Your venomhide is strong and healthy and you've developed quite a bond. You'll be ready to ride him once I've completed your saddle and bridle. Just like you, they have to be specially conditioned to stand up to the toxins the raptor produces.\n\nAll you'll need to do is bring me some rugged leather, runecloth, and money to buy the rest of the supplies and I'll have that saddle for you in no time.You will receive:", objectives = "Bring 20 Rugged Leather, 20 Runecloth, and 80 gold to Mor'vek in the southeast part of the Marshlands in Un'Goro Crater." }
WordHunterWoW_QuestEN[13909] = { title = "Got Some Flotsam?", description = "We can figure this out, {name}. We just need some Dwarven ingenuity. Think, Groffy, think!\n\nThese murlocs are just looking for a home, right? Let's do something constructive. I mean that literally.\n\nAll sorts of debris was washed ashore during the catastrophe, and some of the decimated murloc hovels may still be salvageable. Run along the shore here and gather up any building materials fit for a murloc. That's an admittedly low standard. ", objectives = "Collect 5 pieces of Salvageable Greymist Wreckage from along the shore and in the water near the Remtravel Excavation.", progress = "Wet enough for ya?", completion = "<Archaeologist Groff picks through the wreckage.>\n\nWell, not much here that don't look stepped on, sat on, or soaked in a toilet. But toss some thatch on top and it'll do.\n\nTell me, <name>, do you consider yourself an architect?" }
WordHunterWoW_QuestEN[13910] = { title = "A New Home", description = "Can we build it? Yes we can! Just west of the dig site I planted a banner on the shore. The sand is firm and it's as good a site as any. Take my tools and the parts you collected and build these ornery pests a different place to live.", objectives = "Build a murloc hovel at a site Groff marked with a flag on the nearby shore.", progress = "How goes our new seaside condo?", completion = "Har har, that sounds like quite a heap you built there. Did they take to it? Good, good! Let's see if my plan comes to fruition.\n\n<Archaeologist Groff watches as scores of murlocs stream down the beach, pouring into the hovel from all corners of the compass. Gradually his brows knit together.>\n\nWhat have I done?" }
WordHunterWoW_QuestEN[13911] = { title = "The Absent-Minded Prospector", description = "Who are you again? {name}? Have we met? If you're here from the League, you can tell them I'm not leaving! Not without my find. I had it, right in my hands! Then the screaming. Then the wetness.\n\nListen here whos-yer-name, I documented the whole thing in my journal the day the tidal wave hit. And I know just where I left it! The journal. Not the find. Help me get the one so we can get the other! Or vice-versa! Do you follow? Follow me!", objectives = "Escort the confused Prospector Remtravel to his missing journal. Talk to Jr. Archaeologist Ferd at the dig site when you're done.", completion = "Ah, you've helped the Prospector find his missing journal! To think it was here all along.\n\nSomeday you'll have to show me this other set of ruins he's always going on about." }
WordHunterWoW_QuestEN[13912] = { title = "Swamped Secrets", description = "Underneath Remtravel's forgetful exterior is the mind of a genius, an enigma cloaked in senility. But I'm not about to give up on the old man. Look at what I found in his notes... not there... no, that's a shopping list... Here, on the page where he's trying to figure out what year it is: The Disc!\n\nWe think this Titan artifact is some sort of encrypted storage wheel. We were carefully unearthing it when the disaster hit, but hopefully it's still in the ruins. Dive in and grab it for me! ", objectives = "Find a Mud-Crusted Ancient Disc from within the nearby ruins.", progress = "Did you find it? Groff wants to clear out of these ruins as soon as possible!", completion = "Spectacular! Good work, <name>. I'm sure Remtravel would thank you himself if he could remember your name.\n\nLook at the surface of the disc - these microscopic etchings - this is amazing. I'm certain this strange wheel holds information, if only we could read it..." }
WordHunterWoW_QuestEN[13913] = { title = "They Took Our Gnomes", description = "The gnome explosives squad we requested from Tinker Town arrived last week. Just in time to face an assault by the Horde. We lost a lot of soldiers that day. Most of the gnome team was taken as well. Now we're neck deep in Horde, Silverwind Refuge has been lost and we're down a dozen gnomes.\n\nI'm begging for your help here, {name}. Travel east to Silverwind Refuge and look for any gnome survivors. They were all carted off by a big, merciless orc named Thundrak. Find him and you'll find our gnomes.", objectives = "Rescue Boog the \"Gear Whisperer\" and Minx from Painmaster Thundrak's Wagon of Unending Agony.", completion = "Thank you, <name>. Grim news you bring of the rest of the gnome team, but at least you managed to save a few. For that I am grateful." }
WordHunterWoW_QuestEN[13914] = { title = "Searing Roc Feathers", description = "The hatchling looks at you for a moment, almost as if wondering whether you'll understand. It scrawls a picture of a pair of feathers in the dirt, then points with one claw to the bindings at its elbows and knees.\n\nIt doesn't seem hungry, but what could the feathers be for?\n\nIt must want them for adornments like the ones you've seen on other raptors. The largest feathers come from the searing rocs that congregate around the bones of large creatures in western Tanaris, northeast of Thistleshrub Valley.", objectives = "Your Venomhide Hatchling wants you to get 5 pieces of Searing Roc Plumage.", progress = "Your venomhide hatchling looks at you with anticipation.", completion = "The venomhide hatchling accepts the feathers and begins looking them over, holding several up to its armbands." }
WordHunterWoW_QuestEN[13915] = { title = "Hungry, Hungry Hatchling", description = "The venomhide hatchling looks at you expectantly, then begins to scrawl a pictogram into the dirt.\n\nThe drawings are rough, but you can make out the shapes of diemetradons, stegodons, and pterrordaxes. As the raptor finishes the sketch, it looks up at you, bares its teeth, and makes a biting motion.\n\nYour venomhide hatchling must be craving fresh meat from these animals. Find and kill any type of diematradon, stegodon, or pterrordax in Un'Goro Crater and feed its meat to your hungry hatchling.", objectives = "Your Venomhide Hatchling wants you to feed it 15 pieces of Fresh Dinosaur Meat.", completion = "The venomhide hatchling seems satisfied with the giant meal you've provided, but there's no way of telling when it will be hungry again." }
WordHunterWoW_QuestEN[13916] = { title = "Poached, Scrambled, Or Raw?", description = "The venomhide hatchling's stomach growls as it gestures to get your attention. It begins scratching pictures of silithids into the dirt, adding small ovals underneath them. It looks at you hopefully and gestures at the circles.\n\nThey can only mean silithid eggs. The Noxious Lair, in western Tanaris and near the border with Un'Goro Crater, would probably be a great place to find the eggs your little hatchling wants.", objectives = "Your Venomhide Hatchling wants you to feed it 12 Silithid Eggs.", completion = "Your hatchling licks its lips after devouring the meal of silithid eggs. For a moment, you think it seems disappointed that feeding time has come to an end." }
WordHunterWoW_QuestEN[13917] = { title = "Gorishi Grub", description = "The venomhide hatchling looks at you expectantly, then begins to scrawl a pictogram into the dirt.\n\nThe hatchling's drawings seem to resemble various types of large insects, perhaps the gorishi silithids. The hatchling finishes his picture, then gestures at it with one short arm, snaps its jaws, and licks its lips.\n\nIt must want you to go to the Slithering Scar, in the center of the southern part of Un'Goro Crater, and gather silithid meat. When you have the meat, feed it to your hungry hatchling.", objectives = "Your Venomhide Hatchling wants you to feed it 10 Silithid Meat.", completion = "Your venomhide hatchling flashes you a toothy smile and then settles in for a nap." }
WordHunterWoW_QuestEN[13918] = { title = "The Titans' Terminal", description = "Now that we have the disc, a lot of our earlier finds are starting to make sense. Shortly after my arrival, Prospector Remtravel unearthed what he presumed to be a prehistoric toaster.\n\nIt's my belief that this slotted box is some sort of data reader. Unfortunately, it broke apart and washed away with the rest of our base camp when the tidal wave struck!\n\nIt can't have gone far, {name}. Pieces must be buried in the nearby sand. Here, use my trusty buried artifact detector to comb the beach for them.", objectives = "Use Buried Artifact Detector on the beach near Remtravel's Excavation site to locate 5 Ancient Device Fragments. Combine them to create the Ancient Slotted Device.", progress = "Did you assemble all the pieces of the slotted device? We may need to remove Prospector Remtravel's sandwich from the ancient data interface.", completion = "Why yes, yes, this is it! See here, the slot is the exact dimensions of the ancient disc, just as I'd surmised. Here's your reward, <name> - you've earned it.\n\n\n\nAre you ready to meet history face to face? Let's see what the ancients have to say!" }
WordHunterWoW_QuestEN[13919] = { title = "A Trip to the Moonwell", description = "It didn't work.\n\n<A sorrowful and resigned expression upon his face, Pelturas removes the tear from the soup and gently washes it.>\n\nThe eruption of Thunder Peak must have affected it in some way. You must take the tear to the Moonwell of Purity, which still lies intact, protected by the goddess' power, at the southeast base of the volcano.\n\nThere, you will wash it in the sacred waters of Elune. What happens beyond that, I cannot say. I fear for my daughter's life. It is in your hands now, {name}.", objectives = "Take the Tear of Elune and cleanse it in the waters of the Moonwell of Purity in Ashenvale." }
WordHunterWoW_QuestEN[13920] = { title = "Before You Go...", description = "We have urgent need for good {class}s at Hellscream's Watch, {name}. But before you're dispatched, there remains something that needs doing here.\n\nMost of our perishable goods were lost at sea due mainly to Alliance attacks. We must stock enough food to carry out our Ashenvale campaign.\n\nJust east of here, you should find wildlife in abundance. Bring back the best meat you can find for our troops!", objectives = "Bring 5 Venison Steaks to Commander Grimfang in Zoram'gar.", progress = "Yes, <race>?", completion = "These venison should make our soldiers' spirits rise for the coming battles. Here's something for your troubles." }
WordHunterWoW_QuestEN[13921] = { title = "He Who Would Be Forgiven", description = "<A voice from inside the moonwell flows over your mind, bringing you a perfect sense of peace.>\n\nYou seek to cure a child, but know that all things come at a cost. To the east lies Raynewood Tower. Standing outside the tower, next to my moonwell, is one who has fallen into corruption.\n\nAvrus Illwhisper seeks forgiveness and redemption, {name}. Will you help him to attain that which he desires and in so doing achieve your own goal?", objectives = "Speak with Avrus Illwhisper at Raynewood Tower in Ashenvale.", completion = "<The satyr sneers, but when he realizes you are not here to chastise him, he changes his expression.>\n\nFinally, my redemption is at hand. I have waited long for this day and I think I know how to help you in turn." }
WordHunterWoW_QuestEN[13922] = { title = "In the Hands of the Perverse", description = "My former clan, the Felmusk of Night Run, raided Fallen Sky Lake some time ago, stealing the moonstones that were unique to the area.\n\nThose moonstones are known to have great healing properties and surely can be used to cure the little girl that lies sick in Astranaar.\n\nNight Run rests up the road to the east that runs north. There are multiple paths that lead up into the hills on its eastern side, and it is there that you will find my unrepentant brethren. They will have what you seek.", objectives = "Obtain 5 Fallen Moonstones.", progress = "Five moonstones are required to assure that the girl is healed.", completion = "You have all of the moonstones that are needed. And yet, it is said that a sacrifice of life is the only way to be ensure the saving of another.\n\nI will ensure that no matter what, the moonstones will cure Relara." }
WordHunterWoW_QuestEN[13923] = { title = "To Hellscream's Watch", description = "Into the fray with you, {race}!\n\nHellscream's Watch is one of our most contentious fronts in Ashenvale. The experience should serve you well... assuming you survive.\n\nWhen you've made ready, speak with Andruk. I've arranged for him to transport you directly to your station.\n\nOnce you've arrived, seek out Captain Goggath. He will guide you further.\n\nBring pain and death to our enemies! For the Horde!", objectives = "Speak to Captain Goggath at Hellscream's Watch.", completion = "You come here as a child, <race>.\n\nYou shall leave here a battle-hardened <class> of the Horde!\n\nThat, or a corpse...." }
WordHunterWoW_QuestEN[13924] = { title = "All's Well", description = "Thank you for saving me from a fate worse than death, {name}! For saving both the child and myself!\n\nWell, the child is almost saved. All you have to do is take the moonstones back west down the road to Astranaar. Hand them to Pelturas and he will know what to do.\n\nGo in peace, my friend. Elune be praised!", objectives = "Deliver the Sanctified Moonstones to Pelturas Whitemoon at Astranaar in Ashenvale.", progress = "<name>, is that you? Have you returned with the cure for Relara?", completion = "Oh, <name>, you have saved my daughter! I know the power of the moonstones will give back my daughter her strength!\n\nI can never repay you fully for the aid you have given me, but... please, take this. Other than Relara, it is my most dear possession." }
WordHunterWoW_QuestEN[13925] = { title = "An Ounce of Prevention", description = "Are you familiar with the Old Ones, {name}? Onu and I agree that the artifact you found in the lake can only be their work, and it's devouring Darkshore. Something is stirring up terrors we thought dead long ago. This is bigger than you or me, but my first concern is protecting the wildlife.\n\nHere, this sapling contains the life essence you gathered for me. I believe it can protect the local fauna. Test it out on a nearby un-consumed bear, stag, or moonstalker, and let me know what happens!", objectives = "Test the Lifebringer Sapling on any nearby healthy Grizzled Thistle Bear, Whitetail Stag, or Moonstalker Matriarch/Sire.", progress = "The sapling you carry grows in power even as we speak. Life is regenerative, <name>. Did it work?", completion = "Interesting ... It sounds like our cure will keep the wildlife safe, but you say you saw something else? Some kind of angry presence?\n\nThis is a good sign, <name>. Whatever is behind this isn't happy, and that means we're on to something." }
WordHunterWoW_QuestEN[13926] = { title = "Little Orphan Roo Of The Oracles", description = "The orphans have been looking forward to the opportunity to meet friends like you, {name}. It's wonderful that you've agreed to take one into your care.\n\nTake this whistle.  With it, you will be able to call for the orphan you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, {name}, call upon your orphan.  He will be excited to meet you and see the sights of Northrend with you.", objectives = "Speak to Orphan Matron Aria, then use the Oracle Orphan Whistle to call the orphan you will be taking care of during Children's Week.", progress = "You taking care of us?", completion = "You take us away from puppy-men hatchlings? Good. We like you already. Mean puppy-men hatchlings took all our favorite toys away." }
WordHunterWoW_QuestEN[13927] = { title = "Little Orphan Kekek Of The Wolvar", description = "The orphans have been looking forward to the opportunity to meet friends like you, {name}. It's wonderful that you've agreed to take one into your care.\n\nTake this whistle.  With it, you will be able to call for the orphan you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, {name}, call upon your orphan.  He will be excited to meet you and see the sights of Northrend with you.", objectives = "Speak to Orphan Matron Aria, then use the Wolvar Orphan Whistle to call the orphan you will be taking care of during Children's Week.", progress = "Orphan lady say Kekek go with you.", completion = "You take Kekek hunting? Good to get away from mean old orphan lady who doesn't let Kekek hunt." }
WordHunterWoW_QuestEN[13928] = { title = "Recover the Fallen", description = "I and my sentinels have been ordered by Keeper Ordanus to stay here and hold the tower. So far we've been able to repel the Horde, but now they're going around us to directly attack the retreat to the north.\n\nThe keeper sent out his dryads to defend the tree, but they do not seem to be much of a match for the vanguard of the Warsong orcs.\n\nI need you to go out there and recover as many laughing sister corpses as you can. Take them to Halannia inside the tree at the retreat. She will know what to do.", objectives = "Recover 10 Laughing Sister's Corpses.", progress = "I'm amazed that you broke through the Horde lines and managed to get in here, <race>.", completion = "Thank you, <class>. We have our hands full defending the retreat, but when I can catch my breath, I'll see to it that these sisters are returned to life, the goddess willing.\n\nYou've demonstrated your prowess... we can use your help." }
WordHunterWoW_QuestEN[13929] = { title = "The Biggest Tree Ever!", description = "Before there was a big war and we left the village, we remember Soo-say telling us all about the biggest tree ever!\n\nSoo-say call it Grizzlemaw or something. Soo-say tell us it in the middle Grizzle Hills. No, wait, that not what Soo-say say. Soo-say say Grizzly Hills. Now we remember! Tree is big and right in middle of Grizzly Hills. Can't miss!\n\nYou take us there, oki? We see inside of giant tree? Soo-say tell us big bear men live in tree too. Maybe we see them.", objectives = "Take your orphan, Roo, to visit Grizzlemaw. Make sure to call for him if he is not present when you enter the trunk of the great tree.", progress = "Can we see the big tree? Can we?", completion = "We never knew trees got that big! Nope. Maybe Great Ones had special plan for it?" }
WordHunterWoW_QuestEN[13930] = { title = "Home Of The Bear-Men", description = "High Shaman Rakjak always tell stories of mighty warriors, even ones far away. Sometimes he tell stories about giant bear-men fighting great battle for tree-city.\n\nMaybe you take Kekek there, see tree, see battle! High Shaman Rakjak tell Kekek that giant tree-city Grizzlemaw stand in the middle of Grizzly Hills.\n\nKekek never see a city before meeting orphan lady, but this city have no warriors, only men in purple dresses. Kekek want to see real warriors fight for real city.", objectives = "Take your orphan, Kekek, to visit Grizzlemaw. Make sure to call for him if he is not present when you enter the trunk of the great tree.", progress = "Kekek want to visit bear-men tree. We go.", completion = "This is Kekek's kind of city. Bear-men fight for home just like Frenzyheart do. Orphan lady tell Kekek not to fight with other pups, but Kekek fight anyway." }
WordHunterWoW_QuestEN[13931] = { title = "Another Year, Another Souvenir.", description = "Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", objectives = "Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp." }
WordHunterWoW_QuestEN[13932] = { title = "Another Year, Another Souvenir.", description = "Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.\n\nIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.", objectives = "Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp." }
WordHunterWoW_QuestEN[13933] = { title = "The Bronze Dragonshrine", description = "Sometimes High-Oracle Soo-say tell stories about a shrine to dragon-things, not like great rain stone, but different. Soo-say tell us maybe we see ourselves there, but not like in a shiny. Soo-say mean we could see what we are like many years from now.\n\nYou take us there? We remember shrine to bronze dragon-things in place called Dragonblight. Soo-say say great rain stone show him shrine to northeast of Wyrmrest Temple, or northwest of place dryskins call Wintergarde Keep. We go?", objectives = "Take your orphan, Roo, to visit the Bronze Dragonshrine. Make sure to call for him if he is not present when you get there.", completion = "We very glad you brought us here, <name>. We always worried what would happen to us when the orphan matron found us in Sholazar." }
WordHunterWoW_QuestEN[13934] = { title = "The Bronze Dragonshrine", description = "When Kekek was a pup, he sometimes heard elders talking about a far-off shrine. Sometimes they say that bronze dragon-things there know all about future.\n\nKekek tell you he be great warrior, now we go see. Bronze dragon-thing shrine somewhere in Dragonblight, northeast of dragon-thing temple called Wyrmrest, also northwest of man-town called Wintergarde.\n\nWe go there, see future. Prove orphan-lady wrong about Kekek. Kekek warrior, not bully.", objectives = "Take your orphan, Kekek, to visit the Bronze Dragonshrine. Make sure to call for him if he is not present when you get there.", completion = "See? Kekek never get tired of saying, \"Kekek tell you so.\"\n\nMaybe now you believe other things Kekek tell you, like how sky is green." }
WordHunterWoW_QuestEN[13935] = { title = "Defend the Tree!", description = "We have been using the power of the Forest Heart to defend the tree from the Horde, but its power is not without limit. We must use it to take the fight to them!\n\nShadumbra, the great cat of the forest, prowls nearby. It is from her that we shall draw our inspiration. You will become one with the shade of Shadumbra. You will take the essence of the panther into you and lay waste to those who dare attack the might of Ashenvale!", objectives = "Speak with Halannia to summon the Shade of Shadumbra and use its power to destroy any 50 Warsong enemies at Raynewood Retreat.", completion = "A brutal display, but one fitting for the enemies of Ashenvale. The Horde dares to think that they can take our beloved forest away from us.\n\nThey are fatally mistaken!\n\nYou have saved Raynewood from destruction, <name>. Surely we can find a reward suitable for our champion?" }
WordHunterWoW_QuestEN[13936] = { title = "Tweedle's Dumb", description = "Delays, delays, delays! I'm at wit's end!\n\nI was told that this goblin was brilliant - that he'd come up with gadgets sure to shock the enemy into submission. So far he's produced nothing but empty promises. If he comes up empty-handed again, I'm going to toss him off the cliff!\n\nYou go and speak to him, {class}. Let him know that my fuse is running short!", objectives = "Captain Goggath wants you to speak with Tweedle at Hellscream's Watch.", completion = "Let me tell ya somethin' <class>!\n\nThe bossman simply doesn't appreciate the art and craftsmanship that goes into making fine explosives." }
WordHunterWoW_QuestEN[13937] = { title = "A Trip To The Wonderworks", description = "We have time for one more stop? We heard Dalaran has toy store, but we never get to go there. Orphan mistress says too many orphans would crowd the store. Maybe we can go, just us?\n\nWe can have a small paper zeppelin? We think they have those at Wonderworks in Dalaran. We always wanted to play with one. Maybe you throw one to us?", objectives = "Purchase a Small Paper Zeppelin at the Wonderworks and then throw it to your orphan, Roo.", progress = "We go to the Wonderworks?", completion = "That was fun! We like toy store. Maybe orphan matron take us sometimes. We ask. Maybe you tell her too?" }
WordHunterWoW_QuestEN[13938] = { title = "A Visit To The Wonderworks", description = "You take Kekek one more place? Orphan lady say Dalaran have toy store called Wonderworks, but Kekek never seen it. She say that if one orphan go, she have to take everyone. Maybe you take Kekek?\n\nKekek seen other children playing with small paper zeppelin? Kekek hear those come from Wonderworks. Maybe you get one and throw it around with Kekek?", objectives = "Purchase a Small Paper Zeppelin at The Wonderworks and then throw it to your orphan, Kekek.", progress = "This toy store yet?", completion = "Kekek like playing with paper zeppelin. Not as good as hunting, but give something to do when bored at orphanage." }
WordHunterWoW_QuestEN[13939] = { title = "Fel Moss Corruption", description = "I'd hoped to never return to Teldrassil for such grim business. I'd hoped that its corruption had been wiped away completely.  Something fowl lingers.\n\nThe corruption of the wicked fel moss still threatens to turn peaceful creatures against us. The grells and gellkin still infest the area and threaten Shadowglen's residents.\n\nEngage these grells and grellkin, <name>, and see if they are indeed caught under the enchantment of the wicked fel moss. Once we know for certain, we will know how to proceed.You will receive:", objectives = "Collect 6 Fel Moss." }
WordHunterWoW_QuestEN[13940] = { title = "Leaving the Dream", description = "Hold on tight, {name}.  The journey back to the waking world can be a little rough on unprepared minds and bodies.", objectives = "Speak to Malfurion at the Eye of the Vortex in Darkshore.", completion = "You're just in time, <name>.  I don't know how much longer we can hold." }
WordHunterWoW_QuestEN[13941] = { title = "Vile Touch", description = "Githyiss the Vile was known for possessing a poison more potent than any other webwood spider. Dirania Silvershrine at the base of Aldrassil would surely be interested in using Githyiss' engorged venom sac to concoct an antidote equally as potent. Perhaps so interested as to even offer a reward...You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the Engorged Venom Sac to Dirania Silvershrine at the base of Aldrassil." }
WordHunterWoW_QuestEN[13942] = { title = "Set Us Up the Bomb", description = "I'm definitely on to something here!\n\nI have enough volatile elements salvaged from our arsenal to make the explosives Goggath wants, but I need to stabilize it and pack it into bombs.\n\nWhat I need is some clay - and not just any clay... moon-kissed clay.\n\nIt's only found on the northern banks of Astranaar Lake, and it possesses the qualities I need to bring out the full potential of my discovery!", objectives = "Tweedle at Hellscream's Watch wants you to collect 10 samples of Moon-Kissed Clay.", progress = "Let's see what you've brought me, <race>.", completion = "This is PERFECT!\n\nOh, just wait 'til you see what I can do with this...." }
WordHunterWoW_QuestEN[13943] = { title = "Breathing Room", description = "Our forces are not ready to assault Astranaar just yet, {class}. They know we're coming, though, and they're not content to sit and wait for us. At the base of this cliff they've created a camp from which they launch bothersome attacks by the light of the moon.\n\nBefore these skirmishes bolster their confidence any further, I want you to visit them with the wrath of the Horde! Return to me when the elves have been humbled a bit.", objectives = "Captain Goggath wants you to kill 10 Astranaar Skirmishers and 3 Astranaar Officers.", completion = "Well done, <race>. But there is much that remains to be done here." }
WordHunterWoW_QuestEN[13944] = { title = "Small Stature, Short Fuse", description = "<Tweedle gesticulates emphatically.>\n\nI've done it! This should satisfy even Goggath!\n\nWe just need a test that will sufficiently show off our efforts... ahh, the wagon!\n\nThe bossman's wanted that rotted out piece of junk hauled off for days. Use my explosives to get rid of it, then see what the captain has to say!", objectives = "Use the Improvised Explosive Stick on the Broken-down Wagon at Hellscream's Watch.", progress = "What have you done, <race>?", completion = "So, Tweedle found a way to get those explosives working, eh?\n\nIt's about time..." }
